	[DataUpgrader(Version = "1.0.72", Date = "2026/08/10")]
	private void FixAbnormalAlertnessData(DataContext context)
	{
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = taiwuChar.GetId();
		foreach (KeyValuePair<RelationKey, RelatedCharacter> pair in _relations)
		{
			if (pair.Key.CharId != taiwuCharId && pair.Key.RelatedCharId != taiwuCharId)
			{
				continue;
			}
			int relatedCharId = ((pair.Key.CharId == taiwuCharId) ? pair.Key.RelatedCharId : pair.Key.CharId);
			if (!IsCharacterAlive(relatedCharId))
			{
				continue;
			}
			Character npcChar = GetElement_Objects(relatedCharId);
			if (npcChar.GetCreatingType() == 1 && DomainManager.Extra.GetIsInteractedCharacter(relatedCharId))
			{
				CharacterAlertnessData alertnessData = GetAlertnessData(context, relatedCharId, init: false);
				if (alertnessData == null)
				{
					InitAlertnessData(context, npcChar, taiwuChar);
				}
			}
		}
	}

	[DataUpgrader(Version = "0.84.54", Date = "2026/06/11")]
	private void FixAbnormalCharacterProfessionData(DataContext context)
	{
		foreach (var (charId, professionList) in _characterProfessions)
		{
			foreach (ProfessionData profession in professionList.GetAllProfession())
			{
				profession.Type = 1;
				profession.SkillsData = null;
			}
		}
	}

	[DataUpgrader(Version = "1.0.23", Date = "2026/06/23")]
	private void FixAbnormalTravelingTaoistMonkSkill3(DataContext context)
	{
		if (DomainManager.Extra.IsCharacterDying(DomainManager.Taiwu.GetTaiwuCharId()) && DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(59))
		{
			Character taiwu = DomainManager.Taiwu.GetTaiwu();
			ProfessionData professionData = DomainManager.Extra.GetProfessionData(14);
			TravelingTaoistMonkSkillsData skillsData = professionData.GetSkillsData<TravelingTaoistMonkSkillsData>();
			skillsData.BonusMaxHealth += 36;
			DomainManager.Extra.SetProfessionData(context, professionData);
			short baseMaxHealth = taiwu.GetBaseMaxHealth();
			taiwu.SetBaseMaxHealth(baseMaxHealth, context);
		}
	}

	[DataUpgrader(Version = "1.0.24", Date = "2026/06/25")]
	private void FixCarrier(DataContext context)
	{
		AdaptableLog.Warning("FixCarrier called");
		HashSet<ItemKey> carriers = (from animal in DomainManager.Extra.GetAnimals()
			select animal.ItemKey into key
			where key.IsValid()
			select key).ToHashSet();
		List<ItemKey> clist = new List<ItemKey>();
		foreach (Character value in _objects.Values)
		{
			Character character = value;
			Dictionary<ItemKey, int> dict = character.GetInventory()?.Items;
			if (dict != null)
			{
				FixCarrierImpl(dict.Keys, character.GetId(), ItemOwnerType.CharacterInventory);
			}
			FixCarrierImpl(character.GetEquipment(), character.GetId(), ItemOwnerType.CharacterEquipment);
			void FixCarrierImpl(IEnumerable<ItemKey> keys, int charId, ItemOwnerType type)
			{
				foreach (ItemKey itemKey in keys)
				{
					if (itemKey.IsValid() && DomainManager.Item.ItemExists(itemKey) && itemKey.ItemType == 4 && !carriers.Add(itemKey))
					{
						clist.Add(itemKey);
					}
				}
				foreach (ItemKey itemKey2 in clist)
				{
					ItemBase carrier = DomainManager.Item.GetBaseItem(itemKey2);
					ItemOwnerKey owner = carrier.Owner;
					AdaptableLog.Warning($"FixCarrier called for {itemKey2} with character {charId} (owner: {carrier.Owner}), remove it.");
					character.RemoveInventoryItem(context, itemKey2, 1, deleteItem: false, offLine: true);
					carrier.SetOwner(owner.OwnerType, owner.OwnerId);
				}
				if (clist.Count > 0)
				{
					character.SetInventory(character.GetInventory(), context);
				}
				clist.Clear();
			}
		}
	}

