	[DataUpgrader(Version = "1.0.45", Date = "2026/07/01")]
	private void FixHuanxinFeatureOnNonTaiwu(DataContext context)
	{
		HashSet<short> huanxinOpenEyes = new HashSet<short> { 863, 865, 867 };
		HashSet<short> huanxinCloseEyes = new HashSet<short> { 864, 866, 868 };
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		short? transferFeatureId = null;
		bool preferOpenEyes = false;
		foreach (Character character in _objects.Values)
		{
			if (character.IsTaiwu())
			{
				continue;
			}
			short? foundOpenEye = null;
			short? foundCloseEye = null;
			foreach (short featureId in character.GetFeatureIds())
			{
				if (huanxinOpenEyes.Contains(featureId))
				{
					foundOpenEye = featureId;
				}
				else if (huanxinCloseEyes.Contains(featureId))
				{
					foundCloseEye = featureId;
				}
			}
			if (foundOpenEye.HasValue)
			{
				character.RemoveFeature(context, foundOpenEye.Value);
				if (!preferOpenEyes)
				{
					transferFeatureId = foundOpenEye.Value;
					preferOpenEyes = true;
				}
			}
			if (foundCloseEye.HasValue)
			{
				character.RemoveFeature(context, foundCloseEye.Value);
				if (!transferFeatureId.HasValue)
				{
					transferFeatureId = foundCloseEye.Value;
				}
			}
		}
		if (transferFeatureId.HasValue)
		{
			taiwu.AddFeature(context, transferFeatureId.Value, removeMutexFeature: true);
		}
	}

	[DataUpgrader(Version = "1.0.47", Date = "2026/07/01")]
	private void FixOrphanChildClothingFromOutterWorld(DataContext context)
	{
		List<ItemKey> toRemove = new List<ItemKey>();
		foreach (Character character in _objects.Values)
		{
			if (!character.GetFeatureIds().Contains(879))
			{
				continue;
			}
			ItemKey clothingKey = character.GetEquipment()[4];
			if (clothingKey.IsValid() && IsBabyOrChildClothing(clothingKey))
			{
				OrganizationMemberItem orgMemberCfg = OrganizationDomain.GetOrgMemberConfig(character.GetOrganizationInfo());
				short newClothingTemplateId = OrganizationDomain.GetRandomOrgMemberClothing(context.Random, orgMemberCfg);
				character.ForceReplaceClothing(context, newClothingTemplateId);
				AdaptableLog.Warning($"FixOrphanChildClothingFromOutterWorld: replaced child clothing on adult character {character.GetId()}");
			}
			Inventory inventory = character.GetInventory();
			if (inventory?.Items == null)
			{
				continue;
			}
			foreach (var (itemKey2, _) in inventory.Items)
			{
				if (itemKey2.IsValid() && DomainManager.Item.ItemExists(itemKey2) && IsBabyOrChildClothing(itemKey2))
				{
					toRemove.Add(itemKey2);
				}
			}
			foreach (ItemKey itemKey3 in toRemove)
			{
				int amount = inventory.Items[itemKey3];
				inventory.OfflineRemove(itemKey3, amount);
				DomainManager.Character.ClearItemUsingState(context, itemKey3, character.GetId());
				if (DomainManager.Item.ItemExists(itemKey3))
				{
					DomainManager.Item.ForceRemoveItem(context, itemKey3);
				}
				AdaptableLog.Warning($"FixOrphanChildClothingFromOutterWorld: removed orphan child clothing {itemKey3} from character {character.GetId()}");
			}
			if (toRemove.Count > 0)
			{
				character.SetInventory(inventory, context);
			}
			toRemove.Clear();
		}
	}

	private static bool IsBabyOrChildClothing(ItemKey itemKey)
	{
		bool flag = itemKey.ItemType == 3;
		bool flag2 = flag;
		if (flag2)
		{
			short templateId = itemKey.TemplateId;
			bool flag3 = (uint)(templateId - 64) <= 1u;
			flag2 = flag3;
		}
		return flag2;
	}

	public unsafe override void FixAbnormalDomainArchiveData(DataContext context)
	{
		ClearObsoleteRelationData(context);
		FixIncompleteRelation(context);
		FixDuplicateLifeSkills(context);
		FixAbnormalExtraNeiliAllocationByProgress(context);
		RemoveAbnormalInfectedCharacterGroup(context);
		RemoveDuplicateCharacterLocationAtBlocks(context);
		RemoveDuplicateKidnappedCharacters(context);
		RemoveAbnormalSkeletonCharacters(context);
		RemoveAbnormalCrossAreaTravelingCharacters(context);
		HashSet<ItemKey> worldCharacterItems = new HashSet<ItemKey>(1048576);
		worldCharacterItems.UnionWith(DomainManager.Taiwu.WarehouseItems.Keys);
		worldCharacterItems.UnionWith(DomainManager.Taiwu.GetItems(ItemSourceType.Treasury).Keys);
		HashSet<int> unreleasedCalledCharacters = new HashSet<int>();
		DomainManager.Adventure.CollectAllCharactersInAdventure(unreleasedCalledCharacters, includeTemporaryCharacters: true);
		HashSet<int> ignoreCharIds = _temporaryIntelligentCharIds.GetCollection();
		foreach (int charId in ignoreCharIds)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			Location charLocation = character.GetLocation();
			if (charLocation.IsValid())
			{
				MapBlockData block = DomainManager.Map.GetBlock(charLocation);
				if (block.CharacterSet != null && block.CharacterSet.Contains(charId))
				{
					Events.RaiseCharacterLocationChanged(context, charId, charLocation, Location.Invalid);
					Logger.Warn($"Removing temporary character {character} from map.");
				}
				if (block.InfectedCharacterSet != null && block.InfectedCharacterSet.Contains(charId))
				{
					Events.RaiseInfectedCharacterLocationChanged(context, charId, charLocation, Location.Invalid);
					Logger.Warn($"Removing temporary character {character} from map.");
				}
			}
			else
			{
				character.SetLocation(DomainManager.Taiwu.GetTaiwuVillageLocation(), context);
			}
		}
		Dictionary<int, Character> allPreexistingCharIds = new Dictionary<int, Character>();
		int key;
		foreach (KeyValuePair<int, Character> @object in _objects)
		{
			@object.Deconstruct(out key, out var value);
			int charId2 = key;
			Character character2 = value;
			FixCharacterConsummateLevel(context, character2);
			if (ignoreCharIds.Contains(charId2))
			{
				continue;
			}
			PreexistenceCharIds preexistingCharIds = character2.GetPreexistenceCharIds();
			if (preexistingCharIds.Count > 0 && preexistingCharIds.CharIds[0] >= 0)
			{
				int preexistingCharId = preexistingCharIds.CharIds[0];
				if (allPreexistingCharIds.TryGetValue(preexistingCharId, out var otherChar))
				{
					Logger.Warn($"Removing duplicate preexisting character {preexistingCharId} of {character2} (already reincarnated as {otherChar})");
					character2.ClearPreexistenceCharIds(context);
				}
				else
				{
					allPreexistingCharIds.Add(preexistingCharId, character2);
				}
			}
			if (character2.IsActiveExternalRelationState(4uL) && !unreleasedCalledCharacters.Contains(charId2) && !unreleasedCalledCharacters.Contains(character2.GetLeaderId()))
			{
				character2.DeactivateExternalRelationState(context, 4uL);
				Logger.Warn($"Canceling called by adventure state for {character2}");
			}
			FixAbnormalFeature(context, character2);
			FixAbnormalGroupState(context, character2);
			FixAbnormalCharacterLocation(context, character2);
			FixAbnormalPregnantState(context, character2);
			FixAbnormalCharacterOrganization(context, character2);
			FixInventoryAndEquippedItem(context, character2, worldCharacterItems);
			FixCharacterMaxNeili(context, character2);
			FixCharacterCurrNeili(context, character2);
			FixErrorEatItems(context, character2);
			int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
			if (charId2 != taiwuCharId)
			{
				FixAbnormalAvatar(context, character2);
			}
			FixSpecialIdentityCharacterOrganizationAndIdentity(context, character2);
			FixAbnormalConsumedOwner(context, character2);
			FixAbnormalIdealSect(context, character2);
			FixAbnormalGuardFeature(context, character2);
			if (charId2 == taiwuCharId)
			{
				FixAbnormalTaiwuExtraNeiliAllocation(context, character2);
			}
			FixAbnormalCombatSkillPageActivation(context, character2);
		}
		List<ItemKey> itemKeys = context.AdvanceMonthRelatedData.ItemKeys.Occupy();
		foreach (KeyValuePair<int, Grave> grafe in _graves)
		{
			grafe.Deconstruct(out key, out var value2);
			int charId3 = key;
			Grave grave = value2;
			Inventory inventory = grave.GetInventory();
			itemKeys.Clear();
			itemKeys.AddRange(inventory.Items.Keys);
			bool inventoryChanged = false;
			foreach (ItemKey itemKey in itemKeys)
			{
				if (ItemTemplateHelper.IsPureStackable(itemKey))
				{
					continue;
				}
				if (DomainManager.Item.ItemExists(itemKey))
				{
					if (!worldCharacterItems.Add(itemKey))
					{
						Logger.Warn($"Removing duplicate item {itemKey} in grave {charId3}");
						inventory.OfflineRemove(itemKey, inventory.Items[itemKey]);
						inventoryChanged = true;
					}
				}
				else
				{
					Logger.Warn($"Removing ghost item {itemKey} in grave {charId3}");
					inventory.OfflineRemove(itemKey, inventory.Items[itemKey]);
					inventoryChanged = true;
				}
			}
			if (inventoryChanged)
			{
				grave.SetInventory(inventory, context);
			}
		}
		context.AdvanceMonthRelatedData.ItemKeys.Release(ref itemKeys);
	}

	private void FixAbnormalTaiwuExtraNeiliAllocation(DataContext context, Character character)
	{
		short maxNeiliAllocation = GlobalConfig.Instance.MaxExtraNeiliAllocation;
		int maxProgress = Character.GetNeiliAllocationMaxProgress();
		int[] progress = character.GetExtraNeiliAllocationProgress();
		NeiliAllocation extraNeiliAllocation = character.GetExtraNeiliAllocation();
		for (int i = 0; i < 4; i++)
		{
			if (progress[i] >= maxProgress && extraNeiliAllocation[i] < maxNeiliAllocation)
			{
				extraNeiliAllocation[i] = maxNeiliAllocation;
			}
		}
		character.SetExtraNeiliAllocation(extraNeiliAllocation, context);
	}

	private void FixAbnormalCombatSkillPageActivation(DataContext context, Character character)
	{
		List<short> learnedCombatSkillIds;
		int charId;
		if (DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 79, 21))
		{
			learnedCombatSkillIds = character.GetLearnedCombatSkills();
			charId = character.GetId();
			DomainManager.Character.AutoActivateReadCombatSkillNormalPages(context, IterLearnedCombatSkills(), charId);
		}
		IEnumerable<GameData.Domains.CombatSkill.CombatSkill> IterLearnedCombatSkills()
		{
			using List<short>.Enumerator enumerator = learnedCombatSkillIds.GetEnumerator();
			while (enumerator.MoveNext())
			{
				CombatSkillKey skillKey = new CombatSkillKey(skillTemplateId: enumerator.Current, charId: charId);
				if (DomainManager.CombatSkill.TryGetElement_CombatSkills(skillKey, out var combatSkill))
				{
					yield return combatSkill;
					combatSkill = null;
				}
			}
		}
	}

	private void FixSpecialIdentityCharacterOrganizationAndIdentity(DataContext context, Character character)
	{
		if (!DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 74))
		{
			return;
		}
		short templateId = character.GetTemplateId();
		CharacterItem config = Config.Character.Instance[templateId];
		if (!string.IsNullOrEmpty(config.SpecialGradeName))
		{
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			if (orgInfo.OrgTemplateId == 0 && config.OrganizationInfo.OrgTemplateId != 0)
			{
				orgInfo.OrgTemplateId = config.OrganizationInfo.OrgTemplateId;
				orgInfo.Grade = config.OrganizationInfo.Grade;
				character.SetOrganizationInfo(orgInfo, context);
			}
		}
	}

	private void FixAbnormalConsumedOwner(DataContext context, Character character)
	{
		if (!DomainManager.LegendaryBook.IsLegendaryBookConsumed(character.GetId()))
		{
			return;
		}
		DomainManager.Organization.ChangeOrganization(context, character, OrganizationInfo.None);
		Location location = character.GetLocation();
		if (!location.IsValid() || location.AreaId >= 45)
		{
			return;
		}
		List<short> brokenAreas = ObjectPool<List<short>>.Instance.Get();
		DomainManager.Map.GetAllBrokenAreaInState(DomainManager.Map.GetStateIdByAreaId(location.AreaId), brokenAreas);
		if (brokenAreas.Count > 0)
		{
			CollectionUtils.Shuffle(context.Random, brokenAreas);
			List<MapBlockData> validBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
			short areaId = brokenAreas[0];
			DomainManager.Map.GetValidBlocksForRandomEnemy(areaId, -1, -1, onSettlement: true, nearTaiwu: true, validBlocks);
			if (validBlocks.Count > 0)
			{
				CollectionUtils.Shuffle(context.Random, validBlocks);
				Location destLocation = validBlocks[0].GetLocation();
				DomainManager.Character.LeaveGroup(context, character, bringWards: false);
				character.SetLocation(destLocation, context);
				Events.RaiseCharacterLocationChanged(context, character.GetId(), location, destLocation);
			}
			ObjectPool<List<MapBlockData>>.Instance.Return(validBlocks);
		}
		ObjectPool<List<short>>.Instance.Return(brokenAreas);
		Logger.Info($"Fix Abnormal Consumed Character: {character}");
	}

	private void FixAbnormalIdealSect(DataContext context, Character character)
	{
		sbyte orig = character.GetIdealSect();
		if (orig <= 0)
		{
			List<sbyte> randomIdealSectsPool = character.Template.RandomIdealSects;
			sbyte idealSect = ((randomIdealSectsPool != null && randomIdealSectsPool.Count > 0) ? randomIdealSectsPool.GetRandom(context.Random) : ((sbyte)((character.Template.IdealSect > 0) ? character.Template.IdealSect : (-1))));
			if (orig != idealSect)
			{
				character.SetIdealSect(idealSect, context);
				Logger.Info($"Fix Abnormal Character Ideal Sect: {character}, {orig} -> {idealSect}");
			}
		}
	}

	private void FixAbnormalGuardFeature(DataContext context, Character character)
	{
		if (character.GetCreatingType() == 1 && DomainManager.Organization.CharacterTreasuryGuardInfo(character.GetId()) == 0 && character.RemoveFeatureGroup(context, 691))
		{
			Logger.Info($"Fix Abnormal Character Guard Feature: {character}");
		}
	}

	private void ClearObsoleteRelationData(DataContext context)
	{
		int countBefore = _relations.Count;
		foreach (var (charId, deadChar) in _deadCharacters)
		{
			RemoveAllGeneralRelations(context, charId);
		}
		int countAfter = _relations.Count;
		Logger.Info($"Clearing obsolete relations: {countBefore} => {countAfter}");
		int expectedCapacity = countAfter + _objects.Count * 64;
		if (countBefore > expectedCapacity)
		{
			_relations.TrimExcess(expectedCapacity);
			Logger.Info($"Trimming relation dict capacity to {expectedCapacity}");
		}
	}

	private void RemoveAbnormalSkeletonCharacters(DataContext context)
	{
		foreach (var (skeletonId, deadCharId) in _skeletonCharacterCache)
		{
			if (_objects.TryGetValue(skeletonId, out var skeletonChar) && _deadCharacters.TryGetValue(deadCharId, out var deadChar) && (skeletonChar.GetGender() != deadChar.Gender || skeletonChar.GetAgeGroup() != 2))
			{
				Logger.Warn($"Removing abnormal skeleton character {skeletonId} of grave {deadCharId}");
				RemoveNonIntelligentCharacter(context, skeletonChar);
			}
		}
	}

	private void RemoveAbnormalCrossAreaTravelingCharacters(DataContext context)
	{
		foreach (var (charId, travelInfo) in _crossAreaMoveInfos)
		{
			if (!TryGetElement_Objects(charId, out var character))
			{
				Logger.Warn($"Invalid travel info: {charId}(dead) from {travelInfo.FromAreaId} to {travelInfo.ToAreaId}");
				RemoveCrossAreaTravelInfo(context, charId);
			}
			else if (character.GetLocation().IsValid())
			{
				Logger.Warn($"Invalid travel info: {charId} from {travelInfo.FromAreaId} to {travelInfo.ToAreaId}");
				RemoveCrossAreaTravelInfo(context, charId);
			}
		}
	}

	private void FixAbnormalAvatar(DataContext context, Character character)
	{
		AvatarData avatar = character.GetAvatar();
		AvatarGroup avatarGroup = AvatarManager.Instance.GetAvatarGroup(avatar.AvatarId);
		if (avatarGroup.IsHairless(avatar.FrontHairId, avatar.BackHairId))
		{
			(avatar.FrontHairId, avatar.BackHairId) = avatarGroup.GetRandomHairs(context.Random);
			character.SetAvatar(avatar, context);
			Logger.Warn($"Fixing abnormal hairless avatar for character {character}.");
		}
	}

	private void FixIncompleteRelation(DataContext context)
	{
		List<RelationKey> relationsToAdd = null;
		foreach (var (charId, character2) in _objects)
		{
			if (!_relatedCharIds.TryGetValue(charId, out var relatedCharIds))
			{
				continue;
			}
			foreach (int relatedCharId in relatedCharIds.General.GetCollection())
			{
				RelationKey reverseKey = new RelationKey(relatedCharId, charId);
				if (_objects.ContainsKey(relatedCharId) && !_relations.ContainsKey(reverseKey))
				{
					if (relationsToAdd == null)
					{
						relationsToAdd = new List<RelationKey>();
					}
					relationsToAdd.Add(reverseKey);
				}
			}
		}
		if (relationsToAdd == null)
		{
			return;
		}
		foreach (RelationKey relationKey in relationsToAdd)
		{
			RelationKey srcKey = new RelationKey(relationKey.RelatedCharId, relationKey.CharId);
			RelatedCharacter srcRelation = _relations[srcKey];
			AddRelationInternal(context, relationKey.CharId, relationKey.RelatedCharId, 0, srcRelation.EstablishmentDate);
			Logger.Warn($"Add missing relation between {_objects[relationKey.CharId]} and {_objects[relationKey.RelatedCharId]}");
		}
	}

	private unsafe void FixErrorEatItems(DataContext context, Character character)
	{
		EatingItems eatItems = character.GetEatingItems();
		for (int i = 0; i < 9; i++)
		{
			ItemKey itemKey = (ItemKey)eatItems.ItemKeys[i];
			if (EatingItems.IsValid(itemKey) && ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId) != 802 && !DomainManager.Item.ItemExists(itemKey))
			{
				eatItems.ItemKeys[i] = (ulong)ItemKey.Invalid;
				character.SetEatingItems(ref eatItems, context);
				Logger.Warn($"Removing character {character} eatItems,ItemType: {itemKey.ItemType},TemplateId： {itemKey.TemplateId}");
			}
		}
	}

	private void FixDuplicateLifeSkills(DataContext context)
	{
		HashSet<short> lifeSkillIdSet = new HashSet<short>();
		HashSet<int> taiwuGroup = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		foreach (int charId in taiwuGroup)
		{
			Character character = _objects[charId];
			List<LifeSkillItem> learnedLifeSkills = character.GetLearnedLifeSkills();
			lifeSkillIdSet.Clear();
			int index = 0;
			bool isChanged = false;
			while (index < learnedLifeSkills.Count)
			{
				LifeSkillItem lifeSkillItem = learnedLifeSkills[index];
				if (!lifeSkillIdSet.Add(lifeSkillItem.SkillTemplateId))
				{
					learnedLifeSkills.RemoveAt(index);
					Logger.Warn($"Removing {character}'s duplicate life skill {LifeSkill.Instance[lifeSkillItem.SkillTemplateId].Name} ({lifeSkillItem.SkillTemplateId}).");
					isChanged = true;
				}
				else
				{
					index++;
				}
			}
			if (isChanged)
			{
				character.SetLearnedLifeSkills(learnedLifeSkills, context);
			}
		}
	}

	private unsafe void FixAbnormalExtraNeiliAllocationByProgress(DataContext context)
	{
		if (DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 71, 71))
		{
			Character taiwu = DomainManager.Taiwu.GetTaiwu();
			int[] extraNeiliAllocationProgress = taiwu.GetExtraNeiliAllocationProgress();
			int maxProgress = Character.GetNeiliAllocationMaxProgress();
			NeiliAllocation extraNeiliAllocation = default(NeiliAllocation);
			extraNeiliAllocation.Initialize();
			for (int i = 0; i < 4; i++)
			{
				extraNeiliAllocation.Items[i] = (short)Character.GetExtraNeiliAllocationByProgress(Math.Clamp(extraNeiliAllocationProgress[i], 0, maxProgress));
			}
			taiwu.SetExtraNeiliAllocation(extraNeiliAllocation, context);
		}
	}

	private void RemoveDuplicateCharacterLocationAtBlocks(DataContext context)
	{
		ConcurrentBag<(MapBlockData block, int charId)> duplicateCharacterBlocks = new ConcurrentBag<(MapBlockData, int)>();
		Parallel.For(0, 141, delegate(int i)
		{
			CollectDuplicateCharacterLocationBlocksInArea(i, duplicateCharacterBlocks);
		});
		if (duplicateCharacterBlocks.Count <= 0)
		{
			return;
		}
		Logger.Warn($"{duplicateCharacterBlocks.Count} duplicate/invalid block characters found.");
		foreach (var item in duplicateCharacterBlocks)
		{
			MapBlockData block = item.block;
			int charId = item.charId;
			Character character;
			string removedCharName = (_objects.TryGetValue(charId, out character) ? character.ToString() : charId.ToString());
			Logger.Warn($"Removing character {removedCharName} at ({block.AreaId}, {block.BlockId})");
			block.RemoveCharacter(charId);
			block.RemoveInfectedCharacter(charId);
			DomainManager.Map.SetBlockData(context, block);
		}
	}

	private void FixAbnormalInfectedCharacterInPrisonAndBlock(DataContext context)
	{
		foreach (int infectedCharId in _infectedCharSet)
		{
			Character character = _objects[infectedCharId];
			if (character.IsActiveExternalRelationState(32uL))
			{
				Location validLocation = character.GetValidLocation();
				MapBlockData blockData = DomainManager.Map.GetBlock(validLocation);
				if (blockData.InfectedCharacterSet != null && blockData.InfectedCharacterSet.Contains(infectedCharId))
				{
					Logger.Warn($"Removing infected prisoner {character} from block {validLocation}.");
					Events.RaiseInfectedCharacterLocationChanged(context, infectedCharId, validLocation, Location.Invalid);
				}
			}
		}
	}

	private void RemoveAbnormalInfectedCharacterGroup(DataContext context)
	{
		foreach (int infectedCharId in _infectedCharSet)
		{
			Character character = _objects[infectedCharId];
			int leaderId = character.GetLeaderId();
			Location location = character.GetLocation();
			if (character.GetLeaderId() < 0)
			{
				continue;
			}
			Logger.Warn($"Removing infected character {character} from group with leader {leaderId} at {location}");
			LeaveGroup(context, character, bringWards: false);
			location = character.GetLocation();
			if (location.IsValid())
			{
				MapBlockData block = DomainManager.Map.GetBlock(location);
				if (block.CharacterSet.Contains(infectedCharId))
				{
					block.RemoveCharacter(infectedCharId);
					block.AddInfectedCharacter(infectedCharId);
					DomainManager.Map.SetBlockData(context, block);
					Logger.Warn($"Re-adjusting infected character {character}'s location at {location}.");
				}
			}
		}
	}

	private void RemoveDuplicateKidnappedCharacters(DataContext context)
	{
		Dictionary<int, int> toRemoveKidnappedCharDict = ObjectPool<Dictionary<int, int>>.Instance.Get();
		toRemoveKidnappedCharDict.Clear();
		int key;
		foreach (KeyValuePair<int, KidnappedCharacterList> kidnappedChar2 in _kidnappedChars)
		{
			kidnappedChar2.Deconstruct(out key, out var value);
			int charId = key;
			KidnappedCharacterList kidnappedCharacterList = value;
			foreach (KidnappedCharacter kidnappedChar in kidnappedCharacterList.GetCollection())
			{
				int kidnappedCharId = kidnappedChar.CharId;
				if (!_objects.TryGetValue(kidnappedCharId, out var character))
				{
					toRemoveKidnappedCharDict[kidnappedCharId] = charId;
					continue;
				}
				if (character.GetKidnapperId() != charId)
				{
					toRemoveKidnappedCharDict[kidnappedCharId] = charId;
					continue;
				}
				Location charLocation = character.GetLocation();
				if (charLocation.IsValid())
				{
					MapBlockData blockData = DomainManager.Map.GetBlock(charLocation);
					if (blockData.RemoveCharacter(kidnappedCharId) || blockData.RemoveInfectedCharacter(kidnappedCharId))
					{
						Logger.Warn($"Removing duplicated kidnapped character {kidnappedCharId} by {charId} at ({blockData.AreaId},{blockData.BlockId})");
						DomainManager.Map.SetBlockData(context, blockData);
						character.SetLocation(Location.Invalid, context);
					}
				}
			}
		}
		foreach (KeyValuePair<int, int> item in toRemoveKidnappedCharDict)
		{
			item.Deconstruct(out key, out var value2);
			int kidnappedCharId2 = key;
			int kidnapperCharId = value2;
			KidnappedCharacterList kidnappedCharList = _kidnappedChars[kidnapperCharId];
			kidnappedCharList.Remove(kidnappedCharId2);
			if (kidnappedCharList.GetCount() > 0)
			{
				SetElement_KidnappedChars(kidnapperCharId, kidnappedCharList, context);
			}
			else
			{
				RemoveElement_KidnappedChars(kidnappedCharId2, context);
				Character kidnapper = _objects[kidnapperCharId];
				kidnapper.DeactivateExternalRelationState(context, 2uL);
			}
			Logger.Warn($"Removing kidnap relation: {kidnapperCharId} kidnapped {kidnappedCharId2}.");
		}
		ObjectPool<Dictionary<int, int>>.Instance.Return(toRemoveKidnappedCharDict);
	}

	private void CollectDuplicateCharacterLocationBlocksInArea(int areaId, ConcurrentBag<(MapBlockData block, int charId)> duplicateCharacterBlocks)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks((short)areaId);
		List<int> stoneRoomChars = DomainManager.Extra.GetStoneRoomCharList();
		int i = 0;
		for (int blocksCount = blocks.Length; i < blocksCount; i++)
		{
			Location blockLocation = new Location((short)areaId, (short)i);
			HashSet<int> charIds = blocks[i].CharacterSet;
			if (charIds != null)
			{
				foreach (int charId in charIds)
				{
					if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
					{
						duplicateCharacterBlocks.Add((blocks[i], charId));
					}
					else if (!character.GetLocation().Equals(blockLocation))
					{
						duplicateCharacterBlocks.Add((blocks[i], charId));
					}
					else if (character.GetLeaderId() == taiwuCharId)
					{
						duplicateCharacterBlocks.Add((blocks[i], charId));
					}
				}
			}
			else
			{
				charIds = EmptyCharacterSet;
			}
			HashSet<int> infectedCharIds = blocks[i].InfectedCharacterSet;
			if (infectedCharIds == null)
			{
				continue;
			}
			foreach (int charId2 in infectedCharIds)
			{
				if (!DomainManager.Character.TryGetElement_Objects(charId2, out var character2))
				{
					duplicateCharacterBlocks.Add((blocks[i], charId2));
				}
				else if (!character2.GetLocation().Equals(blockLocation))
				{
					duplicateCharacterBlocks.Add((blocks[i], charId2));
				}
				else if (character2.GetLeaderId() == taiwuCharId)
				{
					duplicateCharacterBlocks.Add((blocks[i], charId2));
				}
				else if (charIds.Contains(charId2))
				{
					duplicateCharacterBlocks.Add((blocks[i], charId2));
				}
				else if (stoneRoomChars.Contains(charId2))
				{
					duplicateCharacterBlocks.Add((blocks[i], charId2));
				}
			}
		}
	}

	private void FixInventoryAndEquippedItem(DataContext context, Character character, HashSet<ItemKey> worldCharacterItems)
	{
		int charId = character.GetId();
		Inventory inventory = character.GetInventory();
		List<ItemKey> inventoryList = context.AdvanceMonthRelatedData.ItemKeys.Occupy();
		inventoryList.AddRange(inventory.Items.Keys);
		bool changed = false;
		for (int i = 0; i < inventoryList.Count; i++)
		{
			ItemKey key = inventoryList[i];
			int amount = inventory.Items[key];
			if (!ItemTemplateHelper.CheckTemplateValid(key.ItemType, key.TemplateId))
			{
				Logger.Warn($"Removing {character}'s inventory item {key.Id} with invalid template: ItemType {key.ItemType}, TemplateId {key.TemplateId}");
				inventory.OfflineRemove(key, amount);
				if (DomainManager.Item.ItemExists(key))
				{
					DomainManager.Item.ForceRemoveItem(context, key);
				}
				changed = true;
			}
			else if (DomainManager.Item.ItemExists(key))
			{
				ItemBase baseItem = DomainManager.Item.GetBaseItem(key);
				ItemKey baseKey = baseItem.GetItemKey();
				if (!key.Equals(baseKey))
				{
					Logger.Warn($"Fixing {character}'s inventory item {key}'s refine effect.");
					inventory.OfflineRemove(key, amount);
					inventory.OfflineAdd(baseKey, amount);
					changed = true;
				}
				if (!ItemTemplateHelper.IsPureStackable(baseKey))
				{
					if (amount > 1)
					{
						Logger.Warn($"Fixing character {character}'s stacked non-stackable item {baseKey}");
						inventory.Items[baseKey] = 1;
						changed = true;
					}
					if (!worldCharacterItems.Add(baseKey))
					{
						Logger.Warn($"Removing character {character}'s duplicate item {baseKey}");
						inventory.OfflineRemove(baseKey, 1);
						changed = true;
					}
				}
			}
			else
			{
				Logger.Warn($"Removing ghost item {key} from {character}'s inventory.");
				inventory.OfflineRemove(key, amount);
				changed = true;
			}
		}
		context.AdvanceMonthRelatedData.ItemKeys.Release(ref inventoryList);
		if (changed)
		{
			character.SetInventory(inventory, context);
		}
		ItemKey[] equipArray = character.GetEquipment();
		for (int j = 0; j < equipArray.Length; j++)
		{
			ItemKey key2 = equipArray[j];
			if (!key2.IsValid())
			{
				continue;
			}
			if (!ItemTemplateHelper.CheckTemplateValid(key2.ItemType, key2.TemplateId))
			{
				Logger.Warn($"Removing {character}'s equipped item {key2.Id} with invalid template: ItemType {key2.ItemType}, TemplateId {key2.TemplateId}");
				equipArray[j] = ItemKey.Invalid;
				character.SetEquipment(equipArray, context);
				if (DomainManager.Item.ItemExists(key2))
				{
					DomainManager.Item.ForceRemoveItem(context, key2);
				}
			}
			else if (DomainManager.Item.ItemExists(key2))
			{
				EquipmentBase baseEquipment = DomainManager.Item.GetBaseEquipment(key2);
				if (baseEquipment.GetTemplateId() != key2.TemplateId || baseEquipment.GetId() != key2.Id)
				{
					equipArray[j] = ItemKey.Invalid;
					character.SetEquipment(equipArray, context);
					DomainManager.Item.ForceRemoveItem(context, key2);
					Logger.Warn($"Removing {character}'s equipped item {key2} whose key differs from object ({baseEquipment.GetType().Name}, {baseEquipment.GetTemplateId()}, {baseEquipment.GetId()}).");
					continue;
				}
				ItemKey baseKey2 = baseEquipment.GetItemKey();
				if (!key2.Equals(baseKey2))
				{
					Logger.Warn($"Fixing {character}'s equipment {key2}'s refine effect.");
					equipArray[j] = baseKey2;
					character.SetEquipment(equipArray, context);
				}
				if (inventory.Items.ContainsKey(key2))
				{
					inventory.OfflineRemove(key2);
					character.SetInventory(inventory, context);
					Logger.Warn($"Removing {key2} from {charId}'s inventory because it already exists in equipments.");
				}
				else if (!worldCharacterItems.Add(baseKey2))
				{
					Logger.Warn($"Removing character {character}'s duplicate item {baseKey2}");
					if (baseEquipment.GetEquippedCharId() == charId)
					{
						baseEquipment.SetEquippedCharId(-1, context);
					}
					equipArray[j] = ItemKey.Invalid;
					character.SetEquipment(equipArray, context);
				}
				else if (baseEquipment.GetEquippedCharId() != charId && character.GetCreatingType() == 1)
				{
					Logger.Warn($"Fixing {character}'s equipment {key2}'s equipped char id.");
					baseEquipment.SetEquippedCharId(charId, context);
				}
			}
			else
			{
				equipArray[j] = ItemKey.Invalid;
				character.SetEquipment(equipArray, context);
				Logger.Warn($"Removing ghost item {key2} from {charId}'s equipment.");
			}
		}
	}

