	private void FixAbnormalCharacterOrganization(DataContext context, Character character)
	{
		if (character.GetCreatingType() != 1)
		{
			return;
		}
		int charId = character.GetId();
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		SettlementCharacter settlementChar2;
		if (orgInfo.SettlementId < 0)
		{
			if (orgInfo.OrgTemplateId == 20 && !character.GetFeatureIds().Contains(211) && !character.GetFeatureIds().Contains(814))
			{
				DomainManager.Organization.JoinNearbyVillageTownAsBeggar(context, character, -1);
				(string surname, string givenName) realName = GetRealName(character);
				string surname = realName.surname;
				string givenName = realName.givenName;
				OrganizationItem oldOrgCfg = Config.Organization.Instance[orgInfo.OrgTemplateId];
				OrganizationItem newOrgCfg = Config.Organization.Instance[character.GetOrganizationInfo().OrgTemplateId];
				Logger.Warn($"Fixing character {character} ({surname + givenName})'s organization - {oldOrgCfg.Name} => {newOrgCfg.Name}");
			}
			else if (OrganizationDomain.IsLargeSect(orgInfo.OrgTemplateId))
			{
				orgInfo.SettlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(orgInfo.OrgTemplateId);
				if (!DomainManager.Organization.TryGetSettlementCharacter(charId, out var _))
				{
					var (surname2, givenName2) = GetRealName(character);
					Logger.Warn($"Fixing character {character} ({surname2 + givenName2})'s organization - {Config.Organization.Instance[orgInfo.OrgTemplateId].Name}");
					DomainManager.Organization.JoinOrganization(context, character, orgInfo, charIsCreating: false);
				}
				character.SetOrganizationInfo(orgInfo, context);
			}
		}
		else if (!DomainManager.Organization.TryGetSettlementCharacter(charId, out settlementChar2))
		{
			var (surname3, givenName3) = GetRealName(character);
			Logger.Warn($"Fixing character {character} ({surname3 + givenName3})'s organization - {Config.Organization.Instance[orgInfo.OrgTemplateId].Name}");
			if (orgInfo.OrgTemplateId == 16)
			{
				orgInfo.Grade = 0;
				orgInfo.Principal = true;
				orgInfo.SettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
				character.SetOrganizationInfo(orgInfo, context);
			}
			DomainManager.Organization.JoinOrganization(context, character, orgInfo, charIsCreating: false);
		}
		if (orgInfo.OrgTemplateId == 16 && orgInfo.SettlementId == DomainManager.Taiwu.GetTaiwuVillageSettlementId() && orgInfo.Grade > 0 && orgInfo.Grade < 8 && DomainManager.Extra.GetVillagerRole(charId) == null)
		{
			Logger.Warn($"Fixing no-role villager {character}'s grade: {orgInfo.Grade} => {0}");
			DomainManager.Organization.ChangeGrade(context, character, 0, destPrincipal: true);
		}
		if (!character.IsCompletelyInfected() && !character.IsTaiwu() && (character.GetFeatureIds().Contains(211) || character.GetFeatureIds().Contains(814)))
		{
			Logger.Warn($"Fixing abnormal non-xiangshu infected character {character} with infected features.");
			character.AddFeature(context, 209, removeMutexFeature: true);
			_infectedCharSet?.Remove(charId);
			Events.RaiseInfectedCharacterLocationChanged(context, charId, character.GetLocation(), Location.Invalid);
			DomainManager.Map.TryResetXiangshuInfectedDemon(context, charId);
		}
	}

