	private unsafe void FixCharacterMaxNeili(DataContext context, Character character)
	{
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> combatSkills = DomainManager.CombatSkill.GetCharCombatSkills(character.GetId());
		foreach (KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> item in combatSkills)
		{
			item.Deconstruct(out var key, out var value);
			short combatSkillTemplateId = key;
			GameData.Domains.CombatSkill.CombatSkill combatSkill = value;
			short obtainedNeili = combatSkill.GetObtainedNeili();
			if (obtainedNeili < 0)
			{
				short obtainableNeili = combatSkill.GetTotalObtainableNeili();
				combatSkill.SetObtainedNeili(obtainableNeili, context);
				Logger.Warn($"Fixing {character}'s abnormal combat skill {Config.CombatSkill.Instance[combatSkillTemplateId].Name}'s obtained neili {obtainedNeili} => {obtainableNeili}");
			}
		}
		NeiliAllocation baseNeiliAllocation = character.GetBaseNeiliAllocation();
		if (baseNeiliAllocation.GetTotal() < 0)
		{
			character.ResetBaseNeiliAllocation(context);
			Logger.Warn($"Fixing {character}'s abnormal base neili allocation: {baseNeiliAllocation} => {character.GetBaseNeiliAllocation()}");
			return;
		}
		int maxNeili = character.GetMaxNeili();
		sbyte consummateLevel = character.GetConsummateLevel();
		short maxTotalNeiliAllocation = CombatHelper.GetMaxTotalNeiliAllocationConsideringFeature(consummateLevel, character.GetFeatureIds(), DomainManager.World.GetChallengeModeData());
		if (maxNeili >= 0)
		{
			return;
		}
		NeiliAllocation newAllocation = baseNeiliAllocation;
		for (int type = 0; type < 4; type++)
		{
			if (newAllocation.Items[type] > 100)
			{
				newAllocation.Items[type] = 100;
			}
		}
		character.SetBaseNeiliAllocation(newAllocation, context);
		while (character.GetMaxNeili() < 0 || newAllocation.GetTotal() > maxTotalNeiliAllocation)
		{
			sbyte maxType = -1;
			int maxTypeValue = 0;
			for (sbyte type2 = 0; type2 < 4; type2++)
			{
				if (newAllocation.Items[type2] > maxTypeValue)
				{
					maxTypeValue = newAllocation.Items[type2];
					maxType = type2;
				}
			}
			if (maxType >= 0)
			{
				newAllocation.Items[maxType] = (short)(maxTypeValue - 1);
				character.SetBaseNeiliAllocation(newAllocation, context);
			}
		}
		Logger.Warn($"Fixing {character}'s abnormal base neili allocation: {baseNeiliAllocation} => {newAllocation}");
		Logger.Warn($"Fixing {character}'s abnormal max neili: {maxNeili} => {character.GetMaxNeili()}");
	}

