	private void FixAbnormalGroupState(DataContext context, Character character)
	{
		int charId = character.GetId();
		int leaderId = character.GetLeaderId();
		if (leaderId < 0 || (leaderId == DomainManager.Taiwu.GetTaiwuCharId() && DomainManager.Taiwu.IsInGroup(charId)) || _characterGroups.ContainsKey(leaderId))
		{
			return;
		}
		IReadOnlySet<int> specialGroup = DomainManager.Character.GetSpecialGroup(leaderId);
		if (!specialGroup.Contains(charId))
		{
			if (_joinGroupDates.ContainsKey(charId))
			{
				RemoveElement_JoinGroupDates(charId, context);
			}
			character.SetLeaderId(-1, context);
			Logger.Warn($"Fixing character {character}'s invalid group state with leader {leaderId}.");
		}
	}

	private unsafe void FixAbnormalInsectFeature(DataContext context, Character character)
	{
		List<short> featureIds = character.GetFeatureIds();
		if (featureIds.Contains(171))
		{
			int charId = character.GetId();
			RelatedCharacters relatedChars = GetRelatedCharacters(charId);
			int* actualBloodParents = stackalloc int[2];
			GetActualBloodParents(charId, relatedChars, actualBloodParents);
			int fatherId = actualBloodParents[1];
			int motherId = *actualBloodParents;
			if (fatherId >= 0 && motherId >= 0 && fatherId != motherId && !IsInsect(fatherId, motherId))
			{
				character.RemoveFeature(context, 171);
				Logger.Warn($"Removing character {character}'s abnormal insect feature.");
			}
		}
	}

	private void FixAbnormalFeature(DataContext context, Character character)
	{
		bool featureChanged = false;
		int charId = character.GetId();
		List<short> featureIds = character.GetFeatureIds();
		for (int i = featureIds.Count - 1; i >= 0; i--)
		{
			short featureId = featureIds[i];
			CharacterFeatureItem config = CharacterFeature.Instance[featureId];
			int date;
			if (config == null)
			{
				featureIds.RemoveAt(i);
				Logger.Warn($"Removing character {character}'s invalid feature {featureId}.");
				featureChanged = true;
			}
			else if (config.Duration > 0 && !TryGetTemporaryFeatureExpireDate(charId, featureId, out date) && character.GetCreatingType() == 1)
			{
				RegisterCharacterTemporaryFeature(context, charId, featureId);
				Logger.Warn($"Fixing character {character}'s feature {config.Name}'s expiring date.");
				featureChanged = true;
			}
		}
		if (featureChanged)
		{
			character.SetFeatureIds(featureIds, context);
		}
	}

	private void FixAbnormalCharacterLocation(DataContext context, Character character)
	{
		int charId = character.GetId();
		Location location = character.GetLocation();
		int leaderId = character.GetLeaderId();
		if (character.GetCreatingType() != 1 || character.IsActiveExternalRelationState(188uL))
		{
			return;
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		if (taiwuCharId == charId || character.GetKidnapperId() >= 0)
		{
			return;
		}
		if (location.IsValid())
		{
			MapBlockData block = DomainManager.Map.GetBlock(location);
			if (character.IsCompletelyInfected())
			{
				if (block.InfectedCharacterSet != null && block.InfectedCharacterSet.Contains(charId))
				{
					if (!block.IsPassable())
					{
						short edgeBlockId = DomainManager.Map.GetRandomEdgeBlock(context.Random, block.AreaId, (sbyte)context.Random.Next(4));
						GroupMove(context, character, new Location(location.AreaId, edgeBlockId));
						Logger.Warn($"Fixing character {character}'s not passable location {location}");
					}
					return;
				}
				if (DomainManager.Taiwu.IsInGroup(charId))
				{
					return;
				}
				block.AddInfectedCharacter(charId);
				DomainManager.Map.SetBlockData(context, block);
				Logger.Warn($"Fixing character {character}'s hidden state at {location}");
			}
			else
			{
				if (block.CharacterSet != null && block.CharacterSet.Contains(charId))
				{
					if (!block.IsPassable())
					{
						short edgeBlockId2 = DomainManager.Map.GetRandomEdgeBlock(context.Random, block.AreaId, (sbyte)context.Random.Next(4));
						GroupMove(context, character, new Location(location.AreaId, edgeBlockId2));
						Logger.Warn($"Fixing character {character}'s not passable location {location}");
					}
					return;
				}
				if (DomainManager.Taiwu.IsInGroup(charId))
				{
					return;
				}
				block.AddCharacter(charId);
				DomainManager.Map.SetBlockData(context, block);
				Logger.Warn($"Fixing character {character}'s hidden state at {location}");
			}
		}
		else if (character.IsCrossAreaTraveling() || leaderId == taiwuCharId)
		{
			return;
		}
		if (leaderId >= 0)
		{
			Location leaderLocation = _objects[leaderId].GetLocation();
			if (!leaderLocation.Equals(location))
			{
				Events.RaiseCharacterLocationChanged(context, charId, location, leaderLocation);
				character.SetLocation(leaderLocation, context);
				Logger.Warn($"Fixing character {character}'s location from {location} to {character.GetLocation()}");
			}
			else if (!leaderLocation.IsValid())
			{
				Location birthLocation = character.GetBirthLocation();
				Location targetLocation = (birthLocation.IsValid() ? birthLocation : DomainManager.Taiwu.GetTaiwuVillageLocation());
				GroupMove(context, character, targetLocation);
				Logger.Warn($"Fixing character {character}'s location from {location} to {character.GetLocation()}");
			}
		}
		else if (!location.IsValid())
		{
			Location birthLocation2 = character.GetBirthLocation();
			Location targetLocation2 = (birthLocation2.IsValid() ? birthLocation2 : DomainManager.Taiwu.GetTaiwuVillageLocation());
			if (character.IsCompletelyInfected())
			{
				Events.RaiseInfectedCharacterLocationChanged(context, charId, location, targetLocation2);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, charId, location, targetLocation2);
			}
			character.SetLocation(targetLocation2, context);
			Logger.Warn($"Fixing character {character}'s location from {location} to {character.GetLocation()}");
		}
	}

	private void FixMerchantCharToType(DataContext context, Character character)
	{
		int charId = character.GetId();
		OrganizationInfo organizationInfo = character.GetOrganizationInfo();
		OrganizationItem organizationConfig = Config.Organization.Instance[organizationInfo.OrgTemplateId];
		OrganizationMemberItem organizationMemberConfig = OrganizationDomain.GetOrgMemberConfig(organizationInfo);
		List<sbyte> identityInteractConfig = organizationMemberConfig.IdentityInteractConfig;
		sbyte type3;
		if (organizationConfig.IsCivilian && organizationInfo.Grade == 4 && identityInteractConfig != null && identityInteractConfig.Contains(4))
		{
			if (!DomainManager.Extra.TryGetMerchantCharToType(charId, out var _))
			{
				MerchantData merchantData;
				sbyte type2 = ((!DomainManager.Merchant.TryGetMerchantData(charId, out merchantData)) ? ((sbyte)context.Random.Next(7)) : merchantData.MerchantType);
				DomainManager.Extra.AddMerchantCharToType(charId, type2, context);
				Logger.Warn($"Fix abnormal merchant type for {character}: _ => {type2}.");
			}
		}
		else if (DomainManager.Extra.TryGetMerchantCharToType(charId, out type3))
		{
			VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(charId);
			if (!(villagerRole is VillagerRoleMerchant))
			{
				DomainManager.Extra.RemoveMerchantCharToType(charId, context);
				Logger.Warn($"Fix abnormal merchant type for {character}: {type3} => _");
			}
		}
	}

	[DataUpgrader(Version = "0.84.49", Date = "2026/06/09")]
	private void ResetPregeneratedRandomEnemies(DataContext context)
	{
		List<int> pregeneratedRandomEnemies = _pregeneratedRandomEnemies;
		if (pregeneratedRandomEnemies == null || pregeneratedRandomEnemies.Count <= 0)
		{
			return;
		}
		foreach (int pregeneratedRandomEnemy in _pregeneratedRandomEnemies)
		{
			if (_objects.TryGetValue(pregeneratedRandomEnemy, out var character))
			{
				RemoveNonIntelligentCharacter(context, character);
			}
		}
		_pregeneratedRandomEnemies.Clear();
		SetPregeneratedRandomEnemies(_pregeneratedRandomEnemies, context);
	}

