	[DomainMethod]
	public List<IntPair> SortCharacterListByMaxCombatSkill(List<int> managerList)
	{
		managerList.Sort((int l, int r) => _objects[l].GetMaxCombatSkillAttainment().CompareTo(_objects[r].GetMaxCombatSkillAttainment()));
		List<IntPair> managerCombatSkill = new List<IntPair>();
		for (int i = 0; i < managerList.Count; i++)
		{
			managerCombatSkill.Add(new IntPair(managerList[i], _objects[managerList[i]].GetMaxCombatSkillAttainment()));
		}
		return managerCombatSkill;
	}

	[DomainMethod]
	public (sbyte, short) GetCharacterMaxCombatSkillAttainment(int charId)
	{
		return _objects[charId].GetMaxCombatSkillAttainmentType();
	}

	[ElementListDependency(2, 68, 15)]
	[ObjectCollectionDependency(4, 0, new ushort[] { 83 }, Condition = InfluenceCondition.CharIsXiangshuInfectedDemon)]
	private OuterAndInnerInts CalcXiangshuInfectedDemonsPenetrationResistsBonus()
	{
		OuterAndInnerInts value = OuterAndInnerInts.Zero;
		for (int stateId = 0; stateId < 15; stateId++)
		{
			XiangshuInfectedDemonData demonData = DomainManager.Map.GetElement_StateXiangshuInfectedDemons(stateId);
			if (demonData != null && demonData.CharId >= 0 && DomainManager.Character.TryGetElement_Objects(demonData.CharId, out var character))
			{
				OuterAndInnerInts demonValue = character.GetPenetrationResists();
				value.Outer += demonValue.Outer * 20 / 100;
				value.Inner += demonValue.Inner * 20 / 100;
			}
		}
		return value;
	}

