	public sbyte SelectHarmfulActionType(DataContext context, Character selfChar, Character targetChar)
	{
		sbyte behaviorType = selfChar.GetBehaviorType();
		sbyte[] priorityList = AiHelper.PrioritizedActionConstants.TakeRevengeActionPriorities[behaviorType];
		sbyte selectedHarmType = -1;
		int targetCharId = targetChar.GetId();
		MainAttributes selfMainAttributes = selfChar.GetCurrMainAttributes();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		bool canTaiwuBeTarget = DomainManager.Taiwu.CanTaiwuBeSneakyHarmfulActionTarget();
		bool needToAvoidCombat = selfChar.NeedToAvoidCombat(CombatType.Die);
		sbyte[] array = priorityList;
		foreach (sbyte actionType in array)
		{
			if (actionType == 0)
			{
				if (needToAvoidCombat)
				{
					continue;
				}
			}
			else if (targetCharId == taiwuCharId && canTaiwuBeTarget)
			{
				continue;
			}
			sbyte mainAttributeType = AiHelper.HarmActionType.ToMainAttributeType(actionType);
			if (mainAttributeType < 0 || selfChar.GetCurrMainAttribute(mainAttributeType) >= GlobalConfig.Instance.HarmfulActionCost)
			{
				short rateAdjust = DomainManager.Character.GetAiActionRateAdjust(selfChar.GetId(), 5, actionType);
				int chance = 60 + AiHelper.HarmActionType.ToPersonalityType[actionType] + rateAdjust;
				if (context.Random.CheckPercentProb(chance))
				{
					selectedHarmType = actionType;
					break;
				}
			}
		}
		return selectedHarmType;
	}

	public bool HandleAttackAction(DataContext context, Character selfChar, Character targetChar)
	{
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int selfCharId = selfChar.GetId();
		int targetCharId = targetChar.GetId();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int selfLeaderId = selfChar.GetLeaderId();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = selfChar.GetLocation();
		if (selfCharId == taiwuCharId)
		{
			AiHelper.NpcCombatResultType resultType = SimulateCharacterCombat(context, selfChar, targetChar, CombatType.Beat, isGroupCombat: false);
			bool flag = (uint)resultType <= 1u;
			bool isVictory = flag;
			if (isVictory)
			{
				SimulateCharacterCombatResult(context, selfChar, targetChar, -2147483647, -2147483647, 100);
			}
			else
			{
				SimulateCharacterCombatResult(context, targetChar, selfChar, -2147483647, -2147483647, 100);
			}
			return isVictory;
		}
		if (selfLeaderId >= 0 && selfLeaderId == targetChar.GetLeaderId())
		{
			LeaveGroup(context, selfChar);
		}
		if (taiwuCharId == targetCharId)
		{
			AddLockMovementCharSet(selfCharId);
			MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
			if (selfChar.IsCompletelyInfected())
			{
				if (DomainManager.Character.IsAiActionInCooldown(selfCharId, 3, 1))
				{
					return false;
				}
				monthlyEventCollection.AddInfectedCharacterAttack(location, selfCharId);
				DomainManager.Character.AddAiActionCooldown(context, selfCharId, 3, 1, 3);
			}
			else if (DomainManager.LegendaryBook.IsCharacterActingCrazy(selfChar))
			{
				if (DomainManager.Character.IsAiActionInCooldown(selfCharId, 3, 2))
				{
					return false;
				}
				switch (selfChar.GetLegendaryBookOwnerState())
				{
				case 1:
					monthlyEventCollection.AddLegendaryBookShockedAttack(taiwuCharId, location, selfCharId);
					break;
				case 2:
					monthlyEventCollection.AddLegendaryBookInsaneAttack(taiwuCharId, location, selfCharId);
					break;
				case 3:
					monthlyEventCollection.AddLegendaryBookConsumedAttack(taiwuCharId, location, selfCharId);
					break;
				}
				DomainManager.Character.AddAiActionCooldown(context, selfCharId, 3, 2, 3);
			}
			else
			{
				if (DomainManager.Character.IsAiActionInCooldown(selfCharId, 3, 0))
				{
					return false;
				}
				monthlyEventCollection.AddRevengeAttack(targetCharId, location, selfCharId);
				DomainManager.Character.AddAiActionCooldown(context, selfCharId, 3, 0, 3);
			}
			return true;
		}
		if (location.Equals(taiwuChar.GetLocation()) && (targetChar.GetLeaderId() == taiwuCharId || (CheckRequestHelpFromTaiwu(context.Random, targetCharId, taiwuCharId) && CheckNeedProtection(targetChar, selfChar))) && !selfChar.IsCompletelyInfected() && !DomainManager.LegendaryBook.IsCharacterActingCrazy(selfChar))
		{
			MonthlyEventCollection monthlyEventCollection2 = DomainManager.World.GetMonthlyEventCollection();
			monthlyEventCollection2.AddAskProtectByRevengeAttack(targetCharId, location, selfCharId, taiwuCharId);
			return true;
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		if (blockData.CharacterSet != null)
		{
			foreach (int charId in blockData.CharacterSet)
			{
				if (charId == selfCharId)
				{
					continue;
				}
				Character protector = GetElement_Objects(charId);
				if (!protector.IsProtectingTarget(targetCharId) || protector.NeedToAvoidCombat(CombatType.Die) || DomainManager.LegendaryBook.IsCharacterActingCrazy(protector))
				{
					continue;
				}
				SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
				int secretInfoOffset = secretInformationCollection.AddOfferProtection(charId, targetCharId, selfCharId);
				SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
				if (IsTaiwuPeople(charId) || IsTaiwuPeople(targetCharId))
				{
					MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
					monthlyNotifications.AddProtectRelativeOrFriend(charId, targetCharId, selfCharId);
				}
				lifeRecordCollection.AddOfferProtection(charId, currDate, targetCharId, location);
				AiHelper.NpcCombatResultType result = SimulateCharacterCombat(context, selfChar, protector, CombatType.Die);
				if ((uint)result <= 1u)
				{
					SimulateCharacterCombatResult(context, selfChar, protector, 60, 60, 60);
					return true;
				}
				SimulateCharacterCombatResult(context, protector, selfChar, 60, 60, 60);
				return false;
			}
		}
		AiHelper.NpcCombatResultType result2 = SimulateCharacterCombat(context, selfChar, targetChar, CombatType.Die);
		if ((uint)result2 <= 1u)
		{
			SimulateCharacterCombatResult(context, selfChar, targetChar, 60, 60, 60);
			return true;
		}
		SimulateCharacterCombatResult(context, targetChar, selfChar, 60, 60, 60);
		return false;
	}

	public void ApplyPlotHarmActionEffect(DataContext context, Character selfChar, Character targetChar, ItemKey itemKey)
	{
		if (itemKey.ItemType == 12 && itemKey.TemplateId >= 482 && itemKey.TemplateId <= 483)
		{
			selfChar.SpecifyCurrNeili(context, 0);
			short attainment = selfChar.GetLifeSkillAttainment(8);
			int damage = CalcPlotHarmActionBaseDamage(attainment);
			targetChar.TakeDamageRandomParts(context, damage, itemKey.TemplateId == 482);
		}
		if (itemKey.IsValid())
		{
			selfChar.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
			ApplyMedicineEffectForPlotHarm(context, selfChar, itemKey);
		}
	}

	public bool HandlePlotHarmAction(DataContext context, Character selfChar, Character targetChar, ItemKey itemKey, sbyte actionPhase = -1)
	{
		int selfCharId = selfChar.GetId();
		int targetCharId = targetChar.GetId();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = selfChar.GetLocation();
		selfChar.ChangeCurrMainAttribute(context, 4, -GlobalConfig.Instance.HarmfulActionCost);
		if (actionPhase < 0)
		{
			actionPhase = selfChar.GetPlotHarmActionPhase(context.Random, targetChar);
		}
		if (actionPhase >= 4)
		{
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = secretInformationCollection.AddPlotHarmEnemy(selfCharId, targetCharId);
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
			ApplyPlotHarmActionEffect(context, selfChar, targetChar, itemKey);
		}
		switch (actionPhase)
		{
		case 0:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemyFail12(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemyFail1(selfCharId, currDate, targetCharId, location);
			}
			break;
		case 1:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemyFail22(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemyFail2(selfCharId, currDate, targetCharId, location);
			}
			break;
		case 2:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemyFail32(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemyFail3(selfCharId, currDate, targetCharId, location);
			}
			break;
		case 3:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemyFail42(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemyFail4(selfCharId, currDate, targetCharId, location);
			}
			break;
		case 4:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemySucceed2(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemySucceed(selfCharId, currDate, targetCharId, location);
			}
			if (selfCharId != taiwuCharId && targetCharId != taiwuCharId)
			{
				AiHelper.NpcCombatResultType result = SimulateCharacterCombat(context, selfChar, targetChar, CombatType.Die);
				if ((uint)result <= 1u)
				{
					SimulateCharacterCombatResult(context, selfChar, targetChar, 30, 50, 60);
				}
				else
				{
					SimulateCharacterCombatResult(context, targetChar, selfChar, 30, 50, 60);
				}
			}
			else if (DomainManager.World.GetAdvancingMonthState() != 0 && DomainManager.World.GetAdvancingMonthState() != 14)
			{
				if (targetCharId == taiwuCharId)
				{
					MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
					monthlyEventCollection.AddCatchEnemyPlotHarm(targetCharId, location, selfCharId);
				}
				else if (selfCharId == taiwuCharId)
				{
					AiHelper.NpcCombatResultType resultType = SimulateCharacterCombat(context, selfChar, targetChar, CombatType.Beat, isGroupCombat: false);
					if ((uint)resultType <= 1u)
					{
						SimulateCharacterCombatResult(context, selfChar, targetChar, -2147483647, -2147483647, 100);
					}
					else
					{
						SimulateCharacterCombatResult(context, targetChar, selfChar, -2147483647, -2147483647, 100);
					}
				}
			}
			return true;
		default:
			if (itemKey.IsValid())
			{
				lifeRecordCollection.AddPlotHarmEnemySucceedAndEscaped2(selfCharId, currDate, targetCharId, location, itemKey.ItemType, itemKey.TemplateId);
			}
			else
			{
				lifeRecordCollection.AddPlotHarmEnemySucceedAndEscaped(selfCharId, currDate, targetCharId, location);
			}
			if (targetCharId == taiwuCharId && DomainManager.World.GetAdvancingMonthState() != 0 && DomainManager.World.GetAdvancingMonthState() != 14)
			{
				MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
				monthlyNotificationCollection.AddPlotHarmEnemyEscaped(targetCharId, location, selfCharId);
			}
			return true;
		}
		return false;
	}

	public void ApplyPoisonActionEffect(DataContext context, Character selfChar, Character targetChar, ItemKey itemKey)
	{
		if (itemKey.ItemType == 12 && itemKey.TemplateId >= 476 && itemKey.TemplateId <= 481)
		{
			selfChar.SpecifyCurrNeili(context, 0);
			short attainment = selfChar.GetLifeSkillAttainment(9);
			(sbyte level, int amount) tuple = CalcPoisonActionBaseLevelAndAmount(attainment);
			sbyte level = tuple.level;
			int amount = tuple.amount;
			int poisonType = itemKey.TemplateId - 476;
			targetChar.ChangePoisoned(context, (sbyte)poisonType, level, amount);
		}
		if (itemKey.IsValid())
		{
			selfChar.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
			targetChar.AddEatingItem(context, itemKey);
		}
	}

