	private void UpdateAiActionCooldowns(DataContext context)
	{
		List<int> charIdList = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		charIdList.AddRange(_characterAiActionCooldowns.Keys);
		int currDate = DomainManager.World.GetCurrDate();
		foreach (int charId in charIdList)
		{
			AiExtraActionCooldowns cooldown = _characterAiActionCooldowns[charId];
			bool isChanged = false;
			foreach (var (action, offCooldownDate) in cooldown.OffCooldownDates)
			{
				if (offCooldownDate < currDate)
				{
					cooldown.OffCooldownDates.Remove(action);
					isChanged = true;
				}
			}
			if (cooldown.OffCooldownDates.Count == 0)
			{
				RemoveElement_CharacterAiActionCooldowns(charId, context);
			}
			else if (isChanged)
			{
				SetElement_CharacterAiActionCooldowns(charId, cooldown, context);
			}
		}
		context.AdvanceMonthRelatedData.CharIdList.Release(ref charIdList);
	}

