	public short GetAiActionSuccessRateAdjust(int charId, int targetId, sbyte actionType, sbyte actionSubType)
	{
		IntPair key = new IntPair(charId, targetId);
		short result = 0;
		if (targetId >= 0)
		{
			result += GetAiActionSuccessRateAdjust(charId, -1, actionType, actionSubType);
		}
		if (!_characterAiActionSuccessRateAdjusts.TryGetValue(key, out var restrictions))
		{
			return result;
		}
		AiActionKey actionKey = new AiActionKey(actionType, actionSubType);
		if (!restrictions.Collection.TryGetValue(actionKey, out (short, int) info))
		{
			return result;
		}
		return (short)(result + info.Item1);
	}

