	public void RaiseAlertnessChanged(DataContext context, int charId, int value)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		short maxFavor = CalcMaxFavorabilityToTaiwuById(charId);
		short curFavor = GetFavorability(charId, taiwuCharId);
		if (curFavor > maxFavor)
		{
			SetFavorability(context, charId, taiwuCharId, maxFavor);
		}
		CharacterAlertnessData oldAlertness;
		int oldValue = (TryGetElement_Alertness(charId, out oldAlertness) ? oldAlertness.Value : 0);
		InstantNotificationCollection instantNotificationCollection = DomainManager.World.GetInstantNotificationCollection();
		if (oldValue < value)
		{
			instantNotificationCollection.AddAlertnessUp(charId, taiwuCharId);
		}
		else if (oldValue > value)
		{
			instantNotificationCollection.AddAlertnessDown(charId, taiwuCharId);
		}
	}

	public void ChangeAlertness(DataContext context, int charId, int delta)
	{
		if (delta == 0)
		{
			return;
		}
		Character npcChar = GetElement_Objects(charId);
		if (npcChar.GetCreatingType() == 1)
		{
			if (!TryGetElement_Alertness(charId, out var alertnessData))
			{
				Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
				alertnessData = InitAlertnessData(context, npcChar, taiwuChar);
			}
			alertnessData.Value = CharacterAlertnessData.ClampValue(alertnessData.Value + delta);
			SetAlertness(context, charId, alertnessData);
			DomainManager.Global.InvokeGuidingTrigger(context, 254);
		}
	}

	public int CalcAlertnessChangeValue(int delta)
	{
		byte favorabilityChange = DomainManager.World.GetFavorabilityChange();
		short factor = WorldCreation.Instance[(byte)12].InfluenceFactors[favorabilityChange];
		int finalDelta = ((delta >= 0) ? (delta * (200 - factor) / 100) : (delta * (75 + factor) / 100));
		return CharacterAlertnessData.ClampChangeValue(finalDelta);
	}

	private CharacterAlertnessData InitAlertnessData(DataContext context, Character npcChar, Character taiwuChar)
	{
		sbyte taiwuBehaviorType = taiwuChar.GetBehaviorType();
		sbyte taiwuFameType = taiwuChar.GetFameType();
		sbyte worldProgressLevel = DomainManager.World.GetXiangshuLevel();
		sbyte npcBehaviorType = npcChar.GetBehaviorType();
		sbyte npcCharGrade = npcChar.GetOrganizationInfo().Grade;
		short settlementId = npcChar.GetOrganizationInfo().SettlementId;
		Settlement npcOrg = ((settlementId >= 0) ? DomainManager.Organization.GetSettlement(settlementId) : null);
		short npcSectApprovingRate = npcOrg?.CalcApprovingRate() ?? 0;
		sbyte npcOrgGoodness = npcOrg?.OrganizationConfig.Goodness ?? 0;
		bool npcOrgIsSect = npcOrg?.OrganizationConfig.IsSect ?? false;
		if (!TryGetElement_Alertness(npcChar.GetId(), out var alertnessData))
		{
			alertnessData = new CharacterAlertnessData();
		}
		int date = DomainManager.World.GetCurrDate();
		CharacterAlertnessData characterAlertnessData = alertnessData;
		if (characterAlertnessData.RecordCollection == null)
		{
			characterAlertnessData.RecordCollection = new CharacterAlertnessRecordCollection();
		}
		int baseEffect = context.Random.Next(GlobalConfig.Instance.InitialAlertnessBaseRandomRange.First(), GlobalConfig.Instance.InitialAlertnessBaseRandomRange.Last());
		int baseEffectFinal = CalcAlertnessChangeValue(baseEffect);
		alertnessData.RecordCollection.AddBase(date, baseEffectFinal);
		if (1 == 0)
		{
		}
		int num = npcBehaviorType switch
		{
			0 => GlobalConfig.Instance.InitialAlertnessForBehaviorTypeJust[taiwuBehaviorType], 
			1 => GlobalConfig.Instance.InitialAlertnessForBehaviorTypeKind[taiwuBehaviorType], 
			2 => GlobalConfig.Instance.InitialAlertnessForBehaviorTypeEven[taiwuBehaviorType], 
			3 => GlobalConfig.Instance.InitialAlertnessForBehaviorTypeRebel[taiwuBehaviorType], 
			4 => GlobalConfig.Instance.InitialAlertnessForBehaviorTypeEgoistic[taiwuBehaviorType], 
			_ => throw new ArgumentOutOfRangeException(), 
		};
		if (1 == 0)
		{
		}
		int behaviorEffect = num;
		int behaviorEffectFinal = CalcAlertnessChangeValue(behaviorEffect);
		alertnessData.RecordCollection.AddCharBehaviorType(date, behaviorEffectFinal);
		int[] array2;
		if (npcOrgIsSect)
		{
			if (1 == 0)
			{
			}
			int[] array = npcOrgGoodness switch
			{
				-1 => GlobalConfig.Instance.InitialAlertnessForTaiwuFameByEvilSect, 
				0 => GlobalConfig.Instance.InitialAlertnessForTaiwuFameByNeutralSect, 
				1 => GlobalConfig.Instance.InitialAlertnessForTaiwuFameByGoodSect, 
				_ => throw new ArgumentOutOfRangeException("npcOrgGoodness", npcOrgGoodness, null), 
			};
			if (1 == 0)
			{
			}
			array2 = array;
		}
		else
		{
			array2 = GlobalConfig.Instance.InitialAlertnessForTaiwuFameByCivilianSettlement;
		}
		int[] fameArray = array2;
		int fameEffect = fameArray.GetOrDefault((taiwuFameType == -2) ? 3 : taiwuFameType);
		int fameEffectFinal = CalcAlertnessChangeValue(fameEffect);
		alertnessData.RecordCollection.AddTaiwuFame(date, fameEffectFinal);
		int initialAlertness = baseEffectFinal + behaviorEffectFinal + fameEffectFinal;
		initialAlertness = CharacterAlertnessData.ClampValue(initialAlertness);
		if (DomainManager.World.IsChallengeModeEnabled(EChallengeModeImplement.MoreAlertness))
		{
			sbyte npcFameType = npcChar.GetFameType();
			bool flag = BehaviorType.IsConflicting(npcBehaviorType, taiwuBehaviorType);
			bool flag2 = npcBehaviorType == taiwuBehaviorType;
			if (1 == 0)
			{
			}
			num = (flag ? GlobalConfig.Instance.InitialAlertnessChallengeModeBehaviorConflict : ((!flag2) ? GlobalConfig.Instance.InitialAlertnessChallengeModeBehaviorDifferent : 0));
			if (1 == 0)
			{
			}
			int cBehaviour = num * GlobalConfig.Instance.InitialAlertnessChallengeModeFactorBase;
			if (cBehaviour != 0)
			{
				alertnessData.RecordCollection.AddChallengeBehavior(date, cBehaviour);
			}
			sbyte x = GetFameGroup(npcFameType);
			sbyte y = GetFameGroup(taiwuFameType);
			if (1 == 0)
			{
			}
			num = ((x != y) ? ((x != 3 && y != 3) ? GlobalConfig.Instance.InitialAlertnessChallengeModeFameConflict : GlobalConfig.Instance.InitialAlertnessChallengeModeFameDifferent) : 0);
			if (1 == 0)
			{
			}
			int cFame = num * GlobalConfig.Instance.InitialAlertnessChallengeModeFactorBase;
			if (cFame != 0)
			{
				alertnessData.RecordCollection.AddChallengeFame(date, cFame);
			}
			initialAlertness = CharacterAlertnessData.ClampValue(initialAlertness + cFame + cBehaviour);
		}
		alertnessData.Value = initialAlertness;
		SetElement_Alertness(npcChar.GetId(), alertnessData, context);
		RaiseAlertnessChanged(context, npcChar.GetId(), initialAlertness);
		return alertnessData;
		static sbyte GetFameGroup(sbyte fameType)
		{
			sbyte b = fameType;
			sbyte b2 = b;
			if (b2 > 3)
			{
				return 4;
			}
			if (b2 > -1)
			{
				if (b2 == 3)
				{
					return 3;
				}
				return 2;
			}
			if (b2 == -2)
			{
				return -2;
			}
			AdaptableLog.Warning($"fameType {fameType} is not valid, mark it as FameType.Invalid");
			return -1;
		}
	}

	public void ClearAndInitAlertness(DataContext context, Character newTaiwuChar)
	{
		ClearAlertness(context);
		int taiwuCharId = newTaiwuChar.GetId();
		foreach (KeyValuePair<RelationKey, RelatedCharacter> pair in _relations)
		{
			if (pair.Key.CharId != taiwuCharId && pair.Key.RelatedCharId != taiwuCharId)
			{
				continue;
			}
			int relatedCharId = ((pair.Key.CharId == taiwuCharId) ? pair.Key.RelatedCharId : pair.Key.CharId);
			if (IsCharacterAlive(relatedCharId))
			{
				Character npcChar = GetElement_Objects(relatedCharId);
				if (npcChar.GetCreatingType() == 1 && DomainManager.Extra.GetIsInteractedCharacter(relatedCharId))
				{
					InitAlertnessData(context, npcChar, newTaiwuChar);
				}
			}
		}
	}

	public void InitAlertnessOnLoad(DataContext content)
	{
		Dictionary<int, CharacterAlertnessData> alertness = _alertness;
		if (alertness == null || alertness.Count <= 0)
		{
			ClearAndInitAlertness(content, DomainManager.Taiwu.GetTaiwu());
		}
	}

	public void ClearAlertnessRecord(DataContext content)
	{
		foreach (int charId in _alertness.Keys)
		{
			CharacterAlertnessData alertness = GetElement_Alertness(charId);
			CharacterAlertnessRecordCollection recordCollection = alertness.RecordCollection;
			if (recordCollection != null && recordCollection.Count > 0)
			{
				alertness.RecordCollection.Clear();
				SetElement_Alertness(charId, alertness, content);
			}
		}
	}

	public void SetSubscriberOrder(DataContext context, int oldId, int newId, int artisanId)
	{
		if (oldId >= 0 && TryGetElement_SubscriberOrders(oldId, out var oldList))
		{
			oldList.Remove(artisanId);
			SetElement_SubscriberOrders(oldId, oldList, context);
		}
		if (TryGetElement_SubscriberOrders(newId, out var list))
		{
			if (!list.Contains(artisanId))
			{
				list.Add(artisanId);
				SetElement_SubscriberOrders(newId, list, context);
			}
		}
		else
		{
			list = default(CharacterList);
			list.Add(artisanId);
			AddElement_SubscriberOrders(newId, list, context);
		}
	}

	public void RemoveSubscriberOrder(DataContext context, int subscriberId, int artisanId)
	{
		if (subscriberId >= 0 && TryGetElement_SubscriberOrders(subscriberId, out var list))
		{
			list.Remove(artisanId);
			SetElement_SubscriberOrders(subscriberId, list, context);
		}
	}

