	public void AssassinationByJieqing(DataContext context)
	{
		MonthlyNotificationCollection monthlyNotification = DomainManager.World.GetMonthlyNotificationCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		if (!string.IsNullOrEmpty(_targetedForAssassination))
		{
			foreach (Character character in _objects.Values)
			{
				if (character.GetCreatingType() != 1 || IsTemporaryIntelligentCharacter(character.GetId()) || AgeGroup.GetAgeGroup(character.GetActualAge()) != 2)
				{
					continue;
				}
				(string surname, string givenName) realName = GetRealName(character);
				string surname = realName.surname;
				string givenName = realName.givenName;
				string fullName = LocalStringManager.FormatFullName(surname, givenName);
				if (_targetedForAssassination != fullName)
				{
					continue;
				}
				sbyte grade = character.GetOrganizationInfo().Grade;
				int chance = (character.IsActiveExternalRelationState(32uL) ? AdvancingMonthFormula.DefValue.JieqingAssassinatePrisonerChance.Calculate(grade) : AdvancingMonthFormula.DefValue.JieqingAssassinateChance.Calculate(grade));
				if (!context.Random.CheckPercentProb(chance))
				{
					continue;
				}
				if (character.GetId() == taiwuCharId)
				{
					DomainManager.World.SetTaiwuDying();
				}
				else
				{
					DomainManager.Character.MakeCharacterDead(context, character, 7);
				}
				SetTargetedForAssassination(string.Empty, context);
				break;
			}
		}
		if (!DomainManager.Taiwu.IsNormalInteractionUnlocked() || !DomainManager.Item.HasTrackedSpecialItems(12, 267))
		{
			return;
		}
		foreach (Character character2 in _objects.Values)
		{
			if (character2.GetCreatingType() != 1 || character2.GetId() == taiwuCharId || IsTemporaryIntelligentCharacter(character2.GetId()))
			{
				continue;
			}
			ItemKey wuyingItemKey = DomainManager.Item.GetWuYingFromCharacterInventory(character2);
			if (!wuyingItemKey.IsValid())
			{
				continue;
			}
			sbyte grade2 = character2.GetOrganizationInfo().Grade;
			int chance2 = (character2.IsActiveExternalRelationState(32uL) ? AdvancingMonthFormula.DefValue.JieqingAssassinatePrisonerChanceWuYing.Calculate(grade2) : AdvancingMonthFormula.DefValue.JieqingAssassinateChanceWuYing.Calculate(grade2));
			if (context.Random.CheckPercentProb(chance2))
			{
				ItemBase item = DomainManager.Item.GetBaseItem(wuyingItemKey);
				item.ChangeCurrDurability(context, -1);
				if (item.GetCurrDurability() <= 0)
				{
					character2.RemoveInventoryItem(context, wuyingItemKey, 1, deleteItem: true);
				}
				DomainManager.Character.MakeCharacterDead(context, character2, 8);
			}
		}
	}

	public void Test_AssassinationImplementations()
	{
		List<string> targets = new List<string> { "任我行", "古三通", "张无忌", "云襄" };
		List<Character> results = new List<Character>();
		Stopwatch stopwatch = new Stopwatch();
		results.Clear();
		stopwatch.Restart();
		foreach (Character character in _objects.Values)
		{
			var (surname, givenName) = GetRealName(character);
			if (targets.Contains(surname + givenName))
			{
				results.Add(character);
			}
		}
		Logger.Warn($"Time Cost with implementation 2 in ticks: {stopwatch.ElapsedTicks}");
		results.Clear();
		stopwatch.Restart();
		foreach (string target in targets)
		{
			FindIntelligentCharacters((Character character2) => CharacterMatchers.MatchRealName(character2, target), results);
		}
		Logger.Warn($"Time Cost with implementation 1 in ticks: {stopwatch.ElapsedTicks}");
		results.Clear();
		stopwatch.Restart();
		foreach (string target2 in targets)
		{
			MapCharacterFilter.ParallelFind((Character character2) => CharacterMatchers.MatchRealName(character2, target2), results, 0, 135);
		}
		Logger.Warn($"Time Cost with implementation 3 in ticks: {stopwatch.ElapsedTicks}");
	}

	[DomainMethod]
	public bool CharacterShaveAvatar(DataContext context, int cutterCharId, int shaveCharId, AvatarData shaveResult)
	{
		if (TryGetElement_Objects(cutterCharId, out var hairCutter) && TryGetElement_Objects(shaveCharId, out var shavedCharacter))
		{
			int currDate = DomainManager.World.GetCurrDate();
			Location location = shavedCharacter.GetLocation();
			LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
			AvatarData srcData = shavedCharacter.GetAvatar();
			bool hairInfoChanged = srcData.FrontHairId != shaveResult.FrontHairId || srcData.BackHairId != shaveResult.BackHairId || srcData.ColorFrontHairId != shaveResult.ColorFrontHairId || srcData.ColorBackHairId != shaveResult.ColorBackHairId;
			bool hairShaveBald = srcData.GetGrowableElementShowingState(0) != shaveResult.GetGrowableElementShowingState(0);
			bool beard1InfoChanged = srcData.Beard1Id != shaveResult.Beard1Id || srcData.ColorBeard1Id != shaveResult.ColorBeard1Id;
			bool beard1ShaveBald = srcData.GetGrowableElementShowingState(1) != shaveResult.GetGrowableElementShowingState(1);
			bool beard2InfoChanged = srcData.Beard2Id != shaveResult.Beard2Id || srcData.ColorBeard2Id != shaveResult.ColorBeard2Id;
			bool beard2ShaveBald = srcData.GetGrowableElementShowingState(2) != shaveResult.GetGrowableElementShowingState(2);
			bool eyebrowInfoChanged = srcData.EyebrowId != shaveResult.EyebrowId || srcData.EyebrowDistance != shaveResult.EyebrowDistance || srcData.EyebrowAngle != shaveResult.EyebrowAngle || srcData.EyebrowHeight != shaveResult.EyebrowHeight || srcData.EyebrowScale != shaveResult.EyebrowScale || srcData.ColorEyebrowId != shaveResult.ColorEyebrowId;
			bool eyebrowShaveBald = srcData.GetGrowableElementShowingState(6) != shaveResult.GetGrowableElementShowingState(6);
			int obb = 40 + hairCutter.GetLifeSkillAttainment(5) / 5;
			bool success = context.Random.CheckPercentProb(obb);
			if (!success)
			{
				bool hairSuccessState = hairShaveBald || !hairInfoChanged;
				bool beard1SuccessState = beard1ShaveBald || !beard1InfoChanged;
				bool beard2SuccessState = beard2ShaveBald || !beard2InfoChanged;
				bool eyebrowSuccessState = eyebrowShaveBald || !eyebrowInfoChanged;
				success = hairSuccessState && beard1SuccessState && beard2SuccessState && eyebrowSuccessState;
			}
			bool hairFailed = false;
			bool beardFailed = false;
			bool eyebrowFailed = false;
			if (success)
			{
				AvatarGroup avatarGroup = AvatarManager.Instance.GetAvatarGroup(srcData.AvatarId);
				if (beard1ShaveBald)
				{
					shaveResult.SetGrowableElementShowingState(1, show: false);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 1);
				}
				if (beard2ShaveBald)
				{
					shaveResult.SetGrowableElementShowingState(2, show: false);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 2);
				}
				if (eyebrowShaveBald)
				{
					shaveResult.SetGrowableElementShowingState(6, show: false);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 6);
				}
				short prevAttraction = shavedCharacter.GetAttraction();
				avatarGroup = AvatarManager.Instance.GetAvatarGroup(shaveResult.AvatarId);
				CheckShaveResult(avatarGroup, shaveResult, hairInfoChanged, beard1InfoChanged, beard2InfoChanged, eyebrowInfoChanged);
				shavedCharacter.SetAvatar(shaveResult, context);
				short attraction = shavedCharacter.GetAttraction();
				if (attraction >= prevAttraction)
				{
					shavedCharacter.AddFeature(context, 688, removeMutexFeature: true);
					DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, shavedCharacter, hairCutter, 3000);
					DomainManager.Character.ChangeAlertness(context, shaveCharId, -500);
					lifeRecordCollection.AddBarbSucceed(cutterCharId, currDate, shaveCharId, location);
					SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
					int secretInfoOffset = secretInformationCollection.AddRehaircutSuccess(cutterCharId, shaveCharId);
					DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
				}
				else
				{
					shavedCharacter.AddFeature(context, 689, removeMutexFeature: true);
					DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, shavedCharacter, hairCutter, -1500);
					DomainManager.Character.ChangeAlertness(context, shaveCharId, 200);
					lifeRecordCollection.AddBarbMistake(cutterCharId, currDate, shaveCharId, location);
					SecretInformationCollection secretInformationCollection2 = DomainManager.Information.GetSecretInformationCollection();
					int secretInfoOffset2 = secretInformationCollection2.AddRehaircutIncompleted(cutterCharId, shaveCharId);
					DomainManager.Information.AddSecretInformation(context, secretInfoOffset2);
				}
				DomainManager.TaiwuEvent.SetListenerEventActionBoolArg("CharacterShaveComplete", "ShaveAttraction", attraction >= prevAttraction);
			}
			else
			{
				shavedCharacter.AddFeature(context, 690, removeMutexFeature: true);
				DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, shavedCharacter, hairCutter, -6000);
				DomainManager.Character.ChangeAlertness(context, shaveCharId, 1000);
				lifeRecordCollection.AddBarbFail(cutterCharId, currDate, shaveCharId, location);
				SecretInformationCollection secretInformationCollection3 = DomainManager.Information.GetSecretInformationCollection();
				int secretInfoOffset3 = secretInformationCollection3.AddRehaircutFail(cutterCharId, shaveCharId);
				DomainManager.Information.AddSecretInformation(context, secretInfoOffset3);
				if (hairInfoChanged)
				{
					srcData.ResetGrowableElementShowingState(0);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 0);
					hairFailed = true;
				}
				if (beard1InfoChanged || beard2InfoChanged)
				{
					srcData.ResetGrowableElementShowingState(1);
					srcData.ResetGrowableElementShowingState(2);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 1);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 2);
					beardFailed = true;
				}
				if (eyebrowInfoChanged)
				{
					srcData.ResetGrowableElementShowingState(6);
					DomainManager.Character.InitializeAvatarElementGrowthProgress(context, shaveCharId, 6);
					eyebrowFailed = true;
				}
				shavedCharacter.SetAvatar(srcData, context);
				AchievementManager.RequestSetStat(context, 11, 1);
			}
			DomainManager.TaiwuEvent.SetListenerEventActionBoolArg("CharacterShaveComplete", "ShaveSuccess", success);
			if (!success)
			{
				if (hairFailed)
				{
					DomainManager.TaiwuEvent.SetListenerEventActionBoolArg("CharacterShaveComplete", "ShaveHairFailFlag", value: true);
				}
				if (beardFailed)
				{
					DomainManager.TaiwuEvent.SetListenerEventActionBoolArg("CharacterShaveComplete", "ShaveBeardFailFlag", value: true);
				}
				if (eyebrowFailed)
				{
					DomainManager.TaiwuEvent.SetListenerEventActionBoolArg("CharacterShaveComplete", "ShaveEyebrowFailFlag", value: true);
				}
				DomainManager.TaiwuEvent.TriggerListener("CharacterShaveComplete", value: true);
			}
			return success;
		}
		return false;
	}

