	{
		AvatarElementsGrownDates dates;
		bool existed = _avatarElementGrowthProgress.TryGetValue(charId, out dates);
		if (!existed)
		{
			dates.Initialize();
		}
		sbyte duration = GlobalConfig.Instance.AvatarElementGrowthDurations[elementType];
		dates.Items[elementType] = DomainManager.World.GetCurrDate() + duration;
