		else
		{
			AddElement_AvatarElementGrowthProgress(charId, ref dates, context);
		}
	}

	public void CreatePreexistenceCharactersForChallengeMode(DataContext context, Character character)
	{
		Span<sbyte> charTypes = stackalloc sbyte[9] { 0, 0, 0, 1, 1, 1, 2, 3, 4 };
		CollectionUtils.Shuffle(context.Random, charTypes, charTypes.Length);
		int latestDeathDate = character.GetBirthDate() - 12;
		List<Settlement> settlements = new List<Settlement>();
		DomainManager.Organization.GetAllCivilianSettlements(settlements);
		int count = Math.Min(9, charTypes.Length);
		List<int> charIds = new List<int>();
		for (int i = 0; i < count; i++)
		{
			switch (charTypes[i])
			{
			case 0:
			{
				sbyte orgTemplateId2 = (sbyte)context.Random.Next(1, 16);
				Settlement settlement2 = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId2);
				int charId5 = CreateDeadCharacterByFilterRule(context, 156, latestDeathDate, settlement2.GetLocation());
				latestDeathDate = _deadCharacters[charId5].BirthDate - 12;
				charIds.Add(charId5);
				break;
			}
			case 1:
			{
				int charId3 = DomainManager.Character.CreateDeadAnimal(context, latestDeathDate, 1);
				latestDeathDate = _deadCharacters[charId3].BirthDate - 12;
				charIds.Add(charId3);
				break;
			}
			case 2:
			{
				sbyte orgTemplateId = (sbyte)context.Random.Next(21, 36);
				Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
				int charId2 = CreateDeadCharacterByFilterRule(context, 156, latestDeathDate, settlement.GetLocation());
				latestDeathDate = _deadCharacters[charId2].BirthDate - 12;
				charIds.Add(charId2);
				break;
			}
			case 3:
			{
				Settlement town = settlements.Where((Settlement settlement3) => settlement3.GetOrgTemplateId() == 37).ToArray().GetRandom(context.Random);
				int charId4 = CreateDeadCharacterByFilterRule(context, 156, latestDeathDate, town.GetLocation());
				latestDeathDate = _deadCharacters[charId4].BirthDate - 12;
				charIds.Add(charId4);
				break;
			}
			case 4:
			{
				Settlement village = settlements.Where((Settlement settlement3) => settlement3.GetOrgTemplateId() == 36).ToArray().GetRandom(context.Random);
				int charId = CreateDeadCharacterByFilterRule(context, 156, latestDeathDate, village.GetLocation());
				latestDeathDate = _deadCharacters[charId].BirthDate - 12;
				charIds.Add(charId);
				break;
			}
			}
		}
		PreexistenceCharIds preexistenceCharacters = default(PreexistenceCharIds);
		preexistenceCharacters.Reset();
		preexistenceCharacters.Add(context.Random, charIds[charIds.Count - 1]);
		for (int i2 = charIds.Count - 2; i2 >= 0; i2--)
		{
			int charId6 = charIds[i2];
			_deadCharacters[charId6].PreexistenceCharIds = preexistenceCharacters;
			preexistenceCharacters.Add(context.Random, charId6);
		}
		character.OfflineSetPreexistenceCharId(context, charIds[0], ignoreBonusFeature: true);
	}

	private int CreateDeadCharacterByFilterRule(DataContext context, short charFilterRulesId, int deathDate, Location location)
	{
		Character tempChar = DomainManager.Character.CreateTemporaryIntelligentCharacter(context, charFilterRulesId, location);
		int charId = tempChar.GetId();
		DeadCharacter deadCharacter = DeadCharacterHelper.CreateDeadCharacter(tempChar, deathDate);
		deadCharacter.BirthDate = CalcBirthDate(deathDate, tempChar.GetActualAge(), tempChar.GetBirthMonth());
		AddElement_DeadCharacters(charId, deadCharacter, context);
		RemoveTemporaryIntelligentCharacter(context, tempChar);
		return charId;
	}

	private static int CalcBirthDate(int deathDate, int actualAge, int birthMonth)
	{
		int ageByMonth = actualAge * 12;
		int deathMonth = deathDate % 12;
		return deathDate - deathMonth - ageByMonth + birthMonth;
	}

	public int GetTopThousandCharacterRanking(int charId)
	{
		int index = _topThousandCharDescendingRanking.IndexOfValue(charId);
		if (index == -1)
		{
			return int.MaxValue;
		}
		return index + 1;
	}

	public void UpdateTopThousandCharRanking()
	{
		_topThousandCharDescendingRanking.Clear();
		List<Settlement> settlements = new List<Settlement>();
		DomainManager.Organization.GetAllSettlements(settlements);
		foreach (Settlement settlement in settlements)
		{
			for (int ranking = 1; ranking <= 1000; ranking++)
			{
				long rankingInfo = settlement.GetRankingInfo(ranking);
				if (rankingInfo == 0)
				{
					break;
				}
				int charId = (int)(rankingInfo & 0xFFFFFFFFu);
				_topThousandCharDescendingRanking.Add(rankingInfo, charId);
				if (_topThousandCharDescendingRanking.Count > 1000)
				{
					long last = _topThousandCharDescendingRanking.Keys[1000];
					_topThousandCharDescendingRanking.RemoveAt(1000);
					if (last == rankingInfo)
					{
						break;
					}
				}
			}
		}
	}

	public static bool TryRemoveCombatSkillFromAttainmentPanel(DataContext context, Character character, short targetSkillTemplateId)
	{
		short[] panels = character.GetCombatSkillAttainmentPanels();
		CombatSkillItem targetCfg = Config.CombatSkill.Instance[targetSkillTemplateId];
		sbyte targetType = targetCfg.Type;
		sbyte targetGrade = targetCfg.Grade;
		if (CombatSkillAttainmentPanelsHelper.Get(panels, targetType, targetGrade) != targetSkillTemplateId)
		{
			return false;
		}
		short currSkillTemplateId = GetEligibleCombatSkillOfAttainmentPanel(character.GetId(), targetType, targetGrade);
		CombatSkillAttainmentPanelsHelper.Set(panels, targetType, targetGrade, currSkillTemplateId);
		character.SetCombatSkillAttainmentPanels(panels, context);
		return true;
	}

	private static short GetEligibleCombatSkillOfAttainmentPanel(int charId, sbyte combatSkillType, sbyte grade)
	{
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> charCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charId);
		foreach (KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> item in charCombatSkills)
		{
			item.Deconstruct(out var key, out var value);
			short skillTemplateId = key;
			GameData.Domains.CombatSkill.CombatSkill skill = value;
			CombatSkillItem skillConfig = Config.CombatSkill.Instance[skillTemplateId];
			if (skillConfig.Type != combatSkillType || skillConfig.Grade != grade || !skill.CanBreakout())
			{
				continue;
			}
			return skillTemplateId;
		}
		return -1;
	}

	public void TryAutoEquipCombatSkillOnAttainmentPanel(DataContext context, int charId, short skillTemplateId)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return;
		}
		CombatSkillItem skillConfig = Config.CombatSkill.Instance[skillTemplateId];
		short[] panels = character.GetCombatSkillAttainmentPanels();
		if (CombatSkillAttainmentPanelsHelper.Get(panels, skillConfig.Type, skillConfig.Grade) < 0)
		{
			CombatSkillKey combatSkillKey = new CombatSkillKey(charId, skillTemplateId);
			if (DomainManager.CombatSkill.TryGetElement_CombatSkills(combatSkillKey, out var skill) && CombatSkillStateHelper.CanEquipOnAttainmentPanel(skill.GetReadingState(), skill.GetRevoked()))
			{
				CombatSkillAttainmentPanelsHelper.Set(panels, skillConfig.Type, skillConfig.Grade, skillTemplateId);
				character.SetCombatSkillAttainmentPanels(panels, context);
			}
		}
	}

	public void BackfillCombatSkillAttainmentPanelsForCharacter(DataContext context, int charId)
	{
		if (!TryGetElement_Objects(charId, out var _))
		{
			return;
		}
		foreach (var (skillTemplateId, _) in DomainManager.CombatSkill.GetCharCombatSkills(charId))
		{
			TryAutoEquipCombatSkillOnAttainmentPanel(context, charId, skillTemplateId);
		}
	}

