	[DomainMethod]
	public AllocateNeiliPreviewDisplayData PreviewAllocateNeili(DataContext context, int charId, byte neiliAllocationType, bool isAdd)
	{
		Character character = GetElement_Objects(charId);
		NeiliAllocation oriBaseAllocation = character.GetBaseNeiliAllocation();
		int oriCurrNeili = character.GetCurrNeili();
		bool success = ((!isAdd) ? character.DeallocateNeili(context, neiliAllocationType) : character.AllocateNeili(context, neiliAllocationType));
		AllocateNeiliPreviewDisplayData result = new AllocateNeiliPreviewDisplayData();
		if (!success)
		{
			result.PropertyDeltas = new Dictionary<short, int>();
			return result;
		}
		CharacterAttributeDisplayData afterAttributes = GetCharacterAttributeDisplayData(charId);
		character.SetBaseNeiliAllocation(oriBaseAllocation, context);
		character.SpecifyCurrNeili(context, oriCurrNeili);
		CharacterAttributeDisplayData beforeAttributes = GetCharacterAttributeDisplayData(charId);
		result.PropertyDeltas = CalcPropertyDeltas(beforeAttributes, afterAttributes);
		return result;
	}

	private unsafe static Dictionary<short, int> CalcPropertyDeltas(CharacterAttributeDisplayData before, CharacterAttributeDisplayData after)
	{
		Dictionary<short, int> deltas = new Dictionary<short, int>(AllocateNeiliPreviewDisplayData.PreviewPropertyKeys.Length);
		for (sbyte i = 0; i < 4; i++)
		{
			short key = (short)(6 + i);
			deltas[key] = after.AtkHitAttribute.Items[i] - before.AtkHitAttribute.Items[i];
		}
		deltas[10] = after.AtkPenetrability.Outer - before.AtkPenetrability.Outer;
		deltas[11] = after.AtkPenetrability.Inner - before.AtkPenetrability.Inner;
		for (sbyte i2 = 0; i2 < 4; i2++)
		{
			short key2 = (short)(12 + i2);
			deltas[key2] = after.DefHitAttribute.Items[i2] - before.DefHitAttribute.Items[i2];
		}
		deltas[16] = after.DefPenetrability.Outer - before.DefPenetrability.Outer;
		deltas[17] = after.DefPenetrability.Inner - before.DefPenetrability.Inner;
		deltas[18] = after.RecoveryOfStanceAndBreath.Outer - before.RecoveryOfStanceAndBreath.Outer;
		deltas[19] = after.RecoveryOfStanceAndBreath.Inner - before.RecoveryOfStanceAndBreath.Inner;
		deltas[20] = after.MoveSpeed - before.MoveSpeed;
		deltas[21] = after.RecoveryOfFlaw - before.RecoveryOfFlaw;
		deltas[22] = after.CastSpeed - before.CastSpeed;
		deltas[23] = after.RecoveryOfBlockedAcupoint - before.RecoveryOfBlockedAcupoint;
		deltas[24] = after.WeaponSwitchSpeed - before.WeaponSwitchSpeed;
		deltas[25] = after.AttackSpeed - before.AttackSpeed;
		deltas[26] = after.InnerRatio - before.InnerRatio;
		deltas[27] = after.RecoveryOfQiDisorder - before.RecoveryOfQiDisorder;
		deltas[28] = after.PoisonResists.Items[0] - before.PoisonResists.Items[0];
		deltas[29] = after.PoisonResists.Items[1] - before.PoisonResists.Items[1];
		deltas[30] = after.PoisonResists.Items[2] - before.PoisonResists.Items[2];
		deltas[31] = after.PoisonResists.Items[3] - before.PoisonResists.Items[3];
		deltas[32] = after.PoisonResists.Items[4] - before.PoisonResists.Items[4];
		deltas[33] = after.PoisonResists.Items[5] - before.PoisonResists.Items[5];
		return deltas;
	}

