	[DomainMethod]
	public int GetAddConsummateLevelRequiredMonth(int charId)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return int.MaxValue;
		}
		sbyte consummateLevel = character.GetConsummateLevel();
		if (consummateLevel >= character.GetMaxConsummateLevel())
		{
			return int.MaxValue;
		}
		int progress = DomainManager.Extra.GetCharacterConsummateLevelProgress(charId);
		int speed = GlobalConfig.Instance.ConsummateLevelProgressSpeed[character.GetOrganizationInfo().Grade];
		int threshold = GlobalConfig.Instance.ConsummateLevelProgressThreshold[consummateLevel];
		int i = 0;
		do
		{
			progress += speed;
			i++;
		}
		while (progress < threshold);
		return i;
	}

	public bool TransferAvoidDeathCharInjuries(DataContext context, Character loser)
	{
		int avoidDeathCharId = GetAvoidDeathCharId();
		if (avoidDeathCharId < 0)
		{
			return false;
		}
		DivineFlameData divineFlameData = DomainManager.Story.GetDivineFlameData();
		if (divineFlameData.IsUnlocked)
		{
			if (DomainManager.World.IsXiangshuAvatarTaskStatusesGood(5))
			{
				if (loser.GetId() == avoidDeathCharId)
				{
					return TransferAvoidDeathCharInjuries(context, loser.GetId());
				}
			}
			else
			{
				if (!loser.IsInteractableAsIntelligentCharacter())
				{
					return false;
				}
				List<int> charIdList = new List<int>();
				DomainManager.Story.GetDivineFlameSelectTargetCharactersInRange(context, loser.GetValidLocation(), charIdList, 2, includeTaiwu: false);
				if (charIdList.Contains(avoidDeathCharId))
				{
					return TransferAvoidDeathCharInjuries(context, loser.GetId(), avoidDeathCharId);
				}
			}
		}
		else if (loser.GetId() == avoidDeathCharId)
		{
			return TransferAvoidDeathCharInjuries(context);
		}
		return false;
	}

	public unsafe void SimulateCharacterCombatResult(DataContext context, Character winner, Character loser, int killBaseChance, int kidnapBaseChance, int releaseBaseChance)
	{
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Location winnerLocation = winner.GetLocation();
		if (!winnerLocation.IsValid())
		{
			winnerLocation = winner.GetValidLocation();
		}
		int defeatMarks = CombatDomain.GetDefeatMarksCountOutOfCombat(loser);
		int escapeChance = (30 - defeatMarks) * 100 / 30;
		bool isCompletelyInfected = loser.IsCompletelyInfected();
		bool loserAvoidDeath = TransferAvoidDeathCharInjuries(context, loser);
		int winnerLeaderId = winner.GetLeaderId();
		int loserLeaderId = loser.GetLeaderId();
		if (winnerLeaderId >= 0 && winnerLeaderId == loserLeaderId)
		{
			if (loserLeaderId == loser.GetId())
			{
				DomainManager.Character.LeaveGroup(context, winner);
			}
			else
			{
				DomainManager.Character.LeaveGroup(context, loser);
			}
		}
		if (isCompletelyInfected || context.Random.CheckPercentProb(escapeChance))
		{
			lifeRecordCollection.AddEnemyEscape(winner.GetId(), currDate, loser.GetId(), winnerLocation);
			if (loser.GetLocation().IsValid())
			{
				EscapeToRandomNearbyBlock(context, loser);
			}
			return;
		}
		if (loser.GetAgeGroup() == 2)
		{
			Personalities personalities = winner.GetPersonalities();
			sbyte behaviorType = winner.GetBehaviorType();
			AiHelper.CombatResultHandleType[] priorities = AiHelper.NpcCombat.ResultHandleTypePriorities[behaviorType];
			for (int i = 0; i < 3; i++)
			{
				switch (priorities[i])
				{
				case AiHelper.CombatResultHandleType.Kill:
				{
					if (!context.Random.CheckPercentProb(killBaseChance + personalities.Items[3]) || loserAvoidDeath)
					{
						break;
					}
					short privateRateAdjust = DomainManager.Character.GetAiActionRateAdjust(winner.GetId(), 7, -1);
					int publicChance = AiHelper.NpcCombat.HandleEnemyInPublicChance[behaviorType] - privateRateAdjust;
					CombatResultHandle_KillEnemy(context, winner, loser, context.Random.CheckPercentProb(publicChance));
					return;
				}
				case AiHelper.CombatResultHandleType.Kidnap:
					if (context.Random.CheckPercentProb(kidnapBaseChance + personalities.Items[1]))
					{
						short privateRateAdjust2 = DomainManager.Character.GetAiActionRateAdjust(winner.GetId(), 8, -1);
						int publicChance2 = AiHelper.NpcCombat.HandleEnemyInPublicChance[behaviorType] - privateRateAdjust2;
						CombatResultHandle_KidnapEnemy(context, winner, loser, context.Random.CheckPercentProb(publicChance2));
						return;
					}
					break;
				case AiHelper.CombatResultHandleType.Release:
					if (context.Random.CheckPercentProb(releaseBaseChance + personalities.Items[0]))
					{
						CombatResultHandle_ReleaseEnemy(context, winner, loser);
						return;
					}
					break;
				}
			}
		}
		CombatResultHandle_ReleaseEnemy(context, winner, loser);
	}

	public void CombatResultHandle_KillEnemy(DataContext context, Character winner, Character loser, bool isInPublic)
	{
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int winnerId = winner.GetId();
		int loserId = loser.GetId();
		CharacterDeathInfo characterDeathInfo = new CharacterDeathInfo(loser.GetValidLocation());
		characterDeathInfo.KillerId = winnerId;
		CharacterDeathInfo deathInfo = characterDeathInfo;
		if (isInPublic)
		{
			lifeRecordCollection.AddKillInPublic(winnerId, currDate, loserId, deathInfo.Location);
			MakeCharacterDead(context, loser, 4, deathInfo);
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = secretInformationCollection.AddKillInPublic(winnerId, loserId);
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
		}
		else
		{
			lifeRecordCollection.AddKillInPrivate(winnerId, currDate, loserId, deathInfo.Location);
			MakeCharacterDead(context, loser, 3, deathInfo);
			SecretInformationCollection secretInformationCollection2 = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset2 = secretInformationCollection2.AddKillInPrivate(winnerId, loserId);
			SecretInformationId secretInfoId2 = DomainManager.Information.AddSecretInformation(context, secretInfoOffset2);
		}
	}

	public void CombatResultHandle_KidnapEnemy(DataContext context, Character winner, Character loser, bool isInPublic)
	{
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = winner.GetLocation();
		int winnerId = winner.GetId();
		int loserId = loser.GetId();
		if (IsTaiwuPeople(winnerId))
		{
			MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
			monthlyNotificationCollection.AddDisappear(loserId, location);
		}
		ItemKey rope = winner.GetInventoryRope(context, winner.GetOrganizationInfo().Grade);
		AddKidnappedCharacter(context, winner, loser, rope);
		if (isInPublic)
		{
			lifeRecordCollection.AddKidnapInPublic(winnerId, currDate, loserId, location, rope.ItemType, rope.TemplateId);
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = ((DomainManager.Organization.GetFugitiveBountySect(loserId) >= 0) ? secretInformationCollection.AddKidnapForPunishment(winnerId, loserId) : secretInformationCollection.AddKidnapInPublic(winnerId, loserId));
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
		}
		else
		{
			lifeRecordCollection.AddKidnapInPrivate(winnerId, currDate, loserId, location, rope.ItemType, rope.TemplateId);
			SecretInformationCollection secretInformationCollection2 = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset2 = secretInformationCollection2.AddKidnapInPrivate(winnerId, loserId);
			SecretInformationId secretInfoId2 = DomainManager.Information.AddSecretInformation(context, secretInfoOffset2);
		}
	}

	public void CombatResultHandle_ReleaseEnemy(DataContext context, Character winner, Character loser)
	{
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = winner.GetLocation();
		if (!location.IsValid())
		{
			location = winner.GetValidLocation();
		}
		EscapeToRandomNearbyBlock(context, loser);
		lifeRecordCollection.AddReleaseLoser(winner.GetId(), currDate, loser.GetId(), location);
	}

