	public void GetTaiwuCombatEnemyTeam(DataContext context, Character targetChar, CombatType combatType, List<int> enemyList)
	{
		List<Character> enemyTeam = ObjectPool<List<Character>>.Instance.Get();
		enemyTeam.Clear();
		if (combatType == CombatType.Beat || combatType == CombatType.Die)
		{
			int targetLeader = targetChar.GetLeaderId();
			if (targetLeader >= 0)
			{
				AddGroupCharactersToCombatTeam(targetChar.GetId(), targetLeader, enemyTeam, combatType);
			}
			AddGuardsToCombatTeam(context, targetChar, enemyTeam, createRealGuard: true);
			GetStrongestThreeAndSelf(targetChar, enemyTeam);
			enemyTeam.Sort((Character a, Character b) => -a.GetCombatPower().CompareTo(b.GetCombatPower()));
		}
		else
		{
			enemyTeam.Add(targetChar);
		}
		foreach (Character character in enemyTeam)
		{
			enemyList.Add(character.GetId());
		}
		ObjectPool<List<Character>>.Instance.Return(enemyTeam);
	}

	public List<int> GetIntelligentNpcCombatTeam(DataContext context, Character targetChar, CombatType combatType, bool exceptGroupChar)
	{
		List<Character> enemyTeam = ObjectPool<List<Character>>.Instance.Get();
		enemyTeam.Clear();
		if ((uint)(combatType - 1) <= 1u)
		{
			int targetLeader = targetChar.GetLeaderId();
			if (targetLeader >= 0 && !exceptGroupChar)
			{
				AddGroupCharactersToCombatTeam(targetChar.GetId(), targetLeader, enemyTeam, combatType);
			}
			AddGuardsToCombatTeam(context, targetChar, enemyTeam, createRealGuard: true);
			GetStrongestThreeAndSelf(targetChar, enemyTeam);
			enemyTeam.Sort((Character a, Character b) => -a.GetCombatPower().CompareTo(b.GetCombatPower()));
		}
		else
		{
			enemyTeam.Add(targetChar);
		}
		List<int> result = enemyTeam.Select((Character x) => x.GetId()).ToList();
		ObjectPool<List<Character>>.Instance.Return(enemyTeam);
		return result;
	}

	public List<int> GetNonIntelligentNpcCombatTeam(DataContext context, Character targetChar)
	{
		List<int> result = new List<int> { targetChar.GetId() };
		CharacterItem config = Config.Character.Instance[targetChar.GetTemplateId()];
		short minionGroupId = config.MinionGroupId;
		if (DomainManager.World.IsChallengeModeEnabled(EChallengeModeImplement.XiangshuMinion) && config.ChallengeModeMinionGroupId >= 0)
		{
			minionGroupId = config.ChallengeModeMinionGroupId;
		}
		if (minionGroupId < 0)
		{
			return result;
		}
		MinionGroupItem minionGroup = MinionGroup.Instance[minionGroupId];
		foreach (short templateId in minionGroup.Minions)
		{
			result.Add(CreateNonIntelligentCharacter(context, templateId));
		}
		return result;
	}

