	internal AiHelper.NpcCombatResultType SimulateEnemyAttackWithEnemyChar(DataContext context, short enemyTemplateId, Character attackedChar, out Character enemyChar)
	{
		CharacterItem enemyConfig = Config.Character.Instance[enemyTemplateId];
		byte creatingType = enemyConfig.CreatingType;
		if (1 == 0)
		{
		}
		Character character = creatingType switch
		{
			2 => (enemyConfig.RandomEnemyId < 0) ? null : GetPregeneratedRandomEnemy(enemyConfig.RandomEnemyId), 
			3 => DomainManager.Character.GetPregeneratedFixedEnemy(enemyConfig.TemplateId), 
			_ => null, 
		};
		if (1 == 0)
		{
		}
		enemyChar = character;
		if (enemyChar == null)
		{
			Logger.AppendWarning($"{attackedChar.GetId()} is attacked by enemy {enemyConfig.Surname}{enemyConfig.GivenName}({enemyConfig.TemplateId}) without valid config.");
			return AiHelper.NpcCombatResultType.MajorDefeat;
		}
		return SimulateCharacterCombat(context, enemyChar, attackedChar, CombatType.Beat);
	}

