	private void AddGuardsToCombatTeam(DataContext context, Character character, List<Character> team, bool createRealGuard = false)
	{
		if (!HasGuard(character.GetId(), character))
		{
			return;
		}
		Span<short> span = stackalloc short[3];
		SpanList<short> guardTemplateIds = span;
		GetGuards(context, character, ref guardTemplateIds);
		if (createRealGuard)
		{
			SpanList<short>.Enumerator enumerator = guardTemplateIds.GetEnumerator();
			while (enumerator.MoveNext())
			{
				short templateId = enumerator.Current;
				Character randomEnemy = CreateRandomEnemy(context, templateId, isTemporary: true);
				CompleteCreatingCharacter(randomEnemy.GetId());
				team.Add(randomEnemy);
			}
		}
		else
		{
			SpanList<short>.Enumerator enumerator2 = guardTemplateIds.GetEnumerator();
			while (enumerator2.MoveNext())
			{
				short templateId2 = enumerator2.Current;
				short randomEnemyTemplateId = Config.Character.Instance[templateId2].RandomEnemyId;
				team.Add(GetPregeneratedRandomEnemy(randomEnemyTemplateId));
			}
		}
	}

	private void GetStrongestThreeAndSelf(Character character, List<Character> team)
	{
		team.Sort((Character a, Character b) => -a.GetCombatPower().CompareTo(b.GetCombatPower()));
		if (team.Count > 3)
		{
			team.RemoveRange(3, team.Count - 3);
		}
		team.Add(character);
	}

	private void SelectBestScoreCombatSkillsInTeam(List<Character> team, List<GameData.Domains.CombatSkill.CombatSkill> combatSkills, int amountToSelect)
	{
		combatSkills.Clear();
		foreach (Character character in team)
		{
			ArraySegmentList<short> attackSkills = character.GetCombatSkillEquipment().Attack;
			Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> charCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(character.GetId());
			ArraySegmentList<short>.Enumerator enumerator2 = attackSkills.GetEnumerator();
			while (enumerator2.MoveNext())
			{
				short combatSkillTemplateId = enumerator2.Current;
				if (combatSkillTemplateId >= 0)
				{
					combatSkills.Add(charCombatSkills[combatSkillTemplateId]);
				}
			}
		}
		combatSkills.Sort((GameData.Domains.CombatSkill.CombatSkill a, GameData.Domains.CombatSkill.CombatSkill b) => -a.GetBaseScore().CompareTo(b.GetBaseScore()));
		if (combatSkills.Count > amountToSelect)
		{
			combatSkills.RemoveRange(amountToSelect, combatSkills.Count - amountToSelect);
		}
	}

