	public void RemoveNonIntelligentCharacter(DataContext context, Character character)
	{
		Tester.Assert(character.GetCreatingType() != 1);
		int charId = character.GetId();
		Events.RaiseNonIntelligentCharacterRemoved(context, character);
		RemoveElement_Objects(charId);
		RemoveAllRelations(context, charId, removeRelatedRelations: true);
		switch (character.GetCreatingType())
		{
		case 0:
		{
			short charTemplateId = character.GetTemplateId();
			DomainManager.Extra.RemoveInteractedCharacter(context, charId);
			_fixedCharactersCache.Remove(charTemplateId);
			switch (charTemplateId)
			{
			case 205:
				_tripleAdoreLocation = Location.Invalid;
				break;
			case 207:
				SetForceKindLocation(Location.Invalid, context);
				break;
			case 156:
			case 157:
			case 158:
			case 159:
			case 160:
			case 161:
			case 162:
			case 163:
			case 164:
				_tripleHateLocation = Location.Invalid;
				break;
			case 174:
			case 175:
			case 176:
			case 177:
			case 178:
			case 179:
			case 180:
			case 181:
			case 182:
				SetForceRebelLocation(Location.Invalid, context);
				break;
			}
			if (TwelveImmortalsConstants.JiaoCharacterToPoisonTypes.ContainsKey(charTemplateId) || TwelveImmortalsConstants.MirrorCharacters.Contains(charTemplateId))
			{
				InvalidateTwelveImmortalsMoveCostCache(context);
			}
			break;
		}
		case 2:
		{
			if (_skeletonCharacterCache.TryGetValue(charId, out var graveId))
			{
				_skeletonCharacterCache.Remove(charId);
				_graves[graveId].SetSkeletonCharId(-1, context);
			}
			break;
		}
		}
		if (character.GetFeatureIds().Contains(880) || character.GetFeatureIds().Contains(861))
		{
			InvalidateTwelveImmortalsMoveCostCache(context);
		}
		RemoveAllItemsBeforeRemovingCharacter(context, character);
	}

	public void RemoveTemporaryIntelligentCharacter(DataContext context, Character character)
	{
		Tester.Assert(character.GetCreatingType() == 1);
		Tester.Assert(IsTemporaryIntelligentCharacter(character.GetId()));
		int charId = character.GetId();
		RemoveElement_Objects(charId);
		Tester.Assert(!_pregnantStates.ContainsKey(charId));
		Tester.Assert(character.GetKidnapperId() < 0);
		Tester.Assert(!_kidnappedChars.ContainsKey(charId));
		RemoveAllRelations(context, charId, removeRelatedRelations: true);
		DomainManager.Extra.RemoveInteractedCharacter(context, charId);
		if (_avatarElementGrowthProgress.ContainsKey(charId))
		{
			RemoveElement_AvatarElementGrowthProgress(charId, context);
		}
		RemoveInfectedCharFromSet(charId);
		Events.RaiseTemporaryIntelligentCharacterRemoved(context, character);
		RemoveAllItemsBeforeRemovingCharacter(context, character);
		UnregisterTemporaryIntelligentCharacter(charId);
	}

