	public static short GetCharacterTemplateIdInGroup(short groupId, sbyte consummateLevel)
	{
		Tester.Assert(groupId >= 0);
		CharacterItem groupBeginTemplate = Config.Character.Instance[groupId];
		CharacterItem groupSecondTemplate = Config.Character.Instance[groupId + 1];
		if (groupSecondTemplate.GroupId != groupId)
		{
			return groupId;
		}
		if (groupSecondTemplate.ConsummateLevel > groupBeginTemplate.ConsummateLevel)
		{
			CharacterItem currTemplate = groupBeginTemplate;
			CharacterItem prevTemplate = currTemplate;
			while (currTemplate != null && currTemplate.GroupId == groupId)
			{
				if (currTemplate.ConsummateLevel >= consummateLevel)
				{
					return currTemplate.TemplateId;
				}
				prevTemplate = currTemplate;
				currTemplate = Config.Character.Instance[prevTemplate.TemplateId + 1];
			}
			return prevTemplate.TemplateId;
		}
		CharacterItem currTemplate2 = groupBeginTemplate;
		CharacterItem prevTemplate2 = currTemplate2;
		while (currTemplate2 != null && currTemplate2.GroupId == groupId)
		{
			if (currTemplate2.ConsummateLevel < consummateLevel)
			{
				return prevTemplate2.TemplateId;
			}
			prevTemplate2 = currTemplate2;
			currTemplate2 = Config.Character.Instance[prevTemplate2.TemplateId + 1];
		}
		return prevTemplate2.TemplateId;
	}

	public static int GetLivedMonths(short age, sbyte birthMonth)
	{
		int monthsAfterBirthday = DomainManager.World.GetCurrMonthInYear() - birthMonth;
		if (monthsAfterBirthday < 0)
		{
			monthsAfterBirthday += 12;
		}
		return age * 12 + monthsAfterBirthday;
	}

	public static int CalcEscapeSuccessRate(sbyte consummateLevelA, sbyte consummateLevelB)
	{
		return Math.Clamp((consummateLevelA - consummateLevelB + 2) * 25, 0, 100);
	}

	public static int CalcBirthDate(short age, sbyte birthMonth)
	{
		if (age >= 0)
		{
			return DomainManager.World.GetCurrDate() - GetLivedMonths(age, birthMonth);
		}
		return -393216 + birthMonth;
	}

	public static (short year, sbyte month) CalcBirthYearAndMonth(int birthDate)
	{
		int birthYear = ((birthDate >= 0) ? (birthDate / 12) : ((birthDate - 11) / 12));
		int birthMonth = birthDate - birthYear * 12;
		return (year: (short)birthYear, month: (sbyte)birthMonth);
	}

	public static short CalcAge(int birthDate)
	{
		int currDate = DomainManager.World.GetCurrDate();
		int age = (currDate - birthDate) / 12;
		return (short)((age >= 32767) ? (-1) : ((short)age));
	}

