	[DomainMethod]
	public ActionPlanningDisplayData GetActionPlanningDsiplayData(int charId)
	{
		ActionPlanningData oriData = GetActionPlanningData(charId);
		Character character = GetElement_Objects(charId);
		int currDate = DomainManager.World.GetCurrDate();
		ActionPlanningDisplayData data = new ActionPlanningDisplayData();
		data.BehaviorType = character?.GetBehaviorType() ?? (-1);
		List<CharacterGoalData> goals = oriData.Goals;
		if (goals != null && goals.Count > 0)
		{
			data.Goals = new List<CharacterGoalDisplayData>();
			foreach (CharacterGoalData goal in oriData.Goals)
			{
				if (goal != null && !goal.Template.HideInUI && goal.State != CharacterGoalData.EGoalState.Achieved)
				{
					data.Goals.Add(ToCharacterGoalDisplayData(goal, currDate, int.MinValue, 0));
				}
			}
		}
		if (oriData.Missions != null)
		{
			for (int i = 0; i < oriData.Missions.Length; i++)
			{
				CharacterMissionData mission = oriData.Missions[i];
				if (mission == null || mission.MissionTemplateId < 0)
				{
					continue;
				}
				CharacterMissionItem missionTemplate = mission.Template;
				if (missionTemplate.IsHidden)
				{
					continue;
				}
				int remainMonth = 0;
				bool isSuccess = mission.IsComplete;
				bool isFail = !isSuccess && mission.IsTimeout;
				bool isInProgress = !isSuccess && !isFail;
				remainMonth = ((!isInProgress) ? ((mission.EndDate != int.MinValue) ? (mission.EndDate + missionTemplate.KeepDuration - currDate) : (mission.StartDate + missionTemplate.Duration + missionTemplate.KeepDuration - currDate)) : (mission.StartDate + missionTemplate.Duration - currDate));
				if (isInProgress || remainMonth > 0)
				{
					data.Missions[i] = ToCharacterMissionDisplayData(mission, currDate, remainMonth);
					if (data.Missions[i] != null)
					{
						data.Missions[i].IsComplete = mission.IsComplete;
						data.Missions[i].IsTimeout = mission.IsTimeout;
					}
				}
			}
		}
		return data;
	}

	private CharacterGoalDisplayData ToCharacterGoalDisplayData(CharacterGoalData goal, int currDate, int missionEndDate = int.MinValue, sbyte missionKeepDuration = 0)
	{
		CharacterGoalDisplayData data = ToCharacterGoalDisplayDataSimple(goal);
		data.RemainMonth = goal.RemainingMonths;
		return data;
	}

	private CharacterGoalDisplayData ToCharacterGoalDisplayDataSimple(CharacterGoalData goal)
	{
		PlanningGoalItem goalTemplate = goal.Template;
		return new CharacterGoalDisplayData
		{
			GoalTemplateId = goal.GoalTemplateId,
			CreateDate = goal.CreateDate,
			Priority = goalTemplate.BasePriority + goal.PriorityDelta,
			Finished = (goal.State == CharacterGoalData.EGoalState.Achieved),
			ParameterContent = FormatGoalParameterContent(goal)
		};
	}

	private static string FormatGoalParameterContent(CharacterGoalData goal)
	{
		PlanningGoalItem template = goal.Template;
		sbyte[] parameters = template.Parameters;
		if (parameters == null || parameters.Length <= 0)
		{
			return string.Empty;
		}
		PlanningContextArg[] contextArgs = goal.ContextArgs;
		if (contextArgs == null || contextArgs.Length <= 0)
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder();
		bool ignoreSymbolFlag = false;
		int validAmount = 0;
		for (int i = 0; i < template.Parameters.Length && i < goal.ContextArgs.Length; i++)
		{
			sbyte parameterTypeId = template.Parameters[i];
			EPlanningParameterType parameterType = PlanningParameter.Instance[parameterTypeId].Type;
			if (PlanningParameter.Instance[parameterTypeId].HideInUI)
			{
				continue;
			}
			string strContent;
			if (parameterType == EPlanningParameterType.Item)
			{
				ItemBase tempItem = DomainManager.Item.TryGetBaseItem(goal.Args.ItemType, goal.Args.ItemId);
				strContent = ((tempItem == null) ? string.Empty : ItemTemplateHelper.GetName(goal.Args.ItemType, tempItem.GetTemplateId()));
			}
			else if (parameterType == EPlanningParameterType.CombatSkillType && template.TemplateId == 267)
			{
				ignoreSymbolFlag = true;
				strContent = "  " + Config.Misc.Instance[Config.CombatSkillType.Instance[goal.Args.CombatSkillType].LegendaryBookTemplateId].Name;
			}
			else if (parameterType == EPlanningParameterType.Character && template.TemplateId == 264)
			{
				DeadCharacter deadChar = DomainManager.Character.TryGetDeadCharacter(goal.Args.TargetCharId);
				if (deadChar == null)
				{
					strContent = string.Empty;
				}
				else
				{
					(string, string) name = DomainManager.Character.GetRealName(goal.Args.TargetCharId);
					strContent = $"{deadChar.OrganizationInfo}-{name.Item1}{name.Item2}";
				}
			}
			else
			{
				switch (parameterType)
				{
				case EPlanningParameterType.Character:
				{
					DomainManager.Character.TryGetElement_Objects(goal.Args.TargetCharId, out var character);
					if (character == null)
					{
						strContent = string.Empty;
						break;
					}
					(string, string) name2 = GetRealName(character);
					strContent = $"{character.GetOrganizationInfo()}-{name2.Item1}{name2.Item2}";
					break;
				}
				case EPlanningParameterType.Adventure:
					strContent = goal.Args.ArgToString(parameterType, goal.ContextArgs[i]);
					if (strContent == "-1")
					{
						strContent = string.Empty;
					}
					break;
				default:
					strContent = goal.Args.ArgToString(parameterType, goal.ContextArgs[i]);
					break;
				}
			}
			if (validAmount > 0 && !ignoreSymbolFlag)
			{
				stringBuilder.Append(',');
			}
			ignoreSymbolFlag = false;
			if (parameterType == EPlanningParameterType.ItemType)
			{
				ignoreSymbolFlag = true;
				strContent = "[" + strContent + "]";
			}
			stringBuilder.Append(strContent);
			validAmount++;
		}
		return stringBuilder.ToString();
	}

	private CharacterMissionDisplayData ToCharacterMissionDisplayData(CharacterMissionData mission, int currDate, int remainMonth)
	{
		CharacterMissionItem missionTemplate = mission.Template;
		CharacterMissionDisplayData displayData = new CharacterMissionDisplayData
		{
			MissionTemplateId = mission.MissionTemplateId,
			EndDate = mission.EndDate,
			RemainMonth = remainMonth
		};
		List<CharacterGoalData> goals = mission.Goals;
		if (goals != null && goals.Count > 0)
		{
			foreach (CharacterGoalData goal in mission.Goals)
			{
				if (goal != null && !goal.Template.HideInUI && goal.State != CharacterGoalData.EGoalState.Achieved)
				{
					displayData.Goals.Add(ToCharacterGoalDisplayData(goal, currDate, mission.EndDate, missionTemplate.KeepDuration));
				}
			}
		}
		if (displayData.Goals.Count == 0)
		{
			return null;
		}
		return displayData;
	}

	private int CalcGoalRemainMonth(CharacterGoalData goal, int currDate, PlanningGoalItem goalTemplate)
	{
		return goalTemplate.Duration - (currDate - goal.CreateDate);
	}

	public void ParallelCreateNewbornChildren(DataContext context, Character mother, bool isDystocia, bool isMotherDead)
	{
		IRandomSource random = context.Random;
		CreateNewBornChildrenModification mod = new CreateNewBornChildrenModification();
		mod.IsDystocia = isDystocia;
		mod.IsMotherDead = isMotherDead;
		int motherId = mother.GetId();
		PregnantState pregnantState = GetElement_PregnantStates(motherId);
		int fatherId = pregnantState.FatherId;
		Character father = null;
		DeadCharacter deadFather = null;
		Genome virtualFatherGenome = default(Genome);
		if (fatherId < 0 || (!TryGetElement_Objects(fatherId, out father) && !TryGetElement_DeadCharacters(fatherId, out deadFather)))
		{
			Genome.CreateRandom(random, ref virtualFatherGenome);
			fatherId = -1;
		}
		Location motherLocation = mother.GetLocation();
		if (!motherLocation.IsValid())
		{
			motherLocation = mother.GetValidLocation();
		}
		sbyte stateId = DomainManager.Map.GetStateIdByAreaId(motherLocation.AreaId);
		pregnantState.CreateMotherRelation = pregnantState.CreateMotherRelation && mother.OrgAndMonkTypeAllowMarriage();
		bool createNominalMotherRelation = pregnantState.CreateMotherRelation;
		bool createNominalFatherRelation;
		if (pregnantState.CreateFatherRelation && fatherId >= 0)
		{
			bool orgAndMonkTypeAllowMarriage = father?.OrgAndMonkTypeAllowMarriage() ?? deadFather.OrgAndMonkTypeAllowMarriage();
			int spouseId = DomainManager.Character.GetAliveSpouse(fatherId);
