	public void HandleNotAbandonedNewbornChildRelationsAndGroup(DataContext context, Character baby, int motherCharId, int fatherCharId, int actualFatherId, bool createMotherRelation, bool createFatherRelation, bool isMotherAlive, bool isFatherAlive)
	{
		int childCharId = baby.GetId();
		Location childLocation = baby.GetLocation();
		SetBloodRelatedRelations(context, childCharId, motherCharId, fatherCharId, actualFatherId, createMotherRelation, createFatherRelation);
		DomainManager.Organization.JoinOrganization(context, baby, baby.GetOrganizationInfo(), charIsCreating: true);
		if (createMotherRelation && isMotherAlive && _objects.TryGetValue(motherCharId, out var mother) && mother.GetKidnapperId() < 0 && !mother.IsCompletelyInfected() && !mother.IsActiveExternalRelationState(32uL))
		{
			Location targetLocation = mother.GetLocation();
			if (!childLocation.Equals(targetLocation))
			{
				Events.RaiseCharacterLocationChanged(context, childCharId, childLocation, targetLocation);
				baby.SetLocation(targetLocation, context);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, childCharId, Location.Invalid, targetLocation);
			}
			if (DomainManager.Taiwu.IsInGroup(mother.GetId()))
			{
				DomainManager.Taiwu.JoinGroup(context, childCharId, showNotification: false);
			}
			else
			{
				JoinGroup(context, baby, mother);
			}
			return;
		}
		if (createFatherRelation && isFatherAlive && _objects.TryGetValue(fatherCharId, out var father) && father.GetKidnapperId() < 0 && !father.IsCompletelyInfected() && !father.IsActiveExternalRelationState(32uL))
		{
			Location targetLocation2 = father.GetLocation();
			if (!childLocation.Equals(targetLocation2))
			{
				Events.RaiseCharacterLocationChanged(context, childCharId, childLocation, targetLocation2);
				baby.SetLocation(targetLocation2, context);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, childCharId, Location.Invalid, targetLocation2);
			}
			if (DomainManager.Taiwu.IsInGroup(father.GetId()))
			{
				DomainManager.Taiwu.JoinGroup(context, childCharId, showNotification: false);
			}
			else
			{
				JoinGroup(context, baby, father);
			}
			return;
		}
		int aliveMentorId = GetAliveMentor(childCharId);
		if (aliveMentorId < 0)
		{
			throw new Exception($"newborn child {childCharId}(child of {motherCharId} and {fatherCharId}) is not abandoned but has nowhere to go.");
		}
		Character aliveMentor = _objects[aliveMentorId];
		Location targetLocation3 = aliveMentor.GetLocation();
		if (!childLocation.Equals(targetLocation3))
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, childLocation, targetLocation3);
			baby.SetLocation(targetLocation3, context);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, Location.Invalid, targetLocation3);
		}
		if (DomainManager.Taiwu.IsInGroup(aliveMentorId))
		{
			DomainManager.Taiwu.JoinGroup(context, childCharId);
		}
		else
		{
			JoinGroup(context, baby, aliveMentor);
		}
	}

	public void AbandonNewbornChild(DataContext context, Character baby, Character assignedAdopter, int motherCharId, int fatherCharId)
	{
		int childCharId = baby.GetId();
		if (_objects.TryGetValue(motherCharId, out var mother))
		{
			mother.ChangeHappiness(context, AiHelper.UpdateStatusConstants.LostChildHappinessChange[mother.GetBehaviorType()]);
			baby.AddGoal(context, 249, (ushort)64);
		}
		SetBloodRelatedRelations(context, childCharId, motherCharId, fatherCharId, -1, createMotherRelation: false, createFatherRelation: false);
		if (assignedAdopter != null)
		{
			if (assignedAdopter.GetId() != DomainManager.Taiwu.GetTaiwuCharId() && assignedAdopter.GetOrganizationInfo().OrgTemplateId == 16)
			{
				AddPotentialAdopterToInfant(childCharId, assignedAdopter.GetId());
				DomainManager.World.GetMonthlyEventCollection().AddTaiwuVillagerAdoptOrphan(assignedAdopter.GetId(), childCharId, motherCharId);
			}
			else
			{
				AssignChildToAdopter(context, assignedAdopter, baby, motherCharId);
			}
			return;
		}
		int aliveMentorId = DomainManager.Character.GetAliveMentor(childCharId);
		if (aliveMentorId >= 0 && DomainManager.Character.TryGetElement_Objects(aliveMentorId, out var mentor) && mentor.IsInteractableAsIntelligentCharacter())
		{
			DomainManager.Character.AssignChildToMentor(context, mentor, baby, motherCharId);
			return;
		}
		OrganizationInfo orgInfo = DomainManager.Character.GetAliveOrgDeadCharacterOrgInfo(motherCharId);
		int adopterId = DomainManager.Character.SelectRandomAdopter(context.Random, baby, orgInfo.OrgTemplateId);
		TryGetElement_Objects(adopterId, out assignedAdopter);
		if (assignedAdopter == null)
		{
			AbandonToNearbySettlement(context, baby, motherCharId);
		}
		else if (assignedAdopter.GetOrganizationInfo().OrgTemplateId == 16 && DomainManager.Taiwu.GetTaiwu().GetOrganizationInfo().OrgTemplateId == 16)
		{
			AddPotentialAdopterToInfant(childCharId, assignedAdopter.GetId());
			DomainManager.World.GetMonthlyEventCollection().AddTaiwuVillagerAdoptOrphan(assignedAdopter.GetId(), childCharId, motherCharId);
		}
		else
		{
			AssignChildToAdopter(context, assignedAdopter, baby, motherCharId);
		}
	}

	internal void AbandonToNearbySettlement(DataContext context, Character baby, int motherCharId, bool nearTaiwuVillage = false)
	{
		MapDomain map = DomainManager.Map;
		Location obj = (nearTaiwuVillage ? DomainManager.Taiwu.GetTaiwuVillageLocation() : baby.GetLocation());
		sbyte stateId = map.GetStateIdByAreaId(obj.AreaId);
		List<short> settlementIds = ObjectPool<List<short>>.Instance.Get();
		DomainManager.Map.GetStateSettlementIds(stateId, settlementIds);
		settlementIds.RemoveAll((short x) => x == DomainManager.Taiwu.GetTaiwuVillageSettlementId());
		short randomSettlementId = (short)((settlementIds.Count == 0) ? (-1) : settlementIds.GetRandom(context.Random));
		ObjectPool<List<short>>.Instance.Return(settlementIds);
		AbandonToNearbySettlement(context, baby, motherCharId, randomSettlementId);
	}

	internal void AbandonToNearbySettlement(DataContext context, Character baby, int motherCharId, short settlementId)
	{
		AddInfant(baby.GetId());
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		OrganizationInfo destOrgInfo = new OrganizationInfo(settlement.GetOrgTemplateId(), 0, principal: true, settlementId);
		baby.SetOrganizationInfo(destOrgInfo, context);
		Events.RaiseCharacterLocationChanged(context, baby.GetId(), baby.GetLocation(), settlement.GetLocation());
		baby.SetLocation(settlement.GetLocation(), context);
		DomainManager.Organization.JoinOrganization(context, baby, destOrgInfo, charIsCreating: true);
		lifeRecordCollection.AddAbandonChild(motherCharId, currDate, baby.GetId(), settlementId);
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int secretInfoOffset = secretInformationCollection.AddAbandonChild(motherCharId, baby.GetId());
		DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
	}

	private int SelectRandomAdopter(IRandomSource random, Character abandonedChild, sbyte motherOrgTemplateId)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(4))
		{
			return -1;
		}
		List<sbyte> orgTemplateIds = Config.Organization.Instance[motherOrgTemplateId].AbandonedBabyOrganizations;
		sbyte orgTemplateId = (sbyte)((orgTemplateIds.Count > 0) ? orgTemplateIds[random.Next(orgTemplateIds.Count)] : (random.CheckPercentProb(GlobalConfig.Instance.AbandonBabyToTaiwuVillageChance) ? 16 : OrganizationDomain.GetRandomSectOrgTemplateId(random, abandonedChild.GetGender())));
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
		int adopterId = GetRandomValidAdopterInSettlement(random, settlement);
		if (adopterId < 0)
		{
			settlement = DomainManager.Organization.GetSettlement(DomainManager.Taiwu.GetTaiwuVillageSettlementId());
			adopterId = GetRandomValidAdopterInSettlement(random, settlement);
		}
		return adopterId;
	}

	internal void AssignChildToAdopter(DataContext context, Character adopter, Character adoptedChild, int motherCharId)
	{
		int currDate = DomainManager.World.GetCurrDate();
		int adopterId = adopter.GetId();
		OrganizationInfo adopterOrgInfo = adopter.GetOrganizationInfo();
		int childCharId = adoptedChild.GetId();
		if (adopterOrgInfo.SettlementId != adoptedChild.GetOrganizationInfo().SettlementId)
		{
			OrganizationInfo childOrgInfo = new OrganizationInfo(adopterOrgInfo.OrgTemplateId, DomainManager.Organization.GetChildGrade(context.Random, OrganizationDomain.GetOrgMemberConfig(adopterOrgInfo).ChildGrade, adopterOrgInfo.SettlementId), principal: true, adopterOrgInfo.SettlementId);
			adoptedChild.SetOrganizationInfo(childOrgInfo, context);
			DomainManager.Organization.JoinOrganization(context, adoptedChild, childOrgInfo, charIsCreating: true);
		}
		else
		{
			DomainManager.Organization.JoinOrganization(context, adoptedChild, adoptedChild.GetOrganizationInfo(), charIsCreating: true);
		}
		FullName newName = GenerateRandomChildName(context, adoptedChild.GetGender(), adopter.GetFullName());
		adoptedChild.SetFullName(newName, context);
		Location adopterLocation = adopter.GetLocation();
		if (!adopterLocation.Equals(adoptedChild.GetLocation()))
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, adoptedChild.GetLocation(), adopterLocation);
			adoptedChild.SetLocation(adopterLocation, context);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, Location.Invalid, adopterLocation);
		}
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		lifeRecordCollection.AddAbandonChild(motherCharId, currDate, childCharId, adoptedChild.GetOrganizationInfo().SettlementId);
		short relatedId = (short)((adopter?.GetGender() == 1) ? 46 : 47);
		if (adoptedChild.GetGender() == 1)
		{
			lifeRecordCollection.AddAdoptSon(adopterId, currDate, childCharId, adopterLocation, relatedId);
		}
		else
		{
			lifeRecordCollection.AddAdoptDaughter(adopterId, currDate, childCharId, adopterLocation, relatedId);
		}
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int secretInfoOffset = secretInformationCollection.AddAbandonChild(motherCharId, childCharId);
		DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
		AddAdoptiveParentRelations(context, childCharId, adopterId, currDate);
		int spouseId = DomainManager.Character.GetAliveSpouse(adopterId);
		if (spouseId >= 0)
		{
			DomainManager.Character.AddAdoptiveParentRelations(context, childCharId, spouseId, currDate);
		}
		if (DomainManager.Taiwu.IsInGroup(adopter.GetId()))
		{
			DomainManager.Taiwu.JoinGroup(context, childCharId);
		}
		else
		{
			JoinGroup(context, adoptedChild, adopter);
		}
	}

	private void AssignChildToMentor(DataContext context, Character mentor, Character child, int motherCharId)
	{
		int currDate = DomainManager.World.GetCurrDate();
		int childCharId = child.GetId();
		Location mentorLocation = mentor.GetLocation();
		Location selfLocation = child.GetLocation();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		lifeRecordCollection.AddAbandonChild(motherCharId, currDate, childCharId, child.GetOrganizationInfo().SettlementId);
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int secretInfoOffset = secretInformationCollection.AddAbandonChild(motherCharId, childCharId);
		DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
		if (!mentorLocation.Equals(selfLocation))
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, selfLocation, mentorLocation);
			child.SetLocation(mentorLocation, context);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, childCharId, Location.Invalid, mentorLocation);
		}
		DomainManager.Organization.JoinOrganization(context, child, child.GetOrganizationInfo(), charIsCreating: true);
		JoinGroup(context, child, mentor);
	}

	public unsafe override void PackCrossArchiveGameData(CrossArchiveGameData crossArchiveGameData)
	{
		crossArchiveGameData.NextObjectId = _nextObjectId;
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = taiwuChar.GetId();
		crossArchiveGameData.TaiwuChar = taiwuChar;
		crossArchiveGameData.DreamBackTaiwuAbridged = GetAbridgeCharacter(taiwuCharId);
		crossArchiveGameData.TaiwuResources = taiwuChar.GetResources();
		crossArchiveGameData.TaiwuExp = taiwuChar.GetExp();
		crossArchiveGameData.FuyuFaith = GetFuyuFaith();
		crossArchiveGameData.ProfessionFeatures = new List<short>();
		List<short> features = taiwuChar.GetFeatureIds();
		for (int index = features.Count - 1; index >= 0; index--)
		{
			short featureId = features[index];
			CharacterFeatureItem config = CharacterFeature.Instance[featureId];
			if (config.MutexGroupId == 252)
			{
				features.RemoveAt(index);
				crossArchiveGameData.ProfessionFeatures.Add(featureId);
			}
		}
		HashSet<int> relatedCharIds = new HashSet<int>();
		GetAllRelatedCharIds(taiwuCharId, relatedCharIds);
		crossArchiveGameData.AbridgedCharacters = new Dictionary<int, AbridgedCharacter>();
		foreach (int relatedCharId in relatedCharIds)
		{
			PackAbridgedCharacter(crossArchiveGameData, relatedCharId);
		}
		Genealogy genealogy = GetGenealogy(taiwuCharId);
		PackAbridgedCharacter(crossArchiveGameData, genealogy.GrandfatherId);
		PackAbridgedCharacter(crossArchiveGameData, genealogy.GrandmotherId);
		PackAbridgedCharacter(crossArchiveGameData, genealogy.MaternalGrandfatherId);
		PackAbridgedCharacter(crossArchiveGameData, genealogy.MaternalGrandmotherId);
		foreach (SpouseAndChildren spouse in genealogy.Spouses)
		{
			PackSpouseAndChildren(spouse);
		}
		crossArchiveGameData.Genealogy = genealogy;
		crossArchiveGameData.PreexistenceDeadCharacters = new Dictionary<int, DeadCharacter>();
		PreexistenceCharIds preexistenceCharIds = taiwuChar.GetPreexistenceCharIds();
		int i = 0;
		for (int count = preexistenceCharIds.Count; i < count; i++)
		{
			int preCharId = preexistenceCharIds.CharIds[i];
			DeadCharacter preChar = DomainManager.Character.TryGetDeadCharacter(preCharId);
			if (preChar != null)
			{
				crossArchiveGameData.PreexistenceDeadCharacters.Add(preCharId, preChar);
			}
		}
		ItemKey[] equipments = taiwuChar.GetEquipment();
		ItemKey[] array = equipments;
		for (int j = 0; j < array.Length; j++)
		{
			ItemKey equipmentKey = array[j];
			if (equipmentKey.IsValid())
			{
				DomainManager.Item.PackCrossArchiveItem(crossArchiveGameData, equipmentKey);
			}
		}
		Inventory inventory = taiwuChar.GetInventory();
		foreach (ItemKey itemKey in inventory.Items.Keys)
		{
			DomainManager.Item.PackCrossArchiveItem(crossArchiveGameData, itemKey);
		}
		crossArchiveGameData.CharacterTemporaryFeatures = _characterTemporaryFeatures;
		void PackSpouseAndChildren(SpouseAndChildren spouseAndChildren)
		{
			PackAbridgedCharacter(crossArchiveGameData, spouseAndChildren.SpouseCharId);
			if (spouseAndChildren.Children != null)
			{
				foreach (CharIdAndRelation child in spouseAndChildren.Children)
				{
					PackAbridgedCharacter(crossArchiveGameData, child.CharId);
				}
			}
			if (spouseAndChildren.BloodChildrenSpouses != null)
			{
				foreach (SpousesAndChildren bloodChildSpouse in spouseAndChildren.BloodChildrenSpouses)
				{
					PackSpousesAndChildren(bloodChildSpouse);
				}
			}
		}
		void PackSpousesAndChildren(SpousesAndChildren spousesAndChildren)
		{
			PackAbridgedCharacter(crossArchiveGameData, spousesAndChildren.CoreCharId);
			if (spousesAndChildren.Spouses != null)
			{
				foreach (SpouseAndChildren spouse2 in spousesAndChildren.Spouses)
				{
					PackSpouseAndChildren(spouse2);
				}
			}
		}
	}

	public unsafe override void UnpackCrossArchiveGameData(DataContext context, CrossArchiveGameData crossArchiveGameData)
	{
		_nextObjectId = Math.Max(crossArchiveGameData.NextObjectId, _nextObjectId);
		SetNextObjectId(_nextObjectId, context);
		SetFuyuFaith(crossArchiveGameData.FuyuFaith, context);
		DomainManager.Extra.SaveOverwrittenTaiwu(context);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Character character = DomainManager.Taiwu.GetTaiwu();
		RemoveElement_Objects(taiwuCharId);
		Dictionary<int, int> preexistenceCharIdMap = new Dictionary<int, int>();
		ref PreexistenceCharIds preexistenceCharIds = ref crossArchiveGameData.TaiwuChar.GetPreexistenceCharIds();
		int i = 0;
		for (int count = preexistenceCharIds.Count; i < count; i++)
		{
			int preCharId = preexistenceCharIds.CharIds[i];
			if (!crossArchiveGameData.PreexistenceDeadCharacters.TryGetValue(preCharId, out var _))
			{
				preexistenceCharIds.CharIds[i] = -1;
				continue;
			}
			int objId = GenerateNextObjectId(context);
			preexistenceCharIdMap.Add(preCharId, objId);
			preexistenceCharIds.CharIds[i] = objId;
		}
		int value;
		foreach (KeyValuePair<int, DeadCharacter> preexistenceDeadCharacter in crossArchiveGameData.PreexistenceDeadCharacters)
		{
			preexistenceDeadCharacter.Deconstruct(out value, out var value2);
			int preexistenceCharId = value;
			DeadCharacter deadChar = value2;
			int convertedCharId = preexistenceCharIdMap[preexistenceCharId];
			PreexistenceCharIds deadCharPreexistenceCharIds = deadChar.PreexistenceCharIds;
			int j = 0;
			for (int count2 = deadCharPreexistenceCharIds.Count; j < count2; j++)
			{
				int preCharId2 = deadCharPreexistenceCharIds.CharIds[j];
				if (!crossArchiveGameData.PreexistenceDeadCharacters.TryGetValue(preCharId2, out var _))
				{
					deadCharPreexistenceCharIds.CharIds[j] = -1;
					continue;
				}
				if (!preexistenceCharIdMap.TryGetValue(preCharId2, out var targetId))
				{
					Logger.Warn($"Invalid character id as preexistence char {targetId}");
					targetId = -1;
				}
				deadCharPreexistenceCharIds.CharIds[j] = targetId;
			}
			deadChar.PreexistenceCharIds = deadCharPreexistenceCharIds;
			AddElement_DeadCharacters(convertedCharId, deadChar, context);
		}
		character.OfflineInheritCrossArchiveCharacter(crossArchiveGameData.TaiwuChar);
		List<short> featureIds = character.GetFeatureIds();
		if (_pregnantStates.ContainsKey(taiwuCharId))
		{
			featureIds.Add(198);
		}
		AddElement_Objects(taiwuCharId, character);
		if (character.GetAgeGroup() == 1)
		{
			character.ReAdjustClothingByAge(context);
		}
		MainAttributes maxMainAttributes = character.GetMaxMainAttributes();
		MainAttributes currMainAttributes = character.GetCurrMainAttributes();
		for (sbyte mainAttrType = 0; mainAttrType < 6; mainAttrType++)
		{
			currMainAttributes.Items[mainAttrType] = Math.Min(currMainAttributes.Items[mainAttrType], maxMainAttributes.Items[mainAttrType]);
		}
		character.SetCurrMainAttributes(currMainAttributes, context);
		int currentDateBeforeDreamBack = crossArchiveGameData.FinalDateBeforeDreamBack;
		int currentDate = DomainManager.World.GetCurrDate();
		foreach (KeyValuePair<IntPair, int> characterTemporaryFeature in crossArchiveGameData.CharacterTemporaryFeatures)
		{
			characterTemporaryFeature.Deconstruct(out var key, out value);
			IntPair pair = key;
			int date = value;
			int charId = pair.First;
			short featureId = (short)pair.Second;
			if (charId == crossArchiveGameData.TaiwuChar.GetId() && character.GetFeatureIds().Contains(featureId))
			{
				int newExpireDate = date - currentDateBeforeDreamBack + currentDate;
				RegisterCharacterTemporaryFeature(context, taiwuCharId, featureId, newExpireDate);
				Logger.Info($"Unacking temporary feature {CharacterFeature.Instance[featureId].Name} expiring in {newExpireDate - currentDate} months.");
			}
		}
		crossArchiveGameData.CharacterTemporaryFeatures = null;
	}

	public void UnpackCrossArchiveGameData_Items(DataContext context, CrossArchiveGameData crossArchiveGameData, bool overwriteEquipments)
	{
		Character character = DomainManager.Taiwu.GetTaiwu();
		Inventory inventory = character.GetInventory();
		ItemKey[] equipment = character.GetEquipment();
		int charId = character.GetId();
		ItemKey[] dreamBackEquipment = crossArchiveGameData.TaiwuChar.GetEquipment();
		for (int index = 0; index < dreamBackEquipment.Length; index++)
		{
			ItemKey equipmentKey = dreamBackEquipment[index];
			if (!equipmentKey.IsValid())
			{
				continue;
			}
			ItemKey newKey = DomainManager.Item.UnpackCrossArchiveItem(context, crossArchiveGameData, equipmentKey);
			if (equipmentKey.ItemType == 3 && (Config.Clothing.Instance[equipmentKey.TemplateId].AgeGroup != 2 || character.GetAgeGroup() != 2))
			{
				if (newKey.IsValid())
				{
					DomainManager.Item.RemoveItem(context, newKey);
					crossArchiveGameData.UnpackedItems.Remove(newKey.Id);
				}
				dreamBackEquipment[index] = equipment[index];
			}
			else
			{
				dreamBackEquipment[index] = newKey;
				if (newKey.IsValid())
				{
					DomainManager.Item.SetOwner(newKey, ItemOwnerType.CharacterInventory, charId);
					inventory.OfflineAdd(newKey, 1);
				}
			}
		}
		if (overwriteEquipments)
		{
			character.ChangeEquipment(context, dreamBackEquipment);
		}
		Inventory dreamBackInventory = crossArchiveGameData.TaiwuChar.GetInventory();
		foreach (var (itemKey2, amount) in dreamBackInventory.Items)
		{
			if (!ItemTemplateHelper.IsInheritable(itemKey2.ItemType, itemKey2.TemplateId))
			{
				continue;
			}
			ItemKey newItemKey = DomainManager.Item.UnpackCrossArchiveItem(context, crossArchiveGameData, itemKey2);
			if (!newItemKey.IsValid())
			{
				continue;
			}
			if (itemKey2.ItemType == 12)
			{
				if (Config.Misc.Instance[itemKey2.TemplateId].ItemSubType == 1202)
				{
					int bookCombatSkillType = itemKey2.TemplateId - 240;
					DomainManager.LegendaryBook.RegisterOwner(context, character, (sbyte)bookCombatSkillType);
				}
				else if (itemKey2.TemplateId == 227)
				{
					if (inventory.GetInventoryItemCount(itemKey2.ItemType, itemKey2.TemplateId) > 0 || DomainManager.Building.IsTaiwuVillageHaveSpecifyBuilding(50))
					{
						continue;
					}
				}
				else if (itemKey2.TemplateId == 226 && (inventory.GetInventoryItemCount(itemKey2.ItemType, itemKey2.TemplateId) > 0 || DomainManager.Building.IsTaiwuVillageHaveSpecifyBuilding(51)))
				{
					continue;
				}
			}
			ItemBase item = DomainManager.Item.GetBaseItem(newItemKey);
			item.ResetOwner();
			item.SetOwner(ItemOwnerType.CharacterInventory, charId);
			inventory.OfflineAdd(newItemKey, amount);
		}
		character.SetInventory(inventory, context);
		dreamBackInventory.Items.Clear();
		RemoveDlcDuplicateClothing(context, fixArchiveData: false);
	}

	public void RemoveDlcDuplicateClothing(DataContext context, bool fixArchiveData)
	{
		foreach (ClothingItem config in (IEnumerable<ClothingItem>)Config.Clothing.Instance)
		{
			if (!string.IsNullOrEmpty(config.DlcName))
			{
				RemoveDuplicateClothing(context, config.TemplateId, fixArchiveData);
			}
		}
	}

	private void RemoveDuplicateClothing(DataContext context, short templateId, bool fixArchiveData)
	{
		Character character = DomainManager.Taiwu.GetTaiwu();
		Inventory inventory = character.GetInventory();
		ItemKey[] equipment = character.GetEquipment();
		int inventoryItemCount = inventory.GetInventoryItemCount(3, templateId);
		int deleteCount = 0;
		if (equipment[4].TemplateId == templateId && inventoryItemCount >= 1)
		{
			deleteCount = inventoryItemCount;
		}
		else if (inventoryItemCount >= 2)
		{
			deleteCount = inventoryItemCount - 1;
		}
		for (int i = 0; i < deleteCount; i++)
		{
			ItemKey inventoryItemKey = inventory.GetInventoryItemKey(3, templateId);
			if (inventoryItemKey.IsValid())
			{
				character.RemoveInventoryItem(context, inventoryItemKey, 1, deleteItem: true);
				if (fixArchiveData)
				{
					Logger.Warn($"FixArchiveData with RemoveDuplicateClothing Func,Clothing templateId:{inventoryItemKey.TemplateId},itemKey.Id:{inventoryItemKey.Id}");
				}
			}
		}
	}

	public void UnpackCrossArchiveGameData_LifeSkills(DataContext context, CrossArchiveGameData crossArchiveGameData)
	{
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<LifeSkillItem> dreamBackLifeSkills = crossArchiveGameData.TaiwuChar.GetLearnedLifeSkills();
		List<LifeSkillItem> currLifeSkills = taiwu.GetLearnedLifeSkills();
		List<LifeSkillItem> mergedLifeSkills = new List<LifeSkillItem>();
		foreach (LifeSkillItem dreamBackLifeSkill in dreamBackLifeSkills)
		{
			int index = taiwu.FindLearnedLifeSkillIndex(dreamBackLifeSkill.SkillTemplateId);
			if (index >= 0)
			{
				LifeSkillItem currLifeSkill = currLifeSkills[index];
				currLifeSkill.ReadingState |= dreamBackLifeSkill.ReadingState;
				mergedLifeSkills.Add(currLifeSkill);
			}
			else
			{
				mergedLifeSkills.Add(dreamBackLifeSkill);
			}
		}
		taiwu.SetLearnedLifeSkills(mergedLifeSkills, context);
		dreamBackLifeSkills.Clear();
	}

	private void PackAbridgedCharacter(CrossArchiveGameData crossArchiveGameData, int charId)
	{
		if (!crossArchiveGameData.AbridgedCharacters.ContainsKey(charId) && charId >= 0)
		{
			AbridgedCharacter abridgedChar = GetAbridgeCharacter(charId);
			if (abridgedChar != null)
			{
				crossArchiveGameData.AbridgedCharacters.Add(charId, abridgedChar);
			}
		}
	}

	public AbridgedCharacter GetAbridgeCharacter(int charId)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		RelationKey selfToTaiwuKey = new RelationKey(charId, taiwuCharId);
		RelationKey taiwuToSelfKey = new RelationKey(taiwuCharId, charId);
		ushort selfRelationToTaiwu = ushort.MaxValue;
		ushort taiwuRelationToSelf = ushort.MaxValue;
		if (charId != taiwuCharId)
		{
			if (_relations.TryGetValue(selfToTaiwuKey, out var selfToTaiwu))
			{
				selfRelationToTaiwu = selfToTaiwu.RelationType;
			}
			if (_relations.TryGetValue(taiwuToSelfKey, out var taiwuToSelf))
			{
				taiwuRelationToSelf = taiwuToSelf.RelationType;
			}
		}
		if (_objects.TryGetValue(charId, out var character))
		{
			return new AbridgedCharacter
			{
				Id = character.GetId(),
				CharTemplateId = character.GetTemplateId(),
				Gender = character.GetGender(),
				ActualAge = character.GetActualAge(),
				CurrAge = character.GetCurrAge(),
				MonkType = character.GetMonkType(),
				Avatar = character.GetAvatar(),
				ClothingDisplayId = character.GetClothingDisplayId(),
				FullName = character.GetFullName(),
				OrganizationInfo = character.GetOrganizationInfo(),
				MonasticTitle = character.GetMonasticTitle(),
				CustomDisplayNameId = DomainManager.Extra.GetCharacterCustomDisplayName(charId),
				SelfRelationToTaiwu = selfRelationToTaiwu,
				TaiwuRelationToSelf = taiwuRelationToSelf,
				AliveState = 0,
				Location = character.GetLocation(),
				BirthDate = character.GetBirthDate()
			};
		}
		Grave grave;
		if (_deadCharacters.TryGetValue(charId, out var deadCharacter))
		{
			return new AbridgedCharacter
			{
				Id = charId,
				CharTemplateId = deadCharacter.TemplateId,
				Gender = deadCharacter.Gender,
				ActualAge = deadCharacter.GetActualAge(),
				CurrAge = deadCharacter.CurrAge,
				MonkType = deadCharacter.MonkType,
				Avatar = deadCharacter.Avatar,
				ClothingDisplayId = deadCharacter.ClothingDisplayId,
				FullName = deadCharacter.FullName,
				OrganizationInfo = deadCharacter.OrganizationInfo,
				MonasticTitle = deadCharacter.MonasticTitle,
				CustomDisplayNameId = DomainManager.Extra.GetCharacterCustomDisplayName(charId),
				SelfRelationToTaiwu = selfRelationToTaiwu,
				TaiwuRelationToSelf = taiwuRelationToSelf,
				AliveState = 1,
				Location = (_graves.TryGetValue(charId, out grave) ? grave.GetLocation() : Location.Invalid),
				BirthDate = deadCharacter.BirthDate
			};
		}
		Logger.Info($"Unable to find character {charId} for creating abridged data.");
		return null;
	}

	public (Dictionary<short, int> Total, Dictionary<short, int> Child, Dictionary<short, int> Adult, Dictionary<short, int> Semi, Dictionary<short, int> Old) CalcCharacterBelongStatDict()
	{
		Dictionary<short, int> all = new Dictionary<short, int>();
		Dictionary<short, int> child = new Dictionary<short, int>();
		Dictionary<short, int> adult = new Dictionary<short, int>();
		Dictionary<short, int> semi = new Dictionary<short, int>();
		Dictionary<short, int> old = new Dictionary<short, int>();
		foreach (Character character in _objects.Values)
		{
			if (character.GetCreatingType() != 1 || character.GetDarkAshProtector() != 0)
			{
				continue;
			}
			short belong = character.GetOrganizationInfo().SettlementId;
			if (!all.TryAdd(belong, 1))
			{
				all[belong]++;
			}
			short actualAge = character.GetActualAge();
			short num = actualAge;
			if (num < 40)
			{
				if (num < 16)
				{
					if (!child.TryAdd(belong, 1))
					{
						child[belong]++;
					}
				}
				else if (!adult.TryAdd(belong, 1))
				{
					adult[belong]++;
				}
			}
			else if (num < 70)
			{
				if (!semi.TryAdd(belong, 1))
				{
					semi[belong]++;
				}
			}
			else if (!old.TryAdd(belong, 1))
			{
				old[belong]++;
			}
		}
		return (Total: all, Child: child, Adult: adult, Semi: semi, Old: old);
	}

	public Dictionary<short, ((int Exceed, int Total) Adult, (int Exceed, int Total) Semi, (int Exceed, int Total) Old)> CalcExceedPopulations(IRandomSource random, IEnumerable<short> settlementIds, Dictionary<short, int> childs, Dictionary<short, int> adults, Dictionary<short, int> semis, Dictionary<short, int> olds)
	{
		short factor = WorldCreation.DefValue.WorldPopulation.InfluenceFactors[DomainManager.World.GetWorldPopulationType()];
		Dictionary<short, ((int, int), (int, int), (int, int))> dict = new Dictionary<short, ((int, int), (int, int), (int, int))>();
		foreach (short settlementId in settlementIds)
		{
			childs.TryGetValue(settlementId, out var _);
			adults.TryGetValue(settlementId, out var adultCount);
			semis.TryGetValue(settlementId, out var semiCount);
			olds.TryGetValue(settlementId, out var oldCount);
			Settlement settlement = ((settlementId >= 0) ? DomainManager.Organization.GetSettlement(settlementId) : null);
			if (settlement == null)
			{
				continue;
			}
			int total = settlement.OrganizationConfig.PopulationThreshold * random.Next(100, GlobalConfig.Instance.PopulationLimitRandomRateMax) / 100;
			int exceed = oldCount + semiCount + adultCount - total * factor / 100;
			int semiDelta = semiCount - adultCount / 2;
			int oldDelta = oldCount - adultCount / 3;
			if (exceed <= 0 && semiDelta <= 0 && oldDelta <= 0)
			{
				continue;
			}
			int adult = adultCount;
			int semi = semiCount * 3;
			int old = oldCount * 6;
			int totalWeight = adult + semi + old;
			if (totalWeight > 0)
			{
				adult = adult * exceed / totalWeight;
				semi = semi * exceed / totalWeight;
				old = old * exceed / totalWeight;
			}
			adult = Math.Min(adult, adultCount);
			semi = Math.Min(Math.Max(semiDelta, semi), semiCount);
			old = Math.Min(Math.Max(oldDelta, old), oldCount);
			if ((adult | semi | old) == 0)
			{
				continue;
			}
			short? num = settlement?.GetLocation().AreaId;
			if (num.HasValue)
			{
				short valueOrDefault = num.GetValueOrDefault();
				if (valueOrDefault >= 0 && valueOrDefault <= 135)
				{
					dict[settlementId] = ((adult, adultCount), (semi, semiCount), (old, oldCount));
				}
			}
		}
		return dict;
	}

	public void MarkExceedPopulationsNew(DataContext context, HashSet<short> targetSettlements, Dictionary<short, (int Expected, int Primary, int NonPrimary)[]> adultPlan)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		HashSet<int> checks = new HashSet<int>();
		GetTaiwuPeople(checks);
		HashSet<int> following = DomainManager.Extra.GetFollowingNpcList().ToHashSet();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		foreach (Character character in _objects.Values.OrderBy((Character character2) => -character2.GetPhysiologicalAge()))
		{
			if (character.GetCreatingType() != 1 || character.GetDarkAshProtector() != 0)
			{
				continue;
			}
			OrganizationInfo organizationInfo = character.GetOrganizationInfo();
			if (organizationInfo.Grade == 8 && organizationInfo.Principal)
			{
				continue;
			}
			OrganizationInfo org = character.GetOrganizationInfo();
			short belong = org.SettlementId;
			if (!targetSettlements.Contains(belong))
			{
				continue;
			}
			sbyte grade = org.Grade;
			if (!adultPlan.TryGetValue(belong, out (int, int, int)[] markPlan) || !markPlan.CheckIndex(grade))
			{
				continue;
			}
			(int, int, int) plan = markPlan[grade];
			int num = context.Random.Next(60) * plan.Item1;
			short physiologicalAge = character.GetPhysiologicalAge();
			if (1 == 0)
			{
			}
			int num2 = ((physiologicalAge < 40) ? ((physiologicalAge >= 16) ? 1 : 0) : ((physiologicalAge >= 70) ? 6 : 3));
			if (1 == 0)
			{
			}
			if (num < num2 * (plan.Item2 - plan.Item1))
			{
				plan.Item1--;
				character.AddDarkAsh(context, lifeRecordCollection);
				if (checks.Contains(character.GetId()))
				{
					monthlyNotificationCollection.AddFirstGetInfected0(character.GetId(), character.GetLocation(), character.DarkAshDuration);
				}
				if (following.Contains(character.GetId()))
				{
					monthlyNotificationCollection.AddFirstGetInfected1(character.GetId(), character.GetLocation(), character.DarkAshDuration);
				}
			}
		}
	}

	public void MarkExceedPopulations(DataContext context, Dictionary<short, ((int Exceed, int Total) Adult, (int Exceed, int Total) Semi, (int Exceed, int Total) Old)> plan)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		HashSet<int> checks = new HashSet<int>();
		GetTaiwuPeople(checks);
		HashSet<int> following = DomainManager.Extra.GetFollowingNpcList().ToHashSet();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		foreach (Character character in _objects.Values)
		{
			if (character.GetCreatingType() != 1 || character.GetDarkAshProtector() != 0)
			{
				continue;
			}
			short belong = character.GetOrganizationInfo().SettlementId;
			if (!plan.TryGetValue(belong, out ((int, int), (int, int), (int, int)) markPlan))
			{
				continue;
			}
			short actualAge = character.GetActualAge();
			short num = actualAge;
			bool infected;
			if (num < 40)
			{
				if (num < 16)
				{
					continue;
				}
				if (infected = context.Random.Next(markPlan.Item1.Item2--) < markPlan.Item1.Item1)
				{
					markPlan.Item1.Item1--;
				}
			}
			else if (num < 70)
			{
				if (infected = context.Random.Next(markPlan.Item2.Item2--) < markPlan.Item2.Item1)
				{
					markPlan.Item2.Item1--;
				}
			}
			else if (infected = context.Random.Next(markPlan.Item3.Item2--) < markPlan.Item3.Item1)
			{
				markPlan.Item3.Item1--;
			}
			if (infected)
			{
				character.AddDarkAsh(context, lifeRecordCollection);
				if (checks.Contains(character.GetId()))
				{
					monthlyNotificationCollection.AddFirstGetInfected0(character.GetId(), character.GetLocation(), character.DarkAshDuration);
				}
				if (following.Contains(character.GetId()))
				{
					monthlyNotificationCollection.AddFirstGetInfected1(character.GetId(), character.GetLocation(), character.DarkAshDuration);
				}
			}
			plan[belong] = markPlan;
		}
	}

