	public void PostAdvanceMonthCalcDarkAsh(DataContext context)
	{
		Dictionary<short, (int, int, int)[]> adultPlan = DomainManager.Organization.GetSettlementDarkAshTriple();
		(Dictionary<short, int> Total, Dictionary<short, int> Child, Dictionary<short, int> Adult, Dictionary<short, int> Semi, Dictionary<short, int> Old) belongDict = DomainManager.Character.CalcCharacterBelongStatDict();
		DomainManager.Character.MarkExceedPopulationsNew(context, (from x in belongDict.Total
			where (long)(DomainManager.Organization.GetSettlementOrDefault(x.Key)?.OrganizationConfig.PopulationThreshold ?? 0) * (long)context.Random.Next(100, 125) * WorldCreation.DefValue.WorldPopulation.InfluenceFactors[DomainManager.World.GetWorldPopulationType()] / 10000 < belongDict.Adult.GetValueOrDefault(x.Key) + belongDict.Semi.GetValueOrDefault(x.Key) + belongDict.Old.GetValueOrDefault(x.Key)
			select x.Key).ToHashSet(), adultPlan);
		AddDarkAshNotifications();
		int currDate = DomainManager.World.GetCurrDate();
		int[] array = GetAllDarkAshCounterData().ToArray();
		foreach (int id in array)
		{
			if (_characterDarkAshCounterData.TryGetValue(id, out var data))
			{
				if (data.ExpiredDate2 - currDate <= 0 || !TryGetElement_Objects(id, out var character))
				{
					RemoveDarkAshCounterData(context, id);
				}
				else if ((character.GetDarkAshProtector() & 0xFFFFFDFFu) != 0)
				{
					SetDarkAshCounterData(context, id, data.OfflineApplyFaithChangeToExtraData(currDate - 1, 1));
				}
			}
		}
	}

