	public void MakeCharacterDead(DataContext context, Character character, short deathType, CharacterDeathInfo deathInfo)
	{
		Tester.Assert(character.GetCreatingType() == 1);
		Tester.Assert(!IsTemporaryIntelligentCharacter(character.GetId()));
		CharacterDeathTypeItem deathTypeCfg = CharacterDeathType.Instance[deathType];
		if (DomainManager.Taiwu.HandleCricketPolymorphDead(context, character))
		{
			return;
		}
		int charId = character.GetId();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		if (charId != taiwuCharId)
		{
			character.GenerateBequest(context);
		}
		int deathDate = ((deathInfo.DeathDate == int.MinValue) ? DomainManager.World.GetCurrDate() : deathInfo.DeathDate);
		DeadCharacter deadChar = DeadCharacterHelper.CreateDeadCharacter(character, deathDate);
		Logger.Info($"{character} is dead at age {character.GetCurrAge()}.({deathTypeCfg.Name}:{deathInfo})");
		if (character.GetHealth() > 0)
		{
			character.SetHealth(0, context);
		}
		int leaderId = character.GetLeaderId();
		Location charLocation = character.GetLocation();
		if (!charLocation.IsValid())
		{
			if ((leaderId < 0 || charId == leaderId) && _crossAreaMoveInfos.TryGetValue(leaderId, out var crossAreaMoveInfo))
			{
				charLocation = DomainManager.Map.CrossAreaTravelInfoToLocation(crossAreaMoveInfo);
				GroupMove(context, character, charLocation);
			}
			else
			{
				charLocation = character.GetValidLocation();
				character.SetLocation(charLocation, context);
			}
		}
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		if (DomainManager.Taiwu.IsCharacterFollowedByTaiwu(charId))
		{
			if (deathType == 16)
			{
				monthlyNotifications.AddFocusedDieByInfected(charId, deathInfo.Location);
			}
			else
			{
				monthlyNotifications.AddDieNotice(charId, deathInfo.Location);
			}
		}
		if (deathTypeCfg.DefaultMonthlyNotification >= 0 && (!deathTypeCfg.NotifyTaiwuPeopleOnly || character.GetOrganizationInfo().OrgTemplateId == 16 || DomainManager.Character.IsTaiwuPeople(charId)))
		{
			monthlyNotifications.AddDeathNotification(charId, deathTypeCfg, ref deathInfo);
		}
		RemoveCrossAreaTravelInfo(context, charId);
		if (charId == DomainManager.Extra.GetKidnappedTravelData().HunterCharId)
		{
			if (DomainManager.World.GetAdvancingMonthState() == 0)
			{
				DomainManager.TaiwuEvent.OnEvent_TaiwuBeHuntedHunterDie(charId);
			}
			else
			{
				MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
				monthlyEventCollection.AddTaiwuBeHuntedHunterDie(charId, DomainManager.Taiwu.GetTaiwuCharId());
				DomainManager.World.IsTaiwuHunterDie = true;
			}
		}
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int secretInfoOffset = secretInformationCollection.AddDie(charId, charLocation);
		DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
		RemoveAllKidnappedChars(context, character, isEscaped: true);
		RemoveElement_Objects(charId);
		RemoveInfectedCharFromSet(charId);
		if (_pregnantStates.ContainsKey(charId))
		{
			RemoveElement_PregnantStates(charId, context);
		}
		if (_pregnancyLockEndDates.ContainsKey(charId))
		{
			RemoveElement_PregnancyLockEndDates(charId, context);
		}
		character.ActionPlanningData.OnCharacterDead(context, character);
		if (_ongoingVengeances.TryGetValue(charId, out var revengingCharSet))
		{
			revengingCharSet.Clear();
			RemoveElement_OngoingVengeances(charId, context);
		}
		int kidnapperId = character.GetKidnapperId();
		if (kidnapperId >= 0)
		{
			RemoveKidnappedCharacter(context, charId, kidnapperId, isEscaped: true);
		}
		if (_avatarElementGrowthProgress.ContainsKey(charId))
		{
			RemoveElement_AvatarElementGrowthProgress(charId, context);
		}
		HashSet<int> closeCharIds = ObjectPool<HashSet<int>>.Instance.Get();
		GetClosePeople(context.Random, character, closeCharIds, 100);
		closeCharIds.Remove(charId);
		foreach (int closeCharId in closeCharIds)
		{
			if (!TryGetRelation(closeCharId, charId, out var relation) || relation.RelationType == 0)
			{
				continue;
			}
			Character closeChar = _objects[closeCharId];
			for (sbyte typeId = 1; typeId < 17; typeId++)
			{
				ushort relationType = RelationType.GetRelationType(typeId);
				if (RelationType.HasRelation(relation.RelationType, relationType))
				{
					closeChar.AddGoal(context, 249, relationType);
				}
			}
		}
		if (leaderId >= 0)
		{
			DomainManager.Character.LeaveGroup(context, character, bringWards: false);
		}
		Events.RaiseIntelligentCharacterDead(context, character, deathTypeCfg, ref deathInfo);
		character.OnDeathTransferWugKings(context, charLocation);
		ResetEquippedItemCharId(context, character);
		RemoveNonBuryableItemsInInventory(context, character, charLocation);
		RemoveInfant(charId);
		AddElement_DeadCharacters(charId, deadChar, context);
		sbyte advancingMonthState = DomainManager.World.GetAdvancingMonthState();
		if ((advancingMonthState == 0 || advancingMonthState == 14) ? true : false)
		{
			closeCharIds.Remove(taiwuCharId);
		}
		Character undertaker = (deathTypeCfg.FindUndertaker ? SelectUndertaker(context, character, closeCharIds) : null);
		ObjectPool<HashSet<int>>.Instance.Return(closeCharIds);
		Location graveLocation = DomainManager.Map.GetRandomGraveBlock(context.Random, charLocation);
		if (undertaker != null)
		{
			if (undertaker.GetId() == taiwuCharId)
			{
				MonthlyEventCollection monthlyEventCollection2 = DomainManager.World.GetMonthlyEventCollection();
				monthlyEventCollection2.AddDie(charId, charLocation);
				Grave grave = new Grave(context, character, graveLocation, 0);
				AddElement_Graves(charId, grave);
				Events.RaiseGraveLocationChanged(context, charId, Location.Invalid, grave.GetLocation());
			}
			else
			{
				int underTakerMoney = undertaker.GetResource(6);
				sbyte level = Grave.CalcGraveLevel(underTakerMoney);
				if (level == 0)
				{
					undertaker.AddGoal(context, 236, (sbyte)6, (int)GlobalConfig.Instance.GraveLevelMoneyCosts[^1]);
				}
				else
				{
					undertaker.ChangeResource(context, 6, -GlobalConfig.Instance.GraveLevelMoneyCosts[level]);
				}
				Grave grave2 = new Grave(context, character, graveLocation, level);
				AddElement_Graves(charId, grave2);
				Events.RaiseGraveLocationChanged(context, charId, Location.Invalid, grave2.GetLocation());
				secretInfoOffset = secretInformationCollection.AddBuildGrave(undertaker.GetId(), charId);
				SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
				LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
				lifeRecordCollection.AddBuildGrave(undertaker.GetId(), deathDate, charId, grave2.GetLocation());
			}
		}
		else
		{
			Grave grave3 = new Grave(context, character, graveLocation, 0);
			AddElement_Graves(charId, grave3);
			Events.RaiseGraveLocationChanged(context, charId, Location.Invalid, grave3.GetLocation());
		}
		IntPair deathDateAndCharId = new IntPair(deathDate, charId);
		AddElement_RecentDeadCharacters(deathDateAndCharId, default(VoidValue), context);
		AddElement_WaitingReincarnationChars(deathDateAndCharId, default(VoidValue), context);
		character.RemoveMerchantType(context);
		character.RemoveMerchantExp(context);
		RemoveAllGeneralRelations(context, charId);
		DomainManager.Extra.RemoveDyingCharacters(context, charId);
		RemoveElement_Alertness(charId, context);
	}

