	public Character SelectUndertaker(DataContext context, Character character, HashSet<int> closeCharIds)
	{
		if (closeCharIds.Count == 0)
		{
			return null;
		}
		int charId = character.GetId();
		int factionId = character.GetFactionId();
		sbyte selfFameType = character.GetFameType();
		if (selfFameType == -2)
		{
			selfFameType = (sbyte)(context.Random.NextBool() ? 4 : 2);
		}
		int maxScore = 0;
		Character maxScoreChar = null;
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanBeUndertaker;
		foreach (int closeCharId in closeCharIds)
		{
			Character closeChar = _objects[closeCharId];
			if (!matcher.Match(closeChar))
			{
				continue;
			}
			int score = Grave.CalcGraveLevel(closeChar.GetResource(6));
			if (TryGetRelation(closeCharId, charId, out var relation))
			{
				sbyte favorabilityType = FavorabilityType.GetFavorabilityType(relation.Favorability);
				score += ((favorabilityType >= 2) ? (favorabilityType - 2) : 0);
				ushort relationType = relation.RelationType;
				if (RelationType.HasRelation(relationType, 1024) || RelationType.ContainParentRelations(relationType) || RelationType.ContainChildRelations(relationType))
				{
					score += 5;
				}
				else if (RelationType.ContainBrotherOrSisterRelations(relationType) || RelationType.HasRelation(relationType, 16384) || RelationType.HasRelation(relationType, 512))
				{
					score += 4;
				}
				else if (RelationType.HasRelation(relationType, 2048))
				{
					score += 3;
				}
				else if (RelationType.HasRelation(relationType, 8192))
				{
					score += 2;
				}
				else if (factionId >= 0 && closeChar.GetFactionId() == factionId)
				{
					score++;
				}
			}
			else if (factionId >= 0 && closeChar.GetFactionId() == factionId)
			{
				score++;
			}
			switch (closeChar.GetBehaviorType())
			{
			case 0:
			{
				sbyte closeCharFameType = closeChar.GetFameType();
				if (closeCharFameType == -2)
				{
					closeCharFameType = (sbyte)(context.Random.NextBool() ? 4 : 2);
				}
				score = ((!FameType.IsSameSide(selfFameType, closeCharFameType)) ? (score - 2) : (score + 2));
				break;
			}
			case 1:
				score += 4;
				break;
			case 3:
				score += context.Random.Next(-5, 6);
				break;
			case 4:
				score -= 4;
				break;
			}
			if (score > maxScore)
			{
				maxScore = score;
				maxScoreChar = closeChar;
			}
			else if (score == maxScore && maxScoreChar != null && closeCharId > maxScoreChar.GetId())
			{
				maxScore = score;
				maxScoreChar = closeChar;
			}
		}
		return maxScoreChar;
	}

	public void TryRemoveRecentDeadCharacters(DataContext context)
	{
