	public void TryRemoveDeadCharacters(DataContext context)
	{
		int thresholdDate = DomainManager.World.GetCurrDate() - 120;
		List<int> charIdsToBeRemoved = new List<int>();
		List<int> prevTaiwuIds = DomainManager.Taiwu.GetPreviousTaiwuIds();
		foreach (KeyValuePair<int, DeadCharacter> entry in _deadCharacters)
		{
			int charId = entry.Key;
			DeadCharacter deadChar = entry.Value;
			if (deadChar.DeathDate < thresholdDate && _deadCharDeletionStates.TryGetValue(charId, out var state) && state.GraveRemoved && state.DeletedFromOthersPreexistence && !prevTaiwuIds.Contains(charId))
			{
				charIdsToBeRemoved.Add(charId);
			}
		}
		Logger.Info($"Removing dead characters: {charIdsToBeRemoved.Count}/{_deadCharacters.Count}");
		int i = 0;
		for (int count = charIdsToBeRemoved.Count; i < count; i++)
		{
			int charId2 = charIdsToBeRemoved[i];
			DomainManager.Extra.RemoveCharacterCustomDisplayName(context, charId2);
			DomainManager.Extra.RemoveSecretInformationShopCharacterData(context, charId2);
			RemoveElement_DeadCharacters(charId2, context);
			RemoveElement_DeadCharDeletionStates(charId2, context);
			RemoveElement_CharacterCreationMetas(charId2, context);
			RemoveAllRelations(context, charId2, removeRelatedRelations: false);
			DomainManager.Extra.RemoveInteractedCharacter(context, charId2);
		}
	}

