	public unsafe void RenewPreexistence(DataContext context, int newCharId, ref PreexistenceCharIds preexistenceCharIds)
	{
		if (preexistenceCharIds.Count == 9)
		{
			RecordDeletedChar(context, preexistenceCharIds.CharIds[0]);
			for (int i = 1; i < 9; i++)
			{
				preexistenceCharIds.CharIds[i - 1] = preexistenceCharIds.CharIds[i];
			}
			preexistenceCharIds.Count--;
		}
		preexistenceCharIds.Add(context.Random, newCharId);
	}

