	private void RemoveNonBuryableItemsInInventory(DataContext context, Character character, Location location)
	{
		List<ItemKey> itemsToRemove = ObjectPool<List<ItemKey>>.Instance.Get();
		List<MapBlockData> nearbyBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, nearbyBlocks, 2, includeCenter: true);
		itemsToRemove.Clear();
		Inventory inventory = character.GetInventory();
		int charId = character.GetId();
		foreach (var (itemKey2, _) in inventory.Items)
		{
			if (itemKey2.ItemType == 11)
			{
				MapBlockData block = nearbyBlocks[context.Random.Next(nearbyBlocks.Count)];
				DomainManager.Item.RemoveOwner(itemKey2, ItemOwnerType.CharacterInventory, charId);
				DomainManager.Map.AddBlockItem(context, block, itemKey2, 1);
				itemsToRemove.Add(itemKey2);
			}
			else if (itemKey2.ItemType == 4 && ItemTemplateHelper.GetResourceType(itemKey2.ItemType, itemKey2.TemplateId) == 0)
			{
				MapBlockData block2 = nearbyBlocks[context.Random.Next(nearbyBlocks.Count)];
				DomainManager.Item.RemoveOwner(itemKey2, ItemOwnerType.CharacterInventory, charId);
				DomainManager.Map.AddBlockItem(context, block2, itemKey2, 1);
				itemsToRemove.Add(itemKey2);
			}
			else if (!ItemDomain.CanItemBeLost(itemKey2))
			{
				DomainManager.Item.RemoveItem(context, itemKey2);
				itemsToRemove.Add(itemKey2);
			}
		}
		foreach (ItemKey itemKey3 in itemsToRemove)
		{
			inventory.OfflineRemove(itemKey3);
		}
		ObjectPool<List<ItemKey>>.Instance.Return(itemsToRemove);
		ObjectPool<List<MapBlockData>>.Instance.Return(nearbyBlocks);
	}

