	private int PickReincarnationChar(DataContext context, int newCharId, int birthDate, int presetReincarnationCharId = -1, bool disableSavedSoul = false)
	{
		if (presetReincarnationCharId == -2)
		{
			return -1;
		}
		SortedSet<IntPair> waitingReincarnationChars = _waitingReincarnationChars.Collection;
		if (waitingReincarnationChars.Count <= 0)
		{
			if (context.Random.CheckPercentProb(GlobalConfig.Instance.AnimalSamsaraChance))
			{
				return CreateDeadAnimal(context, birthDate - 7);
			}
			return -1;
		}
		IntPair min = waitingReincarnationChars.Min;
		int charId = -1;
		ProfessionData buddhistProfessionData = DomainManager.Extra.GetProfessionData(6);
		BuddhistMonkSkillsData buddhistSkillsData = buddhistProfessionData.GetSkillsData<BuddhistMonkSkillsData>();
		if (presetReincarnationCharId >= 0)
		{
			foreach (IntPair pair in waitingReincarnationChars)
			{
				if (pair.Second != presetReincarnationCharId)
				{
					continue;
				}
				min = pair;
				charId = pair.Second;
				break;
			}
		}
		else
		{
			if (context.Random.CheckPercentProb(GlobalConfig.Instance.AnimalSamsaraChance))
			{
				return CreateDeadAnimal(context, birthDate - 7);
			}
			foreach (IntPair pair2 in waitingReincarnationChars)
			{
				int waitingCharId = pair2.Second;
				if (pair2.First + 7 > birthDate)
				{
					return -1;
				}
				if (DomainManager.Building.IsCharOnSamsaraPlatform(waitingCharId) || buddhistSkillsData.IsDirectedSamsaraCharacter(waitingCharId) || (DomainManager.Extra.IsSavedSoul(waitingCharId) && disableSavedSoul))
				{
					continue;
				}
				min = pair2;
				charId = waitingCharId;
				break;
			}
		}
		if (charId < 0)
		{
			return -1;
		}
		DomainManager.Taiwu.RecordTrace(context, charId, newCharId);
		RemoveElement_WaitingReincarnationChars(min, context);
		return charId;
	}

	private int CreateDeadAnimal(DataContext context, int deathDate, int group = -1)
	{
		int charId = GenerateNextObjectId(context);
		if (group < 0)
		{
			group = context.Random.Next(0, 2);
		}
		short animalTemplateId = GameData.Domains.Map.SharedConstValue.AnimalCharIdGroups.GetRandom(context.Random)[group];
		DeadCharacter deadChar = DeadCharacterHelper.CreateDeadNonIntelligentCharacter(context.Random, animalTemplateId, deathDate);
		deadChar.BirthDate = CalcBirthDate(deathDate, deadChar.CurrAge, context.Random.Next(12));
		deadChar.FeatureIds.Clear();
		deadChar.FeatureIds.AddRange(Config.Character.Instance[animalTemplateId].FeatureIds);
		AddElement_DeadCharacters(charId, deadChar, context);
		return charId;
	}

	public short CalcMaxFavorabilityToTaiwu(Character character)
	{
		if (!_alertness.TryGetValue(character.GetId(), out var alertness))
		{
			return 30000;
		}
		int decrement = CalcMaxFavorabilityDecrementToTaiwu(alertness.Value);
		return (short)Math.Max(30000 - decrement, -30000);
	}

	[DomainMethod]
	public short CalcMaxFavorabilityToTaiwuById(int charId)
	{
		if (TryGetElement_Objects(charId, out var character))
		{
			return CalcMaxFavorabilityToTaiwu(character);
		}
		return 30000;
	}

	[DomainMethod]
	public long GetMaxWorthCanBeLentToTaiwu(int charId)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		if (charId == taiwuCharId)
		{
			return 0L;
		}
		RelationKey relationKey = new RelationKey(charId, taiwuCharId);
		if (!_relations.TryGetValue(relationKey, out var relation))
		{
			return 0L;
		}
		short favor = relation.Favorability;
		int consumableFavor = favor - GlobalConfig.Instance.MinFavorabilityAfterTransferring;
		if (consumableFavor <= 0)
		{
			return 0L;
		}
		Character character = _objects[charId];
		short maxFavor = CalcMaxFavorabilityToTaiwu(character);
		int consumableMaxFavor = maxFavor - GlobalConfig.Instance.MinFavorabilityAfterTransferring;
		if (consumableMaxFavor <= 0)
		{
			return 0L;
		}
		long maxWorthForFavor = (long)consumableFavor * 10L;
		long maxWorthForMaxFavor = (long)consumableMaxFavor * 10L;
		return Math.Min(maxWorthForFavor, maxWorthForMaxFavor);
	}

	[DomainMethod]
	public (sbyte debtChangeType, short favorLevelChangeType) CheckDebtChange(int charId, ResourceInts resources)
	{
		int totalWorthBefore = DomainManager.Character.GetAlertnessValue(charId);
		int totalWorthAfter = totalWorthBefore;
		for (sbyte resourceType = 0; resourceType < 8; resourceType++)
		{
			int resourceAmount = resources.Get(resourceType);
			long worth = ItemDomain.ResourceAmountToWorth(resourceType, Math.Abs(resourceAmount));
			if (worth > 0)
			{
				int clampedWorth = (int)Math.Clamp(worth, -2147483648L, 2147483647L);
				if (resourceAmount > 0)
				{
					InteractAlertnessFormulaItem alertnessFormulaItem = InteractAlertnessFormula.Instance[0];
					int result = alertnessFormulaItem.Calculate(clampedWorth);
					totalWorthAfter -= result;
				}
				else
				{
					InteractAlertnessFormulaItem alertnessFormulaItem2 = InteractAlertnessFormula.Instance[24];
					int result2 = alertnessFormulaItem2.Calculate(clampedWorth);
					totalWorthAfter += result2;
				}
			}
		}
		int favorChange = 0;
		(long positiveWorth, long negativeWorth) resourcesWorth = GetResourcesWorth(ref resources);
		long borrowedWorth = resourcesWorth.positiveWorth;
		long lentWorth = resourcesWorth.negativeWorth;
		bool isAdd = borrowedWorth > lentWorth;
		long diff = Math.Abs(borrowedWorth - lentWorth);
		int resourceFavorChange = AiHelper.GeneralActionConstants.GetResourceFavorabilityChange(6, (int)Math.Clamp(diff, 0L, 2147483647L));
		if (!isAdd)
		{
			resourceFavorChange = -resourceFavorChange;
		}
		favorChange += resourceFavorChange;
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		short srcFavor = GetFavorability(charId, taiwuCharId);
		short dstFavor = (short)Math.Clamp(srcFavor + favorChange, -30000, CalcMaxFavorabilityToTaiwuById(charId));
		if (totalWorthAfter > totalWorthBefore)
		{
			return (debtChangeType: 0, favorLevelChangeType: dstFavor);
		}
		if (totalWorthAfter < totalWorthBefore && totalWorthAfter < 0)
		{
			return (debtChangeType: 4, favorLevelChangeType: dstFavor);
		}
		if (totalWorthAfter == totalWorthBefore)
		{
			return (debtChangeType: 1, favorLevelChangeType: dstFavor);
		}
		if (totalWorthAfter == 0)
		{
			return (debtChangeType: 3, favorLevelChangeType: dstFavor);
		}
		return (debtChangeType: 2, favorLevelChangeType: dstFavor);
	}

	[DomainMethod]
	public bool CheckFavorabilityBeforeTransferring(int charId, ResourceInts resources)
	{
		Character character = _objects[charId];
		sbyte grade = character.GetOrganizationInfo().InteractionGrade;
		short gradeFactor = GlobalConfig.Instance.WorthFactorsOfGrade[grade];
		sbyte behaviorType = character.GetBehaviorType();
		short behaviorTypeFactorOfIncrement = FavorIncrementPercentsOfDebt[behaviorType];
		short behaviorTypeFactorOfDecrement = FavorDecrementPercentsOfDebt[behaviorType];
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		RelationKey relationKey = new RelationKey(charId, taiwuCharId);
		int oriFavor = _relations[relationKey].Favorability;
		long totalWorthLentToTaiwu = 0L;
		int oriMaxFavor = 30000;
		(long positiveWorth, long negativeWorth) resourcesWorth = GetResourcesWorth(ref resources);
		long borrowedWorth = resourcesWorth.positiveWorth;
		long lentWorth = resourcesWorth.negativeWorth;
		long favorIncrement = borrowedWorth / gradeFactor * behaviorTypeFactorOfIncrement / 100;
		long favorDecrement = lentWorth / gradeFactor * behaviorTypeFactorOfDecrement / 100;
		short currFavor = (short)Math.Clamp(oriFavor + favorIncrement - favorDecrement, -30000L, 30000L);
		if (currFavor < oriFavor && currFavor < GlobalConfig.Instance.MinFavorabilityAfterTransferring)
		{
			return false;
		}
		totalWorthLentToTaiwu += lentWorth - borrowedWorth;
		if (totalWorthLentToTaiwu > 0)
		{
			int decrement = (int)Math.Clamp(totalWorthLentToTaiwu / gradeFactor, -2147483648L, 2147483647L);
			int currMaxFavor = Math.Max(30000 - decrement, -30000);
			if (currMaxFavor < oriMaxFavor && currMaxFavor < GlobalConfig.Instance.MinFavorabilityAfterTransferring)
			{
				return false;
			}
		}
		return true;
	}

	public bool CheckFavorabilityAfterTransferring(Character character, short oriFavor, short oriMaxFavor)
	{
		var (currFavor, currMaxFavor) = GetFavorAndMaxFavorToTaiwu(character);
		if (currFavor < oriFavor && currFavor < GlobalConfig.Instance.MinFavorabilityAfterTransferring)
		{
			return false;
		}
		if (currMaxFavor < oriMaxFavor && currMaxFavor < GlobalConfig.Instance.MinFavorabilityAfterTransferring)
		{
			return false;
		}
		return true;
	}

	private static int CalcMaxFavorabilityDecrementToTaiwu(int alertness)
	{
		int maxFavorOffset = ((alertness > 0) ? CharacterAlertnessData.GetEffectMaxFavor(alertness) : 0);
		return Math.Clamp(maxFavorOffset, int.MinValue, int.MaxValue);
	}

	private (short favor, short maxFavor) GetFavorAndMaxFavorToTaiwu(Character character)
	{
		int charId = character.GetId();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		RelationKey relationKey = new RelationKey(charId, taiwuCharId);
		short favor = _relations[relationKey].Favorability;
		short maxFavor = CalcMaxFavorabilityToTaiwu(character);
		return (favor: favor, maxFavor: maxFavor);
	}

