	[DomainMethod]
	public List<CharacterDisplayDataForTasterUltimate> GetCharacterDisplayDataForTasterUltimate(DataContext context, List<ItemKey> bookItemKeyList)
	{
		List<CharacterDisplayDataForTasterUltimate> dataList = new List<CharacterDisplayDataForTasterUltimate>();
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			return dataList;
		}
		MapBlockData belongSettlementBlock = DomainManager.Map.GetBelongSettlementBlock(location);
		if (belongSettlementBlock == null)
		{
			return dataList;
		}
		List<int> charIdList = new List<int>();
		List<short> blockIds = ObjectPool<List<short>>.Instance.Get();
		DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(belongSettlementBlock.AreaId, belongSettlementBlock.BlockId, blockIds);
		int taiwuCharId = taiwu.GetId();
		foreach (short blockId in blockIds)
		{
			MapBlockData block = DomainManager.Map.GetBlock(location.AreaId, blockId);
			if (block.CharacterSet == null)
			{
				continue;
			}
			foreach (int charId in block.CharacterSet)
			{
				if (charId != taiwuCharId)
				{
					charIdList.Add(charId);
				}
			}
		}
		ObjectPool<List<short>>.Instance.Return(blockIds);
		foreach (int charId2 in charIdList)
		{
			Character character = GetElement_Objects(charId2);
			CharacterDisplayDataForGeneralScrollList charDisplayData = GetCharacterDisplayDataForGeneralScrollList(context, charId2);
			List<ReadProgressData> readProgressList = new List<ReadProgressData>();
			foreach (ItemKey bookItemKey in bookItemKeyList)
			{
				if (!DomainManager.Item.ItemExists(bookItemKey))
				{
					continue;
				}
				GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(bookItemKey.Id);
				sbyte[] readingProgress;
				sbyte[] pageTypes;
				bool isBrokenOut;
				if (book.IsCombatSkillBook())
				{
					short skillTemplateId = book.GetCombatSkillTemplateId();
					List<short> learnedSkills = character.GetLearnedCombatSkills();
					if (learnedSkills.Contains(skillTemplateId))
					{
						GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(charId2, skillTemplateId));
						ushort readingState = combatSkill.GetReadingState();
						ushort activationState = combatSkill.GetActivationState();
						byte bookPageTypes = book.GetPageTypes();
						readingProgress = new sbyte[6];
						pageTypes = new sbyte[6];
						sbyte outlinePageType = SkillBookStateHelper.GetOutlinePageType(bookPageTypes);
						byte outlineInternalIndex = CombatSkillStateHelper.GetOutlinePageInternalIndex(outlinePageType);
						readingProgress[0] = (sbyte)(CombatSkillStateHelper.IsPageRead(readingState, outlineInternalIndex) ? 100 : 0);
						pageTypes[0] = outlinePageType;
						for (byte i = 1; i < 6; i++)
						{
							sbyte normalPageType = SkillBookStateHelper.GetNormalPageType(bookPageTypes, i);
							byte internalIndex = CombatSkillStateHelper.GetNormalPageInternalIndex(normalPageType, i);
							readingProgress[i] = (sbyte)(CombatSkillStateHelper.IsPageRead(readingState, internalIndex) ? 100 : 0);
							pageTypes[i] = normalPageType;
						}
						isBrokenOut = CombatSkillStateHelper.IsBrokenOut(activationState);
					}
					else
					{
						readingProgress = new sbyte[6];
						pageTypes = new sbyte[6];
						isBrokenOut = false;
					}
				}
				else
				{
					short skillTemplateId = book.GetLifeSkillTemplateId();
					int learnedIndex = character.FindLearnedLifeSkillIndex(skillTemplateId);
					if (learnedIndex >= 0)
					{
						LifeSkillItem lifeSkill = character.GetLearnedLifeSkills()[learnedIndex];
						readingProgress = new sbyte[5];
						for (byte i2 = 0; i2 < 5; i2++)
						{
							readingProgress[i2] = (sbyte)(lifeSkill.IsPageRead(i2) ? 100 : 0);
						}
					}
					else
					{
						readingProgress = new sbyte[5];
					}
					pageTypes = new sbyte[5];
					isBrokenOut = false;
				}
				readProgressList.Add(new ReadProgressData(bookItemKey.TemplateId, readingProgress, pageTypes, isBrokenOut));
			}
			CharacterDisplayDataForTasterUltimate data = new CharacterDisplayDataForTasterUltimate
			{
				CharacterData = charDisplayData,
				ReadProgressList = readProgressList
			};
			dataList.Add(data);
		}
		return dataList;
	}

