	[DomainMethod]
	public ViewCharacterMenuDisplayData GetViewCharacterMenuDisplayData(DataContext context, int charId, List<int> charIdList)
	{
		ViewCharacterMenuDisplayData result = new ViewCharacterMenuDisplayData();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		List<int> resolvedCharIds = ((charId < 0) ? (charIdList ?? new List<int>()) : GetGroupSet(context, charId));
		if (charId >= 0 && TryGetElement_Objects(charId, out var leaderResolveCharacter))
		{
			int leaderId = leaderResolveCharacter.GetLeaderId();
			result.GroupLeaderId = ((leaderId == taiwuCharId) ? taiwuCharId : leaderId);
		}
		else
		{
			result.GroupLeaderId = -1;
		}
		if (charId >= 0)
		{
			resolvedCharIds.Sort(delegate(int l, int r)
			{
				if (l == taiwuCharId)
				{
					return -1;
				}
				if (r == taiwuCharId)
				{
					return 1;
				}
				bool flag = DomainManager.Taiwu.GetCharCombatGroupIndex(l) != -1;
				bool flag2 = DomainManager.Taiwu.GetCharCombatGroupIndex(r) != -1;
				if (flag && !flag2)
				{
					return -1;
				}
				return (!flag && flag2) ? 1 : l.CompareTo(r);
			});
		}
		result.CharacterDisplayDataList = GetCharacterDisplayDataList(resolvedCharIds);
		result.IsTaiwuTeam = resolvedCharIds.Contains(taiwuCharId);
		HashSet<int> taiwuGroupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		result.TaiwuTeamCharIds = new List<int>(taiwuGroupCharIds.Count);
		foreach (int id in taiwuGroupCharIds)
		{
			if (id >= 0)
			{
				result.TaiwuTeamCharIds.Add(id);
			}
		}
		List<int> specialGroup = DomainManager.Taiwu.GetTaiwuSpecialGroup();
		result.TaiwuSpecialGroup = new List<int>(specialGroup.Count);
		foreach (int id2 in specialGroup)
		{
			if (id2 >= 0)
			{
				result.TaiwuSpecialGroup.Add(id2);
			}
		}
		List<int> gearMateGroup = DomainManager.Taiwu.GetTaiwuGearMateGroup();
		result.TaiwuGearMateGroup = new List<int>(gearMateGroup.Count);
		foreach (int id3 in gearMateGroup)
		{
			if (id3 >= 0)
			{
				result.TaiwuGearMateGroup.Add(id3);
			}
		}
		result.NoNameInfantCharIds = new List<int>();
		foreach (int id4 in resolvedCharIds)
		{
			if ((GetNameAndLifeRelatedData(id4).NameRelatedData.FullName.Type & 0x10) != 0)
			{
				result.NoNameInfantCharIds.Add(id4);
			}
		}
		if (result.IsTaiwuTeam)
		{
			result.TaiwuGroupMaxDisplayCount = DomainManager.Taiwu.GetTaiwuGroupMaxCount() + 1 + result.TaiwuSpecialGroup.Count + DomainManager.Taiwu.GetGroupBabyCount();
		}
		return result;
	}

