	private CharacterDisplayData GetCharacterDisplayDataWithPotentialSuccessor(int charId, bool calcSuccessor)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		CharacterDisplayData data;
		DeadCharacter charData;
		if (_objects.ContainsKey(charId))
		{
			Character character = GetElement_Objects(charId);
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			bool isCompletelyInfected = character.IsCompletelyInfected();
			(ushort, ushort) relationBetweenCharacters = DomainManager.Character.GetRelationBetweenCharacters(charId, taiwuCharId);
			ushort relationToTaiwu = relationBetweenCharacters.Item1;
			ushort relationFromTaiwu = relationBetweenCharacters.Item2;
			Location location = character.GetLocation();
			data = new CharacterDisplayData
			{
				CharacterId = charId,
				TemplateId = character.GetTemplateId(),
				CreatingType = character.GetCreatingType(),
				Gender = character.GetGender(),
				FullName = character.GetFullName(),
				MonkType = character.GetMonkType(),
				MonasticTitle = character.GetMonasticTitle(),
				AvatarRelatedData = character.GenerateAvatarRelatedData(),
				PhysiologicalAge = character.GetPhysiologicalAge(),
				CurrAge = character.GetCurrAge(),
				ActualAge = character.GetActualAge(),
				OrgInfo = orgInfo,
				BehaviorType = character.GetBehaviorType(),
				FameType = character.GetFameType(),
				FavorabilityToTaiwu = (DomainManager.Character.IsInteractedWithTaiwu(charId) ? DomainManager.Character.GetFavorability(charId, taiwuCharId) : short.MinValue),
				TitleIds = new List<short>(),
				CompletelyInfected = isCompletelyInfected,
				ValidKidnapSlotCount = (byte)character.GetKidnapMaxSlotCount(),
				AliveState = 0,
				Location = location,
				BirthDate = character.GetBirthDate(),
				ExternalRelationState = character.GetExternalRelationState(),
				LegendaryBookOwnerState = character.GetLegendaryBookOwnerState(),
				LegendaryBooks = DomainManager.LegendaryBook.GetCharOwnedBookTypes(charId),
				CustomDisplayNameId = DomainManager.Extra.GetCharacterCustomDisplayName(charId),
				CanNotSpeak = character.CanNotSpeak,
				IsFollowedByTaiwu = DomainManager.Taiwu.IsCharacterFollowedByTaiwu(charId),
				NickNameId = DomainManager.Taiwu.GetFollowingNpcNickNameId(charId),
				ExtraNameTextTemplateId = character.GetExtraNameTextTemplateId(),
				IdealSect = character.GetIdealSect(),
				RelationToTaiwu = relationToTaiwu,
				RelationFromTaiwu = relationFromTaiwu,
				Charm = character.GetAttraction(),
				Health = character.GetHealth(),
				LeftMaxHealth = character.GetLeftMaxHealth(),
				HealthStateFlags = GetHealthStateFlags(character),
				DarkAshProtector = character.GetDarkAshProtector(),
				DarkAshCounter = character.GetDarkAshCounter(),
				Happiness = character.GetHappiness(),
				MerchantTemplateId = (sbyte)((character.GetOrganizationInfo().Grade == 4) ? DomainManager.Merchant.GetMerchantTemplateId(charId) : (-1)),
				IsSameFactionWithTaiwu = IsSameFaction(taiwuChar, character),
				FortuneExtraLegacyPointWorth = DomainManager.Extra.GetCharacterExtraLegacyPointWorth(charId),
				Personalities = character.GetPersonalities(),
				AttackMedal = character.GetFeatureMedalValue(0),
				DefenceMedal = character.GetFeatureMedalValue(1),
				WisdomMedal = character.GetFeatureMedalValue(2),
				SamsaraCount = (short)character.GetPreexistenceCharIds().Count,
				FeatureIds = character.GetFeatureIds(),
				AgeAffector = GetPhysiologicalAgeAffector(charId),
				ConsummateLevel = character.GetEffectiveConsummateLevel(),
				Alertness = DomainManager.Character.GetAlertnessValue(charId),
				MerchantType = DomainManager.Extra.GetMerchantCharToType(charId),
				MerchantExpData = DomainManager.Merchant.GetMerchantExpData(DomainManager.TaiwuEvent.MainThreadDataContext, charId, allowCreate: true),
				IsSearchedCharacter = DomainManager.Map.SearchedCharacter.Contains(charId),
				XiangshuType = character.GetXiangshuType()
			};
			if (character.GetCreatingType() == 1)
			{
				data.CurrentProfession = GetCharacterCurrentProfession(charId);
			}
			if (calcSuccessor && character.GetOrganizationInfo().SettlementId >= 0 && DomainManager.Organization.TryGetSettlementCharacter(charId, out var settlementChar))
			{
				data.IsApproveTaiwu = settlementChar.GetApprovedTaiwu();
				data.ApproveTaiwu = settlementChar.GetApprovingRate();
				data.InfluencePower = settlementChar.GetInfluencePower();
				short settlementId = settlementChar.GetSettlementId();
				SettlementTreasury settlementTreasury = DomainManager.Organization.GetTreasury(character.GetOrganizationInfo());
				data.Contribution = settlementTreasury.GetMemberContribution(character);
				data.ContributionPerMonth = character.GetContributionPerMonth();
				data.SettlementTreasuryGuardInfo = DomainManager.Organization.CharacterTreasuryGuardInfo(charId);
				if (settlementId >= 0)
				{
					Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
					ObjectPool<List<int>> pool = ObjectPool<List<int>>.Instance;
					List<int> successors = pool.Get();
					OrganizationInfo actualOrgInfo = orgInfo;
					actualOrgInfo.SettlementId = settlementId;
					successors.Clear();
					settlement.GetOrganizationMemberPotentialSuccessorsForDisplay(charId, actualOrgInfo, successors);
					if (successors.Count > 0)
					{
						data.OrganizationMemberPotentialSuccessor = GetCharacterDisplayDataWithPotentialSuccessor(successors[0], calcSuccessor: false);
					}
					pool.Return(successors);
				}
			}
			character.GetTitles(data.TitleIds);
			data.BountyPunishmentSeverity = -1;
			sbyte sectOrgTemplateId;
			SettlementBounty settlementBounty = DomainManager.Organization.GetBounty(charId, out sectOrgTemplateId);
			if (settlementBounty != null)
			{
				data.BountyPunishmentSeverity = settlementBounty.PunishmentSeverity;
				data.BountyOrgTemplate = sectOrgTemplateId;
			}
		}
		else if (_deadCharacters.TryGetValue(charId, out charData))
		{
			(ushort, ushort) relationBetweenCharacters2 = DomainManager.Character.GetRelationBetweenCharacters(charId, taiwuCharId);
			ushort relationToTaiwu2 = relationBetweenCharacters2.Item1;
			ushort relationFromTaiwu2 = relationBetweenCharacters2.Item2;
			Grave grave;
			Location location2 = (_graves.TryGetValue(charId, out grave) ? grave.GetLocation() : Location.Invalid);
			data = new CharacterDisplayData
			{
				CharacterId = charId,
				TemplateId = charData.TemplateId,
				Gender = charData.Gender,
				CurrAge = charData.CurrAge,
				ActualAge = charData.CurrAge,
				FullName = charData.FullName,
				MonkType = charData.MonkType,
				MonasticTitle = charData.MonasticTitle,
				AvatarRelatedData = charData.GenerateAvatarRelatedData(),
				OrgInfo = charData.OrganizationInfo,
				PhysiologicalAge = charData.CurrAge,
				BehaviorType = BehaviorType.GetBehaviorType(charData.Morality),
				FameType = charData.FameType,
				FavorabilityToTaiwu = (DomainManager.Character.IsInteractedWithTaiwu(charId) ? DomainManager.Character.GetFavorability(charId, taiwuCharId) : short.MinValue),
				AliveState = 1,
				Location = location2,
				BirthDate = charData.BirthDate,
				CustomDisplayNameId = DomainManager.Extra.GetCharacterCustomDisplayName(charId),
				IsFollowedByTaiwu = DomainManager.Taiwu.IsCharacterFollowedByTaiwu(charId),
				NickNameId = DomainManager.Taiwu.GetFollowingNpcNickNameId(charId),
				ExtraNameTextTemplateId = -1,
				IdealSect = -1,
				RelationToTaiwu = relationToTaiwu2,
				RelationFromTaiwu = relationFromTaiwu2,
				Charm = charData.Attraction,
				Health = 0,
				GraveDuration = (grave?.GetDurability() ?? 0),
				DeathDate = charData.DeathDate,
				Happiness = charData.Happiness,
				MerchantTemplateId = -1,
				Personalities = default(Personalities),
				AttackMedal = -1,
				DefenceMedal = -1,
				WisdomMedal = -1,
				BountyPunishmentSeverity = -1,
				SamsaraCount = (short)charData.PreexistenceCharIds.Count,
				FeatureIds = charData.FeatureIds,
				XiangshuType = 0
			};
		}
		else
		{
			data = new CharacterDisplayData
			{
				CharacterId = charId,
				AliveState = 2,
				Location = Location.Invalid,
				AvatarRelatedData = new AvatarRelatedData(),
				IsFollowedByTaiwu = DomainManager.Taiwu.IsCharacterFollowedByTaiwu(charId),
				NickNameId = DomainManager.Taiwu.GetFollowingNpcNickNameId(charId),
				IdealSect = -1,
				MerchantTemplateId = -1,
				RelationToTaiwu = ushort.MaxValue,
				RelationFromTaiwu = ushort.MaxValue,
				SamsaraCount = -1,
				BountyPunishmentSeverity = -1,
				FeatureIds = new List<short>(),
				XiangshuType = 0
			};
			data.AvatarRelatedData.AvatarData = new AvatarData();
		}
		return data;
	}

	private static sbyte GetHealthStateFlags(Character character)
	{
		sbyte flags = 0;
		Injuries injuries = character.GetInjuries();
		if (injuries.AnyOuter)
		{
			flags |= 1;
		}
		if (injuries.AnyInner)
		{
			flags |= 2;
		}
		if (character.GetPoisoned().IsNonZero())
		{
			flags |= 4;
		}
		if (character.GetDisorderOfQi() > 0)
		{
			flags |= 8;
		}
		return flags;
	}

	public static bool IsSameFaction(Character taiwuChar, Character character)
	{
		int taiwuFractionId = taiwuChar.GetFactionId();
		if (taiwuFractionId >= 0 && DomainManager.Organization.TryGetElement_Factions(taiwuFractionId, out var taiwuFraction) && taiwuFraction.GetCollection().Contains(character.GetId()))
		{
			return true;
		}
		int characterFractionId = character.GetFactionId();
		if (characterFractionId >= 0 && DomainManager.Organization.TryGetElement_Factions(characterFractionId, out var characterFraction) && characterFraction.GetCollection().Contains(taiwuChar.GetId()))
		{
			return true;
		}
		return false;
	}

