	public CharacterLocationDisplayData GetCharacterLocationDisplayDataByLocation(Location location)
	{
		CharacterLocationDisplayData result = new CharacterLocationDisplayData();
		result.CharacterId = -1;
		result.IsCapturedInStoneRoom = false;
		result.Location = location;
		if (result.Location.IsValid())
		{
			MapBlockData blockData = (result.BlockData = DomainManager.Map.GetBlockData(result.Location.AreaId, result.Location.BlockId));
			if (blockData.RootBlockId >= 0)
			{
				result.RootBlockData = DomainManager.Map.GetBlockData(result.Location.AreaId, blockData.RootBlockId);
			}
		}
		result.FullBlockName = DomainManager.Map.GetBlockFullName(result.Location);
		return result;
	}

	[DomainMethod]
	public CharacterLocationDisplayData GetCharacterLocationDisplayData(int charId)
	{
		CharacterLocationDisplayData result = new CharacterLocationDisplayData();
		result.CharacterId = charId;
		result.IsCapturedInStoneRoom = false;
		if (_objects.ContainsKey(charId))
		{
			result.DisplayType = 0;
			Character character = GetElement_Objects(charId);
			Location location = character.GetLocation();
			if (character.GetId() == GetOutterWorldCharacter())
			{
				location = Location.Invalid;
			}
			result.Location = location;
			int kidnapperId = character.GetKidnapperId();
			if (kidnapperId >= 0)
			{
				result.DisplayType = 1;
				result.Kidnapper = GetCharacterDisplayData(kidnapperId);
				result.Location = result.Kidnapper.Location;
			}
			if (character.IsActiveExternalRelationState(4uL))
			{
				IAdventureRuntime runtime = DomainManager.Adventure.QueryRuntimeWhereCharacterIn(character);
				result.AdventureCoreId = runtime?.CoreId ?? 0;
			}
			else if (character.IsActiveExternalRelationState(32uL))
			{
				sbyte orgTemplateId = DomainManager.Organization.GetPrisonerSect(character.GetId());
				Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
				result.Location = settlement.GetLocation();
			}
			ulong externRelation = character.GetExternalRelationState();
			result.IsCapturedInStoneRoom = ExternalRelationStateHelper.IsActive(externRelation, 8uL);
			GetBlockData();
			if (result.AdventureCoreId != 0)
			{
				result.DisplayType = 2;
			}
			result.FullBlockName = DomainManager.Map.GetBlockFullName(result.Location);
		}
		else if (_deadCharacters.ContainsKey(charId))
		{
			result.DisplayType = 3;
			result.Location = (_graves.TryGetValue(charId, out var grave) ? grave.GetLocation() : Location.Invalid);
			result.FullBlockName = DomainManager.Map.GetBlockFullName(result.Location);
			GetBlockData();
		}
		else
		{
			result.DisplayType = -1;
			result.Location = Location.Invalid;
			result.FullBlockName = DomainManager.Map.GetBlockFullName(result.Location);
		}
		return result;
		void GetBlockData()
		{
			if (result.Location.IsValid())
			{
				MapBlockData blockData = DomainManager.Map.GetBlockData(result.Location.AreaId, result.Location.BlockId);
				result.BlockData = blockData;
				if (blockData.RootBlockId >= 0)
				{
					result.RootBlockData = DomainManager.Map.GetBlockData(result.Location.AreaId, blockData.RootBlockId);
				}
			}
		}
	}

