	[DomainMethod]
	public List<CharacterDisplayDataForRelations> GetCharacterDisplayDataListForRelations(DataContext context, List<int> charIds)
	{
		List<CharacterDisplayDataForRelations> collection = new List<CharacterDisplayDataForRelations>();
		if (charIds == null)
		{
			return collection;
		}
		int i = 0;
		for (int count = charIds.Count; i < count; i++)
		{
			int charId = charIds[i];
			CharacterDisplayDataForRelations displayData = new CharacterDisplayDataForRelations
			{
				Main = GetCharacterDisplayDataForGeneralScrollList(context, charId),
				DeathDate = -1
			};
			DeadCharacter deadChar;
			if (TryGetElement_Objects(charId, out var character))
			{
				displayData.LifeState = 0;
				displayData.Location = character.GetLocation();
				if (displayData.Location.IsValid())
				{
					MapBlockData block = DomainManager.Map.GetBlock(displayData.Location);
					if (block == null || block.CharacterSet == null || !block.CharacterSet.Contains(charId))
					{
						displayData.Location = Location.Invalid;
					}
				}
			}
			else if (TryGetElement_DeadCharacters(charId, out deadChar))
			{
				displayData.LifeState = 1;
				displayData.DeathDate = deadChar.DeathDate;
				if (TryGetElement_Graves(charId, out var grave))
				{
					displayData.Location = grave.GetLocation();
				}
				else
				{
					displayData.Location = Location.Invalid;
				}
			}
			else
			{
				displayData.LifeState = 2;
			}
			collection.Add(displayData);
		}
		return collection;
	}

	[DomainMethod]
	public List<CharacterDisplayDataForRelations> GetCharacterDisplayDataListForRelationsWithRelationType(DataContext context, int currCharId, List<int> charIds)
	{
		List<CharacterDisplayDataForRelations> collection = GetCharacterDisplayDataListForRelations(context, charIds);
		for (int index = 0; index < collection.Count; index++)
		{
			CharacterDisplayDataForRelations displayData = collection[index];
			int charId = displayData.Main.CharacterId;
			ushort relationType = GetRelationBetweenCharacters(charId, currCharId).Item1;
			displayData.RelationType = relationType;
			collection[index] = displayData;
		}
		return collection;
	}

