	[DomainMethod]
	public CharacterInjuryDisplayData GetCharacterInjuryDisplayData(int charId)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return null;
		}
		(short, short, short, short, short) qiDisorderInfo = character.GetChangeOfQiDisorder();
		(short, short, short, short, short, short, short, short) healthRecoveryInfo = character.GetHealthRecovery(character.IsCompletelyInfected());
		CharacterInjuryDisplayData characterInjuryDisplayData = new CharacterInjuryDisplayData();
		characterInjuryDisplayData.Injuries = character.GetInjuries();
		characterInjuryDisplayData.CompleteDamageStepDisplayData = DomainManager.Combat.GetCompleteDamageStepDisplayData(charId);
		characterInjuryDisplayData.AllBodyPartExists = DomainManager.Character.GetCharacterAllBodyPartExists(charId);
		characterInjuryDisplayData.Poisons = character.GetPoisoned();
		characterInjuryDisplayData.PoisonResists = character.GetPoisonResists();
		characterInjuryDisplayData.DisorderOfQi = character.GetDisorderOfQi();
		characterInjuryDisplayData.ChangeOfQiDisorder = qiDisorderInfo.Item1;
		characterInjuryDisplayData.BuildingChangeQiDisorderValue = qiDisorderInfo.Item2;
		characterInjuryDisplayData.RecoveryOfQiDisorderChangeQiDisorderValue = qiDisorderInfo.Item3;
		characterInjuryDisplayData.EatItemChangeQiDisorderValue = qiDisorderInfo.Item4;
		characterInjuryDisplayData.FeatureChangeQiDisorderValue = qiDisorderInfo.Item5;
		characterInjuryDisplayData.Health = character.GetHealth();
		characterInjuryDisplayData.LeftMaxHealth = character.GetLeftMaxHealth();
		characterInjuryDisplayData.HealthRecovery = healthRecoveryInfo.Item1;
		characterInjuryDisplayData.DisorderOfQiChangeHealthValue = healthRecoveryInfo.Item2;
		characterInjuryDisplayData.InjuryChangeHealthValue = healthRecoveryInfo.Item3;
		characterInjuryDisplayData.PoisonChangeHealthValue = healthRecoveryInfo.Item4;
		characterInjuryDisplayData.BuildingChangeHealthValue = healthRecoveryInfo.Item5;
		characterInjuryDisplayData.EatItemChangeHealthValue = healthRecoveryInfo.Item6;
		characterInjuryDisplayData.FeatureChangeHealthValue = healthRecoveryInfo.Item7;
		characterInjuryDisplayData.HealthCombatMark = DefeatMarkCollection.GetHealthMarkCount((EHealthType)GetHealthType(character.GetId()));
		characterInjuryDisplayData.SpecialEffectChangeHealthValue = healthRecoveryInfo.Rest.Item1;
		characterInjuryDisplayData.CanEatingMaxCount = character.GetCurrMaxEatingSlotsCount();
		characterInjuryDisplayData.EatingItems = character.GetEatingItems();
		characterInjuryDisplayData.EatingItemDisplayDataArray = new ItemDisplayData[9];
		characterInjuryDisplayData.CurMainAttributes = character.GetCurrMainAttributes();
		characterInjuryDisplayData.MaxMainAttributes = character.GetMaxMainAttributes();
		characterInjuryDisplayData.MainAttributeRecoveries = GetMainAttributesRecoveries(charId);
		characterInjuryDisplayData.CharacterId = charId;
		characterInjuryDisplayData.TemplateId = character.Template.TemplateId;
		characterInjuryDisplayData.CombatCharacterDisplayData = DomainManager.Combat.GetCombatCharDisplayData(charId);
		characterInjuryDisplayData.IsImmune = new bool[6];
		characterInjuryDisplayData.IsBornImmune = new bool[6];
		characterInjuryDisplayData.InventoryMedicineItemCount = character.GetInventory().GetInventoryItemTypeCount(8);
		characterInjuryDisplayData.CurrNeili = character.GetCurrNeili();
		characterInjuryDisplayData.MaxNeili = character.GetMaxNeili();
		CharacterInjuryDisplayData data = characterInjuryDisplayData;
		for (sbyte poisonType = 0; poisonType < 6; poisonType++)
		{
			data.IsImmune[poisonType] = character.HasPoisonImmunity(poisonType);
			data.IsBornImmune[poisonType] = character.HasInnatePoisonImmunity(poisonType);
		}
		for (int i = 0; i < 9; i++)
		{
			ItemKey itemKey = data.EatingItems.Get(i);
			data.EatingItemDisplayDataArray[i] = (itemKey.HasTemplate ? (itemKey.IsValid() ? DomainManager.Item.GetItemDisplayData(itemKey, charId) : new ItemDisplayData(itemKey.ItemType, itemKey.TemplateId)) : null);
		}
		return data;
	}

	[DomainMethod]
	public CharacterUsingMedicineDisplayData GetCharacterUsingMedicineDisplayData(int charId)
	{
		DataContext context = DomainManager.TaiwuEvent.MainThreadDataContext;
		Character character = GetElement_Objects(charId);
		bool needAutoUseMedicine;
		Inventory autoUseMedicineInventory = DomainManager.Character.CheckAutoUseMedicine(context, charId, out needAutoUseMedicine);
		CharacterUsingMedicineDisplayData data = new CharacterUsingMedicineDisplayData
		{
			AttributeDisplayData = GetCharacterAttributeDisplayData(charId),
			InjuryDisplayData = GetCharacterInjuryDisplayData(charId),
			CurLoad = character.GetCurrInventoryLoad(),
			MaxLoad = character.GetMaxInventoryLoad(),
			MoveTimeCostPercent = DomainManager.Taiwu.GetMoveTimeCostPercent(),
			NeedAutoUseMedicine = needAutoUseMedicine,
			AutoUseMedicineInventory = autoUseMedicineInventory
		};
		bool isTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		bool isProfessionMeet = DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(54);
		Inventory inventory = new Inventory();
		foreach (var (itemKey2, amount) in character.GetInventory().Items)
		{
			if (itemKey2.ItemType == 8 || ItemTemplateHelper.IsTianJieFuLu(itemKey2.ItemType, itemKey2.TemplateId) || CanMaterialEat(itemKey2, isTaiwu, isProfessionMeet))
			{
				inventory.OfflineAdd(itemKey2, amount);
			}
		}
		data.ItemList = DomainManager.Item.GetItemDisplayDataListOptionalFromInventory(inventory, charId, 1);
		return data;
	}

