	public bool CanMaterialEat(ItemKey itemKey, bool isTaiwu, bool isProfessionMeet)
	{
		if (!isTaiwu)
		{
			return false;
		}
		return isProfessionMeet && itemKey.ItemType == 5 && Config.Material.Instance[itemKey.TemplateId].Grade > 6 && Config.Material.Instance[itemKey.TemplateId].ItemSubType == 505;
	}

	[DomainMethod]
	public CharacterItemsDisplayData GetCharacterItemsDisplayData(DataContext context, int charId)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return null;
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		CharacterItemsDisplayData data = new CharacterItemsDisplayData
		{
			CharacterLoveAndHateItemInfo = DomainManager.Character.GetCharacterLoveAndHateItemInfo(context, charId),
			CharacterDisplayData = DomainManager.Character.GetCharacterDisplayData(charId),
			TaiwuCharacterDisplayData = DomainManager.Character.GetCharacterDisplayData(taiwuCharId),
			Resources = character.GetResources(),
			LifeSkillAttainments = DomainManager.Taiwu.GetTaiwu().GetLifeSkillAttainments(),
			CurMainAttributes = DomainManager.Taiwu.GetTaiwu().GetCurrMainAttributes(),
			CurrNeili = DomainManager.Taiwu.GetTaiwu().GetCurrNeili(),
			MaxNeili = DomainManager.Taiwu.GetTaiwu().GetMaxNeili(),
			Exp = DomainManager.Taiwu.GetTaiwu().GetExp(),
			MaxWorthCanBeLentToTaiwu = DomainManager.Character.GetMaxWorthCanBeLentToTaiwu(charId),
			NeedleAmount = character.GetInventory().GetInventoryItemCount(12, 264),
			InventoryItems = DomainManager.Character.GetAllInventoryItems(charId),
			CurLoad = character.GetCurrInventoryLoad(),
			MaxLoad = character.GetMaxInventoryLoad(),
			MoveTimeCostPercent = DomainManager.Taiwu.GetMoveTimeCostPercent(),
			EmptyToolKey = DomainManager.Item.GetEmptyToolKey(context),
			DivineFlameData = DomainManager.Story.GetDivineFlameData()
		};
		List<ItemDisplayData> resourceItemList = DomainManager.Character.GetResourceItemDisplayDataList(charId);
		data.InventoryItems.AddRange(resourceItemList);
		IEnumerable<ItemDisplayData> equipItemList = from d in DomainManager.Character.GetAllEquipmentItems(charId)
			where d.Key.HasTemplate
			select d;
		data.InventoryItems.AddRange(equipItemList);
		if (charId == taiwuCharId && DomainManager.Taiwu.CanTransferItemToWarehouse(context))
		{
			data.NeedleAmount += DomainManager.Taiwu.GetWarehouseItemCount(12, 264);
			data.NeedleAmount += DomainManager.Taiwu.GetTaiwuTreasury().Inventory.GetInventoryItemCount(12, 264);
		}
		bool[] divineFlameTargetState = new bool[9];
		DivineFlameData divineFlameData = DomainManager.Story.GetDivineFlameData();
		if (divineFlameData.IsUnlocked)
		{
			for (sbyte i = 0; i < 9; i++)
			{
				divineFlameTargetState[i] = DomainManager.Story.CheckDivineFlameTarget(context, i);
			}
		}
		data.DivineFlameTargetState = divineFlameTargetState;
		int avoidDeathCharId = GetAvoidDeathCharId();
		data.DivineFlameTargetCharacter = ((avoidDeathCharId >= 0) ? GetCharacterDisplayData(avoidDeathCharId) : null);
		return data;
	}

	[DomainMethod]
	public unsafe CharacterSamsaraData GetCharacterSamsaraData(int charId)
	{
		List<DeadCharacter> characterList = new List<DeadCharacter>();
		List<NameRelatedData> nameList = new List<NameRelatedData>();
		Character character = GetElement_Objects(charId);
		PreexistenceCharIds preexistenceCharIds = character.GetPreexistenceCharIds();
		int i = 0;
		for (int max = preexistenceCharIds.Count; i < max; i++)
		{
			int preCharId = preexistenceCharIds.CharIds[i];
			DeadCharacter deadCharacter = DomainManager.Character.TryGetDeadCharacter(preCharId);
			characterList.Add(deadCharacter);
			NameRelatedData nameData = DomainManager.Character.GetNameRelatedData(preCharId);
			nameList.Add(nameData);
		}
		return new CharacterSamsaraData
		{
			DeadCharacters = characterList,
			DeadCharacterNames = nameList,
			PreexistenceCharIds = preexistenceCharIds
		};
	}

	[DomainMethod]
	public unsafe CharacterAttributeDisplayData GetEquipmentCompareData(DataContext context, int charId, sbyte srcSlot, sbyte destSlot, ItemKey srcItemKey)
	{
		Character character = GetElement_Objects(charId);
		ItemKey destItemKey = ((destSlot >= 0) ? character.GetEquipment()[destSlot] : ItemKey.Invalid);
		if (srcSlot >= 0)
		{
			srcItemKey = character.GetEquipment()[srcSlot];
		}
		character.ChangeEquipment(context, srcSlot, destSlot, srcItemKey);
		CharacterAttributeDisplayData data = GetCharacterAttributeDisplayData(charId);
		if (srcSlot < 0 && destItemKey.IsValid())
		{
			character.ChangeEquipment(context, srcSlot, destSlot, destItemKey);
		}
		else
		{
			character.ChangeEquipment(context, destSlot, srcSlot, srcItemKey);
		}
		MainAttributes currMainAttributes = character.GetCurrMainAttributes();
		MainAttributes maxMainAttributes = character.GetMaxMainAttributes();
		HitOrAvoidInts hitValues = character.GetHitValues();
		HitOrAvoidInts avoidValues = character.GetAvoidValues();
		OuterAndInnerInts penetrations = character.GetPenetrations();
		OuterAndInnerInts penetrationResists = character.GetPenetrationResists();
		OuterAndInnerShorts recoveryOfStanceAndBreath = character.GetRecoveryOfStanceAndBreath();
		for (sbyte type = 0; type < 6; type++)
		{
			ref short reference = ref data.CurMainAttributes.Items[type];
			reference -= currMainAttributes.Items[type];
			ref short reference2 = ref data.MaxMainAttributes.Items[type];
			reference2 -= maxMainAttributes.Items[type];
		}
		for (sbyte type2 = 0; type2 < 4; type2++)
		{
			ref int reference3 = ref data.AtkHitAttribute.Items[type2];
			reference3 -= hitValues.Items[type2];
			ref int reference4 = ref data.DefHitAttribute.Items[type2];
			reference4 -= avoidValues.Items[type2];
		}
		data.AtkPenetrability.Outer -= penetrations.Outer;
		data.AtkPenetrability.Inner -= penetrations.Inner;
		data.DefPenetrability.Outer -= penetrationResists.Outer;
		data.DefPenetrability.Inner -= penetrationResists.Inner;
		data.RecoveryOfStanceAndBreath.Outer -= recoveryOfStanceAndBreath.Outer;
		data.RecoveryOfStanceAndBreath.Inner -= recoveryOfStanceAndBreath.Inner;
		data.MoveSpeed -= character.GetMoveSpeed();
		data.RecoveryOfFlaw -= character.GetRecoveryOfFlaw();
		data.CastSpeed -= character.GetCastSpeed();
		data.RecoveryOfBlockedAcupoint -= character.GetRecoveryOfBlockedAcupoint();
		data.WeaponSwitchSpeed -= character.GetWeaponSwitchSpeed();
		data.AttackSpeed -= character.GetAttackSpeed();
		data.InnerRatio -= character.GetInnerRatio();
		data.RecoveryOfQiDisorder -= character.GetRecoveryOfQiDisorder();
		return data;
	}

	[DomainMethod]
	public unsafe List<CharacterAttributeDisplayData> GetEquipmentCompare(DataContext context, int charId, ItemKey[] baselineEquipment, ItemKey[] targetEquipment, sbyte slotIndex)
	{
		Character character = GetElement_Objects(charId);
		ItemKey[] originalEquipment = new ItemKey[baselineEquipment.Length];
		for (int i = 0; i < baselineEquipment.Length; i++)
		{
			originalEquipment[i] = character.GetEquipment()[i];
		}
		for (int j = 0; j < baselineEquipment.Length; j++)
		{
			ItemKey baselineItemKey = baselineEquipment[j];
			ItemKey targetItemKey = targetEquipment[j];
			Inventory inventory = character.GetInventory();
			if ((baselineItemKey != ItemKey.Invalid && !inventory.Items.ContainsKey(baselineItemKey) && character.GetEquipment()[j] != baselineItemKey) || (targetItemKey != ItemKey.Invalid && !inventory.Items.ContainsKey(targetItemKey) && character.GetEquipment()[j] != targetItemKey))
			{
				return null;
			}
		}
		character.ChangeEquipment(context, baselineEquipment);
		CharacterAttributeDisplayData baselineAttributes = GetCharacterAttributeDisplayData(charId);
		character.ChangeEquipment(context, targetEquipment);
		CharacterAttributeDisplayData targetAttributes = GetCharacterAttributeDisplayData(charId);
		character.ChangeEquipment(context, originalEquipment);
		if (targetEquipment.CheckIndex(slotIndex) && targetEquipment[slotIndex].IsValid())
		{
			ItemKey targetSlotItemKey = targetEquipment[slotIndex];
			ItemBase targetItem = DomainManager.Item.GetBaseItem(targetSlotItemKey);
			ItemBase itemBase = targetItem;
			ItemBase itemBase2 = itemBase;
			if (!(itemBase2 is GameData.Domains.Item.Weapon weapon))
			{
				if (itemBase2 is GameData.Domains.Item.Armor armor)
				{
					HitOrAvoidShorts armorAvoidFactors = ((charId >= 0) ? armor.GetAvoidFactors(charId) : armor.GetAvoidFactors());
					armor.GetPenetrationResistFactors().Deconstruct(out var armorOuterResistFactor, out var armorInnerResistFactor);
					ItemPowerInfo itemPowerInfo = DomainManager.Character.GetItemPowerInfo(charId, targetSlotItemKey);
					for (sbyte attackType = 0; attackType < 4; attackType++)
					{
						targetAttributes.DefHitAttribute.Items[attackType] = (short)(targetAttributes.DefHitAttribute.Items[attackType] * (100 + armorAvoidFactors.Items[attackType]) / 100);
					}
					targetAttributes.DefPenetrability.Outer = targetAttributes.DefPenetrability.Outer * (100 + armorOuterResistFactor) * itemPowerInfo.Power / 10000;
					targetAttributes.DefPenetrability.Inner = targetAttributes.DefPenetrability.Inner * (100 + armorInnerResistFactor) * itemPowerInfo.Power / 10000;
				}
			}
			else
			{
				HitOrAvoidShorts weaponHitFactors = ((charId >= 0) ? weapon.GetHitFactors(charId) : weapon.GetHitFactors());
				short weaponPenetrationFactor = weapon.GetPenetrationFactor();
				sbyte weaponInnerRatio = Config.Weapon.Instance[weapon.GetTemplateId()].DefaultInnerRatio;
				ItemPowerInfo itemPowerInfo2 = DomainManager.Character.GetItemPowerInfo(charId, targetSlotItemKey);
				for (sbyte attackType2 = 0; attackType2 < 4; attackType2++)
				{
					targetAttributes.AtkHitAttribute.Items[attackType2] = targetAttributes.AtkHitAttribute.Items[attackType2] * (100 + weaponHitFactors.Items[attackType2]) / 100;
				}
				targetAttributes.AtkPenetrability.Inner = (int)((float)targetAttributes.AtkPenetrability.Inner * (1f + (float)(weaponPenetrationFactor * weaponInnerRatio * itemPowerInfo2.Power) / 1000000f));
				targetAttributes.AtkPenetrability.Outer = (int)((float)targetAttributes.AtkPenetrability.Outer * (1f + (float)(weaponPenetrationFactor * (100 - weaponInnerRatio) * itemPowerInfo2.Power) / 1000000f));
			}
		}
		SubtractAttributes(targetAttributes, baselineAttributes);
		return new List<CharacterAttributeDisplayData> { baselineAttributes, targetAttributes };
	}

	[DomainMethod]
	public CharacterAttributeDisplayData GetAttributeDelta(DataContext context, int charId, ItemKey equipKey, int slot)
	{
		return GetAttributeWithDelta(context, charId, equipKey, slot)[1];
	}

	[DomainMethod]
	public unsafe CharacterAttributeDisplayData[] GetAttributeWithDelta(DataContext context, int charId, ItemKey equipKey, int slot = -1)
	{
		Character character = GetElement_Objects(charId);
		ItemKey[] originalEquipment = character.GetEquipment().ToArray();
		ItemKey[] baselineEquipment = originalEquipment.ToArray();
		int equippingSlot = originalEquipment.IndexOf(equipKey);
		if (equippingSlot != -1)
		{
			slot = equippingSlot;
		}
		CharacterAttributeDisplayData currDelta;
		CharacterAttributeDisplayData finalDelta;
		if (originalEquipment.CheckIndex(slot))
		{
			baselineEquipment[slot] = ItemKey.Invalid;
			character.ChangeEquipment(context, baselineEquipment);
			currDelta = GetCharacterAttributeDisplayData(charId);
			baselineEquipment[slot] = equipKey;
			character.ChangeEquipment(context, baselineEquipment);
			finalDelta = GetCharacterAttributeDisplayData(charId);
		}
		else
		{
			currDelta = GetCharacterAttributeDisplayData(charId);
			finalDelta = new CharacterAttributeDisplayData(currDelta);
		}
		int i = baselineEquipment.Length;
		while (i-- > 0)
		{
			baselineEquipment[i] = ItemKey.Invalid;
		}
		character.ChangeEquipment(context, baselineEquipment);
		CharacterAttributeDisplayData baselineAttributes = GetCharacterAttributeDisplayData(charId);
		if (originalEquipment.CheckIndex(slot) && equipKey.IsValid())
		{
			ItemKey targetSlotItemKey = equipKey;
			ItemBase targetItem = DomainManager.Item.GetBaseItem(targetSlotItemKey);
			ItemBase itemBase = targetItem;
			ItemBase itemBase2 = itemBase;
			if (!(itemBase2 is GameData.Domains.Item.Weapon weapon))
			{
				if (itemBase2 is GameData.Domains.Item.Armor armor)
				{
					HitOrAvoidShorts armorAvoidFactors = ((charId >= 0) ? armor.GetAvoidFactors(charId) : armor.GetAvoidFactors());
					armor.GetPenetrationResistFactors().Deconstruct(out var armorOuterResistFactor, out var armorInnerResistFactor);
					ItemPowerInfo itemPowerInfo = DomainManager.Character.GetItemPowerInfo(charId, targetSlotItemKey);
					for (sbyte attackType = 0; attackType < 4; attackType++)
					{
						finalDelta.DefHitAttribute.Items[attackType] = finalDelta.DefHitAttribute.Items[attackType] * (100 + armorAvoidFactors.Items[attackType]) / 100;
					}
					finalDelta.DefPenetrability.Outer = finalDelta.DefPenetrability.Outer * (10000 + armorOuterResistFactor * itemPowerInfo.Power) / 10000;
					finalDelta.DefPenetrability.Inner = finalDelta.DefPenetrability.Inner * (10000 + armorInnerResistFactor * itemPowerInfo.Power) / 10000;
				}
			}
			else
			{
				HitOrAvoidShorts weaponHitFactors = ((charId >= 0) ? weapon.GetHitFactors(charId) : weapon.GetHitFactors());
				short weaponPenetrationFactor = weapon.GetPenetrationFactor();
				WeaponItem weaponConfig = Config.Weapon.Instance[targetSlotItemKey.TemplateId];
				IntPair expect = ((charId == DomainManager.Taiwu.GetTaiwuCharId()) ? DomainManager.Combat.GetWeaponExpectInnerRatio(targetSlotItemKey) : new IntPair(weaponConfig.DefaultInnerRatio, 0));
				int baseRatio = weaponConfig.DefaultInnerRatio;
				int changeRange = weaponConfig.InnerRatioAdjustRange * expect.Second / 100;
				sbyte weaponInnerRatio = (sbyte)Math.Clamp(expect.First, Math.Max(baseRatio - changeRange, 0), Math.Min(baseRatio + changeRange, 100));
				ItemPowerInfo itemPowerInfo2 = DomainManager.Character.GetItemPowerInfo(charId, targetSlotItemKey);
				for (sbyte attackType2 = 0; attackType2 < 4; attackType2++)
				{
					finalDelta.AtkHitAttribute.Items[attackType2] = finalDelta.AtkHitAttribute.Items[attackType2] * (100 + weaponHitFactors.Items[attackType2]) / 100;
				}
				finalDelta.AtkPenetrability.Inner = (int)((float)finalDelta.AtkPenetrability.Inner * (1f + (float)(weaponPenetrationFactor * weaponInnerRatio * itemPowerInfo2.Power) / 1000000f));
				finalDelta.AtkPenetrability.Outer = (int)((float)finalDelta.AtkPenetrability.Outer * (1f + (float)(weaponPenetrationFactor * (100 - weaponInnerRatio) * itemPowerInfo2.Power) / 1000000f));
			}
		}
		character.ChangeEquipment(context, originalEquipment);
		SubtractAttributes(currDelta, finalDelta);
		SubtractAttributes(finalDelta, baselineAttributes);
		return new CharacterAttributeDisplayData[3] { baselineAttributes, finalDelta, currDelta };
	}

	private unsafe static void SubtractAttributes(CharacterAttributeDisplayData left, CharacterAttributeDisplayData right)
	{
		for (sbyte t = 0; t < 6; t++)
		{
			ref short reference = ref left.CurMainAttributes.Items[t];
			reference -= right.CurMainAttributes.Items[t];
			ref short reference2 = ref left.MaxMainAttributes.Items[t];
			reference2 -= right.MaxMainAttributes.Items[t];
		}
		for (sbyte t2 = 0; t2 < 4; t2++)
		{
			ref int reference3 = ref left.AtkHitAttribute.Items[t2];
			reference3 -= right.AtkHitAttribute.Items[t2];
			ref int reference4 = ref left.DefHitAttribute.Items[t2];
			reference4 -= right.DefHitAttribute.Items[t2];
		}
		left.AtkPenetrability.Outer -= right.AtkPenetrability.Outer;
		left.AtkPenetrability.Inner -= right.AtkPenetrability.Inner;
		left.DefPenetrability.Outer -= right.DefPenetrability.Outer;
		left.DefPenetrability.Inner -= right.DefPenetrability.Inner;
		left.RecoveryOfStanceAndBreath.Outer -= right.RecoveryOfStanceAndBreath.Outer;
		left.RecoveryOfStanceAndBreath.Inner -= right.RecoveryOfStanceAndBreath.Inner;
		left.MoveSpeed -= right.MoveSpeed;
		left.RecoveryOfFlaw -= right.RecoveryOfFlaw;
		left.CastSpeed -= right.CastSpeed;
		left.RecoveryOfBlockedAcupoint -= right.RecoveryOfBlockedAcupoint;
		left.WeaponSwitchSpeed -= right.WeaponSwitchSpeed;
		left.AttackSpeed -= right.AttackSpeed;
		left.InnerRatio -= right.InnerRatio;
		left.RecoveryOfQiDisorder -= right.RecoveryOfQiDisorder;
	}

