			Resources = default(ResourceInts),
			CurrInventoryLoad = -1,
			MaxInventoryLoad = -1,
			KidnapCount = -1,
			Gender = deadCharacter.Gender,
			PhysiologicalAge = deadCharacter.CurrAge,
			ClothDisplayId = deadCharacter.ClothingDisplayId,
			FaceVisible = FaceVisible(deadCharacter.Avatar, deadCharacter.ClothingDisplayId),
			CreatingType = Config.Character.Instance[deadCharacter.TemplateId].CreatingType,
			Command = default(SByteList),
			AdvancedCommand = default(SByteList),
			ConsummateLevel = deadCharacter.GetConsummateLevel(),
			IsSpecialGroupMember = false,
			AvatarRelatedData = deadCharacter.GenerateAvatarRelatedData(),
			OrgInfo = deadCharacter.OrganizationInfo,
			RelationToTaiwu = relationToTaiwu,
			RelationFromTaiwu = relationFromTaiwu,
			IsSameFactionWithTaiwu = false,
			IsCompanion = (charId != taiwuCharId && DomainManager.Taiwu.IsInGroup(charId)),
			HideHealth = false,
			XiangshuType = 0
		};
	}

	internal CharacterDisplayDataForGeneralScrollList GetCharacterDisplayDataForGeneralScrollList(DataContext context, int charId)
	{
		if (TryGetElement_Objects(charId, out var character))
		{
			return GetCharacterDisplayDataForGeneralScrollList(context, character);
		}
		if (TryGetElement_DeadCharacters(charId, out var deadCharacter))
		{
			return GetCharacterDisplayDataForGeneralScrollList(context, charId, deadCharacter);
		}
		return null;
	}

	private bool FaceVisible(AvatarData avatarData, short clothingDisplayId)
	{
		return !avatarData.ShowVeil && !avatarData.ShowMask(clothingDisplayId);
	}

	private bool HasIgnoreHealthMark(Character character)
	{
		foreach (short featureId in character.GetFeatureIds())
		{
			if (CharacterFeature.Instance[featureId].IgnoreHealthMark)
			{
				return true;
			}
		}
		return false;
	}

