	public List<VillagerCharDisplayData> GetCharDisplayDataListAsVillager(DataContext context, IEnumerable<int> charIds)
	{
		List<VillagerCharDisplayData> result = new List<VillagerCharDisplayData>();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		foreach (int charId in charIds)
		{
			if (!TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			VillagerWorkData villagerWorkData = DomainManager.Taiwu.GetVillagerWorkDict().GetValueOrDefault(charId, new VillagerWorkData
			{
				WorkType = -1
			});
			VillagerRoleBase villagerRole = villagerWorkData.GetVillagerRole() ?? DomainManager.Extra.GetVillagerRole(charId);
			short buildingBlockTemplateId = villagerWorkData.BlockTemplateId;
			sbyte workType = villagerWorkData.WorkType;
			bool flag = (uint)workType <= 1u;
			if (flag && villagerWorkData.BuildingBlockIndex >= 0)
			{
				BuildingBlockKey buildingBlockKey = new BuildingBlockKey(villagerWorkData.AreaId, villagerWorkData.BlockId, villagerWorkData.BuildingBlockIndex);
				if (DomainManager.Building.TryGetElement_BuildingBlocks(buildingBlockKey, out var buildingBlockData))
				{
					buildingBlockTemplateId = buildingBlockData.TemplateId;
				}
			}
			int swordTombId = -1;
			if (villagerRole is VillagerRoleSwordTombKeeper swordTombKeeper)
			{
				swordTombId = swordTombKeeper.XiangshuAvatarId;
			}
			VillagerCharDisplayData villagerCharDisplayData = new VillagerCharDisplayData();
			villagerCharDisplayData.CharacterId = charId;
			villagerCharDisplayData.CharacterTemplateId = character.GetTemplateId();
			villagerCharDisplayData.RoleTemplateId = DomainManager.Extra.GetVillagerRoleTemplateId(charId);
			villagerCharDisplayData.OrgInfo = character.GetOrganizationInfo();
			villagerCharDisplayData.ExternalRelation = character.GetExternalRelationState();
			villagerCharDisplayData.VillagerWorkData = villagerWorkData;
			villagerCharDisplayData.WorkStatus = DomainManager.Taiwu.GetVillagerWorkStatus(character);
			villagerCharDisplayData.ArrangementTemplateId = villagerRole?.ArrangementTemplateId ?? (-1);
			villagerCharDisplayData.BuildingBlockTemplateId = buildingBlockTemplateId;
			villagerCharDisplayData.IsBuyOperation = villagerRole is VillagerRoleMerchant villagerRoleMerchant && villagerRoleMerchant.ItemTemplateKey.ItemType >= 0;
			villagerCharDisplayData.GraveId = villagerWorkData.GraveId;
			villagerCharDisplayData.SwordTombId = swordTombId;
			villagerCharDisplayData.Location = character.GetLocation();
			villagerCharDisplayData.LocationNameRelatedData = DomainManager.Map.GetLocationNameRelatedData(character.GetLocation());
			villagerCharDisplayData.Potential = (DomainManager.Extra.TryGetElement_TaiwuVillagerPotentialData(charId, out var potential) ? (GlobalConfig.Instance.TaiwuVillagerMaxPotential - potential) : GlobalConfig.Instance.TaiwuVillagerMaxPotential);
			villagerCharDisplayData.Followed = DomainManager.Taiwu.IsCharacterFollowedByTaiwu(charId);
			villagerCharDisplayData.NameData = GetNameRelatedData(charId);
			villagerCharDisplayData.ActualAge = character.GetActualAge();
			villagerCharDisplayData.BirthDate = character.GetBirthDate();
			villagerCharDisplayData.Health = character.GetHealth();
			villagerCharDisplayData.MaxLeftHealth = character.GetLeftMaxHealth();
			villagerCharDisplayData.DefeatMarkCount = (sbyte)CombatDomain.GetDefeatMarksCountOutOfCombat(character);
			villagerCharDisplayData.Charm = character.GetAttraction();
			villagerCharDisplayData.BehaviorType = character.GetBehaviorType();
			villagerCharDisplayData.Fame = character.GetFame();
			villagerCharDisplayData.Happiness = ((DomainManager.Combat.IsInCombat() && DomainManager.Combat.IsCharInCombat(charId)) ? DomainManager.Combat.GetElement_CombatCharacterDict(charId).GetHappiness() : character.GetHappiness());
			villagerCharDisplayData.FavorabilityToTaiwu = (DomainManager.Character.IsInteractedWithTaiwu(charId) ? DomainManager.Character.GetFavorability(charId, taiwuCharId) : short.MinValue);
			villagerCharDisplayData.Alertness = GetAlertnessValue(charId);
			villagerCharDisplayData.IsInteractedWithTaiwu = DomainManager.Character.IsInteractedWithTaiwu(charId);
			villagerCharDisplayData.PreexistenceCharCount = (short)character.GetPreexistenceCharIds().Count;
			villagerCharDisplayData.AttackMedal = character.GetFeatureMedalValue(0);
			villagerCharDisplayData.DefenceMedal = character.GetFeatureMedalValue(1);
			villagerCharDisplayData.WisdomMedal = character.GetFeatureMedalValue(2);
			villagerCharDisplayData.MaxMainAttributes = character.GetMaxMainAttributes();
			villagerCharDisplayData.Penetrations = character.GetPenetrations();
			villagerCharDisplayData.PenetrationResists = character.GetPenetrationResists();
			villagerCharDisplayData.HitValues = character.GetHitValues();
			villagerCharDisplayData.AvoidValues = character.GetAvoidValues();
			villagerCharDisplayData.DisorderOfQi = character.GetDisorderOfQi();
			villagerCharDisplayData.LifeSkillQualifications = character.GetLifeSkillQualifications();
			villagerCharDisplayData.LifeSkillGrowthType = character.GetLifeSkillQualificationGrowthType();
			villagerCharDisplayData.CombatSkillQualifications = character.GetCombatSkillQualifications();
			villagerCharDisplayData.CombatSkillGrowthType = character.GetCombatSkillQualificationGrowthType();
			villagerCharDisplayData.Personalities = character.GetPersonalities();
			villagerCharDisplayData.Resources = character.GetResources();
			villagerCharDisplayData.CurrInventoryLoad = character.GetCurrInventoryLoad();
			villagerCharDisplayData.MaxInventoryLoad = character.GetMaxInventoryLoad();
			villagerCharDisplayData.KidnapCount = (sbyte)GetKidnappedCharacterCount(charId);
			villagerCharDisplayData.Gender = character.GetGender();
			villagerCharDisplayData.PhysiologicalAge = character.GetPhysiologicalAge();
			villagerCharDisplayData.ClothDisplayId = character.GetClothingDisplayId();
			villagerCharDisplayData.FaceVisible = !character.GetAvatar().ShowVeil && !character.GetAvatar().ShowMask(character.GetClothingDisplayId());
			villagerCharDisplayData.CreatingType = character.GetCreatingType();
			villagerCharDisplayData.Command = DomainManager.Extra.GetCharTeammateCommandsSByteList(context, charId);
			villagerCharDisplayData.AdvancedCommand = DomainManager.Extra.GetAdvancedCharTeammateCommandsSByteList(charId);
			villagerCharDisplayData.ConsummateLevel = character.GetConsummateLevel();
			villagerCharDisplayData.IsSpecialGroupMember = IsSpecialGroupMember(character);
			villagerCharDisplayData.AvatarRelatedData = character.GenerateAvatarRelatedData();
			villagerCharDisplayData.IsCompanion = DomainManager.Taiwu.IsInGroup(charId);
			villagerCharDisplayData.CombatSkillAttainments = character.GetCombatSkillAttainments();
			villagerCharDisplayData.LifeSkillAttainments = character.GetLifeSkillAttainments();
			villagerCharDisplayData.GeneralScrollListData = GetCharacterDisplayDataForGeneralScrollList(context, character);
			VillagerCharDisplayData displayData = villagerCharDisplayData;
			result.Add(displayData);
		}
		return result;
	}

