	[DomainMethod]
	public List<CharacterTableDisplayData> GetCharacterTableDisplayDataListWithNeedItem(DataContext context, List<short> types, ItemKey itemKey)
	{
		List<CharacterTableDisplayData> res = new List<CharacterTableDisplayData>();
		List<int> charIds = new List<int>();
		Dictionary<ItemKey, Dictionary<int, sbyte>> dicts = DomainManager.Taiwu.GetTreasuryNeededItemDict();
		Dictionary<int, sbyte> dict = dicts.GetValueOrDefault(itemKey);
		Dictionary<int, int> amountDict = new Dictionary<int, int>();
		foreach (int charId in dict.Keys)
		{
			charIds.Add(charId);
			amountDict[charId] = 0;
			foreach (var (otherItemKey, otherDict) in dicts)
			{
				if (otherItemKey.TemplateEquals(itemKey) && otherDict.ContainsKey(charId))
				{
					amountDict[charId]++;
				}
			}
		}
		foreach (int charId2 in charIds)
		{
			CharacterTableDisplayData data = GetCharacterTableDisplayData(context, charId2, types);
			data.SetInt(108, dict[charId2]);
			data.SetInt(109, amountDict[charId2]);
			res.Add(data);
		}
		if (types.Contains(94) || types.Contains(103))
		{
			foreach (int charId3 in charIds)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId3, out var kidnapped))
				{
					int kidnapperId = kidnapped.GetKidnapperId();
					if (Character.IsCharacterIdValid(kidnapperId))
					{
						Character character = DomainManager.Character.GetElement_Objects(kidnapperId);
						res.Add(new CharacterTableDisplayData
						{
							CharId = kidnapperId,
							CreatingType = character.GetCreatingType(),
							NameData = GetNameRelatedData(kidnapperId),
							AvatarData = character.GenerateAvatarRelatedData(),
							IsDisplayData = false
						});
					}
				}
			}
		}
		return res;
	}

