	public CharacterTableDisplayData GetCharacterTableDisplayData(DataContext context, int charId, List<short> types)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return GetDeadCharacterTableDisplayData(charId, types);
		}
		AvatarRelatedData avatarRelatedData = character.GenerateAvatarRelatedData();
		CharacterTableDisplayData data = new CharacterTableDisplayData
		{
			CharId = charId,
			CreatingType = character.GetCreatingType(),
			NameData = GetNameRelatedData(charId),
			AvatarData = avatarRelatedData,
			IsDisplayData = true
		};
		foreach (short type in types)
		{
			switch (type)
			{
			case 91:
				data.SetOrg(type, character.GetOrganizationInfo());
				break;
			case 92:
				data.SetOrg(type, character.GetOrganizationInfo());
				data.SetInt(96, GetCharacterTableIntData(context, character, 96));
				data.SetInt(2, GetCharacterTableIntData(context, character, 2));
				break;
			case 94:
			case 103:
				data.SetLocation(94, GetCharacterTableLocationData(character));
				break;
			case 77:
				data.SetInt(78, GetCharacterTableIntData(context, character, 78));
				data.SetInt(79, GetCharacterTableIntData(context, character, 79));
				break;
			case 5:
				data.SetInt(5, CharmType.Get(character.GetAttraction(), character.GetPhysiologicalAge(), avatarRelatedData.ClothingDisplayId, CreatingType.IsFixedPresetType(character.GetCreatingType()), avatarRelatedData.AvatarData.FaceVisible));
				data.SetInt(96, character.GetGender());
				break;
			case 46:
			case 61:
				data.SetInt(type, GetCharacterTableIntData(context, character, type));
				data.SetInt(97, character.GetActualAge());
				break;
			case 99:
			case 100:
			case 101:
				data.SetLocation(99, GetCharacterTableWorkLocationData(character));
				data.SetWork(99, GetCharacterTableWorkData(character));
				break;
			default:
				data.SetInt(type, GetCharacterTableIntData(context, character, type));
				break;
			case 0:
			case 1:
			case 108:
			case 109:
				break;
			}
		}
		return data;
	}

	public CharacterTableDisplayData GetDeadCharacterTableDisplayData(int charId, List<short> types)
	{
		if (!TryGetDeadCharacter(charId, out var deadCharacter))
		{
			return null;
		}
		CharacterItem config = Config.Character.Instance[deadCharacter.TemplateId];
		CharacterTableDisplayData data = new CharacterTableDisplayData
		{
			CharId = charId,
			CreatingType = config.CreatingType,
			NameData = GetNameRelatedData(charId),
			AvatarData = deadCharacter.GenerateAvatarRelatedData(),
			IsDisplayData = true
		};
		foreach (short type in types)
		{
			switch (type)
			{
			case 91:
				data.SetOrg(type, deadCharacter.OrganizationInfo);
				break;
			case 92:
				data.SetOrg(type, deadCharacter.OrganizationInfo);
				data.SetInt(96, GetDeadCharacterTableIntData(charId, deadCharacter, 96));
				data.SetInt(2, GetDeadCharacterTableIntData(charId, deadCharacter, 2));
				break;
			case 94:
			case 103:
				data.SetLocation(94, GetDeadCharacterTableLocationData(charId));
				break;
			case 77:
				data.SetInt(78, -1);
				data.SetInt(79, -1);
				break;
			case 5:
				data.SetInt(5, CharmType.Get(deadCharacter.Attraction, deadCharacter.CurrAge, deadCharacter.ClothingDisplayId, CreatingType.IsFixedPresetType(config.CreatingType), deadCharacter.Avatar.FaceVisible));
				data.SetInt(96, deadCharacter.Gender);
				break;
			case 46:
			case 61:
				data.SetInt(type, -1);
				data.SetInt(97, deadCharacter.GetActualAge());
				break;
			case 99:
			case 100:
			case 101:
				data.SetLocation(99, new CharacterTableLocationData());
				data.SetWork(99, default(CharacterTableWorkData));
				break;
			default:
				data.SetInt(type, GetDeadCharacterTableIntData(charId, deadCharacter, type));
				break;
			case 0:
			case 1:
			case 108:
			case 109:
				break;
			}
		}
		return data;
	}

