	[DomainMethod]
	public CharacterDisplayDataForGuard GetCharacterDisplayDataForGuard(DataContext context, int charId)
	{
		CharacterDisplayDataForGuard res = new CharacterDisplayDataForGuard
		{
			CharId = charId,
			GuardCanAffectInteract = false,
			IsMain = true,
			HasGuard = false
		};
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return res;
		}
		if (character.GetOrganizationInfo().OrgTemplateId == 16)
		{
			return res;
		}
		if (character.GetCreatingType() == 1)
		{
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			int targetLeader = character.GetLeaderId();
			List<Character> enemyTeam = new List<Character>();
			if (targetLeader >= 0)
			{
				AddGroupCharactersToCombatTeam(charId, targetLeader, enemyTeam, CombatType.Beat);
			}
			Span<short> span = stackalloc short[3];
			SpanList<short> guardTemplateIds = span;
			GetGuards(context, character, ref guardTemplateIds);
			SpanList<short>.Enumerator enumerator = guardTemplateIds.GetEnumerator();
			while (enumerator.MoveNext())
			{
				short templateId = enumerator.Current;
				enemyTeam.Add(GetPregeneratedRandomEnemy(Config.Character.Instance[templateId].RandomEnemyId));
			}
			GetStrongestThreeAndSelf(character, enemyTeam);
			enemyTeam.Sort((Character a, Character b) => -a.GetCombatPower().CompareTo(b.GetCombatPower()));
			res.HasGuard = HasGuard(charId, character);
			if (enemyTeam[0].GetId() != charId)
			{
				res.IsMain = false;
			}
			foreach (Character teammate in enemyTeam)
			{
				if (teammate.GetId() != charId)
				{
					res.Guards.Add(GetNameRelatedData(teammate.GetId()));
				}
			}
			if (orgInfo.SettlementId >= 0 && Config.Organization.Instance[orgInfo.OrgTemplateId].IsCivilian && res.HasGuard)
			{
				res.GuardCanAffectInteract = true;
			}
		}
		else
		{
			CharacterItem config = Config.Character.Instance[character.GetTemplateId()];
			if (config.MinionGroupId >= 0)
			{
				res.HasGuard = true;
				foreach (short templateId2 in MinionGroup.Instance[config.MinionGroupId].Minions)
				{
					res.Guards.Add(new NameRelatedData
					{
						CharTemplateId = templateId2,
						OrgGrade = Config.Character.Instance[templateId2].OrganizationInfo.Grade
					});
				}
			}
			else
			{
				res.HasGuard = false;
			}
		}
		return res;
	}

