	[DomainMethod]
	public CharacterDisplayDataForMapBlock GetCharacterDisplayDataForMapBlock(int charId)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			return null;
		}
		int skillCount = ((LocalStringManager.CurLanguageType == LocalStringManager.LanguageType.CN) ? 4 : 2);
		int defenseSkillCount = ((LocalStringManager.CurLanguageType != LocalStringManager.LanguageType.CN) ? 1 : 2);
		DataContext context = DataContextManager.GetCurrentThreadDataContext();
		Dictionary<ItemKey, int>.KeyCollection itemKeys = character.GetInventory().Items.Keys;
		int currDate = DomainManager.World.GetCurrDate();
		CharacterDisplayDataForMapBlock characterDisplayDataForMapBlock = new CharacterDisplayDataForMapBlock();
		characterDisplayDataForMapBlock.CharacterId = character.GetId();
		characterDisplayDataForMapBlock.TemplateId = character.GetTemplateId();
		characterDisplayDataForMapBlock.CreatingType = character.GetCreatingType();
		characterDisplayDataForMapBlock.NameRelatedData = DomainManager.Character.GetNameRelatedData(charId);
		characterDisplayDataForMapBlock.AvatarRelatedData = DomainManager.Character.GetAvatarRelatedData(charId);
		characterDisplayDataForMapBlock.Age = character.GetPhysiologicalAge();
		characterDisplayDataForMapBlock.Charm = character.GetAttraction();
		characterDisplayDataForMapBlock.Gender = character.GetGender();
		characterDisplayDataForMapBlock.HappinessType = character.GetHappinessType();
		characterDisplayDataForMapBlock.BehaviorType = character.GetBehaviorType();
		characterDisplayDataForMapBlock.FameType = character.GetFameType();
		characterDisplayDataForMapBlock.OrganizationInfo = character.GetOrganizationInfo();
		characterDisplayDataForMapBlock.IsReclusiveChar = DomainManager.Character.IsReclusive(charId);
		characterDisplayDataForMapBlock.Health = character.GetHealth();
		characterDisplayDataForMapBlock.LeftMaxHealth = character.GetLeftMaxHealth();
		characterDisplayDataForMapBlock.PreexistenceCharCount = (short)character.GetPreexistenceCharIds().Count;
		characterDisplayDataForMapBlock.AttackMedal = character.GetFeatureMedalValue(0);
		characterDisplayDataForMapBlock.DefenceMedal = character.GetFeatureMedalValue(1);
		characterDisplayDataForMapBlock.WisdomMedal = character.GetFeatureMedalValue(2);
		characterDisplayDataForMapBlock.ConsummateLevel = character.GetConsummateLevel();
		characterDisplayDataForMapBlock.BirthMonth = character.GetBirthMonth();
		characterDisplayDataForMapBlock.DisorderOfQi = character.GetDisorderOfQi();
		characterDisplayDataForMapBlock.NeiliProportionOfFiveElements = character.GetNeiliProportionOfFiveElements();
		characterDisplayDataForMapBlock.Injuries = character.GetInjuries();
		characterDisplayDataForMapBlock.Poisons = character.GetPoisoned();
		characterDisplayDataForMapBlock.TeammateCommands = DomainManager.Extra.GetCharTeammateCommands(context, charId);
		characterDisplayDataForMapBlock.LoveAndHateItemInfo = DomainManager.Character.GetCharacterLoveAndHateItemInfo(context, charId);
		characterDisplayDataForMapBlock.FavorabilityToTaiwu = (DomainManager.Character.IsInteractedWithTaiwu(charId) ? GetFavorability(charId, DomainManager.Taiwu.GetTaiwuCharId()) : short.MinValue);
		characterDisplayDataForMapBlock.Alertness = DomainManager.Character.GetAlertnessValue(charId);
		characterDisplayDataForMapBlock.MainAttributes = character.GetMaxMainAttributes();
		characterDisplayDataForMapBlock.CurrMainAttributes = character.GetCurrMainAttributes();
		characterDisplayDataForMapBlock.LifeSkillQualifications = character.GetLifeSkillQualifications();
		characterDisplayDataForMapBlock.LifeSkillAttainments = character.GetLifeSkillAttainments();
		characterDisplayDataForMapBlock.LifeSkillGrowthType = character.GetLifeSkillQualificationGrowthType();
		characterDisplayDataForMapBlock.CombatSkillQualifications = character.GetCombatSkillQualifications();
		characterDisplayDataForMapBlock.CombatSkillAttainments = character.GetCombatSkillAttainments();
		characterDisplayDataForMapBlock.CombatSkillGrowthType = character.GetCombatSkillQualificationGrowthType();
		characterDisplayDataForMapBlock.DivinePower = DomainManager.Character.GetCharacterDivinePower(charId);
		characterDisplayDataForMapBlock.GhostTechnique = DomainManager.Character.GetCharacterGhostTechnique(charId);
		characterDisplayDataForMapBlock.Personalities = character.GetPersonalities();
		characterDisplayDataForMapBlock.FeatureIds = character.GetFeatureIds();
		characterDisplayDataForMapBlock.EquipmentArray = character.GetEquipment();
		characterDisplayDataForMapBlock.SkillBookCountArray = DomainManager.Character.GetSkillBookLibraryGradeCount(charId);
		characterDisplayDataForMapBlock.LegendaryBookTypeList = DomainManager.LegendaryBook.GetCharOwnedBookTypes(charId);
		characterDisplayDataForMapBlock.DarkAshProtector = character.GetDarkAshProtector();
		characterDisplayDataForMapBlock.TitleIdList = new List<short>();
		characterDisplayDataForMapBlock.InfluencePower = (DomainManager.Organization.TryGetSettlementCharacter(charId, out var settlementChar) ? settlementChar.GetInfluencePower() : 0);
		characterDisplayDataForMapBlock.HighestGradeItemArray = (from k in itemKeys.Where(delegate(ItemKey k)
			{
				sbyte itemType = k.ItemType;
				return itemType != 0 && itemType != 10 && ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId) != 1202;
			})
			group k by (ItemType: k.ItemType, TemplateId: k.TemplateId) into g
			select g.First() into k
			orderby ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) descending
			select k).Take(0).ToArray();
		characterDisplayDataForMapBlock.HighestGradeCombatSkillBookArray = (from k in itemKeys
			where ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId) == 1001
			group k by (ItemType: k.ItemType, TemplateId: k.TemplateId) into g
			select g.First() into k
			orderby ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) descending
			select k).Take(0).ToArray();
		characterDisplayDataForMapBlock.HighestGradeLifeSkillBookArray = (from k in itemKeys
			where ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId) == 1000
			group k by (ItemType: k.ItemType, TemplateId: k.TemplateId) into g
			select g.First() into k
			orderby ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) descending
			select k).Take(0).ToArray();
		characterDisplayDataForMapBlock.RelationshipToTaiwuList = new List<short>(RelationDisplayType.Instance.Count);
		characterDisplayDataForMapBlock.RelationshipDict = new Dictionary<ushort, NameAndAvatarArray>(RelationDisplayType.Instance.Count);
		characterDisplayDataForMapBlock.RelationshipCountDict = new Dictionary<ushort, int>(RelationDisplayType.Instance.Count);
		characterDisplayDataForMapBlock.LearnedCombatSkillCountArray = character.GetLearnedCombatSkills().Aggregate(new short[9], delegate(short[] res, short id)
		{
			sbyte grade = Config.CombatSkill.Instance[id].Grade;
			if (res.CheckIndex(grade))
			{
				res[grade]++;
			}
			return res;
		});
		characterDisplayDataForMapBlock.LearnedHighestGradeNeigongCombatSkillArray = (from id in character.GetLearnedCombatSkills()
			where Config.CombatSkill.Instance[id].EquipType == 0
			orderby Config.CombatSkill.Instance[id].Grade descending
			select id).Take(skillCount).ToArray();
		characterDisplayDataForMapBlock.LearnedHighestGradeAttackCombatSkillArray = (from id in character.GetLearnedCombatSkills()
			where Config.CombatSkill.Instance[id].EquipType == 1
			orderby Config.CombatSkill.Instance[id].Grade descending
			select id).Take(skillCount).ToArray();
		characterDisplayDataForMapBlock.LearnedHighestGradeAgileCombatSkillArray = (from id in character.GetLearnedCombatSkills()
			where Config.CombatSkill.Instance[id].EquipType == 2
			orderby Config.CombatSkill.Instance[id].Grade descending
			select id).Take(skillCount).ToArray();
		characterDisplayDataForMapBlock.LearnedHighestGradeDefenseCombatSkillArray = (from id in character.GetLearnedCombatSkills()
			where Config.CombatSkill.Instance[id].EquipType == 3
			orderby Config.CombatSkill.Instance[id].Grade descending
			select id).Take(defenseSkillCount).ToArray();
		characterDisplayDataForMapBlock.LearnedHighestGradeAssistCombatSkillArray = (from id in character.GetLearnedCombatSkills()
			where Config.CombatSkill.Instance[id].EquipType == 4
			orderby Config.CombatSkill.Instance[id].Grade descending
			select id).Take(defenseSkillCount).ToArray();
		characterDisplayDataForMapBlock.TemporaryFeatureLeftTimes = (from featureId in character.GetFeatureIds()
			select CharacterFeature.Instance[featureId] into x
			where x != null
			select x).ToDictionary((CharacterFeatureItem key) => key.TemplateId, (CharacterFeatureItem value) => TryGetTemporaryFeatureExpireDate(charId, value.TemplateId, out var date) ? Math.Max(date - currDate, 0) : value.Duration);
		CharacterDisplayDataForMapBlock data = characterDisplayDataForMapBlock;
		if (character.GetCreatingType() == 1)
		{
			data.CurrentProfession = GetCharacterCurrentProfession(charId);
		}
		character.GetTitles(data.TitleIdList);
		characterDisplayDataForMapBlock = data;
		(Dictionary<short, bool>, int) visibleCharacterInteractionEventOptions = DomainManager.TaiwuEvent.GetVisibleCharacterInteractionEventOptions(charId);
		data.VisibleCharacterInteractionEventOptionDict = visibleCharacterInteractionEventOptions.Item1;
		characterDisplayDataForMapBlock.NoInteractionReason = visibleCharacterInteractionEventOptions.Item2;
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		RelatedCharacters relatedCharacters = DomainManager.Character.GetRelatedCharacters(charId);
		RelatedCharacter relatedCharacter;
		bool hasRelation = DomainManager.Character.TryGetRelation(taiwuCharId, charId, out relatedCharacter);
		Dictionary<ushort, int[]> distinctCounter = new Dictionary<ushort, int[]>();
		for (sbyte i = 0; i < 17; i++)
		{
			sbyte typeId = i;
			ushort type = RelationType.GetRelationType(typeId);
			RelationDisplayTypeItem relationDisplayTypeItem = null;
			RelationDisplayType.Instance.Iterate(delegate(RelationDisplayTypeItem r)
			{
				if (Enumerable.Contains(r.RelationTypeIds, typeId))
				{
					relationDisplayTypeItem = r;
					return false;
				}
				return true;
			});
			if (relationDisplayTypeItem != null)
			{
				short templateId = relationDisplayTypeItem.TemplateId;
				if (hasRelation && RelationType.HasRelation(relatedCharacter.RelationType, type))
				{
					data.RelationshipToTaiwuList.Add(templateId);
				}
				HashSet<int> collection = relatedCharacters?.GetCharacterSet(type).GetCollection();
				int collectionCount = collection?.Count ?? 0;
				if (collectionCount > 0)
				{
					int[] charIdList = (distinctCounter[type] = collection.ToArray());
					Array.Sort(charIdList, Sorter);
					data.RelationshipDict[type] = (from x in charIdList
						select new NameAndAvatar
						{
							Avatar = (DomainManager.Character.TryGetElement_Objects(x, out var element) ? element.GenerateAvatarRelatedData() : null),
							Name = GetNameRelatedData(x),
							CharId = x,
							IsTaiwu = (x == taiwuCharId)
						} into x
						orderby x.Avatar == null
						select x).Take(5).ToArray();
					data.RelationshipCountDict[type] = charIdList.Length;
				}
			}
		}
		Dictionary<ushort, NameAndAvatarArray> relationshipDict = data.RelationshipDict;
		IEnumerable<NameAndAvatar> data2 = data.RelationshipDict.GetValueOrDefault<ushort, NameAndAvatarArray>(2).Data;
		IEnumerable<NameAndAvatar> first = data2 ?? Enumerable.Empty<NameAndAvatar>();
		data2 = data.RelationshipDict.GetValueOrDefault<ushort, NameAndAvatarArray>(16).Data;
		IEnumerable<NameAndAvatar> first2 = first.Concat(data2 ?? Enumerable.Empty<NameAndAvatar>());
		data2 = data.RelationshipDict.GetValueOrDefault<ushort, NameAndAvatarArray>(128).Data;
		relationshipDict[146] = (from x in first2.Concat(data2 ?? Enumerable.Empty<NameAndAvatar>()).DistinctBy((NameAndAvatar x) => x.CharId)
			orderby x.Avatar == null
			select x).Take(5).ToArray();
		data.RelationshipCountDict[146] = distinctCounter.GetValueOrDefault<ushort, int[]>(2, Array.Empty<int>()).Concat(distinctCounter.GetValueOrDefault<ushort, int[]>(16, Array.Empty<int>())).Concat(distinctCounter.GetValueOrDefault<ushort, int[]>(128, Array.Empty<int>()))
			.Distinct()
			.Count();
		return data;
		int Sorter(int a, int b)
		{
			bool aliveA = IsCharacterAlive(a);
			bool aliveB = IsCharacterAlive(b);
			return (aliveA != aliveB) ? aliveB.CompareTo(aliveA) : a.CompareTo(b);
		}
	}

