	public Dictionary<short, HashSet<int>> GetAreaMerchantCharDict(int merchantType)
	{
		Dictionary<short, HashSet<int>> dict = new Dictionary<short, HashSet<int>>();
		foreach (KeyValuePair<int, Character> @object in _objects)
		{
			@object.Deconstruct(out var key, out var value);
			int charId = key;
			Character character = value;
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			OrganizationItem orgConfig = Config.Organization.Instance[orgInfo.OrgTemplateId];
			short memberTemplateId = orgConfig.Members[orgInfo.Grade];
			OrganizationMemberItem memberConfig = OrganizationMember.Instance[memberTemplateId];
			if (character.GetPhysiologicalAge() >= memberConfig.IdentityActiveAge && character.GetCreatingType() == 1 && (DomainManager.Extra.GetMerchantCharToType(charId) == merchantType || merchantType < 0))
			{
				short areaId = character.GetValidLocation().AreaId;
				MapAreaData areaData = DomainManager.Map.GetAreaByAreaId(areaId);
				short areaTemplateId = areaData.GetTemplateId();
				if (!dict.TryGetValue(areaTemplateId, out var set))
				{
					set = (dict[areaTemplateId] = new HashSet<int>());
				}
				set.Add(charId);
			}
		}
		return dict;
	}

