	private int GetLegendaryBookFeature(int charId)
	{
		List<short> featureIds = DomainManager.Character.GetElement_Objects(charId).GetFeatureIds();
		for (sbyte i = 0; i < 14; i++)
		{
			CombatSkillTypeItem config = Config.CombatSkillType.Instance[i];
			if (featureIds.Contains(config.LegendaryBookFeature))
			{
				return config.LegendaryBookFeature;
			}
			if (featureIds.Contains(config.LegendaryBookConsumedFeature))
			{
				return config.LegendaryBookConsumedFeature;
			}
		}
		return -1;
	}

