			}
		}
		return -1;
	}

	private CharacterTableLocationData GetDeadCharacterTableLocationData(int charId)
	{
		if (!TryGetElement_Graves(charId, out var grave))
		{
			return new CharacterTableLocationData();
		}
		Location location = grave.GetLocation();
		int adventureId = -1;
		int blockIndex = -1;
		sbyte stateTemplateId = -1;
		short areaTemplateId = -1;
		short blockTemplateId = -1;
		if (location.IsValid())
		{
			MapBlockData mapBlockData = DomainManager.Map.GetBlock(location);
			blockIndex = mapBlockData.GetBlockIndexInBigBlock(DomainManager.Map.GetAreaSize(location.AreaId));
			stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(location.AreaId);
			areaTemplateId = DomainManager.Map.GetElement_Areas(location.AreaId).GetTemplateId();
			blockTemplateId = mapBlockData.TemplateId;
		}
		CharacterTableLocationData result = new CharacterTableLocationData();
		result.AreaId = location.AreaId;
		result.BlockId = location.BlockId;
		result.BlockIndex = (sbyte)blockIndex;
		result.StateTemplateId = stateTemplateId;
		result.AreaTemplateId = areaTemplateId;
		result.BlockTemplateId = blockTemplateId;
		result.AdventureCoreId = 0;
		result.IsCapturedInStoneRoom = false;
		result.KidnapperId = -1;
		return result;
	}

	private CharacterTableLocationData GetCharacterTableLocationData(Character character)
	{
		int kidnapperId = character.GetKidnapperId();
		bool isInStoneRoom = DomainManager.Extra.GetStoneRoomCharList().Contains(character.GetId());
		Location location = (Character.IsCharacterIdValid(kidnapperId) ? DomainManager.Character.GetElement_Objects(kidnapperId).GetLocation() : character.GetLocation());
		int adventureId = DomainManager.Adventure.QueryRuntimeWhereCharacterIn(character)?.CoreId ?? 0;
		int blockIndex = -1;
		sbyte stateTemplateId = -1;
		short areaTemplateId = -1;
		short blockTemplateId = -1;
		if (DomainManager.Taiwu.GetTaiwuSpecialGroup().Contains(character.GetId()))
		{
			location = DomainManager.Taiwu.GetTaiwu().GetLocation();
		}
		if (location.IsValid())
		{
			MapBlockData mapBlockData = DomainManager.Map.GetBlock(location);
			blockIndex = mapBlockData.GetBlockIndexInBigBlock(DomainManager.Map.GetAreaSize(location.AreaId));
			stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(location.AreaId);
			areaTemplateId = DomainManager.Map.GetElement_Areas(location.AreaId).GetTemplateId();
			blockTemplateId = mapBlockData.TemplateId;
		}
		CharacterTableLocationData result = new CharacterTableLocationData();
		result.AreaId = location.AreaId;
		result.BlockId = location.BlockId;
		result.BlockIndex = (sbyte)blockIndex;
		result.StateTemplateId = stateTemplateId;
		result.AreaTemplateId = areaTemplateId;
		result.BlockTemplateId = blockTemplateId;
		result.AdventureCoreId = adventureId;
		result.IsCapturedInStoneRoom = isInStoneRoom;
		result.KidnapperId = kidnapperId;
		return result;
	}

	private CharacterTableLocationData GetCharacterTableWorkLocationData(Character character)
	{
		VillagerWorkData workData = DomainManager.Taiwu.GetVillagerWorkDict().GetValueOrDefault(character.GetId());
		if (workData != null)
		{
			CharacterTableLocationData result = new CharacterTableLocationData();
			result.AreaId = workData.AreaId;
			result.BlockId = workData.BlockId;
			result.StateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(workData.AreaId);
			result.AreaTemplateId = DomainManager.Map.GetElement_Areas(workData.AreaId).GetTemplateId();
			result.BlockTemplateId = workData.BlockTemplateId;
			return result;
		}
		return new CharacterTableLocationData();
	}

	private CharacterTableWorkData GetCharacterTableWorkData(Character character)
	{
		int charId = character.GetId();
		VillagerWorkData workData = DomainManager.Taiwu.GetVillagerWorkDict().GetValueOrDefault(charId);
		VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(charId);
		byte workStatus = DomainManager.Taiwu.GetVillagerWorkStatus(character);
		sbyte workType = -1;
		int arrangementTemplateId = -1;
		int id = -1;
		bool isLeader = false;
		bool boolValue = false;
		if (villagerRole != null)
		{
			if (villagerRole is VillagerRoleSwordTombKeeper { XiangshuAvatarId: >=0 } keeper)
			{
				id = keeper.XiangshuAvatarId;
			}
			if (villagerRole is VillagerRoleMerchant villagerRoleMerchant && villagerRoleMerchant.ItemTemplateKey.ItemType >= 0)
			{
				boolValue = true;
			}
			arrangementTemplateId = villagerRole.ArrangementTemplateId;
		}
		if (workData != null)
		{
			workType = workData.WorkType;
			BuildingBlockKey workLocation = new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex);
			if (DomainManager.Building.TryGetElement_BuildingBlocks(workLocation, out var blockData))
			{
				if (workType == 0 && blockData.OperationType == 0)
				{
					boolValue = true;
				}
				if (workType == 1 && BuildingBlock.Instance[blockData.TemplateId].ArtisanOrderAvailable)
				{
					boolValue = true;
				}
				bool flag = (uint)workType <= 1u;
				if (flag && workData.WorkerIndex == 0)
				{
					isLeader = true;
				}
				id = blockData.TemplateId;
			}
		}
		return new CharacterTableWorkData
		{
			WorkType = workType,
			WorkStatus = workStatus,
			ArrangementTemplateId = arrangementTemplateId,
			IntValue = id,
			BoolValue = boolValue,
			IsLeader = isLeader
		};
	}

