	[DomainMethod]
	public CharacterMenuInfoDisplayData GetCharacterMenuInfoDisplayData(DataContext context, int charId)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		bool isTaiwu = charId == taiwuCharId;
		if (!TryGetElement_Objects(charId, out var character))
		{
			return null;
		}
		CharacterMenuInfoDisplayData result = new CharacterMenuInfoDisplayData
		{
			CharacterDisplayData = GetCharacterDisplayData(charId),
			TaiwuDisplayData = (isTaiwu ? null : GetCharacterDisplayData(taiwuCharId)),
			InscriptionStatus = GetInscriptionStatus(charId),
			TeammateCommandList = (isTaiwu ? null : DomainManager.Extra.GetCharTeammateCommands(DataContextManager.GetCurrentThreadDataContext(), charId)),
			IsFollowingNpcListMax = DomainManager.Taiwu.GetIsFollowingNpcListMax(),
			IsTemporaryIntelligentCharacter = IsTemporaryIntelligentCharacter(charId),
			AdoredCoolDown = ((!isTaiwu) ? DomainManager.Extra.GetTaiwuAddOneWayRelationCoolDown(charId, isAdoreRelation: true) : 0),
			EnemyCoolDown = ((!isTaiwu) ? DomainManager.Extra.GetTaiwuAddOneWayRelationCoolDown(charId, isAdoreRelation: false) : 0),
			OneWayRelationResultCode = ((!isTaiwu) ? DomainManager.Extra.GetTaiwuAddOneWayRelationResultCode(charId) : 0),
			DebtsOfTaiwu = null,
			ChangedTeammateCharIds = DomainManager.Extra.GetChangedTeammateCharIds(),
			FiveLoongLocation = DomainManager.Extra.FiveLoongDict.Values.ToList(),
			IsInteractedCharacter = (isTaiwu || IsInteractedWithTaiwu(charId)),
			IsReclusiveChar = IsReclusive(charId),
			FameActionRecords = character.GetFameActionRecords(),
			LoveAndHateItemInfo = DomainManager.Character.GetCharacterLoveAndHateItemInfo(context, charId),
			IsTaiwu = character.IsTaiwu(),
			Alertness = DomainManager.Character.GetAlertnessValue(charId)
		};
		List<short> featureIds = character.GetFeatureIds();
		int currDate = DomainManager.World.GetCurrDate();
		result.TemporaryFeatureLeftTimes = new Dictionary<short, int>();
		foreach (short featureId in featureIds)
		{
			CharacterFeatureItem featureConfig = CharacterFeature.Instance[featureId];
			if (featureConfig != null && featureConfig.Type == ECharacterFeatureType.Temporary)
			{
				if (TryGetTemporaryFeatureExpireDate(charId, featureId, out var expireDate))
				{
					int leftTime = expireDate - currDate;
					result.TemporaryFeatureLeftTimes[featureId] = ((leftTime > 0) ? leftTime : 0);
				}
				else
				{
					result.TemporaryFeatureLeftTimes[featureId] = featureConfig.Duration;
				}
			}
		}
		return result;
	}

	public void UpdateDistantMarriages(DataContext context)
	{
		_taiwuRelatedDistanceMarriages.Clear();
		int passConditionCount = 0;
		int passSuccessRateCheckCount = 0;
		int foundTargetCount = 0;
		foreach (KeyValuePair<int, Character> @object in _objects)
		{
			@object.Deconstruct(out var key, out var value);
			int charId = key;
			Character character = value;
			EMarriageAgeGroup marriageAgeGroup = character.GetMarriageAgeGroup();
			if (!CanStartDistantMarriage(character))
			{
				continue;
			}
			passConditionCount++;
			int startChance = marriageAgeGroup.GetDistantMarriageChance();
			if (context.Random.CheckPercentProb(startChance))
			{
				passSuccessRateCheckCount++;
				if (UpdateDistantMarriage(context, character))
				{
					foundTargetCount++;
				}
			}
		}
		Logger.Info($"[DistantMarriage] PassConditionCount={passConditionCount}, PassSuccessRateCheckCount={passSuccessRateCheckCount}, FoundTargetCount={foundTargetCount}");
	}

	private bool UpdateDistantMarriage(DataContext context, Character character)
	{
		var (bestTargetChar, marriageType) = SelectDistantMarriageTarget(context, character);
		if (bestTargetChar == null)
		{
			return false;
		}
		int selfCharId = character.GetId();
		int targetCharId = bestTargetChar.GetId();
		if (TryGetRelation(selfCharId, DomainManager.Taiwu.GetTaiwuCharId(), out var relation) && relation.GetFavorabilityType() >= 4)
		{
			_taiwuRelatedDistanceMarriages.Add(selfCharId, (targetCharId, marriageType));
			DomainManager.World.GetMonthlyEventCollection().AddAiLongDistanceMarriageAskAdvice(selfCharId);
			return false;
		}
		ProcessDistantMarriage(context, selfCharId, targetCharId, marriageType, 0);
		return true;
	}

	public void ProcessDistantMarriage(DataContext context, int selfCharId, int targetCharId, EDistantMarriageType marriageType, short favorDelta = 0)
	{
		Character character = GetElement_Objects(selfCharId);
		Character bestTargetChar = GetElement_Objects(targetCharId);
		short selfSettlementId = character.GetOrganizationInfo().SettlementId;
		short targetSettlementId = bestTargetChar.GetOrganizationInfo().SettlementId;
		int currDate = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		switch (marriageType)
		{
		case EDistantMarriageType.SameArea:
			lifeRecordCollection.AddSameAreaDistantMarriage(selfCharId, currDate, targetSettlementId, targetCharId);
			lifeRecordCollection.AddSameAreaDistantMarriage(targetCharId, currDate, selfSettlementId, selfCharId);
			if (IsTaiwuPeople(selfCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage0(selfSettlementId, selfCharId, targetSettlementId, targetCharId);
			}
			else if (IsTaiwuPeople(targetCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage0(targetSettlementId, targetCharId, selfSettlementId, selfCharId);
			}
			break;
		case EDistantMarriageType.SameState:
			lifeRecordCollection.AddSameStateDistantMarriage(selfCharId, currDate, targetSettlementId, targetCharId);
			lifeRecordCollection.AddSameStateDistantMarriage(targetCharId, currDate, selfSettlementId, selfCharId);
			if (IsTaiwuPeople(selfCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage1(selfSettlementId, selfCharId, targetSettlementId, targetCharId);
			}
			else if (IsTaiwuPeople(targetCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage1(targetSettlementId, targetCharId, selfSettlementId, selfCharId);
			}
			break;
		case EDistantMarriageType.NeighborStates:
			lifeRecordCollection.AddDifferentStateDistantMarriage(selfCharId, currDate, targetSettlementId, targetCharId);
			lifeRecordCollection.AddDifferentStateDistantMarriage(targetCharId, currDate, selfSettlementId, selfCharId);
			if (IsTaiwuPeople(selfCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage2(selfSettlementId, selfCharId, targetSettlementId, targetCharId);
			}
			else if (IsTaiwuPeople(targetCharId))
			{
				monthlyNotifications.AddNpcLongDistanceMarriage2(targetSettlementId, targetCharId, selfSettlementId, selfCharId);
			}
			break;
		}
		character.AddGoal(context, 272, targetCharId);
		bestTargetChar.AddGoal(context, 272, selfCharId);
		DomainManager.Character.AddHusbandOrWifeRelations(context, selfCharId, targetCharId, currDate);
		DomainManager.Organization.UpdateOrganizationAfterMarriage(context, character, bestTargetChar);
		if (favorDelta != 0)
		{
			ChangeFavorabilityOptional(context, character, bestTargetChar, favorDelta, -1);
		}
	}

	public void GetDistantMarriage(int charId, out int targetCharId, out EDistantMarriageType type)
	{
