	}

	private Character SelectDistantMarriageTargetSameArea(DataContext context, Character selfChar, Settlement selfSettlement)
	{
		List<int> charList = context.AdvanceMonthRelatedData.TargetCharIdList.Occupy();
		MapAreaData areaData = DomainManager.Map.GetElement_Areas(selfSettlement.GetLocation().AreaId);
		short settlementId = selfSettlement.GetId();
		Character bestTargetChar = null;
		SettlementInfo[] settlementInfos = areaData.SettlementInfos;
		for (int i = 0; i < settlementInfos.Length; i++)
		{
			SettlementInfo settlementInfo = settlementInfos[i];
			if (settlementInfo.SettlementId >= 0 && settlementInfo.SettlementId != settlementId)
			{
				Settlement settlement = DomainManager.Organization.GetSettlement(settlementInfo.SettlementId);
				OrgMemberCollection members = settlement.GetMembers();
				members.GetAllMembers(charList);
				bestTargetChar = SelectDistantMarriageTarget(selfChar, charList, bestTargetChar);
			}
		}
		context.AdvanceMonthRelatedData.TargetCharIdList.Release(ref charList);
		return bestTargetChar;
	}

	private Character SelectDistantMarriageTargetSameState(DataContext context, Character selfChar, Settlement selfSettlement)
	{
		Location location = selfSettlement.GetLocation();
		sbyte stateId = DomainManager.Map.GetStateIdByAreaId(location.AreaId);
		List<short> areaIds = ObjectPool<List<short>>.Instance.Get();
		Character bestTargetChar = null;
		DomainManager.Map.GetAllAreaInState(stateId, areaIds);
		List<int> charList = context.AdvanceMonthRelatedData.TargetCharIdList.Occupy();
		foreach (short areaId in areaIds)
		{
			if (areaId == location.AreaId)
			{
				continue;
			}
			MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
			SettlementInfo[] settlementInfos = areaData.SettlementInfos;
			for (int i = 0; i < settlementInfos.Length; i++)
			{
				SettlementInfo settlementInfo = settlementInfos[i];
				if (settlementInfo.SettlementId >= 0)
				{
					Settlement settlement = DomainManager.Organization.GetSettlement(settlementInfo.SettlementId);
					OrgMemberCollection members = settlement.GetMembers();
					members.GetAllMembers(charList);
					bestTargetChar = SelectDistantMarriageTarget(selfChar, charList, bestTargetChar);
				}
			}
		}
		ObjectPool<List<short>>.Instance.Return(areaIds);
		context.AdvanceMonthRelatedData.TargetCharIdList.Release(ref charList);
		return bestTargetChar;
	}

	private Character SelectDistantMarriageTargetNeighborStates(DataContext context, Character selfChar, Settlement selfSettlement)
	{
		List<short> areaIds = ObjectPool<List<short>>.Instance.Get();
		Location location = selfSettlement.GetLocation();
		sbyte stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(location.AreaId);
		sbyte[] neighborStateTemplateIds = MapState.Instance[stateTemplateId].NeighborStates;
		List<int> charList = context.AdvanceMonthRelatedData.TargetCharIdList.Occupy();
		Character bestTargetChar = null;
		sbyte[] array = neighborStateTemplateIds;
		foreach (sbyte neighborStateTemplateId in array)
		{
			sbyte neighborStateId = DomainManager.Map.GetStateIdByStateTemplateId(neighborStateTemplateId);
			DomainManager.Map.GetAllAreaInState(neighborStateId, areaIds);
			foreach (short areaId in areaIds)
			{
				MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
				SettlementInfo[] settlementInfos = areaData.SettlementInfos;
				for (int j = 0; j < settlementInfos.Length; j++)
				{
					SettlementInfo settlementInfo = settlementInfos[j];
					if (settlementInfo.SettlementId >= 0)
					{
						Settlement settlement = DomainManager.Organization.GetSettlement(settlementInfo.SettlementId);
						OrgMemberCollection members = settlement.GetMembers();
						members.GetAllMembers(charList);
						bestTargetChar = SelectDistantMarriageTarget(selfChar, charList, bestTargetChar);
					}
				}
			}
		}
		context.AdvanceMonthRelatedData.TargetCharIdList.Release(ref charList);
		ObjectPool<List<short>>.Instance.Return(areaIds);
		return bestTargetChar;
	}

	private (Character targetChar, EDistantMarriageType type) SelectDistantMarriageTarget(DataContext context, Character character)
	{
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		Settlement selfSettlement = DomainManager.Organization.GetSettlement(orgInfo.SettlementId);
		Character bestTargetChar = SelectDistantMarriageTargetSameArea(context, character, selfSettlement);
		if (bestTargetChar != null)
		{
			return (targetChar: bestTargetChar, type: EDistantMarriageType.SameArea);
		}
		Character bestTargetChar2 = SelectDistantMarriageTargetSameState(context, character, selfSettlement);
		if (bestTargetChar2 != null)
		{
			return (targetChar: bestTargetChar2, type: EDistantMarriageType.SameState);
		}
		Character bestTargetChar3 = SelectDistantMarriageTargetNeighborStates(context, character, selfSettlement);
		if (bestTargetChar3 != null)
		{
			return (targetChar: bestTargetChar3, type: EDistantMarriageType.NeighborStates);
		}
		return (targetChar: null, type: EDistantMarriageType.None);
	}

	private Character SelectDistantMarriageTarget(Character character, IEnumerable<int> charIds, Character defaultTargetChar = null)
	{
		Character bestTargetChar = defaultTargetChar;
		foreach (int charId in charIds)
		{
			Character targetChar = GetElement_Objects(charId);
			if (CanBeDistantMarriageTarget(character, targetChar))
			{
				if (bestTargetChar == null)
				{
					bestTargetChar = targetChar;
				}
				else if (CompareCharacterForDistantMarriageTarget(character, targetChar, bestTargetChar) > 0)
				{
					bestTargetChar = targetChar;
				}
			}
		}
		return bestTargetChar;
	}

	private int CompareCharacterForDistantMarriageTarget(Character selfChar, Character first, Character second)
	{
		sbyte firstGrade = first.GetInteractionGrade(second);
		sbyte secondGrade = second.GetInteractionGrade(first);
		if (firstGrade != secondGrade)
		{
			return firstGrade.CompareTo(secondGrade);
		}
		short firstAge = first.GetCurrAge();
		short secondAge = second.GetCurrAge();
		if (firstAge != secondAge)
		{
			return secondAge.CompareTo(firstAge);
		}
		int selfCharId = selfChar.GetId();
		int firstCharId = first.GetId();
		int secondCharId = second.GetId();
		if (!TryGetRelation(selfCharId, firstCharId, out var selfToFirst))
		{
			selfToFirst = CreateFakeRelation(selfChar, first);
		}
		if (!TryGetRelation(firstCharId, selfCharId, out var firstToSelf))
		{
			firstToSelf = CreateFakeRelation(first, selfChar);
		}
		if (!TryGetRelation(selfCharId, secondCharId, out var selfToSecond))
		{
			selfToSecond = CreateFakeRelation(selfChar, second);
		}
		if (!TryGetRelation(secondCharId, selfCharId, out var secondToSelf))
		{
			secondToSelf = CreateFakeRelation(second, selfChar);
		}
		int firstSuccessRate = AiHelper.Relation.GetStartRelationSuccessRate_BoyOrGirlFriend(selfChar, first, selfToFirst, firstToSelf);
		int secondSuccessRate = AiHelper.Relation.GetStartRelationSuccessRate_BoyOrGirlFriend(selfChar, second, selfToSecond, secondToSelf);
		if (firstSuccessRate != secondSuccessRate)
		{
			return firstSuccessRate.CompareTo(secondSuccessRate);
		}
		return firstCharId.CompareTo(secondCharId);
	}

	private RelatedCharacter CreateFakeRelation(Character selfChar, Character relatedChar)
	{
		OrganizationMemberItem selfOrgMemberCfg = selfChar.GetOrganizationInfo().GetOrgMemberConfig();
		sbyte selfBehaviorType = selfChar.GetBehaviorType();
		(short, sbyte, sbyte, short, sbyte, sbyte, OrganizationMemberItem) targetData = GetInitialFavorabilityRelatedDataOfAliveChar(relatedChar, selfChar);
		int initialFavor = CalcInitialFavorability(selfOrgMemberCfg, targetData.Item1, targetData.Item2, targetData.Item3, targetData.Item4, selfBehaviorType, targetData.Item5, hasTaiwu: false, selfIsNotIntelligentCharacter: false);
		return new RelatedCharacter(0, (short)initialFavor, -1);
	}

	private bool CanStartDistantMarriage(Character character)
	{
		if (!character.IsInteractableAsIntelligentCharacter())
		{
			return false;
		}
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		int num;
		if (orgInfo.OrgTemplateId != 16 && orgInfo.OrgTemplateId != 0 && orgInfo.SettlementId >= 0 && orgInfo.Principal && !OrganizationDomain.IsSect(orgInfo.OrgTemplateId))
		{
			OrganizationMemberItem orgMemberConfig = character.GetOrganizationInfo().GetOrgMemberConfig();
			if (orgMemberConfig != null)
			{
				sbyte[] childGrade = orgMemberConfig.ChildGrade;
				if (childGrade != null)
				{
					num = ((childGrade.Length > 0) ? 1 : 0);
					goto IL_0078;
				}
			}
			num = 0;
			goto IL_0078;
		}
		goto IL_0082;
		IL_0082:
		return false;
		IL_0078:
		if (num != 0)
		{
			if (!MapAreaData.IsRegularArea(character.GetLocation().AreaId))
			{
				return false;
			}
			return GetAliveSpouse(character.GetId()) < 0 && character.GetMonkType() == 0 && !character.GetBisexual() && !character.IsInTaiwuGroup() && !DomainManager.Character.IsTemporaryIntelligentCharacter(character.GetId());
		}
		goto IL_0082;
	}

	private bool CanBeDistantMarriageTarget(Character selfChar, Character targetChar)
	{
		if (selfChar.GetGender() == targetChar.GetGender())
		{
			return false;
		}
		if (!DomainManager.Organization.CanPerformDistantMarriage(selfChar, targetChar))
		{
			return false;
		}
		if (!CanStartDistantMarriage(targetChar))
		{
			return false;
		}
		EMarriageAgeGroup selfMarriageAgeGroup = selfChar.GetMarriageAgeGroup();
		if (!selfMarriageAgeGroup.CheckMarriageTargetGradeInRange(selfChar.GetInteractionGrade(targetChar), targetChar.GetInteractionGrade(selfChar)))
		{
			return false;
		}
		if (!selfMarriageAgeGroup.CheckMarriageTargetAgeInRange(targetChar.GetGender(), targetChar.GetCurrAge()))
		{
			return false;
		}
		int selfCharId = selfChar.GetId();
		int targetCharId = targetChar.GetId();
		if (!RelationTypeHelper.AllowAddingHusbandOrWifeRelation(selfCharId, targetCharId))
		{
			return false;
		}
		if (HasEnemyRelationWithFamily(selfCharId, targetCharId) || HasEnemyRelationWithFamily(targetCharId, selfCharId))
		{
			return false;
		}
		return true;
	}

	public void UpdateAdoreRelationsInMarriage(DataContext context)
	{
		HashSet<RelationKey> marriedCouples = new HashSet<RelationKey>();
		foreach (var (charId, character2) in _objects)
		{
			if (!character2.IsInteractableAsIntelligentCharacter())
			{
				continue;
			}
			int spouseId = GetAliveSpouse(charId);
			if (spouseId >= 0)
			{
				RelationKey reverseKey = new RelationKey(spouseId, charId);
				if (!marriedCouples.Contains(reverseKey) && context.Random.CheckPercentProb(GlobalConfig.Instance.HusbandAndWifeStartAdoreChance) && !DomainManager.Character.IsAiActionInCooldown(charId, 4, 0) && !DomainManager.Character.IsAiActionInCooldown(spouseId, 4, 0) && (!HasRelation(charId, spouseId, 16384) || !HasRelation(charId, spouseId, 16384)))
				{
					marriedCouples.Add(new RelationKey(charId, spouseId));
				}
			}
		}
		sbyte cooldown = GlobalConfig.Instance.HusbandAndWifeStartAdoreCooldown;
		int addedCount = 0;
		foreach (RelationKey coupleRelationKey in marriedCouples)
		{
			DomainManager.Character.AddAiActionCooldown(context, coupleRelationKey.CharId, 4, 0, cooldown);
			DomainManager.Character.AddAiActionCooldown(context, coupleRelationKey.RelatedCharId, 4, 0, cooldown);
			Character selfChar = _objects[coupleRelationKey.CharId];
			Character relatedChar = _objects[coupleRelationKey.RelatedCharId];
			RelatedCharacter selfToTarget = GetRelation(coupleRelationKey.CharId, coupleRelationKey.RelatedCharId);
			RelatedCharacter targetToSelf = GetRelation(coupleRelationKey.RelatedCharId, coupleRelationKey.CharId);
			bool selfToTargetAdded = !RelationType.HasRelation(selfToTarget.RelationType, 16384) && UpdateOneWayAdoreRelationInMarriage(context, selfChar, relatedChar, selfToTarget, targetToSelf);
			bool targetToSelfAdded = !RelationType.HasRelation(targetToSelf.RelationType, 16384) && UpdateOneWayAdoreRelationInMarriage(context, relatedChar, selfChar, targetToSelf, selfToTarget);
			if (selfToTargetAdded || targetToSelfAdded)
			{
				addedCount++;
			}
		}
		Logger.Info($"Adore Relations In Marriage: {addedCount}/{marriedCouples.Count}");
	}

	private static bool UpdateOneWayAdoreRelationInMarriage(DataContext context, Character selfChar, Character targetChar, RelatedCharacter selfToTarget, RelatedCharacter targetToSelf)
	{
		int successRate = AiHelper.Relation.GetStartRelationSuccessRate_Adored(selfChar, targetChar, selfToTarget, targetToSelf);
		if (!context.Random.CheckPercentProb(successRate))
		{
			return false;
		}
		int charId = selfChar.GetId();
		int targetCharId = targetChar.GetId();
		int currDate = DomainManager.World.GetCurrDate();
		DomainManager.Character.AddRelation(context, charId, targetCharId, 16384, currDate);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		lifeRecordCollection.AddAdoreInMarriage(charId, currDate, targetCharId);
		selfChar.AddGoal(context, 272, targetCharId);
		return true;
	}

