	private static void InitializeBasicFeaturesPools()
	{
		_normalPositiveBasicFeaturesPool = new List<short>();
		_normalNegativeBasicFeaturesPool = new List<short>();
		_protagonistPositiveBasicFeaturesPool = new List<short>();
		_protagonistNegativeBasicFeaturesPool = new List<short>();
		foreach (CharacterFeatureItem item in (IEnumerable<CharacterFeatureItem>)CharacterFeature.Instance)
		{
			if (item == null || !item.Basic)
			{
				continue;
			}
			if (item.CandidateGroupId == 0)
			{
				for (int i = 0; i < item.AppearProb; i++)
				{
					_normalPositiveBasicFeaturesPool.Add(item.TemplateId);
				}
				for (int j = 0; j < item.ProtagonistAppearProb; j++)
				{
					_protagonistPositiveBasicFeaturesPool.Add(item.TemplateId);
				}
				continue;
			}
			if (item.CandidateGroupId == 1)
			{
				for (int k = 0; k < item.AppearProb; k++)
				{
					_normalNegativeBasicFeaturesPool.Add(item.TemplateId);
				}
				for (int l = 0; l < item.ProtagonistAppearProb; l++)
				{
					_protagonistNegativeBasicFeaturesPool.Add(item.TemplateId);
				}
				continue;
			}
			for (int m = 0; m < item.AppearProb; m++)
			{
				_normalPositiveBasicFeaturesPool.Add(item.TemplateId);
				_normalNegativeBasicFeaturesPool.Add(item.TemplateId);
			}
			for (int n = 0; n < item.ProtagonistAppearProb; n++)
			{
				_protagonistPositiveBasicFeaturesPool.Add(item.TemplateId);
				_protagonistNegativeBasicFeaturesPool.Add(item.TemplateId);
			}
		}
	}

	public static short GetBirthdayFeatureId(sbyte month)
	{
		return (short)(184 + month);
	}

	public unsafe static short GenerateOneYearOldCatchFeature(IRandomSource random)
	{
		sbyte* pProbabilities = stackalloc sbyte[12];
		int totalWeight = 0;
		for (int i = 0; i < 12; i++)
		{
			int featureId = 172 + i;
			totalWeight += (pProbabilities[i] = CharacterFeature.Instance[featureId].AppearProb);
		}
		int index = CollectionUtils.GetRandomWeightedElement(random, pProbabilities, 12, totalWeight);
		return (short)(172 + index);
	}

	public static short GetMergeableFeatureIdByLevel(short groupId, sbyte level)
	{
		if (level > 0)
		{
			return (short)(groupId + (level - 1));
		}
		if (level < 0)
		{
			return (short)(groupId + (2 - level));
		}
		return -1;
	}

	public static void GenerateLongevityFeatures(IRandomSource random, sbyte gender, List<short> featureIds)
	{
		Dictionary<short, short> featureGroup2Id = ObjectPool<Dictionary<short, short>>.Instance.Get();
		foreach (short featureId in featureIds)
		{
			featureGroup2Id[CharacterFeature.Instance[featureId].MutexGroupId] = featureId;
		}
		GenerateLongevityFeatures(random, gender, featureGroup2Id);
		foreach (short featureId2 in featureGroup2Id.Values)
		{
			if (!featureIds.Contains(featureId2))
			{
				featureIds.Add(featureId2);
			}
		}
		ObjectPool<Dictionary<short, short>>.Instance.Return(featureGroup2Id);
	}

	public static void GenerateLongevityFeatures(IRandomSource random, sbyte gender, Dictionary<short, short> featureGroup2Id)
	{
		List<short> actualPool = ObjectPool<List<short>>.Instance.Get();
		actualPool.Clear();
		foreach (CharacterFeatureItem config in (IEnumerable<CharacterFeatureItem>)CharacterFeature.Instance)
		{
			if ((config.Gender == -1 || config.Gender == gender) && config.Level == 1 && config.Basic && !featureGroup2Id.ContainsKey(config.MutexGroupId))
			{
				actualPool.Add(config.TemplateId);
			}
		}
		int maxCount = 6;
		if (actualPool.Count > 1)
		{
			CollectionUtils.Shuffle(random, actualPool);
		}
		for (int i = 0; i < actualPool.Count; i++)
		{
			if (random.CheckProb(maxCount, actualPool.Count - i))
			{
				maxCount--;
				CharacterFeatureItem config2 = CharacterFeature.Instance[actualPool[i]];
				featureGroup2Id.Add(config2.MutexGroupId, config2.TemplateId);
			}
		}
		ObjectPool<List<short>>.Instance.Return(actualPool);
	}

	public static (short groupId, short featureId) GetRandomBasicFeature(IRandomSource random, bool isProtagonist, sbyte gender, bool isPositive, Dictionary<short, short> featureGroup2Id)
	{
		List<short> featuresPool = ((!isProtagonist) ? (isPositive ? _normalPositiveBasicFeaturesPool : _normalNegativeBasicFeaturesPool) : (isPositive ? _protagonistPositiveBasicFeaturesPool : _protagonistNegativeBasicFeaturesPool));
		return GetRandomFeatureFromPool(random, gender, featuresPool, featureGroup2Id);
	}

	public static (short groupId, short featureId) GetRandomBasicFeature(IRandomSource random, bool isProtagonist, sbyte gender, bool isPositive, sbyte medalType, Dictionary<short, short> featureGroup2Id, sbyte maxLevel = 3)
	{
		List<short> featuresPool = ((!isProtagonist) ? (isPositive ? _normalPositiveBasicFeaturesPool : _normalNegativeBasicFeaturesPool) : (isPositive ? _protagonistPositiveBasicFeaturesPool : _protagonistNegativeBasicFeaturesPool));
		List<short> actualPool = featuresPool;
		if (medalType != 3 && isPositive)
		{
			actualPool = ObjectPool<List<short>>.Instance.Get();
			actualPool.Clear();
			foreach (short featureId in featuresPool)
			{
				if (CharacterFeature.Instance[featureId].FeatureMedals[medalType].Values.Count > 0 && CharacterFeature.Instance[featureId].Level <= maxLevel)
				{
					actualPool.Add(featureId);
				}
			}
		}
		(short, short) result = GetRandomFeatureFromPool(random, gender, actualPool, featureGroup2Id);
		if (actualPool != featuresPool)
		{
			ObjectPool<List<short>>.Instance.Return(actualPool);
		}
		return result;
	}

	public static (short groupId, short featureId) GetRandomFeatureFromPool(IRandomSource random, sbyte gender, List<short> featuresPool, Dictionary<short, short> featureGroup2Id)
	{
		int featuresPoolCount = featuresPool.Count;
		int maxTryCount = featuresPoolCount;
		for (int i = 0; i < maxTryCount; i++)
		{
			short featureId = featuresPool[random.Next(featuresPoolCount)];
			CharacterFeatureItem template = CharacterFeature.Instance[featureId];
			if (!featureGroup2Id.ContainsKey(template.MutexGroupId) && (template.Gender == -1 || template.Gender == gender))
			{
				return (groupId: template.MutexGroupId, featureId: featureId);
			}
		}
		Logger.Warn("GetRandomBasicFeature: give up due to exceeding maxTryCount.");
		return (groupId: -1, featureId: -1);
	}

