	public void RegisterCharacterTemporaryFeature(DataContext context, int charId, short featureTemplateId, int expireDate = -1)
	{
		CharacterFeatureItem config = CharacterFeature.Instance[featureTemplateId];
		if (config.Duration > 0 || expireDate >= 0)
		{
			IntPair key = new IntPair(charId, featureTemplateId);
			if (expireDate < 0)
			{
				expireDate = DomainManager.World.GetCurrDate() + config.Duration;
			}
			if (_characterTemporaryFeatures.ContainsKey(key))
			{
				SetElement_CharacterTemporaryFeatures(key, expireDate, context);
			}
			else
			{
				AddElement_CharacterTemporaryFeatures(key, expireDate, context);
			}
		}
	}

	public void UpdateCharacterTemporaryFeatures(DataContext context)
	{
		List<IntPair> toRemove = new List<IntPair>();
		int currDate = DomainManager.World.GetCurrDate();
		bool inAdventure = DomainManager.Adventure.GetAdventureTaiwu().InAdventure;
		foreach (KeyValuePair<IntPair, int> characterTemporaryFeature in _characterTemporaryFeatures)
		{
			characterTemporaryFeature.Deconstruct(out var key, out var value);
			IntPair pair = key;
			int date = value;
			CharacterFeatureItem config = CharacterFeature.Instance[pair.Second];
			if ((pair.Second == 216 && DomainManager.Character.TryGetElement_Objects(pair.First, out var character) && character.GetDarkAshProtector() != 512) || (config.BelongAdventure && inAdventure))
			{
				IntPair elementId = pair;
				Dictionary<IntPair, int> characterTemporaryFeatures = _characterTemporaryFeatures;
				key = pair;
				value = ++characterTemporaryFeatures[key];
				SetElement_CharacterTemporaryFeatures(elementId, value, context);
			}
			else if (currDate >= date)
			{
				toRemove.Add(pair);
			}
		}
		foreach (IntPair pair2 in toRemove)
		{
			int charId = pair2.First;
			short featureId = (short)pair2.Second;
			RemoveElement_CharacterTemporaryFeatures(pair2, context);
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character2))
			{
				character2.RemoveFeature(context, featureId);
			}
		}
	}

