	[DomainMethod]
	public void GmCmd_CreateRandomIntelligentCharacters(DataContext context, int charCount, sbyte orgTemplateId, bool createHere)
	{
		IRandomSource random = context.Random;
		OrganizationItem orgConfig = Config.Organization.Instance[orgTemplateId];
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
		BitArray gradePrincipalFullList = new BitArray(8, defaultValue: false);
		for (int i = 0; i < charCount; i++)
		{
			sbyte grade = (sbyte)random.Next(0, 8);
			if (orgTemplateId == 16)
			{
				grade = 0;
			}
			while (grade > 0 && CheckPrincipalFull(grade))
			{
				grade--;
			}
			short orgMemberId = orgConfig.Members[grade];
			OrganizationMemberItem orgMemberInfo = OrganizationMember.Instance[orgMemberId];
			Location location;
			short areaId;
			if (createHere)
			{
				location = DomainManager.Taiwu.GetTaiwu().GetLocation();
				areaId = ((settlement == null) ? ((short)random.Next(45)) : settlement.GetLocation().AreaId);
			}
			else
			{
				if (settlement == null)
				{
					areaId = (short)random.Next(45);
					short blockId = DomainManager.Map.GetMainSettlementMainBlockId(areaId);
					location = new Location(areaId, blockId);
				}
				else
				{
					location = settlement.GetLocation();
				}
				areaId = location.AreaId;
			}
			short settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(orgTemplateId);
			sbyte mapStateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(areaId);
			sbyte gender = ((orgMemberInfo.Gender == -1) ? Gender.GetRandom(random) : orgMemberInfo.Gender);
			short charTemplateId = Config.Organization.Instance[orgTemplateId].CharTemplateIds[gender];
			if (charTemplateId < 0)
			{
				charTemplateId = MapDomain.GetCharacterTemplateId(mapStateTemplateId, gender);
			}
			IntelligentCharacterCreationInfo info = new IntelligentCharacterCreationInfo(location, new OrganizationInfo(orgTemplateId, grade, principal: true, settlementId), charTemplateId);
			Character character = DomainManager.Character.CreateIntelligentCharacter(context, ref info);
			DomainManager.Character.CompleteCreatingCharacter(character.GetId());
		}
		bool CheckPrincipalFull(sbyte gradeId)
		{
			if (gradePrincipalFullList[gradeId])
			{
				return true;
			}
			short memberId = orgConfig.Members[gradeId];
			OrganizationMemberItem memberInfo = OrganizationMember.Instance[memberId];
			if (settlement != null && memberInfo.RestrictPrincipalAmount)
			{
				int principalAmount = 0;
				HashSet<int> gradeMembers = settlement.GetMembers().GetMembers(gradeId);
				foreach (int charId in gradeMembers)
				{
					if (DomainManager.Character.TryGetElement_Objects(charId, out var chara) && chara.GetOrganizationInfo().Principal)
					{
						principalAmount++;
					}
				}
				return gradePrincipalFullList[gradeId] = principalAmount >= memberInfo.Amount;
			}
			return false;
		}
	}

