	private static Character GmCmd_GetAliveCharByPreexistenceCharInternal(int preexistenceCharId)
	{
		List<Character> characters = new List<Character>();
		DomainManager.Character.FindIntelligentCharacters((Character character) => CharacterMatchers.MatchPreexistenceChar(character, preexistenceCharId), characters);
		if (characters.Count > 1)
		{
			throw new Exception($"More than one alive character own the preexistence: {preexistenceCharId}");
		}
		if (characters.Count == 1)
		{
			return characters[0];
		}
		return null;
	}

	[DomainMethod]
	public void GmCmd_LogCharacterSamsaraInfo()
	{
		foreach (KeyValuePair<int, Character> pair in _objects)
		{
			PreexistenceCharIds preexistenceCharIds = pair.Value.GetPreexistenceCharIds();
			if (preexistenceCharIds.Count > 0)
			{
				(string surname, string givenName) realName = GetRealName(pair.Value.GetId());
				string surName = realName.surname;
				string givenName = realName.givenName;
				Location location = pair.Value.GetLocation();
				MapAreaData areaData = DomainManager.Map.GetElement_Areas(location.AreaId);
				MapBlockData blockData = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId);
				Logger.Info($"{areaData.GetConfig().Name} {blockData.GetConfig().Name}: {surName}{givenName} preexistenceCharIds.Count = {preexistenceCharIds.Count}");
			}
		}
	}

