	[DomainMethod]
	public bool GmCmd_MoveIntelligentCharacter(DataContext context, int charId, Location destLocation)
	{
		if (DomainManager.Character.TryGetElement_Graves(charId, out var grave))
		{
			Events.RaiseGraveLocationChanged(context, charId, grave.GetLocation(), destLocation);
			grave.SetLocation(destLocation, context);
			return true;
		}
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			return false;
		}
		Character character = GetElement_Objects(charId);
		if (character.GetCreatingType() == 0)
		{
			Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), character.GetLocation(), destLocation);
			character.SetLocation(destLocation, context);
			return true;
		}
		Tester.Assert(character.GetCreatingType() == 1);
		Tester.Assert(!IsTemporaryIntelligentCharacter(charId));
		if (!character.GetLocation().IsValid())
		{
			return false;
		}
		int leaderId = character.GetLeaderId();
		if (leaderId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			return false;
		}
		if (leaderId >= 0)
		{
			LeaveGroup(context, character);
		}
		GroupMove(context, character, destLocation);
		return true;
	}

	[DomainMethod]
	public void GmCmd_RandomizeRelationShipsInSettlement(DataContext context, sbyte orgTemplateId)
	{
		ushort[] candidateRelationTypes = new ushort[8] { 64, 512, 1024, 2048, 4096, 8192, 16384, 32768 };
		short settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(orgTemplateId);
		List<int> charIds = new List<int>();
		DomainManager.Organization.GetSettlement(settlementId).GetMembers().GetAllMembers(charIds);
		foreach (int charId in charIds)
		{
			int relatedCharId = charIds[context.Random.Next(charIds.Count)];
			if (relatedCharId == charId)
			{
				continue;
			}
			int spouseCharId = GetLastSpouse(relatedCharId);
			if (spouseCharId >= 0 && spouseCharId == charId)
			{
				continue;
			}
			ushort relationType = candidateRelationTypes[context.Random.Next(candidateRelationTypes.Length)];
			if (!RelationTypeHelper.AllowAddingRelation(charId, relatedCharId, relationType))
			{
				continue;
			}
			switch (relationType)
			{
			case 64:
				AddAdoptiveParentRelations(context, charId, relatedCharId);
				if (spouseCharId >= 0)
				{
					AddAdoptiveParentRelations(context, charId, spouseCharId);
				}
				break;
			case 1024:
				AddHusbandOrWifeRelations(context, charId, relatedCharId);
				break;
			default:
				AddRelation(context, charId, relatedCharId, relationType);
				break;
			}
		}
	}

	[DomainMethod]
	public void GmCmd_MakeCharacterHaveSex(DataContext context, int selfCharId, int targetCharId, bool isRaped, int pregnantRemainTime)
	{
		if (!TryGetElement_Objects(selfCharId, out var father) || !TryGetElement_Objects(targetCharId, out var mother) || !Character.GetMakeLoveRole(context.Random, ref father, ref mother))
		{
			return;
		}
		mother.AddFeature(context, 197, removeMutexFeature: true);
		father.AddFeature(context, 197, removeMutexFeature: true);
		if (!mother.GetFeatureIds().Contains(198) && father.GetFertility() > 0 && mother.GetFertility() > 0 && !TryGetElement_PregnancyLockEndDates(mother.GetId(), out var _))
		{
			CreatePregnantState(context, mother, father, isRaped);
			if (TryGetElement_PregnantStates(mother.GetId(), out var pregnantState))
			{
				int currDate = DomainManager.World.GetCurrDate();
				pregnantState.ExpectedBirthDate = currDate + pregnantRemainTime;
				SetElement_PregnantStates(mother.GetId(), pregnantState, context);
			}
			mother.AddFeature(context, 198, removeMutexFeature: true);
		}
	}

