	[DomainMethod]
	public List<int> GmCmd_GetCharacterActualBloodParents(DataContext context, int charId)
	{
		List<int> result = new List<int>();
		if (TryGetElement_Objects(charId, out var _))
		{
			int fatherId = GetBloodParent(charId, 1);
			int motherId = GetBloodParent(charId, 0);
			result.Add(fatherId);
			result.Add(motherId);
			result.Add(TryGetActualBloodParent(fatherId, charId, out var actualFatherId) ? actualFatherId : (-1));
			result.Add(TryGetActualBloodParent(motherId, charId, out var actualMotherId) ? actualMotherId : (-1));
		}
		else
		{
			result.Add(-1);
			result.Add(-1);
			result.Add(-1);
			result.Add(-1);
		}
		return result;
	}

