	public List<List<CharacterDisplayData>> GmCmd_GetAllGroupMembers()
	{
		CharacterDomain characterDomain = DomainManager.Character;
		List<int> memberList = new List<int>();
		List<List<CharacterDisplayData>> result = new List<List<CharacterDisplayData>>();
		foreach (KeyValuePair<int, CharacterSet> group in _characterGroups)
		{
			memberList.Clear();
			memberList.AddRange(group.Value.GetCollection());
			memberList.Remove(group.Key);
			memberList.Insert(0, group.Key);
			result.Add(characterDomain.GetCharacterDisplayDataList(memberList));
		}
		return result;
	}

	[DomainMethod]
	public void GmCmd_GenerateRandomRefinedItemToCharacter(DataContext context, int charId, sbyte itemType, int times)
	{
		Character character = GetElement_Objects(charId);
		IRandomSource r = context.Random;
		short[] materials = (from m in Config.Material.Instance
			where m.RefiningEffect >= 0
			select m.TemplateId).ToArray();
		ItemDomain item = DomainManager.Item;
		sbyte itemType2 = itemType;
		if (1 == 0)
		{
		}
		int num = itemType switch
		{
			2 => r.Next(0, Config.Accessory.Instance.Count), 
			1 => r.Next(0, Config.Armor.Instance.Count), 
			4 => r.Next(0, Config.Carrier.Instance.Count), 
			3 => r.Next(0, Config.Clothing.Instance.Count), 
			11 => r.Next(0, Config.Cricket.Instance.Count), 
			7 => r.Next(0, Config.Food.Instance.Count), 
			5 => r.Next(0, Config.Material.Instance.Count), 
			8 => r.Next(0, Config.Medicine.Instance.Count), 
			12 => r.Next(0, Config.Misc.Instance.Count), 
			0 => r.Next(0, Config.Weapon.Instance.Count), 
			6 => r.Next(0, Config.CraftTool.Instance.Count), 
			10 => r.Next(0, Config.SkillBook.Instance.Count), 
			9 => r.Next(0, Config.TeaWine.Instance.Count), 
			_ => -1, 
		};
		if (1 == 0)
		{
		}
		ItemKey itemKey = item.CreateItem(context, itemType2, (short)num);
		ItemBase itemBase = DomainManager.Item.GetBaseItem(itemKey);
		times = Math.Min(times, 5);
		for (int i = 0; i < times; i++)
		{
			itemBase = DomainManager.Item.SetRefinedEffects(context, itemBase, i, materials.GetRandom(r)).item;
		}
		character.AddInventoryItem(context, itemBase.GetItemKey(), 1);
	}

