	[DomainMethod]
	public unsafe void GmCmd_DriveWugKing(DataContext context, int charId, sbyte wugType, bool isPositive)
	{
		if (!TryGetElement_Objects(charId, out var character))
		{
			AdaptableLog.Info($"[GmCmd_DriveWugKing] character {charId} not found.");
			return;
		}
		if (wugType == -1)
		{
			EatingItems eatingItems = character.GetEatingItems();
			for (int i = 0; i < 9; i++)
			{
				ItemKey itemKey = (ItemKey)eatingItems.ItemKeys[i];
				if (itemKey.IsValid() && EatingItems.IsWug(itemKey))
				{
					wugType = Config.Medicine.Instance[itemKey.TemplateId].WugType;
					break;
				}
			}
			if (wugType == -1)
			{
				AdaptableLog.Info($"[GmCmd_DriveWugKing] character {charId} has no wug in eating items.");
				return;
			}
		}
		DomainManager.Story.DriveWugKing(context, charId, wugType, (sbyte)(isPositive ? 1 : 2));
	}

