	public void GmCmd_ClearCharacterActionPlanningData(DataContext context, int charId)
	{
		if (_actionPlanningDataDict.TryGetValue(charId, out var planningData))
		{
			planningData.Goals?.Clear();
			for (int index = 0; index < planningData.Missions.Length; index++)
			{
				planningData.Missions[index] = null;
			}
			planningData.InterruptedActions?.Clear();
			planningData.PrimaryGoalActionPoint = 0;
			planningData.SecondaryGoalActionPoint = 0;
			planningData.UpdateActionPoints(ActionPlanningData.ECurrentGoalType.Primary);
			planningData.UpdateActionPoints(ActionPlanningData.ECurrentGoalType.Secondary);
			SetElement_ActionPlanningDataDict(charId, planningData, context);
		}
	}

	[DomainMethod]
	public void GmCmd_ClearAllActionPlanningData(DataContext context)
	{
		foreach (var (charId, planningData) in _actionPlanningDataDict)
		{
			planningData.Goals?.Clear();
			for (int index = 0; index < planningData.Missions.Length; index++)
			{
				planningData.Missions[index] = null;
			}
			planningData.InterruptedActions?.Clear();
			planningData.PrimaryGoalActionPoint = 0;
			planningData.SecondaryGoalActionPoint = 0;
			planningData.UpdateActionPoints(ActionPlanningData.ECurrentGoalType.Primary);
			planningData.UpdateActionPoints(ActionPlanningData.ECurrentGoalType.Secondary);
		}
	}

	private void InitializeSkeletonCharacterCache()
	{
		if (_skeletonCharacterCache == null)
		{
			_skeletonCharacterCache = new Dictionary<int, int>();
		}
		_skeletonCharacterCache.Clear();
		foreach (KeyValuePair<int, Grave> grafe in _graves)
		{
			grafe.Deconstruct(out var key, out var value);
			int graveId = key;
			Grave grave = value;
			int skeletonCharId = grave.GetSkeletonCharId();
			if (skeletonCharId >= 0)
			{
				_skeletonCharacterCache.Add(skeletonCharId, graveId);
			}
		}
	}

	public int GetSkeletonSourceGraveId(int skeletonCharId)
	{
		if (_skeletonCharacterCache.TryGetValue(skeletonCharId, out var graveId))
		{
			return graveId;
		}
		return -1;
	}

	public void GenerateSkeletons(DataContext context)
	{
		for (short areaId = 0; areaId < 45; areaId++)
		{
			Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(areaId);
			Span<MapBlockData> span = blocks;
			for (int i = 0; i < span.Length; i++)
			{
				MapBlockData block = span[i];
				if (block.GetConfig().SubType != EMapBlockSubType.Ruin || block.GraveSet == null)
				{
					continue;
				}
				foreach (int graveId in block.GraveSet)
				{
					Grave grave = _graves[graveId];
					int skeletonCharId = grave.GetSkeletonCharId();
					if (skeletonCharId < 0 && context.Random.CheckPercentProb(50))
					{
						CreateSkeletonCharacter(context, grave);
					}
				}
			}
		}
	}

	public void CreateGraveForFixedCharacter(DataContext context, Character fixedCharacter, Location location, sbyte level, int deathDate = int.MinValue)
	{
		Tester.Assert(fixedCharacter.GetCreatingType() == 0);
		int charId = fixedCharacter.GetId();
		deathDate = ((deathDate == int.MinValue) ? DomainManager.World.GetCurrDate() : deathDate);
		DeadCharacter deadChar = DeadCharacterHelper.CreateDeadCharacter(fixedCharacter, deathDate);
		AddElement_DeadCharacters(charId, deadChar, context);
		Grave grave = new Grave(context, fixedCharacter, location, level);
		AddElement_Graves(charId, grave);
		grave.SetLocation(location, context);
		Events.RaiseGraveLocationChanged(context, charId, Location.Invalid, grave.GetLocation());
		RemoveNonIntelligentCharacter(context, fixedCharacter);
	}

	public DeadCharacter SectMainStoryJingangCreateDeadMonk(DataContext context, Character fixedCharacter)
	{
		Tester.Assert(fixedCharacter.GetCreatingType() == 0);
		int charId = fixedCharacter.GetId();
		int deathDate = DomainManager.World.GetCurrDate();
		DeadCharacter deadChar = DeadCharacterHelper.CreateDeadCharacter(fixedCharacter, deathDate);
		FullName fullname = ConvertFixedCharacterName(context, fixedCharacter.GetTemplateId(), fixedCharacter.GetGender());
		deadChar.FullName = fullname;
		AddElement_DeadCharacters(charId, deadChar, context);
		RemoveNonIntelligentCharacter(context, fixedCharacter);
		return deadChar;
	}

	public bool IsGraveProtected(Grave grave)
	{
		int graveId = grave.GetId();
		Location location = grave.GetLocation();
		MapBlockData block = DomainManager.Map.GetBlock(location);
		if (block.CharacterSet == null)
		{
			return false;
		}
		foreach (int charId in block.CharacterSet)
		{
			if (DomainManager.Taiwu.TryGetElement_VillagerWork(charId, out var workData) && workData.WorkType == 12 && workData.GraveId == graveId)
			{
				return true;
			}
		}
		return false;
	}

	public void DecayGraves(DataContext context)
	{
		List<Grave> gravesToBeRemoved = new List<Grave>();
		HashSet<int> keptGraveSet = ObjectPool<HashSet<int>>.Instance.Get();
		DomainManager.Taiwu.GetKeptGraves(keptGraveSet);
		foreach (KeyValuePair<int, Grave> entry in _graves)
		{
			if (!keptGraveSet.Contains(entry.Key))
			{
				Grave grave = entry.Value;
				short durability = grave.GetDurability();
				if (durability > 1)
				{
					grave.SetDurability((short)(durability - 1), context);
				}
				else
				{
					gravesToBeRemoved.Add(grave);
				}
			}
		}
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int graveIdx = 0;
		for (int count = gravesToBeRemoved.Count; graveIdx < count; graveIdx++)
		{
			Grave grave2 = gravesToBeRemoved[graveIdx];
			RemoveGrave(context, grave2);
		}
		ObjectPool<HashSet<int>>.Instance.Return(keptGraveSet);
	}

	public void RemoveGrave(DataContext context, Grave grave)
	{
		int charId = grave.GetId();
		Location graveLoc = grave.GetLocation();
		int skeletonCharId = grave.GetSkeletonCharId();
		if (skeletonCharId >= 0)
		{
			RemoveNonIntelligentCharacter(context, _objects[skeletonCharId]);
		}
		ClearGraveItemsRelatedData();
		if (graveLoc.IsValid())
		{
			DomainManager.Map.GetRealNeighborBlocks(graveLoc.AreaId, graveLoc.BlockId, _graveNeighborBlocks, 1, includeCenter: true);
		}
		if (_graveNeighborBlocks.Count > 0)
		{
			Inventory inventory = grave.GetInventory();
			int blockCount = _graveNeighborBlocks.Count;
			foreach (var (itemKey2, amount) in inventory.Items)
			{
				if (ItemTemplateHelper.GetGrade(itemKey2.ItemType, itemKey2.TemplateId) >= 6)
				{
					int index = context.Random.Next(blockCount);
					_graveNeighborItems[index].Add((itemKey2, amount));
					DomainManager.Item.RemoveOwner(itemKey2, ItemOwnerType.Grave, charId);
				}
				else
				{
					DomainManager.Item.RemoveItem(context, itemKey2);
				}
			}
			for (int i = 0; i < blockCount; i++)
			{
				List<(ItemKey, int)> items = _graveNeighborItems[i];
				if (items.Count > 0)
				{
					DomainManager.Map.AddBlockItems(context, _graveNeighborBlocks[i], items);
				}
			}
		}
		else
		{
			DomainManager.Item.RemoveItems(context, grave.GetInventory().Items);
			Logger.Warn($"Grave {grave.GetId()} is at invalid location; all items are destroyed.");
		}
		RemoveElement_Graves(charId);
		DomainManager.LifeRecord.RemoveDead(charId);
		RecordGraveRemoved(context, charId);
		if (DomainManager.Character.IsTaiwuPeople(charId))
		{
			DomainManager.World.GetMonthlyNotificationCollection().AddGraveDestroyed(charId);
		}
		Events.RaiseGraveLocationChanged(context, charId, grave.GetLocation(), Location.Invalid);
	}

	private void InitializeGraveItemsRelatedData()
	{
		_graveNeighborBlocks = new List<MapBlockData>();
		_graveNeighborItems = new List<(ItemKey, int)>[9];
		for (int i = 0; i < 9; i++)
		{
			_graveNeighborItems[i] = new List<(ItemKey, int)>();
		}
	}

	private void ClearGraveItemsRelatedData()
	{
		_graveNeighborBlocks.Clear();
		for (int i = 0; i < 9; i++)
		{
			_graveNeighborItems[i].Clear();
		}
	}

	public void UpdateGroupFavorabilities(DataContext context)
	{
		foreach (CharacterSet value in _characterGroups.Values)
		{
			HashSet<int> collection = value.GetCollection();
			foreach (int selfCharId in collection)
			{
				Character selfChar = _objects[selfCharId];
				(short, short) range = AiHelper.UpdateStatusConstants.SameGroupFavorabilityChange[selfChar.GetBehaviorType()];
				foreach (int targetCharId in collection)
				{
					if (selfCharId != targetCharId)
					{
						Character targetChar = _objects[targetCharId];
						int favorDelta = context.Random.Next(range.Item1, range.Item2 + 1);
						ChangeFavorabilityOptionalMonthlyEvolution(context, selfChar, targetChar, favorDelta);
					}
				}
			}
		}
		DomainManager.Taiwu.UpdateTaiwuGroupFavorabilities(context);
	}

	public void JoinGroup(DataContext context, Character character, Character targetLeader)
	{
		int prevLeaderId = character.GetLeaderId();
		if (prevLeaderId >= 0)
		{
			return;
		}
		int charId = character.GetId();
		int groupLeaderId = targetLeader.GetId();
		int actualLeaderId = targetLeader.GetLeaderId();
		int currDate = DomainManager.World.GetCurrDate();
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			DomainManager.Taiwu.JoinGroup(context, charId);
			return;
		}
		if (character.IsCreatedWithFixedTemplate())
		{
			character.SetLeaderId(groupLeaderId, context);
			AddSpecialGroupCharacter(context, groupLeaderId, charId);
			return;
		}
		CharacterSet group;
		if (actualLeaderId < 0)
		{
			group = default(CharacterSet);
			group.Add(charId);
			character.SetLeaderId(groupLeaderId, context);
			AddElement_JoinGroupDates(charId, currDate, context);
			group.Add(groupLeaderId);
			targetLeader.SetLeaderId(groupLeaderId, context);
			AddElement_JoinGroupDates(groupLeaderId, currDate, context);
			AddElement_CharacterGroups(groupLeaderId, group, context);
		}
		else
		{
			group = GetElement_CharacterGroups(actualLeaderId);
			group.Add(charId);
			character.SetLeaderId(actualLeaderId, context);
			AddElement_JoinGroupDates(charId, currDate, context);
			SetElement_CharacterGroups(actualLeaderId, group, context);
		}
		foreach (int groupCharId in group.GetCollection())
		{
			if (groupCharId != charId)
			{
				TryCreateRelation(context, charId, groupCharId);
			}
		}
		Location srcLocation = character.GetLocation();
		Location destLocation = targetLeader.GetLocation();
		if (!srcLocation.Equals(destLocation))
		{
			character.SetLocation(destLocation, context);
			Events.RaiseCharacterLocationChanged(context, charId, srcLocation, destLocation);
		}
		if (targetLeader.IsActiveExternalRelationState(4uL))
		{
			HideSingleCharacterOnMap(context, character, 4uL);
		}
	}

	[DomainMethod]
	public List<int> GetGroupSet(DataContext context, int charId)
	{
		if (TryGetElement_Objects(charId, out var character))
		{
			List<int> retList = new List<int>();
			int leaderId = character.GetLeaderId();
			if (!_characterGroups.TryGetValue(leaderId, out var characterSet))
			{
				if (leaderId == DomainManager.Taiwu.GetTaiwuCharId())
				{
					foreach (int taiwuCharId in DomainManager.Taiwu.GetGroupCharIds().GetCollection())
					{
						retList.Add(taiwuCharId);
					}
				}
				else
				{
					retList.Add(charId);
				}
			}
			else
			{
				retList.Add(leaderId);
				foreach (int iterateCharId in characterSet.GetCollection())
				{
					if (!retList.Contains(iterateCharId))
					{
						retList.Add(iterateCharId);
					}
				}
			}
			int i = 0;
			for (int count = retList.Count; i < count; i++)
			{
				int memberId = retList[i];
				IReadOnlySet<int> specialGroup = GetSpecialGroup(memberId);
				retList.AddRange(specialGroup);
			}
			return retList;
		}
		throw new Exception($"{charId} is not an exist alive character");
	}

	public void LeaveGroup(DataContext context, Character character, bool bringWards = true)
	{
		int charId = character.GetId();
		int groupLeaderId = character.GetLeaderId();
		if (groupLeaderId < 0)
		{
			return;
		}
		if (groupLeaderId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			DomainManager.Taiwu.LeaveGroup(context, charId, bringWards);
			return;
		}
		if (character.IsCreatedWithFixedTemplate())
		{
			character.SetLeaderId(-1, context);
			TryRemoveSpecialGroupCharacter(context, groupLeaderId, charId);
			return;
		}
		if (!_characterGroups.TryGetValue(groupLeaderId, out var group))
		{
			Logger.Warn($"{character} trying to leave a non-existent group with leader {groupLeaderId}");
			if (_objects.ContainsKey(charId))
			{
				character.SetLeaderId(-1, context);
			}
			return;
		}
		HashSet<int> wards = ObjectPool<HashSet<int>>.Instance.Get();
		if (bringWards)
		{
			GetWardsInGroup(character, group, wards);
		}
		Location validLocation = character.GetLocation();
		if (!validLocation.IsValid())
		{
			validLocation = character.GetValidLocation();
		}
		if (groupLeaderId == charId)
		{
			IEnumerable<IAdventureRuntime> adventures = DomainManager.Adventure.QueryAnyInLocation(validLocation);
			HashSet<int> calledCharacters = null;
			foreach (IAdventureRuntime adventure in adventures)
			{
				if (calledCharacters == null)
				{
					calledCharacters = ObjectPool<HashSet<int>>.Instance.Get();
					calledCharacters.Clear();
				}
				adventure.CollectCharacters(calledCharacters);
			}
			foreach (int memberId in group.GetCollection())
			{
				if (TryGetElement_Objects(memberId, out var member))
				{
					member.SetLeaderId(-1, context);
					if (!member.GetLocation().IsValid())
					{
						member.SetLocation(validLocation, context);
					}
					if (member.IsActiveExternalRelationState(4uL) && !(calledCharacters?.Contains(memberId) ?? false))
					{
						UnhideSingleCharacterOnMap(context, member, 4uL);
					}
				}
				RemoveElement_JoinGroupDates(memberId, context);
			}
			if (calledCharacters != null)
			{
				ObjectPool<HashSet<int>>.Instance.Return(calledCharacters);
			}
			group.Clear();
			RemoveElement_CharacterGroups(groupLeaderId, context);
			if (bringWards)
			{
				ChangeGroup(context, wards, character);
			}
			ObjectPool<HashSet<int>>.Instance.Return(wards);
			return;
		}
		group.Remove(charId);
		RemoveElement_JoinGroupDates(charId, context);
		if (group.GetCount() > 1)
		{
			SetElement_CharacterGroups(groupLeaderId, group, context);
		}
		else
		{
			RemoveElement_CharacterGroups(groupLeaderId, context);
			RemoveElement_JoinGroupDates(groupLeaderId, context);
			if (TryGetElement_Objects(groupLeaderId, out var leader))
			{
				leader.SetLeaderId(-1, context);
			}
		}
		if (_objects.ContainsKey(charId))
		{
			if (!character.GetLocation().IsValid())
			{
				character.SetLocation(validLocation, context);
			}
			character.SetLeaderId(-1, context);
		}
		if (bringWards)
		{
			ChangeGroup(context, wards, character);
		}
		ObjectPool<HashSet<int>>.Instance.Return(wards);
	}

	public void GetWardsInGroup(Character character, CharacterSet group, HashSet<int> wards)
	{
		wards.Clear();
		if (character.GetAgeGroup() == 0)
		{
			return;
		}
		RelatedCharacters relatedChars = _relatedCharIds[character.GetId()];
		HashSet<int> groupCollection = group.GetCollection();
		int selfCharId = character.GetId();
		sbyte selfGender = character.GetGender();
		foreach (int groupCharId in groupCollection)
		{
			Character groupChar = _objects[groupCharId];
			if (groupChar.GetAgeGroup() == 0 && groupCharId != selfCharId && !HasBetterGuardianInGroup(selfCharId, GetRelation(selfCharId, groupCharId).RelationType, selfGender, groupCharId, groupCollection))
			{
				wards.Add(groupCharId);
			}
		}
	}

	private bool HasBetterGuardianInGroup(int selfCharId, ushort relationType, sbyte selfGender, int wardCharId, HashSet<int> group)
	{
		bool containsStepParent = !RelationType.HasRelation(relationType, 2);
		if (!containsStepParent && selfGender == 0)
		{
			return false;
		}
		bool containsAdoptiveParent = containsStepParent && !RelationType.HasRelation(relationType, 16);
		int potentialGuardianCount = 0;
		foreach (int groupCharId in group)
		{
			if (groupCharId == selfCharId || groupCharId == wardCharId)
			{
				continue;
			}
			Character groupChar = _objects[groupCharId];
			if (groupChar.GetAgeGroup() == 0)
			{
				continue;
			}
			potentialGuardianCount++;
			sbyte groupCharGender = groupChar.GetGender();
			RelatedCharacter relation = GetRelation(wardCharId, groupCharId);
			if (RelationType.HasRelation(relation.RelationType, 1) && groupCharGender <= selfGender)
			{
				return true;
			}
			if (containsStepParent)
			{
				if (RelationType.HasRelation(relation.RelationType, 8) && groupCharGender <= selfGender)
				{
					return true;
				}
				if (containsAdoptiveParent && RelationType.HasRelation(relation.RelationType, 64) && groupCharId <= selfGender)
				{
					return true;
				}
			}
		}
		return potentialGuardianCount > 0;
	}

	public void ChangeGroup(DataContext context, HashSet<int> memberIds, Character targetLeader)
	{
		int targetLeaderId = targetLeader.GetId();
		foreach (int memberId in memberIds)
		{
			Character memberChar = _objects[memberId];
			int currLeaderId = memberChar.GetLeaderId();
			if (currLeaderId >= 0 && currLeaderId != targetLeaderId)
			{
				LeaveGroup(context, memberChar);
			}
			JoinGroup(context, memberChar, targetLeader);
		}
	}

	public void HideCharacterOnMap(DataContext context, Character character, ulong hideCharacterState, bool bringWards = true)
	{
		Tester.Assert(character.GetCreatingType() == 1);
		Tester.Assert((hideCharacterState & 0xBC) != 0);
		LeaveGroup(context, character, bringWards);
		if (character.GetLeaderId() < 0)
		{
			HideSingleCharacterOnMap(context, character, hideCharacterState);
			return;
		}
		List<Character> groupChars = ObjectPool<List<Character>>.Instance.Get();
		GetGroupCharactersOrSelf(groupChars, character);
		foreach (Character groupChar in groupChars)
		{
			HideSingleCharacterOnMap(context, groupChar, hideCharacterState);
		}
		ObjectPool<List<Character>>.Instance.Return(groupChars);
	}

	private void HideSingleCharacterOnMap(DataContext context, Character character, ulong hideCharacterState)
	{
		Location location = character.GetLocation();
		character.ActiveExternalRelationState(context, hideCharacterState);
		if (character.IsCompletelyInfected())
		{
			Events.RaiseInfectedCharacterLocationChanged(context, character.GetId(), location, Location.Invalid);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, character.GetId(), location, Location.Invalid);
		}
	}

	public void UnhideCharacterOnMap(DataContext context, Character character, ulong hideCharacterState)
	{
		Tester.Assert(character.GetCreatingType() == 1);
		Tester.Assert((hideCharacterState & 0xBC) != 0);
		if (!character.IsActiveExternalRelationState(hideCharacterState))
		{
			return;
		}
		if (character.GetLeaderId() < 0)
		{
			UnhideSingleCharacterOnMap(context, character, hideCharacterState);
			return;
		}
		List<Character> groupChars = ObjectPool<List<Character>>.Instance.Get();
		GetGroupCharactersOrSelf(groupChars, character);
		foreach (Character groupChar in groupChars)
		{
			UnhideSingleCharacterOnMap(context, groupChar, hideCharacterState);
		}
		ObjectPool<List<Character>>.Instance.Return(groupChars);
	}

	private void UnhideSingleCharacterOnMap(DataContext context, Character character, ulong hideCharacterState)
	{
		Location location = character.GetValidLocation();
		character.DeactivateExternalRelationState(context, hideCharacterState);
		if (!character.IsActiveExternalRelationState(188uL))
		{
			if (character.IsCompletelyInfected())
			{
				Events.RaiseInfectedCharacterLocationChanged(context, character.GetId(), Location.Invalid, location);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, character.GetId(), Location.Invalid, location);
			}
		}
	}

	private void GetGroupCharactersOrSelf(List<Character> groupChars, Character character)
	{
		groupChars.Clear();
		if (character.GetLeaderId() < 0)
		{
			groupChars.Add(character);
		}
		else
		{
			groupChars.AddRange(GetGroup(character.GetLeaderId()).GetCollection().Select(GetElement_Objects));
		}
	}

	public void GroupMove(DataContext context, Character character, Location targetLocation)
	{
		if (character.GetKidnapperId() >= 0)
		{
			return;
		}
		int groupLeaderId = character.GetLeaderId();
		Location srcLocation = character.GetLocation();
		int selfCharId = character.GetId();
		if (groupLeaderId < 0)
		{
			RemoveCrossAreaTravelInfo(context, selfCharId);
			if (character.IsCompletelyInfected())
			{
				Events.RaiseInfectedCharacterLocationChanged(context, selfCharId, srcLocation, targetLocation);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, selfCharId, srcLocation, targetLocation);
			}
			character.SetLocation(targetLocation, context);
			return;
		}
		RemoveCrossAreaTravelInfo(context, groupLeaderId);
		if (!TryGetElement_CharacterGroups(groupLeaderId, out var group))
		{
			return;
		}
		foreach (int groupCharId in group.GetCollection())
		{
			Character groupMember = _objects[groupCharId];
			Events.RaiseCharacterLocationChanged(context, groupCharId, groupMember.GetLocation(), targetLocation);
			groupMember.SetLocation(targetLocation, context);
		}
	}

	public bool IsInTheSameGroup(int charIdA, int charIdB)
	{
		Character charA;
		Character charB;
		return _objects.TryGetValue(charIdA, out charA) && _objects.TryGetValue(charIdB, out charB) && charA.GetLeaderId() >= 0 && charA.GetLeaderId() == charB.GetLeaderId();
	}

	public CharacterSet GetGroup(int leaderId)
	{
		return _characterGroups[leaderId];
	}

	public bool HasNonBabyMemberInGroup(int leaderId)
	{
		if (leaderId < 0 || !_characterGroups.TryGetValue(leaderId, out var group))
		{
			return false;
		}
		foreach (int memberId in group.GetCollection())
		{
			if (_objects[memberId].GetAgeGroup() != 0 && leaderId != memberId)
			{
				return true;
			}
		}
		return false;
	}

	public void UpdateExceedingGroupChars(DataContext context)
	{
		Dictionary<int, CharacterSet> toRemoveDict = new Dictionary<int, CharacterSet>();
		List<long> sortedGroupChars = ObjectPool<List<long>>.Instance.Get();
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanBeRemovedFromGroup;
		int key;
		CharacterSet value;
		foreach (KeyValuePair<int, CharacterSet> characterGroup in _characterGroups)
		{
			characterGroup.Deconstruct(out key, out value);
			int leaderId = key;
			CharacterSet groupCharSet = value;
			HashSet<int> groupChars = groupCharSet.GetCollection();
			if (groupChars.Count <= AiHelper.FixedActionConstants.NpcGroupSoftMaxCount)
			{
				continue;
			}
			int toRemoveCount = groupChars.Count - AiHelper.FixedActionConstants.NpcGroupSoftMaxCount;
			sortedGroupChars.Clear();
			foreach (int groupCharId in groupChars)
			{
				if (groupCharId == leaderId)
				{
					continue;
				}
				Character groupChar = _objects[groupCharId];
				if (matcher.Match(groupChar))
				{
					RelatedCharacter relation = GetRelation(groupCharId, leaderId);
					if (!RelationType.HasRelation(relation.RelationType, 1024) && !RelationType.ContainParentRelations(relation.RelationType))
					{
						sortedGroupChars.Add(((long)relation.Favorability << 32) + groupCharId);
					}
				}
			}
			if (sortedGroupChars.Count <= toRemoveCount)
			{
				toRemoveCount = sortedGroupChars.Count;
			}
			else
			{
				sortedGroupChars.Sort();
			}
			if (toRemoveCount > 0)
			{
				CharacterSet toRemoveSet = default(CharacterSet);
				for (int i = 0; i < toRemoveCount; i++)
				{
					long groupCharInfo = sortedGroupChars[i];
					int groupCharId2 = (int)groupCharInfo;
					toRemoveSet.Add(groupCharId2);
				}
				if (toRemoveSet.GetCount() > 0)
				{
					toRemoveDict.Add(leaderId, toRemoveSet);
				}
			}
		}
		foreach (KeyValuePair<int, CharacterSet> item in toRemoveDict)
		{
			item.Deconstruct(out key, out value);
			int leaderId2 = key;
			CharacterSet toRemoveSet2 = value;
			CharacterSet group = _characterGroups[leaderId2];
			foreach (int toRemoveCharId in toRemoveSet2.GetCollection())
			{
				LeaveGroup(context, _objects[toRemoveCharId]);
				if (group.GetCount() <= AiHelper.FixedActionConstants.NpcGroupSoftMaxCount)
				{
					break;
				}
			}
		}
		ObjectPool<List<long>>.Instance.Return(sortedGroupChars);
	}

