	public int CreateNonIntelligentCharacter(DataContext context, short templateId)
	{
		CharacterItem characterCfg = Config.Character.Instance[templateId];
		byte creatingType = characterCfg.CreatingType;
		if (creatingType == 0 && DomainManager.Character.TryGetFixedCharacterByTemplateId(templateId, out var fixedCharacter))
		{
			return fixedCharacter.GetId();
		}
		if (1 == 0)
		{
		}
		Character character = creatingType switch
		{
			0 => DomainManager.Character.CreateFixedCharacter(context, templateId), 
			2 => DomainManager.Character.CreateRandomEnemy(context, templateId, isTemporary: true), 
			3 => DomainManager.Character.CreateFixedEnemy(context, templateId, isTemporary: true), 
			_ => throw new ArgumentOutOfRangeException("templateId", $"character with template id {templateId} is neither fixed character nor random enemy"), 
		};
		if (1 == 0)
		{
		}
		Character enemy = character;
		int enemyId = enemy.GetId();
		DomainManager.Character.CompleteCreatingCharacter(enemyId);
		if (creatingType == 2)
		{
			sbyte affectedByLegendaryBookRate = 50;
			Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
			if (location.IsValid() && (characterCfg.OrganizationInfo.OrgTemplateId == 17 || characterCfg.OrganizationInfo.OrgTemplateId == 18) && context.Random.CheckPercentProb(affectedByLegendaryBookRate))
			{
				HashSet<int> charIds = ObjectPool<HashSet<int>>.Instance.Get();
				DomainManager.LegendaryBook.GetLegendaryBookConsumedCharacters(charIds);
				for (sbyte combatSkillType = 0; combatSkillType < 14; combatSkillType++)
				{
					int ownerId = DomainManager.LegendaryBook.GetOwner(combatSkillType);
					if (ownerId >= 0 && DomainManager.Character.TryGetElement_Objects(ownerId, out var bookOwner) && bookOwner.GetLegendaryBookOwnerState() >= 1 && bookOwner.GetLocation().AreaId == location.AreaId)
					{
						enemy.AddFeature(context, 213);
						break;
					}
				}
				ObjectPool<HashSet<int>>.Instance.Return(charIds);
			}
		}
		return enemyId;
	}

