	public void TransferSpecialGroup(DataContext context, int fromLeaderId, int toLeaderId, bool clearDestGroupFirst = false)
	{
		CharacterSet destGroup;
		bool destLeaderHasGroup = _characterSpecialGroup.TryGetValue(toLeaderId, out destGroup);
		if (destLeaderHasGroup && clearDestGroupFirst)
		{
			foreach (int charId in destGroup.GetCollection())
			{
				if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
				{
					DomainManager.Character.RemoveNonIntelligentCharacter(context, character);
				}
			}
			destGroup.Clear();
		}
		if (_characterSpecialGroup.TryGetValue(fromLeaderId, out var fromGroup))
		{
			foreach (int charId2 in fromGroup.GetCollection())
			{
				if (DomainManager.Character.TryGetElement_Objects(charId2, out var character2))
				{
					character2.SetLeaderId(toLeaderId, context);
					destGroup.Add(charId2);
				}
			}
			fromGroup.Clear();
			RemoveElement_CharacterSpecialGroup(fromLeaderId, context);
		}
		if (destLeaderHasGroup)
		{
			SetElement_CharacterSpecialGroup(toLeaderId, destGroup, context);
		}
		else
		{
			AddElement_CharacterSpecialGroup(toLeaderId, destGroup, context);
		}
	}

