	private static void InitializeRandomEnemyCharTemplateCache()
	{
		_randomEnemyCharTemplateCache = new Dictionary<sbyte, List<short>[]>();
		HashSet<short> hashSet = new HashSet<short>();
		foreach (EnemyNestItem enemyNestTemplate in (IEnumerable<EnemyNestItem>)EnemyNest.Instance)
		{
			if (enemyNestTemplate.Members != null)
			{
				hashSet.UnionWith(enemyNestTemplate.Members);
			}
		}
		foreach (CharacterItem template in (IEnumerable<CharacterItem>)Config.Character.Instance)
		{
			if (template.CreatingType == 2 && ((template.OrganizationInfo.OrgTemplateId != 18 && template.OrganizationInfo.OrgTemplateId != 17) || hashSet.Contains(template.TemplateId)))
			{
				List<short>[] orgEnemies;
				if (!_randomEnemyCharTemplateCache.ContainsKey(template.OrganizationInfo.OrgTemplateId))
				{
					orgEnemies = new List<short>[9];
					_randomEnemyCharTemplateCache.Add(template.OrganizationInfo.OrgTemplateId, orgEnemies);
				}
				else
				{
					orgEnemies = _randomEnemyCharTemplateCache[template.OrganizationInfo.OrgTemplateId];
				}
				List<short>[] array = orgEnemies;
				int grade = template.OrganizationInfo.Grade;
				if (array[grade] == null)
				{
					array[grade] = new List<short>();
				}
				orgEnemies[template.OrganizationInfo.Grade].Add(template.TemplateId);
			}
		}
	}

	public static short GetRandomEnemyCharTemplateId(IRandomSource random, sbyte orgTemplateId, sbyte expectedGrade)
	{
		if (!_randomEnemyCharTemplateCache.TryGetValue(orgTemplateId, out var orgEnemies))
		{
			return -1;
		}
		for (sbyte currGrade = expectedGrade; currGrade >= 0; currGrade--)
		{
			if (orgEnemies[currGrade] != null && orgEnemies[currGrade].Count > 0)
			{
				return orgEnemies[currGrade].GetRandom(random);
			}
		}
		return -1;
	}

	public void CreatePregeneratedCityTownGuards(DataContext context)
	{
		for (sbyte stateTemplateId = 0; stateTemplateId < 16; stateTemplateId++)
		{
			for (sbyte grade = 0; grade < 9; grade++)
			{
				short hereticTemplateId = PregenerateHereticTemplateIds[grade];
				Character hereticChar = CreateRandomEnemy(context, hereticTemplateId, isTemporary: false);
				int hereticCharIndex = CalcPregeneratedCityTownGuardIndex(stateTemplateId, isHeretic: true, grade);
				_pregeneratedCityTownGuards[hereticCharIndex] = hereticChar.GetId();
				CompleteCreatingCharacter(hereticChar.GetId());
				short righteousTemplateId = PregenerateRighteousTemplateIds[grade];
				Character righteousChar = CreateRandomEnemy(context, righteousTemplateId, isTemporary: false);
				int righteousCharIndex = CalcPregeneratedCityTownGuardIndex(stateTemplateId, isHeretic: false, grade);
				_pregeneratedCityTownGuards[righteousCharIndex] = righteousChar.GetId();
				CompleteCreatingCharacter(righteousChar.GetId());
			}
		}
		SetPregeneratedCityTownGuards(_pregeneratedCityTownGuards, context);
	}

	public void CreatePregeneratedRandomEnemies(DataContext context)
	{
		_pregeneratedRandomEnemies.Clear();
		for (int i = 0; i < RandomEnemy.Instance.Count; i++)
		{
			_pregeneratedRandomEnemies.Add(-1);
		}
		for (short templateId = 0; templateId < Config.Character.Instance.Count; templateId++)
		{
			CharacterItem config = Config.Character.Instance[templateId];
			if (config.RandomEnemyId >= 0)
			{
				Character randomEnemy = CreateRandomEnemy(context, templateId, isTemporary: false);
				_pregeneratedRandomEnemies[config.RandomEnemyId] = randomEnemy.GetId();
				CompleteCreatingCharacter(randomEnemy.GetId());
			}
		}
		SetPregeneratedRandomEnemies(_pregeneratedRandomEnemies, context);
	}

	private void ComplementPregeneratedRandomEnemies(DataContext context, DataUid uid)
	{
		int previousCount = _pregeneratedRandomEnemies.Count;
		for (int templateId = previousCount; templateId < RandomEnemy.Instance.Count; templateId++)
		{
			_pregeneratedRandomEnemies.Add(-1);
		}
		for (short templateId2 = 0; templateId2 < Config.Character.Instance.Count; templateId2++)
		{
			CharacterItem config = Config.Character.Instance[templateId2];
			if (config.RandomEnemyId >= previousCount)
			{
				Logger.Info($"Complement pregenerated random enemy: {config.Surname}{config.GivenName}({config.TemplateId})");
				Character randomEnemy = CreateRandomEnemy(context, templateId2, isTemporary: false);
				_pregeneratedRandomEnemies[config.RandomEnemyId] = randomEnemy.GetId();
				CompleteCreatingCharacter(randomEnemy.GetId());
			}
		}
		CreatePregeneratedFixedEnemies(context);
		SetPregeneratedRandomEnemies(_pregeneratedRandomEnemies, context);
		RemovePostModificationHandler(uid, "ComplementPregeneratedRandomEnemies");
	}

