	public bool HasGuard(int charId, Character character)
	{
		if (character.IsCompletelyInfected())
		{
			return !_unguardedChars.Contains(charId);
		}
		if (character.GetKidnapperId() >= 0)
		{
			return false;
		}
		if (character.GetKidnappingAdventure() != null)
		{
			return false;
		}
		if (character.GetSrcCharId() == DomainManager.Taiwu.GetTaiwuCharId())
		{
			return false;
		}
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		if (orgInfo.SettlementId < 0 || orgInfo.OrgTemplateId == 16)
		{
			return false;
		}
		Settlement settlement = DomainManager.Organization.GetSettlement(orgInfo.SettlementId);
		if (settlement.GetLocation().AreaId >= 45)
		{
			return false;
		}
		Location location = character.GetLocation();
		if (MapAreaData.IsBrokenArea(location.AreaId))
		{
			return false;
		}
		bool flag = location.IsValid();
		bool flag2 = flag;
		if (flag2)
		{
			EMapBlockType blockType = DomainManager.Map.GetBlock(location).BlockType;
			bool flag3 = (uint)(blockType - 6) <= 1u;
			flag2 = flag3;
		}
		if (flag2)
		{
			return false;
		}
		return !_unguardedChars.Contains(charId);
	}

