	public void UpdateInfectedCharacterActions(DataContext context)
	{
		if (_infectedCharSet.Count == 0)
		{
			return;
		}
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		Location taiwuCharLocation = taiwuChar.GetLocation();
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanPerformInfectedAction;
		CharacterMatcherItem targetMatcher = CharacterMatcher.DefValue.CanBeAttackedByInfectedCharacter;
		foreach (int infectedCharId in _infectedCharSet)
		{
			Character infectedChar = _objects[infectedCharId];
			if (IsLockMovementChar(infectedCharId) || !matcher.Match(infectedChar))
			{
				continue;
			}
			Location location = infectedChar.GetLocation();
			if (!location.IsValid())
			{
				continue;
			}
			MapBlockData block = DomainManager.Map.GetBlock(location);
			if (block.InfectedCharacterSet == null || !block.InfectedCharacterSet.Contains(infectedCharId))
			{
				continue;
			}
			int targetCharId = -1;
			if (location.Equals(taiwuCharLocation))
			{
				if (targetMatcher.Match(taiwuChar))
				{
					targetCharId = taiwuChar.GetId();
				}
			}
			else
			{
				if (block.CharacterSet == null)
				{
					continue;
				}
				List<int> charIdList = context.AdvanceMonthRelatedData.CharIdList.Occupy();
				charIdList.Clear();
				foreach (int charId in block.CharacterSet)
				{
					if (targetMatcher.Match(_objects[charId]))
					{
						charIdList.Add(charId);
					}
				}
				targetCharId = charIdList.GetRandomOrDefault(context.Random, -1);
				context.AdvanceMonthRelatedData.CharIdList.Release(ref charIdList);
			}
			if (targetCharId >= 0)
			{
				Character targetChar = GetElement_Objects(targetCharId);
				switch (DomainManager.Character.SelectHarmfulActionType(context, infectedChar, targetChar))
				{
				case 0:
					DomainManager.Character.HandleAttackAction(context, infectedChar, targetChar);
					break;
				case 1:
					DomainManager.Character.HandlePoisonAction(context, infectedChar, targetChar, ItemKey.Invalid, -1);
					break;
				case 2:
					DomainManager.Character.HandlePlotHarmAction(context, infectedChar, targetChar, ItemKey.Invalid, -1);
					break;
				}
			}
		}
	}

