	[DomainMethod]
	public CharacterLoveAndHateItemInfo GetCharacterLoveAndHateItemInfo(DataContext context, int charId)
	{
		CharacterLoveAndHateItemInfo info = null;
		if (TryGetElement_Objects(charId, out var character))
		{
			sbyte favorabilityType = FavorabilityType.GetFavorabilityType(DomainManager.Character.GetFavorability(charId, DomainManager.Taiwu.GetTaiwuCharId()));
			if (favorabilityType >= 3 && IsInteractedWithTaiwu(charId))
			{
				character.SetLovingItemRevealed(lovingItemRevealed: true, context);
				character.SetHatingItemRevealed(hatingItemRevealed: true, context);
			}
			info = new CharacterLoveAndHateItemInfo();
			info.CharacterId = charId;
			info.CreatingType = character.GetCreatingType();
			info.LovingItemSubType = character.GetLovingItemSubType();
			info.LovingItemRevealed = character.GetLovingItemRevealed();
			info.HatingItemSubType = character.GetHatingItemSubType();
			info.HatingItemRevealed = character.GetHatingItemRevealed();
			info.HobbyExpirationDate = character.GetHobbyExpirationDate();
			info.NeedShowFirstRevealLovingEffect = info.LovingItemRevealed && !DomainManager.Extra.IsCharacterLovingItemRevealed(charId);
			info.NeedShowFirstRevealHatingEffect = info.HatingItemRevealed && !DomainManager.Extra.IsCharacterHatingItemRevealed(charId);
		}
		return info;
	}

	[DomainMethod]
	public void TransferResourcesWithDebt(DataContext context, int srcCharId, int destCharId, ResourceInts resources, bool checkFavorability)
	{
		Character srcChar = GetElement_Objects(srcCharId);
		Character destChar = GetElement_Objects(destCharId);
		if (srcChar.GetCreatingType() == 1 && destChar.GetCreatingType() == 1)
		{
			UpdateDebtByResourceTransfer(context, srcChar, destChar, resources, changeFavorAndHappiness: true);
		}
		TransferResource(context, srcChar, destChar, ref resources);
	}

	public void UpdateDebtByResourceTransfer(DataContext context, Character srcChar, Character destChar, ResourceInts resources, bool changeFavorAndHappiness)
	{
		int destCharId = destChar.GetId();
		int srcCharId = srcChar.GetId();
		Tester.Assert(srcCharId != destCharId);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Character relatedChar = destChar;
		if (destCharId == taiwuCharId)
		{
			relatedChar = srcChar;
			resources = resources.GetReversed();
		}
		else if (srcCharId != taiwuCharId)
		{
			throw new Exception($"Neither party is taiwu: {srcCharId}, {destCharId}");
		}
		if (relatedChar.GetCreatingType() != 1)
		{
			return;
		}
		short oriFavor;
		short oriMaxFavor;
		if (changeFavorAndHappiness)
		{
			(oriFavor, oriMaxFavor) = GetFavorAndMaxFavorToTaiwu(relatedChar);
		}
		else
		{
			oriFavor = 0;
			oriMaxFavor = 0;
		}
		var (borrowedWorth, lentWorth) = GetResourcesWorth(ref resources);
		if (lentWorth != 0)
		{
			int charId = relatedChar.GetId();
			if (DomainManager.Taiwu.IsInGroup(charId))
			{
				for (sbyte resourceType = 0; resourceType < 8; resourceType++)
				{
					int amount = resources.Get(resourceType);
					if (amount < 0)
					{
						EventHelper.ChangeAlertnessOnTakeTeammateResource(relatedChar.GetId(), resourceType, -amount);
					}
				}
			}
			if (changeFavorAndHappiness)
			{
				short favorDecrement = AiHelper.GeneralActionConstants.GetResourceFavorabilityChange(6, (int)Math.Clamp(lentWorth, 0L, 2147483647L));
				Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
				ChangeFavorabilityOptionalGiftItem(context, relatedChar, taiwuChar, -favorDecrement);
				sbyte happinessDecrement = AiHelper.GeneralActionConstants.GetResourceHappinessChange(6, (int)Math.Clamp(lentWorth, 0L, 2147483647L));
				relatedChar.ChangeHappiness(context, -happinessDecrement);
			}
		}
		if (borrowedWorth != 0)
		{
			for (sbyte resourceType2 = 0; resourceType2 < 8; resourceType2++)
			{
				int amount2 = resources.Get(resourceType2);
				if (amount2 > 0)
				{
					EventHelper.ChangeAlertnessOnGiveTeammateResource(relatedChar.GetId(), resourceType2, amount2);
				}
			}
			if (changeFavorAndHappiness)
			{
				short favorIncrement = AiHelper.GeneralActionConstants.GetResourceFavorabilityChange(6, (int)Math.Clamp(borrowedWorth, 0L, 2147483647L));
				Character taiwuChar2 = DomainManager.Taiwu.GetTaiwu();
				ChangeFavorabilityOptionalGiftItem(context, relatedChar, taiwuChar2, favorIncrement);
				sbyte happinessDecrement2 = AiHelper.GeneralActionConstants.GetResourceHappinessChange(6, (int)Math.Clamp(borrowedWorth, 0L, 2147483647L));
				relatedChar.ChangeHappiness(context, happinessDecrement2);
			}
		}
		if (changeFavorAndHappiness && !CheckFavorabilityAfterTransferring(relatedChar, oriFavor, oriMaxFavor))
		{
			var (currFavor, currMaxFavor) = GetFavorAndMaxFavorToTaiwu(relatedChar);
			Logger.Warn($"CheckFavorabilityAfterTransferring failed. Related character: {destCharId}, oriFavor: {oriFavor}, oriMaxFavor: {oriMaxFavor}borrowedWorth: {borrowedWorth}, lentWorth: {lentWorth}currFavor: {currFavor}, currMaxFavor: {currMaxFavor}");
		}
	}

	public void TransferResource(DataContext context, Character srcChar, Character destChar, sbyte resourceType, int amount)
	{
		Tester.Assert(srcChar.GetId() != destChar.GetId());
		Tester.Assert(resourceType >= 0 && resourceType < 8);
		Tester.Assert(amount > 0);
		srcChar.ChangeResource(context, resourceType, -amount);
		destChar.ChangeResource(context, resourceType, amount);
	}

	public void TransferResource(DataContext context, Character srcChar, Character destChar, ref ResourceInts resources)
	{
		Tester.Assert(srcChar.GetId() != destChar.GetId());
		destChar.ChangeResources(context, ref resources);
		resources = resources.GetReversed();
		srcChar.ChangeResources(context, ref resources);
	}

	[DomainMethod]
	public void TransferInventoryItemWithDebt(DataContext context, int srcCharId, int destCharId, ItemKey itemKey, int amount, bool checkFavorability)
	{
		if (amount <= 0)
		{
			return;
		}
		Character srcChar = DomainManager.Character.GetElement_Objects(srcCharId);
		Character destChar = DomainManager.Character.GetElement_Objects(destCharId);
		ClearItemUsingState(context, itemKey, srcCharId);
		TransferInventoryItem(context, srcChar, destChar, itemKey, amount);
		if (destChar.GetCreatingType() == 1 && srcChar.GetCreatingType() == 1)
		{
			UpdateDebtByItemTransfer(context, srcChar, destChar, itemKey, amount, changeFavorAndHappiness: true);
			if (DomainManager.Taiwu.GetTaiwuCharId() == srcCharId && DomainManager.Taiwu.IsInGroup(destCharId))
			{
				EventHelper.ChangeAlertnessOnGiveTeammateItem(destCharId, itemKey, amount);
			}
			if (DomainManager.Taiwu.IsInGroup(srcCharId) && DomainManager.Taiwu.GetTaiwuCharId() == destCharId)
			{
				EventHelper.ChangeAlertnessOnTakeTeammateItem(srcCharId, itemKey, amount);
			}
		}
	}

	public void UpdateDebtByItemTransfer(DataContext context, Character srcChar, Character destChar, ItemKey itemKey, int amount, bool changeFavorAndHappiness)
	{
		int destCharId = destChar.GetId();
		int srcCharId = srcChar.GetId();
		Tester.Assert(srcCharId != destCharId);
		Tester.Assert(amount > 0);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		Character relatedChar = destChar;
		if (destCharId == taiwuCharId)
		{
			relatedChar = srcChar;
			amount = -amount;
		}
		else if (srcCharId != taiwuCharId)
		{
			throw new Exception($"Neither party is taiwu: {srcCharId}, {destCharId}");
		}
		if (relatedChar.GetCreatingType() == 1)
		{
			short oriFavor;
			short oriMaxFavor;
			if (changeFavorAndHappiness)
			{
				(oriFavor, oriMaxFavor) = GetFavorAndMaxFavorToTaiwu(relatedChar);
			}
			else
			{
				oriFavor = 0;
				oriMaxFavor = 0;
			}
			if (changeFavorAndHappiness && !ItemTemplateHelper.IsMiscResource(itemKey.ItemType, itemKey.TemplateId))
			{
				ItemBase item = DomainManager.Item.GetBaseItem(itemKey);
				int favorChange = item.GetFavorabilityChange() * amount;
				ChangeFavorabilityOptionalGiftItem(context, relatedChar, taiwuChar, favorChange);
				relatedChar.ChangeHappiness(context, (destCharId == taiwuCharId) ? (-item.GetHappinessChange()) : item.GetHappinessChange());
			}
			if (changeFavorAndHappiness && !CheckFavorabilityAfterTransferring(relatedChar, oriFavor, oriMaxFavor))
			{
				var (currFavor, currMaxFavor) = GetFavorAndMaxFavorToTaiwu(relatedChar);
				Logger.Warn($"CheckFavorabilityAfterTransferring failed. Related character: {destCharId}, oriFavor: {oriFavor}, oriMaxFavor: {oriMaxFavor},currFavor: {currFavor}, currMaxFavor: {currMaxFavor}");
			}
		}
	}

