	public List<ItemDisplayData> GetAllItems(int charId, bool includeResource, bool includeEquipment)
	{
		Character character = GetElement_Objects(charId);
		Inventory inventory = character.GetInventory();
		List<ItemDisplayData> inventoryList = GetItemDisplayData(charId, inventory.Items, ItemSourceType.Inventory);
		IEnumerable<ItemDisplayData> result = inventoryList;
		if (includeResource)
		{
			List<ItemDisplayData> resourceList = GetResourceItemDisplayDataList(charId);
			result = result.Union(resourceList);
		}
		if (includeEquipment)
		{
			List<ItemDisplayData> equipmentList = GetAllEquipmentValidItems(charId);
			result = result.Union(equipmentList);
		}
		return result.ToList();
	}

