	[DomainMethod]
	public SimulateEatingEffectResult SimulateEatingEffect(DataContext context, int charId, ItemKey itemKey, int amount)
	{
		if (!_objects.TryGetValue(charId, out var character))
		{
			return null;
		}
		PoisonInts poisoned = default(PoisonInts);
		poisoned.Add(ref character.GetPoisoned());
		Injuries injuries = default(Injuries);
		injuries.Initialize();
		injuries.Change(character.GetInjuries());
		short disorderOfQi = character.GetDisorderOfQi();
		short health = character.GetHealth();
		SimulateEatingEffectResult simulateEatingEffectResult = new SimulateEatingEffectResult();
		switch (itemKey.ItemType)
		{
		case 9:
		{
			int baseValue = Config.TeaWine.Instance[itemKey.TemplateId].DirectChangeOfQiDisorder * amount;
			(int max, int min) tuple = CFormula.RandomCalcDisorderOfQiRange(baseValue);
			int deltaMin = tuple.max;
			int deltaMax = tuple.min;
			deltaMin = character.CalcDisorderOfQiDelta(deltaMin);
			deltaMax = character.CalcDisorderOfQiDelta(deltaMax);
			int disorderOfQiDeltaMin = Math.Clamp(disorderOfQi + deltaMin, 0, DisorderLevelOfQi.MaxValue);
			int disorderOfQiDeltaMax = Math.Clamp(disorderOfQi + deltaMax, 0, DisorderLevelOfQi.MaxValue);
			simulateEatingEffectResult.MinDisorderOfQi = Math.Min(disorderOfQiDeltaMin, disorderOfQiDeltaMax);
			simulateEatingEffectResult.MaxDisorderOfQi = Math.Max(disorderOfQiDeltaMin, disorderOfQiDeltaMax);
			break;
		}
		case 8:
		{
			MedicineItem config = Config.Medicine.Instance[itemKey.TemplateId];
			MedicineEatingInstantEffect effect = new MedicineEatingInstantEffect(config);
			for (int i = 0; i < amount; i++)
			{
				switch (config.EffectType)
				{
				case EMedicineEffectType.RecoverOuterInjury:
					character.CalcMedicineEffect_RecoverInjury(ref injuries, context.Random, inner: false, ref effect, itemKey.Id);
					break;
				case EMedicineEffectType.RecoverInnerInjury:
					character.CalcMedicineEffect_RecoverInjury(ref injuries, context.Random, inner: true, ref effect, itemKey.Id);
					break;
				case EMedicineEffectType.ChangeDisorderOfQi:
					character.CalcMedicineEffect_RecoverDisorderOfQi(ref disorderOfQi, ref effect, itemKey.Id);
					simulateEatingEffectResult.MaxDisorderOfQi = (simulateEatingEffectResult.MinDisorderOfQi = disorderOfQi);
					break;
				case EMedicineEffectType.RecoverHealth:
					character.CalcMedicineEffect_RecoverHealth(ref health, ref effect, itemKey.Id);
					break;
				case EMedicineEffectType.DetoxPoison:
					character.CalcMedicineEffect_DetoxPoison(ref poisoned, ref effect, itemKey.Id);
					break;
				case EMedicineEffectType.ApplyPoison:
					character.CalcMedicineEffect_ApplyPoison(ref poisoned, ref effect, itemKey.Id);
					break;
				}
			}
			break;
		}
		}
		simulateEatingEffectResult.Health = health;
		simulateEatingEffectResult.Poisons = poisoned;
		simulateEatingEffectResult.Injuries = injuries;
		return simulateEatingEffectResult;
	}

	[DomainMethod]
	public SimulateEatingEffectResult SimulateProfessionDoctorSkill0(DataContext context, int patientId, ItemKey itemKey, int amount, int doctorId)
	{
		if (!_objects.TryGetValue(patientId, out var patient) || !_objects.TryGetValue(doctorId, out var doctor))
		{
			return null;
		}
		MedicineItem config = Config.Medicine.Instance[itemKey.TemplateId];
		EMedicineEffectType effectType = config.EffectType;
		bool flag = (uint)effectType <= 1u;
		SimulateEatingEffectResult result;
		if (flag && config.InstantAffect)
		{
			result = new SimulateEatingEffectResult
			{
				Injuries = patient.GetInjuries(),
				Poisons = patient.GetPoisoned(),
				Health = patient.GetHealth(),
				MaxDisorderOfQi = patient.GetDisorderOfQi(),
				MinDisorderOfQi = patient.GetDisorderOfQi()
			};
			(bool, sbyte) eatResult = EventHelper.GetMedicineTopicalEffectResult(patient, itemKey);
			if (eatResult.Item1)
			{
				bool isInner = config.EffectType == EMedicineEffectType.RecoverInnerInjury;
				sbyte originValue = result.Injuries.Get(eatResult.Item2, isInner);
				int effectValue = patient.GetSpecialEffectModifiedMedicineEffectValue(config.EffectValue, itemKey.Id);
				sbyte previewValue = (sbyte)Math.Max(0, originValue - effectValue);
				result.Injuries.Set(eatResult.Item2, isInner, previewValue);
			}
		}
		else
		{
			result = SimulateEatingEffect(context, patientId, itemKey, amount);
		}
		switch (config.EffectType)
		{
		case EMedicineEffectType.RecoverOuterInjury:
		case EMedicineEffectType.RecoverInnerInjury:
			result.Injuries = DomainManager.Combat.HealInjury(patientId, result.Injuries, doctor);
			break;
		case EMedicineEffectType.DetoxPoison:
			result.Poisons = DomainManager.Combat.HealPoison(patientId, result.Poisons, doctor);
			break;
		case EMedicineEffectType.ChangeDisorderOfQi:
			if (patient.GetDisorderOfQi() > 0)
			{
				result.Poisons = DomainManager.Combat.HealPoison(patientId, result.Poisons, doctor);
				short changeValue = EventHelper.GetChangeDisorderOfQiByDoctorSkill0();
				result.MaxDisorderOfQi -= changeValue;
				result.MinDisorderOfQi -= changeValue;
			}
			break;
		}
		return result;
	}

	private Inventory CheckAutoUseMedicine(DataContext context, int charId, out bool need)
	{
		need = false;
		if (!_objects.TryGetValue(charId, out var character))
		{
			return null;
		}
		Inventory usingMedicines = new Inventory();
		Inventory inventoryItems = character.GetInventory();
		List<KeyValuePair<ItemKey, int>> medicineItemList = (from x in inventoryItems.Items
			where x.Key.ItemType == 8 && !DomainManager.Taiwu.IsItemLocked(x.Key)
			orderby ItemTemplateHelper.GetGrade(x.Key.ItemType, x.Key.TemplateId)
			select x).ToList();
		Injuries injuries = default(Injuries);
		injuries.Initialize();
		injuries.Change(character.GetInjuries());
		EatingItems eatingItems = character.GetEatingItems();
		for (int i = 0; i < 9; i++)
		{
			ItemKey itemKey = eatingItems.GetItem(i);
			short duration = eatingItems.GetDuration(i);
			if (itemKey.ItemType != 8)
			{
				continue;
			}
			MedicineItem config = Config.Medicine.Instance[itemKey.TemplateId];
			EMedicineEffectType effectType = config.EffectType;
			if ((uint)effectType <= 1u)
			{
				bool isInner = config.EffectType == EMedicineEffectType.RecoverInnerInjury;
				for (int j = 0; j < duration; j++)
				{
					MedicineEatingInstantEffect effect = new MedicineEatingInstantEffect(config);
					character.CalcMedicineEffect_RecoverInjury(ref injuries, context.Random, isInner, ref effect, itemKey.Id);
				}
			}
		}
		need = injuries.HasAnyInjury();
		MainAttributes mainAttributes = character.GetCurrMainAttributes();
		MainAttributes simulateAttributes = default(MainAttributes);
		for (int i2 = 0; i2 < 6; i2++)
		{
			simulateAttributes[i2] = mainAttributes[i2];
		}
		sbyte currMaxEatingSlotsCount = character.GetCurrMaxEatingSlotsCount();
		sbyte eatCount = 0;
		SimulateEat(ref injuries, ref eatCount, isInner: false);
		SimulateEat(ref injuries, ref eatCount, isInner: true);
		return usingMedicines;
		bool IsEnoughAttributes(MedicineItem medicineItem)
		{
			return medicineItem.RequiredMainAttributeType < 0 || simulateAttributes[medicineItem.RequiredMainAttributeType] >= medicineItem.RequiredMainAttributeValue;
		}
		bool IsEnoughEatingSlot(MedicineItem medicineItem)
		{
			if (medicineItem.Duration <= 0)
			{
				return true;
			}
			sbyte max = (sbyte)(currMaxEatingSlotsCount - eatCount);
			sbyte availableEatingSlot = character.GetEatingItems().GetAvailableEatingSlot(max);
			return availableEatingSlot >= 0;
		}
		void SimulateEat(ref Injuries reference, ref sbyte reference2, bool flag)
		{
			int maxValue;
			do
			{
				maxValue = 0;
				for (sbyte part = 0; part < 7; part++)
				{
					sbyte value = reference.Get(part, flag);
					maxValue = Math.Max(maxValue, value);
				}
				if (maxValue <= 0)
				{
					break;
				}
				foreach (KeyValuePair<ItemKey, int> item in medicineItemList)
				{
					item.Deconstruct(out var key, out var value2);
					ItemKey itemKey2 = key;
					int amount = value2;
					MedicineItem config2 = Config.Medicine.Instance[itemKey2.TemplateId];
					MedicineEatingInstantEffect effect2 = new MedicineEatingInstantEffect(config2);
					EMedicineEffectType effectType2 = (flag ? EMedicineEffectType.RecoverInnerInjury : EMedicineEffectType.RecoverOuterInjury);
					if (config2.EffectType == effectType2 && effect2.EffectValue >= maxValue && IsEnoughAttributes(config2) && IsEnoughEatingSlot(config2))
					{
						int usingCount = usingMedicines.GetInventoryItemCount(itemKey2);
						if (usingCount < amount)
						{
							character.CalcMedicineEffect_RecoverInjury(ref reference, context.Random, flag, ref effect2, itemKey2.Id);
							usingMedicines.OfflineAdd(itemKey2, 1);
							if (config2.Duration > 0)
							{
								reference2++;
							}
							if (config2.RequiredMainAttributeType >= 0)
							{
								simulateAttributes[config2.RequiredMainAttributeType] -= config2.RequiredMainAttributeValue;
							}
							maxValue = 0;
							break;
						}
					}
				}
			}
			while (maxValue == 0);
		}
	}

