	public static void GetLostItemsByAmount(DataContext context, int amountToLose, Dictionary<ItemKey, int> oriItems, List<(ItemBase item, int amount)> itemsToBeLost, bool isTaiwuInventory = false)
	{
		IRandomSource random = context.Random;
		List<(ItemBase, int)>[] classifiedItems = context.AdvanceMonthRelatedData.ClassifiedItems.Occupy();
		ClassifyItemsToLose(classifiedItems, oriItems, isTaiwuInventory);
		GetLostItemsByAmount(random, amountToLose, classifiedItems, itemsToBeLost);
		context.AdvanceMonthRelatedData.ClassifiedItems.Release(ref classifiedItems);
	}

	public static void GetLostItemsByAmount(IRandomSource random, int amountToLose, List<(ItemBase item, int amount)>[] classifiedItems, List<(ItemBase item, int amount)> itemsToBeLost)
	{
		int lostAmount = 0;
		int i = 0;
		for (int count = classifiedItems.Length; i < count; i++)
		{
			List<(ItemBase, int)> currItems = classifiedItems[i];
			while (currItems.Count > 0 && lostAmount < amountToLose)
			{
				int randomIndex = random.Next(currItems.Count);
				(ItemBase, int) tuple = currItems[randomIndex];
				ItemBase item = tuple.Item1;
				int amount = tuple.Item2;
				int amountToBeLost = ((amount <= 1) ? 1 : (random.Next(amount) + 1));
				amountToBeLost = Math.Min(amountToBeLost, amountToLose - lostAmount);
				itemsToBeLost.Add((item, amountToBeLost));
				if (amountToBeLost >= amount)
				{
					CollectionUtils.SwapAndRemove(currItems, randomIndex);
				}
				else
				{
					currItems[randomIndex] = (item, amount - amountToBeLost);
				}
				lostAmount += amountToBeLost;
			}
		}
	}

	public static void GetLostItemsDueToOverload(DataContext context, int overloadedWeight, IReadOnlyDictionary<ItemKey, int> oriItems, List<(ItemBase item, int amount)> itemsToBeLost, bool isTaiwuInventory = false)
	{
		itemsToBeLost.Clear();
		List<(ItemBase, int)>[] classifiedItems = context.AdvanceMonthRelatedData.ClassifiedItems.Occupy();
		ClassifyItemsToLose(classifiedItems, oriItems, isTaiwuInventory);
		int singleItemLostWeightLine = Math.Max(overloadedWeight * 20 / 100, 10);
		int lostWeight = 0;
		int i = 0;
		for (int count = classifiedItems.Length; i < count; i++)
		{
			List<(ItemBase, int)> currItems = classifiedItems[i];
			currItems.RemoveAll(delegate((ItemBase item, int amount) pair)
			{
				int weight = pair.item.GetWeight();
				return weight > singleItemLostWeightLine || weight == 0;
			});
			currItems.RemoveAll(delegate((ItemBase item, int amount) pair)
			{
				List<int> locks = pair.item.GetTaskLock();
				return locks != null && locks.Count > 0 && DomainManager.World.GetSortedTaskList().Any((TaskDisplayData task) => (task.InnerTaskData.TaskStatus & 6) == 0 && locks.Contains(task.InnerTaskData.TaskChainId));
			});
			if (isTaiwuInventory)
			{
				currItems.Sort(delegate((ItemBase, int) itemA, (ItemBase, int) itemB)
				{
					bool flag = DomainManager.Taiwu.IsItemLocked(itemA.Item1.GetItemKey());
					bool flag2 = DomainManager.Taiwu.IsItemLocked(itemB.Item1.GetItemKey());
					return (flag != flag2) ? flag.CompareTo(flag2) : itemA.Item1.GetWeight().CompareTo(itemB.Item1.GetWeight());
				});
			}
			else
			{
				currItems.Sort(((ItemBase, int) itemA, (ItemBase, int) itemB) => itemA.Item1.GetWeight().CompareTo(itemB.Item1.GetWeight()));
			}
			while (currItems.Count > 0)
			{
				int index = 0;
				(ItemBase, int) tuple = currItems[index];
				ItemBase item = tuple.Item1;
				int amount = tuple.Item2;
				int amountToBeLost = 1;
				itemsToBeLost.Add((item, amountToBeLost));
				if (amountToBeLost >= amount)
				{
					CollectionUtils.SwapAndRemove(currItems, index);
				}
				else
				{
					currItems[index] = (item, amount - amountToBeLost);
				}
				lostWeight += item.GetWeight() * amountToBeLost;
				if (lostWeight >= singleItemLostWeightLine)
				{
					context.AdvanceMonthRelatedData.ClassifiedItems.Release(ref classifiedItems);
					return;
				}
			}
		}
		context.AdvanceMonthRelatedData.ClassifiedItems.Release(ref classifiedItems);
	}

	public static void GetItemSubTypeStats(DataContext context, Dictionary<ItemKey, int> inventoryItems, ItemKey[] equipmentItems)
	{
		Dictionary<short, (sbyte, int)> itemSubTypeStats = context.AdvanceMonthRelatedData.ItemSubTypeStats.Get();
		itemSubTypeStats.Clear();
		foreach (KeyValuePair<ItemKey, int> pair in inventoryItems)
		{
			ItemKey itemKey = pair.Key;
			int amount = pair.Value;
			short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
			sbyte itemGrade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
			if (itemSubTypeStats.TryGetValue(itemSubType, out var itemInfo))
			{
				itemGrade = Math.Max(itemInfo.Item1, itemGrade);
				amount = itemInfo.Item2 + amount;
			}
			itemSubTypeStats[itemSubType] = (itemGrade, amount);
		}
		for (int i = 0; i < equipmentItems.Length; i++)
		{
			ItemKey itemKey2 = equipmentItems[i];
			if (itemKey2.IsValid())
			{
				int amount2 = 1;
				short itemSubType2 = ItemTemplateHelper.GetItemSubType(itemKey2.ItemType, itemKey2.TemplateId);
				sbyte itemGrade2 = ItemTemplateHelper.GetGrade(itemKey2.ItemType, itemKey2.TemplateId);
				if (itemSubTypeStats.TryGetValue(itemSubType2, out var itemInfo2))
				{
					itemGrade2 = Math.Max(itemInfo2.Item1, itemGrade2);
					amount2 = itemInfo2.Item2 + amount2;
				}
				itemSubTypeStats[itemSubType2] = (itemGrade2, amount2);
			}
		}
	}

	public static GameData.Domains.Item.Medicine SelectMedicineToUse(DataContext context, EMedicineEffectType effectType, sbyte poisonType, int targetValue)
	{
		List<(GameData.Domains.Item.Medicine, int)>[] categorizedRegenItems = context.AdvanceMonthRelatedData.CategorizedMedicines.Get();
		int bestDiff = int.MaxValue;
		GameData.Domains.Item.Medicine bestMedicine = null;
		foreach (var (item, amount) in categorizedRegenItems[(int)effectType])
		{
			if (poisonType == item.GetEffectSubType().PoisonType() && !ModificationStateHelper.IsActive(item.GetModificationState(), 1))
			{
				short effectValue = item.GetEffectValue();
				int diff = effectValue - targetValue;
				diff *= diff;
				if (diff < bestDiff)
				{
					bestDiff = diff;
					bestMedicine = item;
				}
			}
		}
		return bestMedicine;
	}

