	public short GetItemPower(int charId, ItemKey itemKey)
	{
		if (!ItemPowerHelper.IsSupport(itemKey.ItemType))
		{
			throw new Exception($"Cannot get use power of item type {itemKey.ItemType}");
		}
		int power = GetItemRequirementsPower(charId, itemKey);
		power *= ItemPowerHelper.CalcPowerModify(charId, itemKey);
		return (short)Math.Clamp(power, 0, 9999);
	}

	public short GetItemMaxPower(int charId, ItemKey itemKey)
	{
		if (!ItemPowerHelper.IsSupport(itemKey.ItemType))
		{
			throw new Exception($"Cannot get use power of item type {itemKey.ItemType}");
		}
		if (itemKey.ItemType == 2 && Config.Accessory.Instance[itemKey.TemplateId].ItemSubType == 201)
		{
			return 0;
		}
		int maxPower = GlobalConfig.Instance.EquipmentBaseMaxPower;
		maxPower *= ItemPowerHelper.CalcMaxPowerModify(charId, itemKey);
		EquipmentBase equip = DomainManager.Item.TryGetBaseEquipment(itemKey);
		if (equip != null && ModificationStateHelper.IsActive(equip.GetModificationState(), 2))
		{
			RefiningEffects refiningEffects = DomainManager.Item.GetRefinedEffects(itemKey);
			sbyte itemType = itemKey.ItemType;
			if (1 == 0)
			{
			}
			int num = itemType switch
			{
				0 => refiningEffects.GetWeaponPropertyBonus(ERefiningEffectWeaponType.MaxPower), 
				1 => refiningEffects.GetArmorPropertyBonus(ERefiningEffectArmorType.MaxPower), 
				_ => 0, 
			};
			if (1 == 0)
			{
			}
			int refineBonus = num;
			refineBonus = ProfessionSkillHandle.GetRefineBonus_CraftSkill_2(refineBonus, equip.GetEquippedCharId());
			maxPower += refineBonus;
		}
		return (short)Math.Clamp(maxPower, 0, 9999);
	}

	public short GetItemRequirementsPower(int charId, ItemKey itemKey)
	{
		if (!ItemPowerHelper.IsSupport(itemKey.ItemType))
		{
			throw new Exception($"Cannot get use power of item type {itemKey.ItemType}");
		}
		Character character = GetElement_Objects(charId);
		short fixPower = character.CalcItemFixPower(itemKey);
		if (fixPower >= 0)
		{
			return fixPower;
		}
		int power = 0;
		IReadOnlyList<PropertyAndValue> requirements = ItemPowerHelper.CalcRequirements(itemKey);
		short maxPower = GetItemMaxPower(charId, itemKey);
		CValuePercent requirementPercent = ItemPowerHelper.CalcRequirementPercent(charId, itemKey);
		int requirementsCount = requirements.Count;
		int compatibilityPower = 0;
		if (DomainManager.Item.TryGetElement_MysteryData(itemKey.Id, out var mysteryData))
		{
			int compatibility = mysteryData.Compatibility?.GetOrDefault(charId) ?? 0;
			int require = itemKey.GetConfig().MysteryEffect.CompatibilityRequirement;
			compatibilityPower = Math.Min(compatibility * 100 / require, maxPower);
		}
		if (requirementsCount > 0)
		{
			for (int i = 0; i < requirementsCount; i++)
			{
				PropertyAndValue requirement = requirements[i];
				if (requirement.Value > 0)
				{
					int actualValue = character.GetPropertyValue((ECharacterPropertyReferencedType)requirement.PropertyId);
					int requireValue = requirement.Value * requirementPercent;
					int requirementPower = Math.Min(actualValue * 100 / requireValue, maxPower);
					if (requirementPower >= compatibilityPower)
					{
						power += requirementPower;
						continue;
					}
					power += compatibilityPower;
					compatibilityPower = requirementPower;
				}
			}
			if (requirementsCount > 1)
			{
				power /= requirementsCount;
			}
		}
		else
		{
			power = 100;
		}
		return (short)Math.Clamp(power, 0, maxPower);
	}

	public int CalcWeaponChangeTrickValue(int charId, ItemKey itemKey, bool isFirstAttack = true, bool hit = true)
	{
		int addValue = (isFirstAttack ? GlobalConfig.Instance.FirstAttackAddChangeTrickProgress : GlobalConfig.Instance.PursueAttackAddChangeTrickProgress);
		addValue = addValue * GetWeaponChangeTrickPercent(charId, itemKey) / 100;
		if (hit)
		{
			return addValue;
		}
		GameData.Domains.Item.Weapon weapon = DomainManager.Item.GetElement_Weapons(itemKey.Id);
		sbyte attackPointCost = weapon.GetAttackPreparePointCost();
		int factor = GlobalConfig.Instance.AvoidChangeTrickProgressPercentByWeapon[attackPointCost];
		return addValue * (CValuePercent)factor;
	}

	public int GetWeaponChangeTrickPercent(int charId, ItemKey itemKey)
	{
		if (itemKey.ItemType != 0)
		{
			throw new Exception($"Cannot get use ChangeTrickPercent of item type {itemKey.ItemType}");
		}
		short usePower = GetItemPower(charId, itemKey);
		int percent = Config.Weapon.Instance[itemKey.TemplateId].ChangeTrickPercent * usePower / 100;
		if (DomainManager.Item.TryGetElement_Weapons(itemKey.Id, out var weapon) && ModificationStateHelper.IsActive(weapon.GetModificationState(), 2))
		{
			int refineBonus = DomainManager.Item.GetRefinedEffects(itemKey).GetWeaponPropertyBonus(ERefiningEffectWeaponType.ChangeTrickPercent);
			refineBonus = ProfessionSkillHandle.GetRefineBonus_CraftSkill_2(refineBonus, weapon.GetEquippedCharId());
			percent = percent * (100 + refineBonus) / 100;
		}
		return percent;
	}

	public List<(int type, int required, int actual)> GetItemRequirementsAndActualValues(int charId, ItemKey itemKey)
	{
		if (!ItemPowerHelper.IsSupport(itemKey.ItemType))
		{
			throw new Exception($"Cannot get use power of item type {itemKey.ItemType}");
		}
		Character character = ((charId >= 0) ? GetElement_Objects(charId) : null);
		IReadOnlyList<PropertyAndValue> requirements = ItemPowerHelper.CalcRequirements(itemKey);
		List<(int, int, int)> result = new List<(int, int, int)>();
		CValuePercent requirementPercent = ItemPowerHelper.CalcRequirementPercent(charId, itemKey);
		for (int i = 0; i < requirements.Count; i++)
		{
			PropertyAndValue requirement = requirements[i];
			result.Add((requirement.PropertyId, requirement.Value * requirementPercent, character?.GetPropertyValue((ECharacterPropertyReferencedType)requirement.PropertyId) ?? 0));
		}
		if (DomainManager.Item.TryGetElement_MysteryData(itemKey.Id, out var mysteryData))
		{
			int compatibility = mysteryData.Compatibility?.GetOrDefault(charId) ?? 0;
			int require = itemKey.GetConfig().MysteryEffect.CompatibilityRequirement * requirementPercent;
			result.Add((135, require, compatibility));
		}
		return result;
	}

	public void RemoveAllInventoryAndEquippedItems(DataContext context, Character character)
	{
		ItemKey[] equipment = character.GetEquipment();
		for (int i = 0; i < 17; i++)
		{
			ItemKey itemKey = equipment[i];
			if (itemKey.IsValid())
			{
				DomainManager.Item.RemoveItem(context, itemKey);
				equipment[i] = ItemKey.Invalid;
			}
		}
		character.SetEquipment(equipment, context);
		Inventory inventory = character.GetInventory();
		foreach (var (itemKey3, amount) in inventory.Items)
		{
			DomainManager.Item.RemoveItem(context, itemKey3);
		}
		inventory.Items.Clear();
		character.SetInventory(inventory, context);
	}

	public ItemDisplayData.ItemUsingType GetItemUsingType(ItemKey itemKey, int charId)
	{
		bool isTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		ItemDisplayData.ItemUsingType usingType = ItemDisplayData.ItemUsingType.Invalid;
		if (ItemType.IsEquipmentItemType(itemKey.ItemType))
		{
			ItemKey[] equipment = DomainManager.Character.GetElement_Objects(charId).GetEquipment();
			ItemKey[] array = equipment;
			foreach (ItemKey key in array)
			{
				if (key.Equals(itemKey))
				{
					usingType = ItemDisplayData.ItemUsingType.Equiped;
					break;
				}
			}
			if (usingType != ItemDisplayData.ItemUsingType.Equiped && isTaiwu && DomainManager.Taiwu.CheckItemIsInEquipmentPlan(itemKey))
			{
				usingType = ItemDisplayData.ItemUsingType.EquipmentPlaned;
			}
			if (DomainManager.Extra.IsItemJiaoRelated(itemKey) && DomainManager.Extra.TryGetJiaoIdByItemKey(itemKey, out var jiaoId) && DomainManager.Extra.TryGetJiao(jiaoId, out var jiao) && jiao.GrowthStage == 2)
			{
				foreach (JiaoPool jiaoPool in DomainManager.Extra.GetJiaoPools())
				{
					if (jiaoPool.Jiaos.Count >= 2 && jiaoPool.Jiaos.Contains(jiaoId))
					{
						usingType = ItemDisplayData.ItemUsingType.Breeding;
						break;
					}
				}
			}
		}
		else if (itemKey.ItemType == 10 && isTaiwu)
		{
			if (DomainManager.Taiwu.GetCurReadingBook().Equals(itemKey))
			{
				usingType = ItemDisplayData.ItemUsingType.Reading;
			}
			else
			{
				ItemKey[] referenceBooks = DomainManager.Taiwu.GetReferenceBooks();
				ItemKey[] array2 = referenceBooks;
				foreach (ItemKey key2 in array2)
				{
					if (key2.Equals(itemKey))
					{
						usingType = ItemDisplayData.ItemUsingType.Referring;
						break;
					}
				}
			}
		}
		return usingType;
	}

	public void ClearItemUsingState(DataContext context, ItemKey itemKey, int charId, ItemDisplayData.ItemUsingType usingType = ItemDisplayData.ItemUsingType.Invalid)
	{
		if (usingType == ItemDisplayData.ItemUsingType.Invalid)
		{
			usingType = GetItemUsingType(itemKey, charId);
		}
		if (usingType == ItemDisplayData.ItemUsingType.Invalid)
		{
			return;
		}
		bool isTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		switch (usingType)
		{
		case ItemDisplayData.ItemUsingType.Reading:
			if (isTaiwu && DomainManager.Taiwu.GetCurReadingBook().Equals(itemKey))
			{
				DomainManager.Taiwu.SetReadingBook(context, ItemKey.Invalid);
			}
			break;
		case ItemDisplayData.ItemUsingType.Referring:
			if (isTaiwu)
			{
				ItemKey[] referenceBooks = DomainManager.Taiwu.GetReferenceBooks();
				int index = Array.IndexOf(referenceBooks, itemKey);
				DomainManager.Taiwu.SetReferenceBook(context, (sbyte)index, ItemKey.Invalid);
			}
			break;
		case ItemDisplayData.ItemUsingType.Equiped:
		{
			ItemKey[] equipment = DomainManager.Character.GetElement_Objects(charId).GetEquipment();
			sbyte slot = EquipmentSlotHelper.GetEquipmentSlot(itemKey, equipment);
			if (slot != -1)
			{
				DomainManager.Character.ChangeEquipment(context, charId, slot, -1, itemKey);
			}
			break;
		}
		case ItemDisplayData.ItemUsingType.EquipmentPlaned:
		{
			if (isTaiwu && DomainManager.Taiwu.FindItemInEquipmentPlan(itemKey, out var planIndex, out var slotIndex))
			{
				DomainManager.Taiwu.SetEquipmentPlan(context, ItemKey.Invalid, planIndex, slotIndex);
			}
			break;
		}
		case ItemDisplayData.ItemUsingType.Breeding:
			break;
		}
	}

	public void RandomChangeEquipmentDurability(DataContext context, Character character, sbyte itemType, bool isAdd, float percent)
	{
		List<ItemBase> items = new List<ItemBase>();
		if (isAdd)
		{
			ItemKey[] equipment = character.GetEquipment();
			for (int i = 0; i < equipment.Length; i++)
			{
				ItemKey itemKey = equipment[i];
				if (itemKey.Id < 0 || itemKey.ItemType != itemType)
				{
					continue;
				}
				WeaponItem itemConfig = Config.Weapon.Instance[itemKey.TemplateId];
				if (itemConfig.Transferable)
				{
					ItemBase itemBase = DomainManager.Item.GetBaseItem(itemKey);
					if (itemBase.GetMaxDurability() > itemBase.GetCurrDurability())
					{
						items.Add(itemBase);
					}
				}
			}
			if (items.Count != 0)
			{
				ItemBase item = items[context.Random.Next(items.Count)];
				short curValue = (short)Math.Clamp((float)item.GetCurrDurability() * (1f + percent), 0f, item.GetMaxDurability());
				item.SetCurrDurability(curValue, context);
			}
			return;
		}
		ItemKey[] equipment2 = character.GetEquipment();
		for (int j = 0; j < equipment2.Length; j++)
		{
			ItemKey itemKey2 = equipment2[j];
			if (itemKey2.Id >= 0 && itemKey2.ItemType == itemType)
			{
				WeaponItem itemConfig2 = Config.Weapon.Instance[itemKey2.TemplateId];
				if (itemConfig2.Transferable)
				{
					ItemBase itemBase2 = DomainManager.Item.GetBaseItem(itemKey2);
					items.Add(itemBase2);
				}
			}
		}
		if (items.Count != 0)
		{
			ItemBase item2 = items[context.Random.Next(items.Count)];
			short curValue2 = (short)Math.Clamp((float)item2.GetCurrDurability() * (1f - percent), 0f, item2.GetMaxDurability());
			if (curValue2 == 0)
			{
				DomainManager.Taiwu.RemoveItem(context, item2.GetItemKey(), 1, 1, deleteItem: true);
			}
			else
			{
				item2.SetCurrDurability(curValue2, context);
			}
		}
	}

