				list.Add(ItemDisplayData.CreateResource(type, amount, charId));
			}
		}
		return list;
	}

	private static (long positiveWorth, long negativeWorth) GetResourcesWorth(ref ResourceInts values)
	{
		long positiveWorth = 0L;
		long negativeWorth = 0L;
		for (int i = 0; i < 8; i++)
		{
			long worth = (long)GlobalConfig.ResourcesWorth[i] * (long)values.Get(i);
			if (worth >= 0)
			{
				positiveWorth += worth;
			}
			else
			{
				negativeWorth -= worth;
			}
		}
		return (positiveWorth: positiveWorth, negativeWorth: negativeWorth);
	}

	private static void CreateItemDisplayData(int charId, ItemKey itemKey, int amount, List<ItemDisplayData> dataList, Dictionary<int, List<ItemDisplayData>> templateIdToDisplayListDict, ItemSourceType itemSourceType)
	{
		bool isLoveToken = ModificationStateHelper.IsActive(itemKey.ModificationState, 4);
		bool isExtraGoods = ModificationStateHelper.IsActive(itemKey.ModificationState, 8);
		bool needCreate = true;
		int realKey = itemKey.ItemType * 10000 + itemKey.TemplateId;
		if (!templateIdToDisplayListDict.TryGetValue(realKey, out var displayList))
		{
			displayList = new List<ItemDisplayData>();
			templateIdToDisplayListDict.Add(realKey, displayList);
		}
		ItemBase item = DomainManager.Item.TryGetBaseItem(itemKey);
		bool stackable = ItemTemplateHelper.IsStackable(itemKey.ItemType, itemKey.TemplateId);
		MerchantExtraGoodsData.ExtraGoodsType extraGoodsType = MerchantExtraGoodsData.ExtraGoodsType.None;
		if (stackable && !isLoveToken)
		{
			if (item == null)
			{
				ItemDisplayData display = displayList.Find((ItemDisplayData d) => d.Key.TemplateEquals(itemKey));
				if (display != null)
				{
					for (int i = 0; i < amount; i++)
					{
						display.ChangeAmount(itemKey, isAdd: true);
					}
				}
				else
				{
					ItemDisplayData itemDisplayData = new ItemDisplayData(itemKey.ItemType, itemKey.TemplateId)
					{
						Amount = amount,
						OwnerCharId = charId
					};
					dataList.Add(itemDisplayData);
					displayList.Add(itemDisplayData);
				}
				needCreate = false;
				if (!ItemTemplateHelper.IsThanksLetter(itemKey.ItemType, itemKey.TemplateId))
				{
					AdaptableLog.Warning($"Try get not exist item display data by {itemKey}");
				}
			}
			else if (isExtraGoods)
			{
				extraGoodsType = DomainManager.Extra.GetExtraGoodsType(itemKey);
				if (extraGoodsType > MerchantExtraGoodsData.ExtraGoodsType.None)
				{
					ItemDisplayData display = displayList.Find((ItemDisplayData d) => d.Key.TemplateEquals(itemKey) && d.ExtraGoodsType == (sbyte)extraGoodsType);
					if (display != null)
					{
						for (int i2 = 0; i2 < amount; i2++)
						{
							display.ChangeAmount(itemKey, isAdd: true);
						}
						needCreate = false;
					}
				}
			}
			else if (item.GetPoisonable())
			{
				bool hasPoison = ModificationStateHelper.IsActive(item.GetModificationState(), 1);
				FullPoisonEffects poisonEffects = (hasPoison ? DomainManager.Item.PoisonEffects[item.GetId()] : new FullPoisonEffects());
				ItemDisplayData display = ((!poisonEffects.IsIdentified) ? displayList.Find((ItemDisplayData d) => (d.PoisonEffects == null || !d.PoisonEffects.IsIdentified) && d.ExtraGoodsTypeEnum == MerchantExtraGoodsType.None) : displayList.Find((ItemDisplayData d) => poisonEffects.SameOf(d.PoisonEffects) && d.ExtraGoodsTypeEnum == MerchantExtraGoodsType.None));
				if (display != null)
				{
					for (int i3 = 0; i3 < amount; i3++)
					{
						display.ChangeAmount(itemKey, isAdd: true);
					}
					needCreate = false;
				}
			}
		}
		if (needCreate)
		{
			ItemDisplayData itemDisplayData2 = DomainManager.Item.GetItemDisplayData(item, amount, charId, (sbyte)itemSourceType);
			itemDisplayData2.ExtraGoodsType = (sbyte)extraGoodsType;
			dataList.Add(itemDisplayData2);
			displayList.Add(itemDisplayData2);
		}
	}

	public static List<ItemDisplayData> GetItemDisplayData(int charId, List<(ItemKey itemKey, int amount)> items, ItemSourceType itemSourceType)
	{
		List<ItemDisplayData> dataList = new List<ItemDisplayData>();
		Dictionary<int, List<ItemDisplayData>> templateIdToDisplayListDict = new Dictionary<int, List<ItemDisplayData>>();
		int i = 0;
		for (int count = items.Count; i < count; i++)
		{
			var (itemKey, amount) = items[i];
			CreateItemDisplayData(charId, itemKey, amount, dataList, templateIdToDisplayListDict, itemSourceType);
		}
		return dataList;
	}

	public static List<ItemDisplayData> GetItemDisplayData(int charId, IReadOnlyDictionary<ItemKey, int> items, ItemSourceType itemSourceType)
	{
		List<ItemDisplayData> dataList = new List<ItemDisplayData>();
		Dictionary<int, List<ItemDisplayData>> templateIdToDisplayListDict = new Dictionary<int, List<ItemDisplayData>>();
		foreach (var (itemKey2, amount) in items)
		{
			CreateItemDisplayData(charId, itemKey2, amount, dataList, templateIdToDisplayListDict, itemSourceType);
		}
		return dataList;
	}

	private static void RemoveTaiwuReadingBookFromClassifiedItems(List<(ItemBase, int)>[] classifiedItems)
	{
		List<ItemKey> cannotBeLost = new List<ItemKey>();
		cannotBeLost.AddRange(DomainManager.Taiwu.GetReferenceBooks());
		cannotBeLost.Add(DomainManager.Taiwu.GetCurReadingBook());
		for (int i = 0; i < cannotBeLost.Count; i++)
		{
			ItemKey itemKey = cannotBeLost[i];
			if (!itemKey.IsValid())
			{
				continue;
			}
			ItemBase item = DomainManager.Item.GetBaseItem(itemKey);
			List<(ItemBase, int)> itemList = classifiedItems[item.GetGrade() / 3];
			for (int j = itemList.Count - 1; j >= 0; j--)
			{
				if (itemList[j].Item1.GetItemKey().Equals(itemKey))
				{
					itemList.RemoveAt(j);
					break;
				}
			}
		}
	}

	private unsafe void RemoveAllItemsBeforeRemovingCharacter(DataContext context, Character character)
	{
		ItemKey[] equipment = character.GetEquipment();
		for (int i = 0; i < 17; i++)
		{
			ItemKey itemKey = equipment[i];
			if (itemKey.IsValid())
			{
				DomainManager.Item.RemoveItem(context, itemKey);
			}
		}
		Inventory inventory = character.GetInventory();
		foreach (var (itemKey3, amount) in inventory.Items)
		{
			if (itemKey3.IsValid())
			{
				DomainManager.Item.RemoveItem(context, itemKey3);
			}
		}
		EatingItems eatingItems = character.GetEatingItems();
		for (int j = 0; j < 9; j++)
		{
			ItemKey itemKey4 = (ItemKey)eatingItems.ItemKeys[j];
			if (itemKey4.IsValid())
			{
				DomainManager.Item.RemoveItem(context, itemKey4);
			}
		}
	}

