	[DomainMethod]
	public void TransferKidnappedCharacters(DataContext context, int targetKidnapperId, int sourceKidnapperId, KidnappedCharacterList kidnappedCharsToTransfer)
	{
		List<KidnappedCharacter> kidnappedChars = kidnappedCharsToTransfer.GetCollection();
		if (kidnappedChars.Count != 0)
		{
			KidnappedCharacterList targetKidnappedCharList;
			bool isKidnapper = TryGetElement_KidnappedChars(targetKidnapperId, out targetKidnappedCharList);
			if (targetKidnappedCharList == null)
			{
				targetKidnappedCharList = new KidnappedCharacterList();
			}
			if (!TryGetElement_KidnappedChars(sourceKidnapperId, out var sourceKidnappedCharList))
			{
				throw new Exception("The source kidnapper has not kidnapped anyone.");
			}
			for (int i = kidnappedChars.Count - 1; i >= 0; i--)
			{
				KidnappedCharacter kidnappedCharData = kidnappedChars[i];
				kidnappedCharData.OfflineChangeResistance(GlobalConfig.Instance.ResistChangeOnKidnapCharacterTransfer);
				Character kidnappedChar = GetElement_Objects(kidnappedCharData.CharId);
				TryCreateRelation(context, targetKidnapperId, kidnappedCharData.CharId);
				kidnappedChar.SetKidnapperId(targetKidnapperId, context);
				targetKidnappedCharList.Add(kidnappedCharData);
				sourceKidnappedCharList.Remove(kidnappedCharData.CharId);
				Logger.Info($"{kidnappedChar} is being transfered from one kidnapper to another: {sourceKidnapperId} => {targetKidnapperId}.");
			}
			Character sourceKidnapper = GetElement_Objects(sourceKidnapperId);
			Character targetKidnapper = GetElement_Objects(targetKidnapperId);
			if (sourceKidnappedCharList.GetCount() == 0)
			{
				RemoveElement_KidnappedChars(sourceKidnapperId, context);
				sourceKidnapper.DeactivateExternalRelationState(context, 2uL);
			}
			else
			{
				SetElement_KidnappedChars(sourceKidnapperId, sourceKidnappedCharList, context);
			}
			if (isKidnapper)
			{
				SetElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
			}
			else
			{
				AddElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
			}
			RemoveAllKidnappedChars(context, sourceKidnapper, isEscaped: false);
			targetKidnapper.ActiveExternalRelationState(context, 2uL);
			kidnappedCharsToTransfer.Clear();
		}
	}

	[DomainMethod]
	public void ChangeKidnappedCharacterRope(DataContext context, int kidnapperId, int kidnappedCharId, ItemKey newRopeKey)
	{
		if (!TryGetElement_KidnappedChars(kidnapperId, out var kidnappedChars))
		{
			throw new Exception($"Character {kidnappedCharId} is not kidnapped by character {kidnapperId}");
		}
		for (int i = 0; i < kidnappedChars.GetCount(); i++)
		{
			KidnappedCharacter kidnappedChar = kidnappedChars.Get(i);
			if (kidnappedChar.CharId == kidnappedCharId)
			{
				DomainManager.Item.RemoveItem(context, kidnappedChar.RopeItemKey);
				kidnappedChar.RopeItemKey = newRopeKey;
				Character kidnapper = GetElement_Objects(kidnapperId);
				kidnapper.RemoveInventoryItem(context, newRopeKey, 1, deleteItem: false);
				DomainManager.Item.SetOwner(newRopeKey, ItemOwnerType.KidnapperRope, kidnappedCharId);
				SetElement_KidnappedChars(kidnapperId, kidnappedChars, context);
				return;
			}
		}
		throw new Exception($"Character {kidnappedCharId} is not kidnapped by character {kidnapperId}");
	}

