	[DomainMethod]
	public unsafe void TransferKidnappedCharacter(DataContext context, int targetKidnapperId, int sourceKidnapperId, KidnappedCharacter kidnappedCharData)
	{
		KidnappedCharacterList targetKidnappedCharList;
		bool isKidnapper = TryGetElement_KidnappedChars(targetKidnapperId, out targetKidnappedCharList);
		if (!TryGetElement_KidnappedChars(sourceKidnapperId, out var sourceKidnappedCharList))
		{
			throw new Exception("The source kidnapper has not kidnapped anyone.");
		}
		Character targetKidnapper = GetElement_Objects(targetKidnapperId);
		Character kidnappedChar = GetElement_Objects(kidnappedCharData.CharId);
		Personalities kidnappedCharPersonalities = kidnappedChar.GetPersonalities();
		kidnappedCharData.ExtraResistance = kidnappedCharPersonalities.Items[3];
		kidnappedCharData.KidnapBeginDate = DomainManager.World.GetCurrDate();
		kidnappedChar.SetKidnapperId(targetKidnapperId, context);
		if (targetKidnappedCharList == null)
		{
			targetKidnappedCharList = new KidnappedCharacterList();
		}
		targetKidnappedCharList.Add(kidnappedCharData);
		sourceKidnappedCharList.Remove(kidnappedCharData.CharId);
		Logger.Info($"{kidnappedChar} is being transfered from one kidnapper to another: {sourceKidnapperId} => {targetKidnapperId}.");
		if (sourceKidnappedCharList.GetCount() == 0)
		{
			RemoveElement_KidnappedChars(sourceKidnapperId, context);
			if (DomainManager.Character.TryGetElement_Objects(sourceKidnapperId, out var sourceKidnapper))
			{
				sourceKidnapper.DeactivateExternalRelationState(context, 2uL);
				RecordIsTaiwuGetKidnapper(context, sourceKidnapperId, targetKidnapperId, sourceKidnapper, targetKidnapper, kidnappedChar);
			}
		}
		else
		{
			SetElement_KidnappedChars(sourceKidnapperId, sourceKidnappedCharList, context);
			if (DomainManager.Character.TryGetElement_Objects(sourceKidnapperId, out var sourceKidnapper2))
			{
				RecordIsTaiwuGetKidnapper(context, sourceKidnapperId, targetKidnapperId, sourceKidnapper2, targetKidnapper, kidnappedChar);
			}
		}
		if (isKidnapper)
		{
			SetElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
		}
		else
		{
			AddElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
		}
		targetKidnapper.ActiveExternalRelationState(context, 2uL);
	}

	private void RecordIsTaiwuGetKidnapper(DataContext context, int sourceKidnapperId, int targetKidnapperId, Character sourceKidnapper, Character targetKidnapper, Character kidnappedChar)
	{
		if (targetKidnapperId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			int value = (int)KidnapCharDisplayData.ValueImpl(kidnappedChar.GetFame(), kidnappedChar.GetAvatar().GetCharm(kidnappedChar.GetPhysiologicalAge(), kidnappedChar.GetClothingDisplayId()), kidnappedChar.GetOrganizationInfo().Grade, kidnappedChar.GetDisplayingGender(), kidnappedChar.GetPhysiologicalAge());
			int result = value / 5;
			result = DomainManager.Character.CalcAlertnessChangeValue(result);
			CharacterAlertnessData alertnessData = DomainManager.Character.GetAlertnessData(context, sourceKidnapperId, init: true);
			if (alertnessData != null)
			{
				DomainManager.Character.ChangeAlertness(context, sourceKidnapperId, result);
			}
			ChangeFavorabilityOptionalGiftItem(context, sourceKidnapper, targetKidnapper, -GlobalConfig.Instance.GetPrisonerFavorChange[kidnappedChar.GetOrganizationInfo().Grade]);
			targetKidnapper.ChangeHappiness(context, -GlobalConfig.Instance.GetPrisonerHappinessChange[kidnappedChar.GetOrganizationInfo().Grade]);
		}
	}

	[DomainMethod]
	public void RemoveKidnappedCharacter(DataContext context, int kidnappedCharId, int kidnapperId, bool isEscaped)
	{
		Character kidnapper = GetElement_Objects(kidnapperId);
		KidnappedCharacterList kidnappedChars = _kidnappedChars[kidnapperId];
		int slotIndex = kidnappedChars.IndexOf(kidnappedCharId);
		if (slotIndex < 0)
		{
			throw new Exception($"Character {kidnappedCharId} is not kidnapped by character {kidnapperId}");
		}
		RemoveKidnappedCharacter(context, kidnapper, kidnappedChars, slotIndex, isEscaped);
	}

	public unsafe void AddKidnappedCharacter(DataContext context, Character character, Character kidnappedChar, ItemKey ropeItemKey)
	{
		Logger.Info($"{character} is kidnapping {kidnappedChar}.");
		if (kidnappedChar.GetCreatingType() == 2)
		{
			ConvertRandomEnemy(context, kidnappedChar, character.GetLocation());
		}
		else if (IsTemporaryIntelligentCharacter(kidnappedChar.GetId()))
		{
			ConvertTemporaryIntelligentCharacter(context, kidnappedChar);
		}
		TryCreateGeneralRelation(context, character, kidnappedChar);
		TransferKidnappedCharsToGrandKidnapper(context, character, kidnappedChar);
		int charId = character.GetId();
		int kidnappedCharId = kidnappedChar.GetId();
		Personalities kidnappedCharPersonalities = kidnappedChar.GetPersonalities();
		sbyte initialResistance = kidnappedCharPersonalities.Items[3];
		if (charId == kidnappedCharId)
		{
			throw new Exception($"Character {charId} cannot kidnap him or herself.");
		}
		if (kidnappedChar.GetKidnapperId() >= 0)
		{
			throw new Exception($"Character {character} cannot kidnap {kidnappedChar} who is already kidnapped by {kidnappedChar.GetKidnapperId()}.");
		}
		if (kidnappedChar.GetLeaderId() >= 0)
		{
			LeaveGroup(context, kidnappedChar, bringWards: false);
		}
		character.RemoveInventoryItem(context, ropeItemKey, 1, deleteItem: false);
		DomainManager.Item.SetOwner(ropeItemKey, ItemOwnerType.KidnapperRope, kidnappedCharId);
		if (!_kidnappedChars.TryGetValue(charId, out var kidnappedChars))
		{
			kidnappedChars = new KidnappedCharacterList();
			kidnappedChars.Add(kidnappedCharId, initialResistance, ropeItemKey, DomainManager.World.GetCurrDate());
			AddElement_KidnappedChars(charId, kidnappedChars, context);
		}
		else
		{
			kidnappedChars.Add(kidnappedCharId, initialResistance, ropeItemKey, DomainManager.World.GetCurrDate());
			SetElement_KidnappedChars(charId, kidnappedChars, context);
		}
		Location srcLocation = kidnappedChar.GetLocation();
		Location destLocation = Location.Invalid;
		kidnappedChar.SetLocation(destLocation, context);
		if (kidnappedChar.IsCompletelyInfected())
		{
			Events.RaiseInfectedCharacterLocationChanged(context, kidnappedCharId, srcLocation, destLocation);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, kidnappedCharId, srcLocation, destLocation);
		}
		kidnappedChar.SetKidnapperId(charId, context);
		character.ActiveExternalRelationState(context, 2uL);
		Events.RaiseKidnappedStatusChanged(context, kidnappedChar, charId, isKidnapped: true);
	}

	public void RemoveKidnappedCharacter(DataContext context, Character character, KidnappedCharacterList kidnappedChars, int slotIndex, bool isEscaped)
	{
		int charId = character.GetId();
		KidnappedCharacter kidnappedCharData = kidnappedChars.Get(slotIndex);
		ItemKey ropeItemKey = kidnappedCharData.RopeItemKey;
		Logger.Info($"Removing {character}'s kidnapped character: {kidnappedCharData.CharId} (isEscape={isEscaped}).");
		kidnappedChars.RemoveAt(slotIndex);
		if (kidnappedChars.GetCount() <= 0)
		{
			RemoveElement_KidnappedChars(charId, context);
			character.DeactivateExternalRelationState(context, 2uL);
		}
		else
		{
			SetElement_KidnappedChars(charId, kidnappedChars, context);
		}
		if (TryGetElement_Objects(kidnappedCharData.CharId, out var kidnappedChar))
		{
			Location srcLocation = kidnappedChar.GetLocation();
			Location destLocation = character.GetLocation();
			if (!destLocation.IsValid())
			{
				destLocation = character.GetValidLocation();
			}
			kidnappedChar.SetLocation(destLocation, context);
			if (kidnappedChar.IsCompletelyInfected())
			{
				Events.RaiseInfectedCharacterLocationChanged(context, kidnappedCharData.CharId, srcLocation, destLocation);
			}
			else
			{
				Events.RaiseCharacterLocationChanged(context, kidnappedCharData.CharId, srcLocation, destLocation);
			}
			kidnappedChar.SetKidnapperId(-1, context);
			Events.RaiseKidnappedStatusChanged(context, kidnappedChar, charId, isKidnapped: false);
		}
		if (ropeItemKey.IsValid())
		{
			DomainManager.Item.RemoveOwner(ropeItemKey, ItemOwnerType.KidnapperRope, kidnappedCharData.CharId);
			if (isEscaped)
			{
				DomainManager.Item.RemoveItem(context, ropeItemKey);
			}
			else
			{
				character.AddInventoryItem(context, ropeItemKey, 1);
			}
		}
	}

	private unsafe void TransferKidnappedCharsToGrandKidnapper(DataContext context, Character targetKidnapper, Character sourceKidnapper)
	{
		int sourceKidnapperId = sourceKidnapper.GetId();
		int targetKidnapperId = targetKidnapper.GetId();
		if (!TryGetElement_KidnappedChars(sourceKidnapperId, out var sourceKidnappedCharList))
		{
			return;
		}
		KidnappedCharacterList targetKidnappedCharList;
		bool isKidnapper = TryGetElement_KidnappedChars(targetKidnapperId, out targetKidnappedCharList);
		if (targetKidnappedCharList == null)
		{
			targetKidnappedCharList = new KidnappedCharacterList();
		}
		List<KidnappedCharacter> collection = sourceKidnappedCharList.GetCollection();
		for (int i = collection.Count - 1; i >= 0; i--)
		{
			KidnappedCharacter kidnappedCharData = collection[i];
			if (!context.Random.CheckProb(40, 100))
			{
				Character kidnappedChar = GetElement_Objects(kidnappedCharData.CharId);
				Personalities kidnappedCharPersonalities = kidnappedChar.GetPersonalities();
				kidnappedCharData.ExtraResistance = kidnappedCharPersonalities.Items[3];
				kidnappedCharData.KidnapBeginDate = DomainManager.World.GetCurrDate();
				TryCreateRelation(context, targetKidnapperId, kidnappedCharData.CharId);
				kidnappedChar.SetKidnapperId(targetKidnapperId, context);
				targetKidnappedCharList.Add(kidnappedCharData);
				sourceKidnappedCharList.RemoveAt(i);
				Logger.Info($"{kidnappedChar} is being transfered from one kidnapper to another: {sourceKidnapperId} => {targetKidnapperId}.");
			}
		}
		if (sourceKidnappedCharList.GetCount() == 0)
		{
			RemoveElement_KidnappedChars(sourceKidnapperId, context);
			sourceKidnapper.DeactivateExternalRelationState(context, 2uL);
		}
		else
		{
			SetElement_KidnappedChars(sourceKidnapperId, sourceKidnappedCharList, context);
		}
		if (isKidnapper)
		{
			SetElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
		}
		else
		{
			AddElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
		}
		RemoveAllKidnappedChars(context, sourceKidnapper, isEscaped: true);
		targetKidnapper.ActiveExternalRelationState(context, 2uL);
	}

	public void TransferKidnappedCharactersToTaiwuSuccessor(DataContext context, Character targetKidnapper, Character sourceKidnapper)
	{
		int sourceKidnapperId = sourceKidnapper.GetId();
		int targetKidnapperId = targetKidnapper.GetId();
		if (TryGetElement_KidnappedChars(sourceKidnapperId, out var sourceKidnappedCharList))
		{
			KidnappedCharacterList targetKidnappedCharList;
			bool isKidnapper = TryGetElement_KidnappedChars(targetKidnapperId, out targetKidnappedCharList);
			if (targetKidnappedCharList == null)
			{
				targetKidnappedCharList = new KidnappedCharacterList();
			}
			List<KidnappedCharacter> collection = sourceKidnappedCharList.GetCollection();
			for (int i = collection.Count - 1; i >= 0; i--)
			{
				KidnappedCharacter kidnappedCharData = collection[i];
				kidnappedCharData.OfflineChangeResistance(GlobalConfig.Instance.ResistChangeOnKidnapCharacterTransfer);
				Character kidnappedChar = GetElement_Objects(kidnappedCharData.CharId);
				TryCreateRelation(context, targetKidnapperId, kidnappedCharData.CharId);
				kidnappedChar.SetKidnapperId(targetKidnapperId, context);
				targetKidnappedCharList.Add(kidnappedCharData);
				sourceKidnappedCharList.RemoveAt(i);
				Logger.Info($"{kidnappedChar} is being transfered from one kidnapper to another: {sourceKidnapperId} => {targetKidnapperId}.");
			}
			if (sourceKidnappedCharList.GetCount() == 0)
			{
				RemoveElement_KidnappedChars(sourceKidnapperId, context);
				sourceKidnapper.DeactivateExternalRelationState(context, 2uL);
			}
			else
			{
				SetElement_KidnappedChars(sourceKidnapperId, sourceKidnappedCharList, context);
			}
			if (isKidnapper)
			{
				SetElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
			}
			else
			{
				AddElement_KidnappedChars(targetKidnapperId, targetKidnappedCharList, context);
			}
			RemoveAllKidnappedChars(context, sourceKidnapper, isEscaped: true);
			targetKidnapper.ActiveExternalRelationState(context, 2uL);
		}
	}

	public void UpdateKidnappedCharacters(DataContext context)
	{
		int currDate = DomainManager.World.GetCurrDate();
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		List<int> modifiedKidnappers = ObjectPool<List<int>>.Instance.Get();
		List<int> removedKidnappers = ObjectPool<List<int>>.Instance.Get();
		List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		modifiedKidnappers.Clear();
		removedKidnappers.Clear();
		foreach (KeyValuePair<int, KidnappedCharacterList> kidnappedChar2 in _kidnappedChars)
		{
			kidnappedChar2.Deconstruct(out var key, out var value);
			int kidnapperId = key;
			KidnappedCharacterList kidnappedChars = value;
			List<KidnappedCharacter> kidnappedCharList = kidnappedChars.GetCollection();
			Character kidnapperChar = GetElement_Objects(kidnapperId);
			Location srcLocation = kidnapperChar.GetLocation();
			if (!srcLocation.IsValid())
			{
				srcLocation = kidnapperChar.GetValidLocation();
			}
			bool kidnapperIsTaiwuPeople = IsTaiwuPeople(kidnapperId);
			bool kidnapperIsTaiwuGroup = DomainManager.Taiwu.IsInGroup(kidnapperId);
			int kidnappedCharCount = kidnappedCharList.Count;
			DomainManager.Map.GetRealNeighborBlocks(srcLocation.AreaId, srcLocation.BlockId, neighborBlocks, 3);
			for (int i = kidnappedCharList.Count - 1; i >= 0; i--)
			{
				KidnappedCharacter kidnappedCharInfo = kidnappedCharList[i];
				Character kidnappedChar = GetElement_Objects(kidnappedCharInfo.CharId);
				bool kidnappedCharIsTaiwuPeople = IsTaiwuPeople(kidnappedCharInfo.CharId);
				ChangeFavorabilityOptionalMonthlyEvolution(context, kidnappedChar, kidnapperChar, -3000);
				RelatedCharacter relation = GetRelation(kidnappedCharInfo.CharId, kidnapperId);
				sbyte favorType = FavorabilityType.GetFavorabilityType(relation.Favorability);
				if (favorType <= -2 && !RelationType.HasRelation(relation.RelationType, 32768))
				{
					if (kidnapperId == DomainManager.Taiwu.GetTaiwuCharId())
					{
						monthlyEventCollection.AddCaptiveBecomeEnemy(kidnappedCharInfo.CharId, srcLocation, kidnapperId);
					}
					Character.ApplyAddRelation_Enemy(context, kidnappedChar, kidnapperChar, kidnapperIsTaiwuPeople, 1);
				}
				if (!IsLockMovementChar(kidnappedCharInfo.CharId))
				{
					int exceedingAmount = Math.Max(0, kidnappedCharCount - kidnapperChar.GetKidnapMaxSlotCount());
					int totalResistance = CalcKidnappedCharacterTotalResistance(kidnapperChar, kidnappedCharInfo);
					if (kidnappedCharInfo.WillEscape(totalResistance))
					{
						int escapeRate = kidnappedCharInfo.CalcEscapeRate(totalResistance, exceedingAmount, kidnappedChar.IsEscapeCertainly());
						if (!context.Random.CheckPercentProb(escapeRate))
						{
							if (kidnappedCharIsTaiwuPeople || kidnapperIsTaiwuPeople)
							{
								monthlyNotificationCollection.AddEscapeFailed(kidnapperId, kidnappedCharInfo.CharId);
							}
							if (totalResistance >= 100 && kidnapperIsTaiwuGroup)
							{
								InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
								instantNotifications.AddPrepareEscape(kidnapperChar.GetId(), kidnappedChar.GetId(), escapeRate);
							}
						}
						else
						{
							ItemKey ropeItemKey = kidnappedCharInfo.RopeItemKey;
							kidnappedChars.RemoveAt(i);
							MapBlockData destBlock = neighborBlocks.GetRandom(context.Random);
							Location destLocation = new Location(destBlock.AreaId, destBlock.BlockId);
							if (kidnappedChar.IsCompletelyInfected())
							{
								Events.RaiseInfectedCharacterLocationChanged(context, kidnappedCharInfo.CharId, kidnappedChar.GetLocation(), destLocation);
							}
							else
							{
								Events.RaiseCharacterLocationChanged(context, kidnappedCharInfo.CharId, kidnappedChar.GetLocation(), destLocation);
							}
							kidnappedChar.SetLocation(destLocation, context);
							kidnappedChar.SetKidnapperId(-1, context);
							Events.RaiseKidnappedStatusChanged(context, kidnappedChar, kidnapperId, isKidnapped: false);
							if (ropeItemKey.IsValid())
							{
								DomainManager.Item.RemoveItem(context, ropeItemKey);
							}
							kidnappedChar.AddGoal(context, 274, kidnapperId);
							lifeRecordCollection.AddKidnappedCharacterEscaped(kidnappedCharInfo.CharId, currDate, kidnapperId, srcLocation);
							SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
							int secretInfoOffset = secretInformationCollection.AddKidnappedCharacterEscaped(kidnappedCharInfo.CharId, kidnapperId);
							SecretInformationId metaDataId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
							if (kidnapperId == DomainManager.Taiwu.GetTaiwuCharId())
							{
								monthlyEventCollection.AddEscapeFromPrison(kidnappedCharInfo.CharId, srcLocation, kidnapperId);
							}
							if (kidnappedCharIsTaiwuPeople || kidnapperIsTaiwuPeople)
							{
								AddEscapeMonthlyNotification(kidnappedCharInfo.CharId, kidnapperId, srcLocation);
								DomainManager.Information.ReceiveSecretInformation(context, metaDataId, DomainManager.Taiwu.GetTaiwuCharId(), kidnappedCharIsTaiwuPeople ? kidnappedCharInfo.CharId : kidnapperId);
							}
							Logger.Info($"{kidnapperChar}'s kidnapped character escaped: {kidnappedChar}.");
						}
					}
				}
			}
			if (kidnappedChars.GetCount() <= 0)
			{
				kidnappedChars.Clear();
				removedKidnappers.Add(kidnapperId);
				kidnapperChar.DeactivateExternalRelationState(context, 2uL);
			}
			else
			{
				modifiedKidnappers.Add(kidnapperId);
			}
		}
		foreach (int removedKidnapper in removedKidnappers)
		{
			RemoveElement_KidnappedChars(removedKidnapper, context);
		}
		foreach (int modifiedKidnapper in modifiedKidnappers)
		{
			SetElement_KidnappedChars(modifiedKidnapper, _kidnappedChars[modifiedKidnapper], context);
		}
		ObjectPool<List<int>>.Instance.Return(modifiedKidnappers);
		ObjectPool<List<int>>.Instance.Return(removedKidnappers);
		ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
	}

	private void AddEscapeMonthlyNotification(int kidnappedCharId, int kidnapperId, Location location)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		Character kidnappedChar = GetElement_Objects(kidnappedCharId);
		if (kidnappedChar.IsCompletelyInfected())
		{
			monthlyNotificationCollection.AddInfectedKidnapedCharacterEscape(kidnappedCharId, kidnapperId, location);
		}
		else if (kidnappedChar.IsOwningBook())
		{
			List<sbyte> ownedBookTypes = DomainManager.LegendaryBook.GetCharOwnedBookTypes(kidnappedCharId);
			ItemKey bookItemKey = DomainManager.LegendaryBook.GetLegendaryBookItem(ownedBookTypes.First());
			monthlyNotificationCollection.AddOwningBookKidnapedCharacterEscape(kidnappedCharId, kidnapperId, location, bookItemKey.ItemType, bookItemKey.TemplateId);
		}
		else
		{
			monthlyNotificationCollection.AddEscapeFromPrison(kidnappedCharId, location, kidnapperId);
		}
	}

	private int CalcKidnappedCharacterBaseResistance(Character kidnapper, KidnappedCharacter kidnappedChar)
	{
		Character kidnapped = DomainManager.Character.GetElement_Objects(kidnappedChar.CharId);
		int behaviorFactor = kidnapped.GetBehaviorType() + 1;
		int baseValue = behaviorFactor * 10;
		int levelEffect = GlobalConfig.Instance.MaxConsummateLevel + kidnapped.GetConsummateLevel() - kidnapper.GetConsummateLevel();
		short favor = DomainManager.Character.GetFavorability(kidnapped.GetId(), kidnapper.GetId());
		int favorEffect = -favor / 500;
		return baseValue + levelEffect + favorEffect;
	}

	public int CalcKidnappedCharacterTotalResistance(Character kidnapper, KidnappedCharacter kidnappedChar)
	{
		Character kidnapped = DomainManager.Character.GetElement_Objects(kidnappedChar.CharId);
		if (kidnapped.IsEscapeCertainly())
		{
			return 999;
		}
		int value = CalcKidnappedCharacterBaseResistance(kidnapper, kidnappedChar);
		return value + kidnappedChar.ExtraResistance;
	}

	public void RemoveAllKidnappedChars(DataContext context, Character character, bool isEscaped)
	{
		int charId = character.GetId();
		if (!_kidnappedChars.TryGetValue(charId, out var kidnappedChars))
		{
			return;
		}
		Location destLocation = character.GetLocation();
		List<KidnappedCharacter> collection = kidnappedChars.GetCollection();
		for (int i = 0; i < collection.Count; i++)
		{
			KidnappedCharacter kidnappedCharData = collection[i];
			int kidnappedCharId = kidnappedCharData.CharId;
			ItemKey ropeItemKey = kidnappedCharData.RopeItemKey;
			if (kidnappedCharId >= 0 && TryGetElement_Objects(kidnappedCharId, out var kidnappedChar))
			{
				Location srcLocation = kidnappedChar.GetLocation();
				kidnappedChar.SetLocation(destLocation, context);
				if (kidnappedChar.IsCompletelyInfected())
				{
					Events.RaiseInfectedCharacterLocationChanged(context, kidnappedCharId, srcLocation, destLocation);
				}
				else
				{
					Events.RaiseCharacterLocationChanged(context, kidnappedCharId, srcLocation, destLocation);
				}
				kidnappedChar.SetKidnapperId(-1, context);
			}
			if (ropeItemKey.IsValid())
			{
				DomainManager.Item.RemoveOwner(ropeItemKey, ItemOwnerType.KidnapperRope, kidnappedCharId);
				if (isEscaped)
				{
					DomainManager.Item.RemoveItem(context, ropeItemKey);
				}
				else
				{
					character.AddInventoryItem(context, ropeItemKey, 1);
				}
			}
		}
		kidnappedChars.Clear();
		RemoveElement_KidnappedChars(charId, context);
		character.DeactivateExternalRelationState(context, 2uL);
	}

	public void SyncLifeSkillReadingStateToCharacter(DataContext context, Character sourceCharacter, Character targetCharacter, sbyte lifeSkillType)
	{
		List<LifeSkillItem> targetNewLearnedLifeSkills = new List<LifeSkillItem>();
		foreach (LifeSkillItem lifeSkillItem in targetCharacter.GetLearnedLifeSkills())
		{
			if (LifeSkill.Instance[lifeSkillItem.SkillTemplateId].Type != lifeSkillType)
			{
				targetNewLearnedLifeSkills.Add(lifeSkillItem);
			}
		}
		foreach (LifeSkillItem lifeSkillItem2 in sourceCharacter.GetLearnedLifeSkills())
		{
			if (LifeSkill.Instance[lifeSkillItem2.SkillTemplateId].Type == lifeSkillType)
			{
				targetNewLearnedLifeSkills.Add(lifeSkillItem2);
			}
		}
		targetCharacter.SetLearnedLifeSkills(targetNewLearnedLifeSkills, context);
	}

	[DomainMethod]
	public CharacterMenuLifeSkillDisplayData GetCharacterMenuLifeSkillDisplayData(DataContext context, int charId)
	{
		bool isTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		CharacterMenuLifeSkillDisplayData data = new CharacterMenuLifeSkillDisplayData();
		Character targetChar = GetElement_Objects(charId);
		data.LearnedLifeSkills = targetChar.GetLearnedLifeSkills();
		if (isTaiwu)
		{
			data.TaiwuLifeSkills = DomainManager.Taiwu.GetTaiwuLearnLifeSkillReadingProgressAll();
			data.TaiwuNotLearnLifeSkills = DomainManager.Taiwu.GetTaiwuNotLearnLifeSkillReadingProgressAll();
		}
		return data;
	}

	[DomainMethod]
	public CharacterMenuAttainmentDisplayData GetCharacterMenuAttainmentDisplayData(DataContext context, int charId)
	{
		if (charId < 0)
		{
			return null;
		}
		bool isTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		TryGetElement_Objects(charId, out var targetChar);
		if (targetChar == null)
		{
			return null;
		}
		targetChar.GetCombatSkillAttainmentPanels();
		CharacterMenuAttainmentDisplayData data = new CharacterMenuAttainmentDisplayData
		{
			ActualAge = targetChar.GetActualAge(),
			CombatSkillAttainmentPanels = targetChar.GetCombatSkillAttainmentPanels(),
			CombatSkillGrowthType = targetChar.GetCombatSkillQualificationGrowthType(),
			CombatSkillQualifications = targetChar.GetCombatSkillQualifications(),
			LearnedCombatSkills = targetChar.GetLearnedCombatSkills(),
			CombatSkillAttainments = targetChar.GetCombatSkillAttainments(),
			DivinePower = GetCharacterDivinePower(targetChar.GetId()),
			GhostTechnique = GetCharacterGhostTechnique(targetChar.GetId()),
			LearnedLifeSkills = targetChar.GetLearnedLifeSkills(),
			LifeSkillAttainments = targetChar.GetLifeSkillAttainments(),
			LifeSkillQualifications = targetChar.GetLifeSkillQualifications(),
			LifeSkillGrowthType = targetChar.GetLifeSkillQualificationGrowthType(),
			CreationType = targetChar.GetCreatingType()
		};
		if (isTaiwu)
		{
			data.TaiwuLifeSkills = DomainManager.Taiwu.GetTaiwuLearnLifeSkillReadingProgressAll();
			data.TaiwuNotLearnLifeSkills = DomainManager.Taiwu.GetTaiwuNotLearnLifeSkillReadingProgressAll();
			data.CombatSkillAttainmentPlans = DomainManager.Taiwu.GetCombatSkillAttainmentPanelPlans();
		}
		data.LearnedCombatSkillDatasSimple = DomainManager.CombatSkill.GetCharacterMenuCombatSkillListItemDisplayData(context, charId);
		return data;
	}

	public void ResetLuckEventPrediction()
	{
		_predictedLuckEvent = (charId: -1, isPositive: false, isAvoided: false);
	}

	public void AddLuckEventPrediction(int charId, bool isPositive, bool isAvoided)
	{
		_predictedLuckEvent = (charId: charId, isPositive: isPositive, isAvoided: isAvoided);
	}

	public unsafe void UpdateLuckEvents(DataContext context)
	{
		long[] charLucks = new long[_objects.Count];
		int length = 0;
		foreach (var (id, character2) in _objects)
		{
			if (character2.GetCreatingType() == 1 && !IsTemporaryIntelligentCharacter(id))
			{
				Personalities personalities = character2.GetPersonalities();
				charLucks[length] = ((long)personalities.Items[5] << 32) + id;
				length++;
			}
		}
		if (length == 0)
		{
			return;
		}
		List<int> luckyChars = new List<int>(100);
		List<int> unluckyChars = new List<int>(100);
		fixed (long* pList = charLucks)
		{
			CollectionUtils.Sort(pList, length);
			for (int i = 0; i < length && i < 100; i++)
			{
				int unluckyCharId = (int)(pList[i] & 0xFFFFFFFFu);
				if (unluckyCharId != _predictedLuckEvent.charId)
				{
					unluckyChars.Add(unluckyCharId);
				}
				int luckyCharId = (int)(pList[length - 1 - i] & 0xFFFFFFFFu);
				if (luckyCharId != _predictedLuckEvent.charId)
				{
					luckyChars.Add(luckyCharId);
				}
			}
			if (_predictedLuckEvent.charId >= 0 && !_predictedLuckEvent.isAvoided && DomainManager.Character.TryGetElement_Objects(_predictedLuckEvent.charId, out var targetChar))
			{
				ApplyLuckEventToCharacter(context, targetChar, _predictedLuckEvent.isPositive);
			}
			ResetLuckEventPrediction();
			ApplyLucky_Resource(context, luckyChars, 5, 15);
			ApplyLucky_Item(context, luckyChars, 3, 2, 10);
			ApplyLucky_Item(context, luckyChars, 3, 0, 5);
			ApplyLucky_Item(context, luckyChars, 3, 1, 5);
			ApplyLucky_CombatSkillBook(context, luckyChars, 3, 3);
			ApplyLucky_LifeSkillBook(context, luckyChars, 3, 5);
			ApplyLucky_Regen(context, luckyChars, 5, 8);
			ApplyUnlucky_Resource(context, unluckyChars, 5, 15);
			ApplyUnlucky_Item(context, unluckyChars, 3, 2, 10);
			ApplyUnlucky_Item(context, unluckyChars, 3, 0, 5);
			ApplyUnlucky_Item(context, unluckyChars, 3, 1, 5);
			ApplyUnlucky_CombatSkillBook(context, unluckyChars, 3, 3);
			ApplyUnlucky_LifeSkillBook(context, unluckyChars, 3, 5);
			ApplyUnlucky_Harm(context, unluckyChars, 5, 8);
		}
	}

	public void ApplyLuckEventToCharacter(DataContext context, Character character, bool isPositive)
	{
		List<int> targets = new List<int>(1) { character.GetId() };
		Span<sbyte> order = stackalloc sbyte[7];
		for (sbyte i = 0; i < order.Length; i++)
		{
			order[i] = i;
		}
		CollectionUtils.Shuffle(context.Random, order, order.Length);
		Span<sbyte> span = order;
		for (int j = 0; j < span.Length; j++)
		{
			sbyte eventType = span[j];
			if (isPositive)
			{
				if (1 == 0)
				{
				}
				int num = eventType switch
				{
					0 => ApplyLucky_Resource(context, targets, 1, 100), 
					1 => ApplyLucky_Item(context, targets, 1, 2, 100), 
					2 => ApplyLucky_Item(context, targets, 1, 0, 100), 
					3 => ApplyLucky_Item(context, targets, 1, 1, 100), 
					4 => ApplyLucky_CombatSkillBook(context, targets, 1, 100), 
					5 => ApplyLucky_LifeSkillBook(context, targets, 1, 100), 
					6 => ApplyLucky_Regen(context, targets, 1, 100), 
					_ => 0, 
				};
				if (1 == 0)
				{
				}
				int amount = num;
				if (amount > 0)
				{
					break;
				}
			}
			else
			{
				if (1 == 0)
				{
				}
				int num = eventType switch
				{
					0 => ApplyUnlucky_Resource(context, targets, 1, 100), 
					1 => ApplyUnlucky_Item(context, targets, 1, 2, 100), 
					2 => ApplyUnlucky_Item(context, targets, 1, 0, 100), 
					3 => ApplyUnlucky_Item(context, targets, 1, 1, 100), 
					4 => ApplyUnlucky_CombatSkillBook(context, targets, 1, 100), 
					5 => ApplyUnlucky_LifeSkillBook(context, targets, 1, 100), 
					6 => ApplyUnlucky_Harm(context, targets, 1, 100), 
					_ => 0, 
				};
				if (1 == 0)
				{
				}
				int amount2 = num;
				if (amount2 > 0)
				{
					break;
				}
			}
		}
	}

	private int ApplyLucky_Resource(DataContext context, List<int> luckyChars, int amountOfChars, sbyte chance)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int luckyAmount = 0;
		Span<int> selectedIndices = stackalloc int[amountOfChars];
		RandomUtils.GetRandomUnrepeated(context.Random, 0, luckyChars.Count - 1, selectedIndices);
		for (int i = 0; i < amountOfChars; i++)
		{
			if (context.Random.CheckPercentProb(chance))
			{
				int charId = luckyChars[selectedIndices[i]];
				int worth = context.Random.Next(12000, 24001);
				sbyte resourceType = (sbyte)context.Random.Next(7);
				int resourceAmount = worth / GlobalConfig.ResourcesWorth[resourceType];
				Character luckyChar = _objects[charId];
				Location location = luckyChar.GetLocation();
				luckyChar.AddGoal(context, 237, (sbyte)6, luckyChar.GetAdjustedResourceSatisfyingAmount(6));
				luckyChar.ChangeResource(context, resourceType, resourceAmount);
				luckyChar.ChangeHappiness(context, worth / 1000);
				lifeRecordCollection.AddUnexpectedResourceGain(charId, currDate, location, resourceType, resourceAmount);
				monthlyNotificationCollection.AddUnexpectedlyGetResource(charId, location, resourceAmount, resourceType);
				int secretInfoOffset = secretInformationCollection.AddUnexpectedResourceGain(charId, resourceType, location);
				SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
				luckyAmount++;
			}
		}
		return luckyAmount;
	}

	private unsafe int ApplyUnlucky_Resource(DataContext context, List<int> unluckyChars, int amountOfChars, sbyte chance)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int unluckyAmount = 0;
		Span<int> selectedIndices = stackalloc int[amountOfChars];
		RandomUtils.GetRandomUnrepeated(context.Random, 0, unluckyChars.Count - 1, selectedIndices);
		for (int i = 0; i < amountOfChars; i++)
		{
			if (context.Random.CheckPercentProb(chance))
			{
				int charId = unluckyChars[selectedIndices[i]];
				int worth = context.Random.Next(12000, 24001);
				Character unluckyChar = _objects[charId];
				ResourceInts resources = unluckyChar.GetResources();
				sbyte resourceType = SelectRandomResourceTypeToLose(context.Random, ref resources);
				if (resourceType >= 0)
				{
					int resourceAmount = Math.Min(worth / GlobalConfig.ResourcesWorth[resourceType], resources.Items[resourceType]);
					Location location = unluckyChar.GetLocation();
					unluckyChar.AddGoal(context, 236, (sbyte)6, worth / GlobalConfig.ResourcesWorth[6]);
					unluckyChar.ChangeResource(context, resourceType, -resourceAmount);
					unluckyChar.ChangeHappiness(context, -worth / 1000);
					lifeRecordCollection.AddUnexpectedResourceLose(charId, currDate, location, resourceType, resourceAmount);
					monthlyNotificationCollection.AddUnexpectedlyLoseResource(charId, location, resourceAmount, resourceType);
					int secretInfoOffset = secretInformationCollection.AddUnexpectedResourceLose(charId, resourceType, location);
					SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
					unluckyAmount++;
				}
			}
		}
		return unluckyAmount;
	}

	private int ApplyLucky_Item(DataContext context, List<int> luckyChars, int amountOfChars, short itemType, sbyte chance)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int luckyAmount = 0;
		Span<int> selectedIndices = stackalloc int[amountOfChars];
		RandomUtils.GetRandomUnrepeated(context.Random, 0, luckyChars.Count - 1, selectedIndices);
		for (int i = 0; i < amountOfChars; i++)
		{
			if (context.Random.CheckPercentProb(chance))
			{
				int charId = luckyChars[selectedIndices[i]];
				short itemSubType = ItemSubType.Type2SubTypes[itemType].GetRandom(context.Random);
				if (ItemSubType.IsHobbyType(itemSubType))
				{
					sbyte grade = (sbyte)(context.Random.CheckProb(chance, 1000) ? 7 : 6);
					short itemTemplateId = ItemDomain.GetRandomItemIdInSubType(context.Random, itemSubType, grade);
					ItemKey itemKey = DomainManager.Item.CreateItem(context, ItemSubType.GetType(itemSubType), itemTemplateId);
					int worth = ItemTemplateHelper.GetBaseValue(itemKey.ItemType, itemKey.TemplateId);
					Character luckyChar = _objects[charId];
					Location location = luckyChar.GetLocation();
					luckyChar.AddGoal(context, 237, (sbyte)6, luckyChar.GetAdjustedResourceSatisfyingAmount(6));
					luckyChar.AddInventoryItem(context, itemKey, 1);
					luckyChar.ChangeHappiness(context, worth / 1000);
					lifeRecordCollection.AddUnexpectedItemGain(charId, currDate, location, itemKey.ItemType, itemKey.TemplateId);
					monthlyNotificationCollection.AddUnexpectedlyGetRareItem(charId, location, itemKey.ItemType, itemKey.TemplateId);
					int secretInfoOffset = secretInformationCollection.AddUnexpectedItemGain(charId, (ulong)itemKey, location);
					SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
					luckyAmount++;
				}
			}
		}
		return luckyAmount;
	}

	private int ApplyUnlucky_Item(DataContext context, List<int> unluckyChars, int amountOfChars, sbyte itemType, sbyte chance)
	{
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int unluckyAmount = 0;
		Span<int> selectedIndices = stackalloc int[amountOfChars];
		RandomUtils.GetRandomUnrepeated(context.Random, 0, unluckyChars.Count - 1, selectedIndices);
		for (int i = 0; i < amountOfChars; i++)
		{
			if (!context.Random.CheckPercentProb(chance))
			{
				continue;
			}
			int charId = unluckyChars[selectedIndices[i]];
			Character unluckyChar = _objects[charId];
			ItemKey itemKey = SelectItemFromItemTypeToLose(context.Random, unluckyChar, itemType);
			if (!itemKey.IsValid())
			{
				continue;
			}
			int worth = ItemTemplateHelper.GetBaseValue(itemKey.ItemType, itemKey.TemplateId);
			Location location = unluckyChar.GetLocation();
			unluckyChar.AddGoal(context, 236, (sbyte)6, worth / GlobalConfig.ResourcesWorth[6]);
			if (!unluckyChar.GetInventory().Items.ContainsKey(itemKey))
			{
				ItemKey[] equipments = unluckyChar.GetEquipment();
				for (int slot = 0; slot < equipments.Length; slot++)
				{
					if (itemKey.Equals(equipments[slot]))
					{
						equipments[slot] = ItemKey.Invalid;
						unluckyChar.SetEquipment(equipments, context);
						DomainManager.Item.RemoveItem(context, itemKey);
						break;
					}
				}
			}
			else
			{
				unluckyChar.RemoveInventoryItem(context, itemKey, 1, deleteItem: true);
			}
			unluckyChar.ChangeHappiness(context, -worth / 1000);
			lifeRecordCollection.AddUnexpectedItemLose(charId, currDate, location, itemKey.ItemType, itemKey.TemplateId);
			monthlyNotificationCollection.AddUnexpectedlyLoseRareItem(charId, location, itemKey.ItemType, itemKey.TemplateId);
			int secretInfoOffset = secretInformationCollection.AddUnexpectedItemLose(charId, (ulong)itemKey, location);
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
			unluckyAmount++;
		}
		return unluckyAmount;
	}

