				lifeRecordCollection.AddUnexpectedOuterInjuryHarm(charId, currDate, location, amount4);
				if (charId != taiwuCharId)
				{
				}
				break;
			}
			case 2:
			{
				Injuries injuries = unluckyChar.GetInjuries();
				sbyte amount3 = (sbyte)AdvancingMonthFormula.DefValue.BadLuckEventInjury.Calculate();
				GetFixedInjuries(context.Random, ref injuries, isInnerInjury: true, amount3);
				unluckyChar.SetInjuries(injuries, context);
				monthlyNotificationCollection.AddUnexpectedlySufferInneInjury(charId, location, amount3);
				lifeRecordCollection.AddUnexpectedInnerInjuryHarm(charId, currDate, location, amount3);
				if (charId != taiwuCharId)
				{
				}
				break;
			}
			case 3:
			{
				PoisonInts poisoned = default(PoisonInts);
				int amount2 = AdvancingMonthFormula.DefValue.BadLuckEventPoison.Calculate();
				sbyte poisonType = (sbyte)context.Random.Next(6);
				ref int reference = ref poisoned.Items[poisonType];
				reference += amount2;
				unluckyChar.DirectlyChangePoisoned(context, ref poisoned);
				monthlyNotificationCollection.AddUnexpectedlySufferPoison(charId, location, poisonType);
				lifeRecordCollection.AddUnexpectedPoisonHarm(charId, currDate, location, poisonType);
				if (charId != taiwuCharId)
				{
				}
				break;
			}
			case 4:
			{
				int amount = AdvancingMonthFormula.DefValue.BadLuckEventQi.Calculate();
				unluckyChar.ChangeDisorderOfQi(context, (short)amount);
				monthlyNotificationCollection.AddUnexpectedlySufferDisorderOfQi(charId, location);
				lifeRecordCollection.AddUnexpectedDisorderOfQiHarm(charId, currDate, location);
				if (charId != taiwuCharId)
				{
