	private sbyte SelectRandomRecoveryType(IRandomSource random, Character character)
	{
		Span<sbyte> selectables = stackalloc sbyte[5];
		int count = 0;
		if (character.GetHealth() != character.GetLeftMaxHealth())
		{
			selectables[count] = 0;
			count++;
		}
		if (character.GetInjuries().HasAnyInjury(isInnerInjury: false))
		{
			selectables[count] = 1;
			count++;
		}
		if (character.GetInjuries().HasAnyInjury(isInnerInjury: true))
		{
			selectables[count] = 2;
			count++;
		}
		if (character.GetPoisoned().IsNonZero())
		{
			selectables[count] = 3;
			count++;
		}
		if (character.GetDisorderOfQi() > 0)
		{
			selectables[count] = 4;
			count++;
		}
		if (count > 0)
		{
			return selectables[random.Next(count)];
		}
		return -1;
	}

	private unsafe sbyte SelectRandomResourceTypeToLose(IRandomSource random, ref ResourceInts resources)
	{
		Span<sbyte> selectables = stackalloc sbyte[7];
		int count = 0;
		for (sbyte resType = 0; resType < 7; resType++)
		{
			if (resources.Items[resType] > 0)
			{
				selectables[count] = resType;
				count++;
			}
		}
		if (count > 0)
		{
			return selectables[random.Next(count)];
		}
		return -1;
	}

	private ItemKey SelectItemFromItemTypeToLose(IRandomSource random, Character character, sbyte itemType)
	{
		List<ItemKey> validItems = ObjectPool<List<ItemKey>>.Instance.Get();
		validItems.Clear();
		sbyte currGrade = -1;
		foreach (var (itemKey2, _) in character.GetInventory().Items)
		{
			if (itemKey2.ItemType == itemType)
			{
				sbyte grade = ItemTemplateHelper.GetGrade(itemKey2.ItemType, itemKey2.TemplateId);
				if (grade > currGrade)
				{
					validItems.Clear();
				}
				else if (grade < currGrade)
				{
					continue;
				}
				validItems.Add(itemKey2);
			}
		}
		ItemKey[] equipment = character.GetEquipment();
		for (int i = 0; i < equipment.Length; i++)
		{
			ItemKey itemKey3 = equipment[i];
			if (itemKey3.IsValid() && itemKey3.ItemType == itemType)
			{
				sbyte grade2 = ItemTemplateHelper.GetGrade(itemKey3.ItemType, itemKey3.TemplateId);
				if (grade2 > currGrade)
				{
					validItems.Clear();
				}
				else if (grade2 < currGrade)
				{
					continue;
				}
				validItems.Add(itemKey3);
			}
		}
		ItemKey selectedItem = ItemKey.Invalid;
		if (validItems.Count > 0)
		{
			selectedItem = validItems.GetRandom(random);
		}
		ObjectPool<List<ItemKey>>.Instance.Return(validItems);
		return selectedItem;
	}

