	private bool RecoverFixedInjuries(IRandomSource random, ref Injuries injuries, bool isInnerInjury, sbyte totalRecoverAmount)
	{
		int healCount = 0;
		Span<sbyte> selectables = stackalloc sbyte[7];
		for (int i = 0; i < totalRecoverAmount; i++)
		{
			int count = 0;
			for (sbyte part = 0; part < 7; part++)
			{
				if (injuries.Get(part, isInnerInjury) > 0)
				{
					selectables[count] = part;
					count++;
				}
			}
			if (count == 0)
			{
				return false;
			}
			sbyte selectedPart = selectables[random.Next(count)];
			injuries.Change(selectedPart, isInnerInjury, -1);
			healCount++;
		}
		return healCount > 0;
	}

	public void GetOrHealRandomInjuriesWithoutChecking(IRandomSource random, ref Injuries injuries, int minAmount, int maxAmount)
	{
		int totalAmount = random.Next(minAmount, maxAmount + 1);
		for (int i = 0; i < totalAmount; i++)
		{
			sbyte selectedIndex = (sbyte)random.Next(14);
			injuries.Change(selectedIndex, 1);
		}
		for (int j = totalAmount; j < 0; j++)
		{
			if (random.NextBool())
			{
				if (!RecoverFixedInjuries(random, ref injuries, isInnerInjury: true, 1))
				{
					RecoverFixedInjuries(random, ref injuries, isInnerInjury: false, 1);
				}
			}
			else if (!RecoverFixedInjuries(random, ref injuries, isInnerInjury: false, 1))
			{
				RecoverFixedInjuries(random, ref injuries, isInnerInjury: true, 1);
			}
		}
	}

	public unsafe void GetOrDetoxRandomPoisonsWithoutChecking(IRandomSource random, ref PoisonInts poisoned, int poisonTypeCount, int minAmount, int maxAmount)
	{
		for (int i = 0; i < poisonTypeCount; i++)
		{
			int poisonType = random.Next(6);
			int amount = random.Next(minAmount, maxAmount + 1);
			ref int reference = ref poisoned.Items[poisonType];
			reference += amount;
			if (poisoned.Items[poisonType] < 0)
			{
				poisoned.Items[poisonType] = 0;
			}
		}
	}

	private void GetFixedInjuries(IRandomSource random, ref Injuries injuries, bool isInnerInjury, sbyte totalInjureAmount)
	{
		Span<sbyte> selectables = stackalloc sbyte[7];
		for (int i = 0; i < totalInjureAmount; i++)
		{
			int count = 0;
			for (sbyte part = 0; part < 7; part++)
			{
				if (injuries.Get(part, isInnerInjury) < 6)
				{
					selectables[count] = part;
					count++;
				}
			}
			if (count == 0)
			{
				break;
			}
			sbyte selectedPart = selectables[random.Next(count)];
			injuries.Change(selectedPart, isInnerInjury, 1);
		}
	}

	private unsafe sbyte RecoverFixedPoisoned(IRandomSource random, ref PoisonInts poisoned, int totalRecoverAmount)
	{
		Span<sbyte> selectables = stackalloc sbyte[6];
		int count = 0;
		for (sbyte poisonType = 0; poisonType < 6; poisonType++)
		{
			if (poisoned.Items[poisonType] > 0)
			{
				selectables[count] = poisonType;
				count++;
			}
		}
		Tester.Assert(count > 0);
		sbyte selectedPoisonType = selectables[random.Next(count)];
		Tester.Assert(selectedPoisonType >= 0 && selectedPoisonType < 6, $"{selectedPoisonType} >= 0 && {selectedPoisonType} < PoisonType.Count");
		int poison = poisoned.Items[selectedPoisonType];
		int recoveredAmount = Math.Min(totalRecoverAmount, poison);
		ref int reference = ref poisoned.Items[selectedPoisonType];
		reference -= recoveredAmount;
		return selectedPoisonType;
	}

