	private static void InitializeCharacterMissions()
	{
		_typesInMissionGroups = new ECharacterMissionType[4][];
		_typesInMissionGroups[0] = new ECharacterMissionType[2]
		{
			ECharacterMissionType.Sect,
			ECharacterMissionType.MapState
		};
		_typesInMissionGroups[1] = new ECharacterMissionType[2]
		{
			ECharacterMissionType.Grade,
			ECharacterMissionType.Identity
		};
		_typesInMissionGroups[2] = new ECharacterMissionType[3]
		{
			ECharacterMissionType.Trivia,
			ECharacterMissionType.Relation,
			ECharacterMissionType.LifeSkill
		};
		_typesInMissionGroups[3] = new ECharacterMissionType[1] { ECharacterMissionType.Taiwu };
		_missionCollections = new ICharacterMissionCollection[8];
		_missionCollections[0] = new SectMissionCollection();
		_missionCollections[1] = new MapStateMissionCollection();
		_missionCollections[2] = new GradeMissionCollection();
		_missionCollections[3] = new IdentityMissionCollection();
		_missionCollections[4] = new TriviaMissionCollection();
		_missionCollections[5] = new RelationMissionCollection();
		_missionCollections[6] = new LifeSkillMissionCollection();
		_missionCollections[7] = new TaiwuMissionCollection();
		foreach (CharacterMissionItem missionTemplate in (IEnumerable<CharacterMissionItem>)CharacterMission.Instance)
		{
			if (IsMissionReachable(missionTemplate))
			{
				_missionCollections[(int)missionTemplate.Type].RegisterMission(missionTemplate);
			}
		}
	}

	public ICharacterMissionCollection GetMissionCollection(ECharacterMissionType missionType)
	{
		return _missionCollections[(int)missionType];
	}

	public IReadOnlyList<ECharacterMissionType> GetMissionTypesInGroup(ECharacterMissionGroup missionGroup)
	{
		return _typesInMissionGroups[(int)missionGroup];
	}

	private static bool IsMissionReachable(CharacterMissionItem missionTemplate)
	{
		int[] goals = missionTemplate.Goals;
		foreach (int goalTemplateId in goals)
		{
			if (CharacterActionPlanner.Instance.GetGoalNode(goalTemplateId).Reachable)
			{
				return true;
			}
		}
		return false;
	}

	public bool TryAddCharacterAvatarSnapshot(DataContext context, Character character)
	{
		int charId = character.GetId();
		IntPair effectKey = new IntPair(charId, 23);
		int date = DomainManager.World.GetCurrDate();
		if (_mixedPoisonEffectTriggerDates.ContainsKey(effectKey))
		{
			SetElement_MixedPoisonEffectTriggerDates(effectKey, date, context);
		}
		else
		{
			AddElement_MixedPoisonEffectTriggerDates(effectKey, date, context);
		}
		if (_characterAvatarSnapshot.ContainsKey(charId))
		{
			return false;
		}
		AddElement_CharacterAvatarSnapshot(charId, new AvatarData(character.GetAvatar()), context);
		return true;
	}

	public void TryRestoreCharacterAvatars(DataContext context)
	{
		int currDate = DomainManager.World.GetCurrDate();
		List<int> restoredCharIds = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		foreach (var (charId, avatar) in _characterAvatarSnapshot)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				restoredCharIds.Add(charId);
			}
			else
			{
				if (character.GetMixedPoisonTypeRelatedMarkCount(23) > 0)
				{
					continue;
				}
				IntPair key = new IntPair(charId, 23);
				if (_mixedPoisonEffectTriggerDates.TryGetValue(key, out var date))
				{
					if (date + 3 > currDate)
					{
						continue;
					}
					RemoveElement_MixedPoisonEffectTriggerDates(key, context);
				}
				character.SetAvatar(avatar, context);
				restoredCharIds.Add(charId);
			}
		}
		foreach (int charId2 in restoredCharIds)
		{
			RemoveElement_CharacterAvatarSnapshot(charId2, context);
		}
		context.AdvanceMonthRelatedData.CharIdList.Release(ref restoredCharIds);
	}

