	public void OnFixedCharacterLocationChanged(DataContext context, int charId, Location srcLocation, Location destLocation)
	{
		Character character = _objects[charId];
		short charTemplateId = character.GetTemplateId();
		switch (charTemplateId)
		{
		case 205:
			_tripleAdoreLocation = destLocation;
			break;
		case 207:
			SetForceKindLocation(destLocation, context);
			break;
		case 209:
			_noAgeIncreaseLocation = destLocation;
			break;
		case 156:
		case 157:
		case 158:
		case 159:
		case 160:
		case 161:
		case 162:
		case 163:
		case 164:
			_tripleHateLocation = destLocation;
			break;
		case 174:
		case 175:
		case 176:
		case 177:
		case 178:
		case 179:
		case 180:
		case 181:
		case 182:
			SetForceRebelLocation(destLocation, context);
			break;
		case 192:
		case 193:
		case 194:
		case 195:
		case 196:
		case 197:
		case 198:
		case 199:
		case 200:
			_doubleAgeIncreaseLocation = destLocation;
			break;
		}
		if (character.Template.XiangshuType == 3 && !srcLocation.IsValid() && destLocation.IsValid())
		{
			int templateId = 95 + XiangshuAvatarIds.GetXiangshuAvatarIdByCharacterTemplateId(charTemplateId);
			DomainManager.Taiwu.RecordLifeSummary(context, templateId);
		}
	}

	private unsafe bool TransferAvoidDeathCharInjuries(DataContext context, int avoidDeathCharId = -1, int targetCharId = -1)
	{
		bool isMovement = avoidDeathCharId < 0 && targetCharId < 0;
		if (avoidDeathCharId < 0)
		{
			avoidDeathCharId = _avoidDeathCharId;
		}
		if (avoidDeathCharId < 0)
		{
			return false;
		}
		Character avoidDeathChar = _objects[avoidDeathCharId];
		if (!avoidDeathChar.IsInteractableAsIntelligentCharacter() && avoidDeathChar.GetTemplateId() != 206)
		{
			return false;
		}
		Location location = avoidDeathChar.GetLocation();
		if (!location.IsValid())
		{
			location = avoidDeathChar.GetValidLocation();
		}
		if (targetCharId < 0)
		{
			targetCharId = GetRandomCharacterInRange(context, location, 2, includeTaiwu: true);
		}
		if (targetCharId < 0)
		{
			return false;
		}
		Character targetChar = _objects[targetCharId];
		Injuries injuries = avoidDeathChar.GetInjuries();
		targetChar.ChangeInjuries(context, injuries);
		injuries.Initialize();
		avoidDeathChar.SetInjuries(injuries, context);
		PoisonInts poisons = avoidDeathChar.GetPoisoned();
		for (sbyte poisonType = 0; poisonType < 6; poisonType++)
		{
			targetChar.ChangePoisoned(context, poisonType, 3, poisons.Items[poisonType]);
		}
		poisons = default(PoisonInts);
		avoidDeathChar.SetPoisoned(ref poisons, context);
		avoidDeathChar.TransferDisorderOfQi(context, targetChar, avoidDeathChar.GetDisorderOfQi());
		EatingItems eatingItems = avoidDeathChar.GetEatingItems();
		for (sbyte slotIndex = 0; slotIndex < 9; slotIndex++)
		{
			ItemKey itemKey = (ItemKey)eatingItems.ItemKeys[slotIndex];
			if (itemKey.ItemType == 8 && ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId) == 802)
			{
				targetChar.AddWug(context, itemKey.TemplateId, -1);
				avoidDeathChar.RemoveWug(context, itemKey.TemplateId);
			}
		}
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		if (isMovement)
		{
			if (avoidDeathChar.GetCreatingType() == 0)
			{
				lifeRecordCollection.AddWeiQiBad(targetCharId, currDate, targetChar.GetLocation());
			}
			else
			{
				lifeRecordCollection.AddWeiQiGood(avoidDeathCharId, currDate, location);
			}
		}
		else if (DomainManager.World.IsXiangshuAvatarTaskStatusesGood(5))
		{
			lifeRecordCollection.AddWeiQiGood(avoidDeathCharId, currDate, location);
			lifeRecordCollection.AddWeiQiGoodOther(targetCharId, currDate, location, avoidDeathCharId);
			DomainManager.World.GetInstantNotificationCollection().AddWeiQiGood(avoidDeathCharId);
		}
		else
		{
			lifeRecordCollection.AddWeiQiBadOther(targetCharId, currDate, location, avoidDeathCharId);
			DomainManager.World.GetInstantNotificationCollection().AddWeiQiBad(targetCharId);
		}
		if (DomainManager.World.GetAdvancingMonthState() == 0)
		{
			DomainManager.LifeRecord.CommitCurrLifeRecords();
		}
		SetAvoidDeathCharId(-1, context);
		return true;
	}

