			List<short> list = ObjectPool<List<short>>.Instance.Get();
			list.Clear();
			int num = 3;
			for (int i = 0; i < num; i++)
			{
				short num2 = (short)(b * num + i);
				if (num2 != mapStateItem.MainAreaID && num2 != mapStateItem.SectAreaID)
				{
					list.Add(num2);
