	private void OldMonkMovement(DataContext context, Character character)
	{
		EventArgBox globalArgBox = DomainManager.TaiwuEvent.GetGlobalEventArgumentBox();
		int swordTombCount = globalArgBox.GetInt("OldMonkToSwordTombCount");
		if (swordTombCount > 7)
		{
			swordTombCount = 0;
		}
		for (; swordTombCount <= 7; swordTombCount++)
		{
			Location tombLocation = DomainManager.Map.GetElement_SwordTombLocations(swordTombCount);
			MapBlockData swordTombBlock = DomainManager.Map.GetBlock(tombLocation);
			swordTombBlock = GetBlockWithSwordTombAdventure(swordTombBlock);
			if (swordTombBlock != null && swordTombBlock.BlockSubType == EMapBlockSubType.SwordTomb)
			{
				Location targetLocation = swordTombBlock.GetLocation();
