		static MapBlockData GetBlockWithSwordTombAdventure(MapBlockData blockData)
		{
			AdventureRuntime adventure = DomainManager.Adventure.QueryAdventureInLocation(blockData.GetLocation());
			if (adventure != null && XiangshuAvatarIds.IsSwordTombAdventure(adventure.CoreId))
			{
				return blockData;
			}
			List<MapBlockData> groupBlockList = blockData.GroupBlockList;
			if (groupBlockList != null && groupBlockList.Count > 0)
			{
				foreach (MapBlockData subBlock in blockData.GroupBlockList)
				{
					adventure = DomainManager.Adventure.QueryAdventureInLocation(subBlock.GetLocation());
					if (adventure != null && XiangshuAvatarIds.IsSwordTombAdventure(adventure.CoreId))
					{
						return subBlock;
					}
				}
			}
			return null;
		}
	}

