	private Location FixedCharacterMoveInRange(DataContext context, Character character, Location targetLocation, int maxSteps, MapBlockMatcherItem matcher = null)
	{
		List<MapBlockData> neighborBlocks = context.AdvanceMonthRelatedData.Blocks.Occupy();
		DomainManager.Map.GetRealNeighborBlocks(targetLocation.AreaId, targetLocation.BlockId, neighborBlocks, maxSteps, includeCenter: true);
		matcher?.UnstableFilter(neighborBlocks);
		MapBlockData nextLocationBlock = neighborBlocks.GetRandomOrDefault(context.Random, null);
		Location srcLocation = character.GetLocation();
		Location nextLocation = nextLocationBlock?.GetLocation() ?? srcLocation;
		context.AdvanceMonthRelatedData.Blocks.Release(ref neighborBlocks);
		if (!srcLocation.Equals(nextLocation))
		{
			Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), character.GetLocation(), nextLocation);
			character.SetLocation(nextLocation, context);
		}
		return nextLocation;
	}

