	public void CullCanSelectBlocks(List<MapBlockData> blocks)
	{
		if (blocks.Count <= 1)
		{
			return;
		}
		int count = 0;
		foreach (MapBlockData block in blocks)
		{
			if (FiveLoongDlcEntry.IsBlockLoongBlock(block))
			{
				count++;
			}
		}
		if (count == blocks.Count)
		{
			return;
		}
		for (int i = blocks.Count - 1; i >= 0; i--)
		{
			if (FiveLoongDlcEntry.IsBlockLoongBlock(blocks[i]))
			{
				blocks.RemoveAt(i);
			}
		}
		count = 0;
		foreach (MapBlockData block2 in blocks)
		{
			if (block2.GetConfig().TemplateId == 124)
			{
				count++;
			}
		}
		if (count == blocks.Count)
		{
			return;
		}
		for (int i2 = blocks.Count - 1; i2 >= 0; i2--)
		{
			if (blocks[i2].GetConfig().TemplateId == 124)
			{
				blocks.RemoveAt(i2);
			}
		}
		count = 0;
		foreach (MapBlockData block3 in blocks)
		{
			if (block3.GetConfig().SubType == EMapBlockSubType.Ruin)
			{
				count++;
			}
		}
		if (count == blocks.Count)
		{
			return;
		}
		for (int i3 = blocks.Count - 1; i3 >= 0; i3--)
		{
			if (blocks[i3].GetConfig().SubType == EMapBlockSubType.Ruin)
			{
				blocks.RemoveAt(i3);
			}
		}
	}

