	private void TripodVesselOfMedicineMovement(DataContext context, Character character)
	{
		int selfCharId = character.GetId();
		Location srcLocation = character.GetLocation();
		short medicineAttainment = character.GetLifeSkillAttainment(8);
		short toxicologyAttainment = character.GetLifeSkillAttainment(9);
		EventArgBox argBox = DomainManager.Extra.GetSectMainStoryEventArgBox(10);
		short targetAreaId = -1;
		if (!argBox.Get(SectMainStoryEventArgKey.DefValue.TripodVesselOfMedicineAreaId, ref targetAreaId) || targetAreaId < 0)
		{
			return;
		}
		if (srcLocation.AreaId != targetAreaId || DomainManager.Map.GetBelongSettlementBlock(srcLocation) == null)
		{
			MapAreaData areaData = DomainManager.Map.GetElement_Areas(targetAreaId);
			for (int i = 0; i < areaData.SettlementInfos.Length; i++)
			{
				SettlementInfo settlementInfo = areaData.SettlementInfos[i];
				if (settlementInfo.SettlementId >= 0)
				{
					List<MapBlockData> blocks = context.AdvanceMonthRelatedData.Blocks.Occupy();
					DomainManager.Map.GetSettlementAffiliatedBlocks(targetAreaId, settlementInfo.BlockId, blocks);
					if (blocks.Count > 0)
					{
						MapBlockData targetBlock = blocks.GetRandom(context.Random);
						Location dstLocation = targetBlock.GetLocation();
						Events.RaiseFixedCharacterLocationChanged(context, selfCharId, srcLocation, dstLocation);
						character.SetLocation(dstLocation, context);
						DomainManager.Map.SetBlockAndViewRangeVisible(context, dstLocation.AreaId, dstLocation.BlockId);
					}
					context.AdvanceMonthRelatedData.Blocks.Release(ref blocks);
					break;
				}
			}
		}
		sbyte actionType = SelectTripodVesselActionType(context.Random, selfCharId);
		if (actionType < 0)
		{
			return;
		}
		AddAiActionCooldown(context, selfCharId, 2, actionType, 2);
		targetAreaId = character.GetLocation().AreaId;
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks(targetAreaId);
		Span<MapBlockData> span = areaBlocks;
		for (int j = 0; j < span.Length; j++)
		{
			MapBlockData block = span[j];
			if (block.CharacterSet == null)
			{
				continue;
			}
			foreach (int charId in block.CharacterSet)
			{
				ExecuteTripodVesselAction(charId);
			}
		}
		if (DomainManager.Taiwu.GetTaiwu().GetLocation().AreaId == targetAreaId)
		{
			HashSet<int> taiwuGroupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
			foreach (int charId2 in taiwuGroupCharIds)
			{
				ExecuteTripodVesselAction(charId2);
			}
		}
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		Location location = new Location(character.GetLocation().AreaId, -1);
		switch (actionType)
		{
		case 0:
			monthlyNotifications.AddSectMainStoryKongsangTripodVesselCures(location);
			break;
		case 1:
			monthlyNotifications.AddSectMainStoryKongsangTripodVesselDetoxifies(location);
			break;
		case 2:
			monthlyNotifications.AddSectMainStoryKongsangTripodVesselRestoresHealth(location);
			break;
		case 3:
			monthlyNotifications.AddSectMainStoryKongsangTripodVesselRemovesQiDisorder(location);
			break;
		}
		void ExecuteTripodVesselAction(int targetCharId)
		{
			Character targetChar = _objects[targetCharId];
			switch (actionType)
			{
			case 0:
			{
				Injuries injuries = targetChar.GetInjuries();
				if (injuries.HasAnyInjury())
				{
					injuries.Initialize();
					targetChar.SetInjuries(injuries, context);
				}
				break;
			}
			case 1:
			{
				PoisonInts poisoned = targetChar.GetPoisoned();
				if (poisoned.IsNonZero())
				{
					poisoned.Initialize();
					targetChar.SetPoisoned(ref poisoned, context);
				}
				break;
			}
			case 2:
			{
				short health = targetChar.GetHealth();
				short leftMaxHealth = targetChar.GetLeftMaxHealth();
				if (health < leftMaxHealth)
				{
					targetChar.SetHealth(leftMaxHealth, context);
				}
				break;
			}
			case 3:
				targetChar.SetDisorderOfQi(0, context);
				break;
			}
		}
		sbyte SelectTripodVesselActionType(IRandomSource random, int charId3)
		{
			Span<sbyte> span2 = stackalloc sbyte[4];
			SpanList<sbyte> availableActionTypes = span2;
			for (sbyte i2 = 0; i2 < availableActionTypes.Capacity; i2++)
			{
				if (!IsAiActionInCooldown(charId3, 2, i2))
				{
					availableActionTypes.Add(i2);
				}
			}
			if (availableActionTypes.Count > 0)
			{
				return availableActionTypes.GetRandom(random);
			}
			return -1;
		}
	}

