	public void JixiMovement(DataContext context, Character character)
	{
		JixiRescueTaiwu(context, character);
		character = DomainManager.Story.TryGetJixi();
		if (character == null || DomainManager.World.IsExtraTaskInProgress(121))
		{
			return;
		}
		if (DomainManager.Organization.GetSectFunctionStatus(15, SectFunctionStatuses.SectFunctionStatusType.UpgradedInteractionUnlocked))
		{
			DomainManager.Extra.GetJixiData().JixiDrainNeili = true;
		}
		int taiwuTargetCharId = DomainManager.Extra.GetJixiData().TaiwuTargetCharacterId;
		if (taiwuTargetCharId >= 0)
		{
			TaiwuTransformFiveElements(context, taiwuTargetCharId);
		}
		int targetCharId = DomainManager.Extra.GetJixiData().JixiTargetCharIdByTaiwu;
		if (targetCharId >= 0 && JixiMovementTarget(context, character, targetCharId))
		{
			return;
		}
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
		if (sectArgBox.GetBool(SectMainStoryEventArgKey.DefValue.JixiFollowOpen))
		{
			JixiMovementFollow(context, character);
		}
		else if (DomainManager.Story.IsJixiFree())
		{
			if (DomainManager.Organization.GetSectFunctionStatus(15, SectFunctionStatuses.SectFunctionStatusType.SpecialInteractionUnlocked))
			{
				JixiMovementFree(context, character);
			}
		}
		else if (DomainManager.World.IsExtraTaskInProgress(131))
		{
			JixiMovementPassLegacy(context, character);
		}
		else
		{
			JixiMovementTaiwu(context, character);
		}
	}

