	private void JixiMovementPassLegacy(DataContext context, Character character)
	{
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
		int awakeTaiwuCharId = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.AwakeJixiTaiwuId);
		int graveStayMonth = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.JixiStayAtGraveMonthKey);
		if (_graves.TryGetValue(awakeTaiwuCharId, out var grave) && graveStayMonth < 7)
		{
			JixiMovementChangeLocation(context, character, grave.GetLocation());
			sectArgBox.Set(SectMainStoryEventArgKey.DefValue.JixiStayAtGraveMonthKey, graveStayMonth + 1);
			DomainManager.Extra.SaveSectMainStoryEventArgumentBox(context, 15);
		}
		else
		{
			DomainManager.Story.DealSectMainStoryEnd(context, 15, 1, DomainManager.World.GetCurrDate());
			JixiMovementChangeLocation(context, character, new Location(137, DomainManager.Map.GetAreaBlocks(137).ToArray().GetRandom(context.Random)
				.BlockId));
		}
	}

	private void JixiMovementFree(DataContext context, Character character)
	{
		UpdateJixiTravelTarget(context, character);
		Location settlementLocation = character.GetNpcTravelTargets()[0].GetRealTargetLocation();
		List<MapBlockData> settlementBlocks = context.AdvanceMonthRelatedData.Blocks.Occupy();
		DomainManager.Map.QueryRegularBelongBlocks(settlementBlocks, settlementLocation, true);
		if (!JixiMovementActionToBlocks(context, character, settlementBlocks))
		{
			List<NpcTravelTarget> travelTargets = character.GetNpcTravelTargets();
			travelTargets.RemoveAt(0);
			character.SetNpcTravelTargets(travelTargets, context);
		}
		JixiKillAllTemplateEnemies(context, character);
		context.AdvanceMonthRelatedData.Blocks.Release(ref settlementBlocks);
	}

	private void UpdateJixiTravelTarget(DataContext context, Character character)
	{
		List<NpcTravelTarget> travelTargets = character.GetNpcTravelTargets();
		if (travelTargets.Count > 0)
		{
			NpcTravelTarget travelTarget = travelTargets[0];
			travelTarget.RemainingMonth--;
			if (travelTarget.RemainingMonth <= 0)
			{
				travelTargets.RemoveAt(0);
			}
			else
			{
				travelTargets[0] = travelTarget;
			}
			character.SetNpcTravelTargets(travelTargets, context);
		}
		if (travelTargets.Count <= 0)
		{
			Location targetLocation = SelectJixiTravelTarget(context, character);
			short templateId = character.GetTemplateId();
			if (1 == 0)
			{
			}
			sbyte b = templateId switch
			{
				877 => 12, 
				878 => 9, 
				879 => 6, 
				_ => throw new Exception($"Template out of range: charId={character.GetId()}, templateId={character.GetTemplateId()}"), 
			};
			if (1 == 0)
			{
			}
			sbyte stayMonth = b;
			NpcTravelTarget travelTarget2 = new NpcTravelTarget(targetLocation, stayMonth);
			character.AddTravelTarget(context, travelTarget2);
		}
	}

	private Location SelectJixiTravelTarget(DataContext context, Character character)
	{
		List<Settlement> settlements = ObjectPool<List<Settlement>>.Instance.Get();
		List<Location> locations = ObjectPool<List<Location>>.Instance.Get();
		Location taiwuVillageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		Location currentLocation = character.GetLocation();
		Location expectedSettlementLocation = Location.Invalid;
		if (currentLocation.IsValid())
		{
			MapBlockData block = DomainManager.Map.GetBlock(currentLocation);
			if (block.BelongBlockId >= 0)
			{
				expectedSettlementLocation = new Location(currentLocation.AreaId, block.BelongBlockId);
			}
		}
		DomainManager.Organization.GetAllCivilianSettlements(settlements);
		foreach (Settlement settlement in settlements)
		{
			Location settlementLocation = settlement.GetLocation();
			if (!(settlementLocation == taiwuVillageLocation) && !(settlementLocation == expectedSettlementLocation) && settlementLocation.AreaId < 45)
			{
				OrganizationItem settlementConfig = Config.Organization.Instance[settlement.GetOrgTemplateId()];
				if (!settlementConfig.IsSect)
				{
					locations.Add(settlementLocation);
				}
			}
		}
		if (context.Random.CheckPercentProb(20))
		{
			int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
			List<Location> taiwuEnemyLocations = ObjectPool<List<Location>>.Instance.Get();
			HashSet<int> taiwuRelatedCharIds = context.AdvanceMonthRelatedData.RelatedCharIds.Occupy();
			GetAllRelatedCharIds(taiwuId, taiwuRelatedCharIds);
			foreach (int charId in taiwuRelatedCharIds)
			{
				if (!_objects.TryGetValue(charId, out var relatedChar) || relatedChar.GetCreatingType() != 1)
				{
					continue;
				}
				Location location = relatedChar.GetLocation();
				if (!location.IsValid() || location.AreaId >= 45)
				{
					continue;
				}
				MapBlockData blockData = DomainManager.Map.GetBlock(location);
				if (blockData.BelongBlockId >= 0 && !IsCharacterRelationFriendly(taiwuId, charId) && IsCharacterRelationUnfriendly(taiwuId, charId))
				{
					Location enemySettlementLocation = new Location(location.AreaId, blockData.BelongBlockId);
					if (locations.Contains(enemySettlementLocation))
					{
						taiwuEnemyLocations.Add(enemySettlementLocation);
					}
				}
			}
			if (taiwuEnemyLocations.Count > 0)
			{
				locations.Clear();
				locations.AddRange(taiwuEnemyLocations);
			}
			context.AdvanceMonthRelatedData.RelatedCharIds.Release(ref taiwuRelatedCharIds);
			ObjectPool<List<Location>>.Instance.Return(taiwuEnemyLocations);
		}
		Location targetLocation = locations.GetRandom(context.Random);
		ObjectPool<List<Settlement>>.Instance.Return(settlements);
		ObjectPool<List<Location>>.Instance.Return(locations);
		return targetLocation;
	}

	private void JixiMovementFollow(DataContext context, Character character)
	{
		List<MapBlockData> taiwuNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		if (DomainManager.Extra.GetJixiData().JixiDrainNeili)
		{
			JixiGetTaiwuCurrentBlock(taiwuNeighborBlocks);
		}
		else
		{
			JixiGetTaiwuNeighborBlocks(taiwuNeighborBlocks);
		}
		JixiMovementActionToBlocks(context, character, taiwuNeighborBlocks);
		ObjectPool<List<MapBlockData>>.Instance.Return(taiwuNeighborBlocks);
		JixiKillAllTemplateEnemies(context, character);
		JixiMovementViewRangeVisible(context, character);
	}

	public void JixiMovementFollowTaiwu(DataContext context, Character character)
	{
		List<MapBlockData> taiwuNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		List<MapBlockData> enemyBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		JixiGetTaiwuNeighborBlocks(taiwuNeighborBlocks);
		foreach (MapBlockData block in taiwuNeighborBlocks)
		{
			if (JixiMatchTemplateEnemyBlock(block))
			{
				enemyBlocks.Add(block);
			}
		}
		MapBlockData dstBlock = ((enemyBlocks.Count > 0) ? enemyBlocks.GetRandom(context.Random) : taiwuNeighborBlocks.GetRandom(context.Random));
		ObjectPool<List<MapBlockData>>.Instance.Return(enemyBlocks);
		ObjectPool<List<MapBlockData>>.Instance.Return(taiwuNeighborBlocks);
		Location dstLocation = dstBlock.GetLocation();
		JixiMovementChangeLocation(context, character, dstLocation);
		JixiKillAllTemplateEnemies(context, character);
		JixiMovementViewRangeVisible(context, character);
	}

	private void JixiGetTaiwuNeighborBlocks(List<MapBlockData> neighborBlocks)
	{
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		if (!taiwuLocation.IsValid())
		{
			taiwuLocation = taiwu.GetValidLocation();
		}
		neighborBlocks.Add(DomainManager.Map.GetAreaBlocks(taiwuLocation.AreaId)[taiwuLocation.BlockId]);
	}

	private void JixiGetTaiwuCurrentBlock(List<MapBlockData> neighborBlocks)
	{
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		if (!taiwuLocation.IsValid())
		{
			taiwuLocation = taiwu.GetValidLocation();
		}
		DomainManager.Map.GetRealNeighborBlocks(taiwuLocation.AreaId, taiwuLocation.BlockId, neighborBlocks, 0, includeCenter: true);
	}

	private bool JixiMatchTemplateEnemyBlock(MapBlockData block)
	{
		if (block.TemplateEnemyList == null)
		{
			return false;
		}
		foreach (MapTemplateEnemyInfo enemyInfo in block.TemplateEnemyList)
		{
			if (Config.Character.Instance[enemyInfo.TemplateId].OrganizationInfo.OrgTemplateId != 19)
			{
				return true;
			}
		}
		return false;
	}

	private void JixiKillAllTemplateEnemies(DataContext context, Character character)
	{
		Location location = character.GetLocation();
		if (!location.IsValid())
		{
			return;
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		if (blockData.TemplateEnemyList == null)
		{
			return;
		}
		List<short> defeatedTemplateIds = ObjectPool<List<short>>.Instance.Get();
		for (int i = blockData.TemplateEnemyList.Count - 1; i >= 0; i--)
		{
			MapTemplateEnemyInfo enemyInfo = blockData.TemplateEnemyList[i];
			if (Config.Character.Instance[enemyInfo.TemplateId].OrganizationInfo.OrgTemplateId != 19)
			{
				defeatedTemplateIds.Add(enemyInfo.TemplateId);
				Events.RaiseTemplateEnemyLocationChanged(context, enemyInfo, location, Location.Invalid);
			}
		}
		if (defeatedTemplateIds.Count > 0)
		{
			int spiritualDebtDelta = DomainManager.Combat.GetAreaSpiritualDebtByJixi(context, defeatedTemplateIds, character.GetLocation(), character, addInstantNotification: true);
			DomainManager.Extra.GetJixiData().TempalteEnemyKilledTotal += defeatedTemplateIds.Count;
			DomainManager.Extra.GetJixiData().KillTempalteEnemyGainTotal += spiritualDebtDelta;
		}
		ObjectPool<List<short>>.Instance.Return(defeatedTemplateIds);
		DomainManager.Extra.SaveArgToSectMainStoryEventArgBox(context, 15, SectMainStoryEventArgKey.DefValue.JixiKilledEnemy, value: true);
	}

	private void JixiRescueTaiwu(DataContext context, Character character)
	{
		if (DomainManager.Organization.GetSectFunctionStatus(15, SectFunctionStatuses.SectFunctionStatusType.SpecialInteractionUnlocked) && character.GetTemplateId() != 877)
		{
			Character taiwu = DomainManager.Taiwu.GetTaiwu();
			short taiwuHealth = taiwu.GetHealth();
			short taiwuMaxHealth = taiwu.GetLeftMaxHealth();
			if (taiwuHealth <= 0)
			{
				DomainManager.Extra.JixiRescueTaiwu(context, character);
				MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
				monthlyNotifications.AddSectMainStoryXuehouJixiRescue(taiwu.GetId());
			}
		}
	}

	internal void JixiMovementChangeLocation(DataContext context, Character character, Location dstLocation)
	{
		Location srcLocation = character.GetLocation();
		if (!(srcLocation == dstLocation) && _objects.ContainsKey(character.GetId()))
		{
			Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), srcLocation, dstLocation);
			character.SetLocation(dstLocation, context);
		}
	}

	private void JixiMovementViewRangeVisible(DataContext context, Character character)
	{
		Location location = character.GetLocation();
		if (location.IsValid())
		{
			MapBlockData blockData = DomainManager.Map.GetBlock(location);
			if (!blockData.Visible)
			{
				blockData.SetVisible(visible: true, context);
			}
		}
	}

	private bool JixiMovementActionToBlocks(DataContext context, Character character, List<MapBlockData> targetBlocks)
	{
		if (JixiMovementKillCheckCd(character))
		{
			if (targetBlocks.Count > 0)
			{
				Location dstLocation = targetBlocks.GetRandom(context.Random).GetLocation();
				JixiMovementChangeLocation(context, character, dstLocation);
				return true;
			}
			return false;
		}
		int targetCharId = JixiMovementKillSelectTarget(context, targetBlocks);
		bool actionSuccess = targetCharId >= 0;
		if (actionSuccess || targetBlocks.Count > 0)
		{
			Location dstLocation2 = (actionSuccess ? _objects[targetCharId].GetLocation() : targetBlocks.GetRandom(context.Random).GetLocation());
			JixiMovementChangeLocation(context, character, dstLocation2);
		}
		if (DomainManager.Extra.GetJixiData().JixiDrainNeili)
		{
			JixiMovementDrainActionTarget(context, character, targetCharId);
		}
		else
		{
			JixiMovementKillActionTarget(context, character, targetCharId);
		}
		return actionSuccess;
	}

	private int JixiMovementKillSelectTarget(DataContext context, List<MapBlockData> validBlocks)
	{
		List<int> targetCharIds = context.AdvanceMonthRelatedData.TargetCharIdList.Occupy();
		List<int> charIds = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanBeJixiKillingTarget;
		int taiwuCharForJixi = DomainManager.Taiwu.GetTaiwuCharIdForJixi();
		foreach (MapBlockData block in validBlocks)
		{
			if (block.CharacterSet == null)
			{
				continue;
			}
			foreach (int charId in block.CharacterSet)
			{
				Character blockCharacter = _objects[charId];
				if (matcher.Match(blockCharacter) && blockCharacter.GetId() != taiwuCharForJixi)
				{
					if (DomainManager.Character.IsCharacterRelationUnfriendly(taiwuCharId, charId))
					{
						targetCharIds.Add(charId);
					}
					else
					{
						charIds.Add(charId);
					}
				}
			}
		}
		int targetCharId = ((targetCharIds.Count > 0) ? targetCharIds.GetRandom(context.Random) : ((charIds.Count > 0) ? charIds.GetRandom(context.Random) : (-1)));
		context.AdvanceMonthRelatedData.TargetCharIdList.Release(ref targetCharIds);
		context.AdvanceMonthRelatedData.CharIdList.Release(ref charIds);
		return targetCharId;
	}

	private bool JixiMovementKillCheckCd(Character character)
	{
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
		int waitingDate = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.JixiWaitingMonthKey);
		int currDate = DomainManager.World.GetCurrDate();
		short templateId = character.GetTemplateId();
		if (1 == 0)
		{
		}
		sbyte b = templateId switch
		{
			877 => 0, 
			878 => 1, 
			879 => 2, 
			_ => throw new Exception($"Template out of range: charId={character.GetId()}, templateId={character.GetTemplateId()}"), 
		};
		if (1 == 0)
		{
		}
		sbyte killedInterval = b;
		return currDate < waitingDate + killedInterval;
	}

	private void JixiMovementKillResetCd(DataContext context)
	{
		int currDate = DomainManager.World.GetCurrDate();
		DomainManager.Extra.SaveArgToSectMainStoryEventArgBox(context, 15, SectMainStoryEventArgKey.DefValue.JixiWaitingMonthKey, currDate);
	}

	private void JixiMovementKillActionTarget(DataContext context, Character character, int targetCharId)
	{
		if (targetCharId >= 0 && _objects.TryGetValue(targetCharId, out var targetChar))
		{
			EventArgBox eventArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
			Location location = character.GetLocation();
			DomainManager.Character.MakeCharacterDead(context, targetChar, 14);
			MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
			monthlyNotifications.AddSectMainStoryXuehouJixiKillsPeople(location, 1);
			int killedCount = eventArgBox.GetInt(SectMainStoryEventArgKey.DefValue.JixiKilledCountKey);
			eventArgBox.Set(SectMainStoryEventArgKey.DefValue.JixiKilledCountKey, ++killedCount);
			SectStoryJixiData jixiData = DomainManager.Extra.GetJixiData();
			jixiData.KillTargets.Add(character.GetId());
			jixiData.CurrentFormKillAmount++;
			jixiData.JixiTempKillAmount++;
			int totalValue = DomainManager.Extra.GetJixiTotalGrowValue(character);
			if (1 == 0)
			{
			}
			short num = (short)((totalValue < 770) ? 877 : ((totalValue >= 1540) ? 879 : 878));
			if (1 == 0)
			{
			}
			short templateId = num;
			if (character.GetTemplateId() != templateId)
			{
				List<NpcTravelTarget> travelTargets = character.GetNpcTravelTargets();
				DomainManager.Story.JixiGrowUp(context, character.GetTemplateId(), templateId);
				character = DomainManager.Character.GetOrCreateFixedCharacterByTemplateId(context, templateId);
				character.SetNpcTravelTargets(travelTargets, context);
			}
			JixiMovementKillResetCd(context);
		}
	}

	private int GetRandomElementFromList(IRandomSource random, List<int> validNeiliType)
	{
		if (validNeiliType == null || validNeiliType.Count <= 0)
		{
			return -1;
		}
		int targetIndex = random.Next(0, validNeiliType.Count);
		int result = validNeiliType[targetIndex];
		validNeiliType.RemoveAt(targetIndex);
		return result;
	}

	private void TaiwuTransformFiveElements(DataContext context, int targetCharId)
	{
		Character targetCharacter;
		bool isAlive = DomainManager.Character.TryGetElement_Objects(targetCharId, out targetCharacter);
		SectStoryJixiData jixiData = DomainManager.Extra.GetJixiData();
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		SectStoryJixiData sectStoryJixiData = jixiData;
		if (sectStoryJixiData.TaiwuTransformFiveElementsCurrent == null)
		{
			sectStoryJixiData.TaiwuTransformFiveElementsCurrent = new int[5];
		}
		if (!isAlive)
		{
			jixiData.TaiwuTargetCharacterId = -1;
			monthlyNotifications.AddSectMainStoryXuehouTaiwuTransFiveElementsFail(targetCharId, DomainManager.Taiwu.GetTaiwuCharId());
			for (int i = 0; i < jixiData.TaiwuTransformFiveElementsCurrent.Length; i++)
			{
				jixiData.TaiwuTransformFiveElementsCurrent[i] = 0;
			}
			return;
		}
		Location location = targetCharacter.GetLocation();
		sbyte taiwuTargetFiveElementsType = jixiData.TaiwuTargetFiveElementsType;
		NeiliProportionOfFiveElements targetNeiliProportion = targetCharacter.GetBaseNeiliProportionOfFiveElements();
		if (taiwuTargetFiveElementsType < 0 || taiwuTargetFiveElementsType >= 5)
		{
			return;
		}
		if (targetNeiliProportion[taiwuTargetFiveElementsType] == 0 || targetCharacter.IsCompletelyInfected() || targetCharacter.IsActiveExternalRelationState(4uL))
		{
			jixiData.TaiwuTargetCharacterId = -1;
			monthlyNotifications.AddSectMainStoryXuehouTaiwuTransFiveElementsFail(targetCharId, DomainManager.Taiwu.GetTaiwuCharId());
			for (int j = 0; j < jixiData.TaiwuTransformFiveElementsCurrent.Length; j++)
			{
				jixiData.TaiwuTransformFiveElementsCurrent[j] = 0;
			}
			return;
		}
		Character taiwu = DomainManager.Taiwu.GetTaiwu();
		NeiliProportionOfFiveElements taiwuNeiliProportion = taiwu.GetBaseNeiliProportionOfFiveElements();
		Character jixiChar = DomainManager.Story.TryGetJixi();
		short templateId = jixiChar.GetTemplateId();
		if (1 == 0)
		{
		}
		int num = templateId switch
		{
			877 => 1, 
			878 => 2, 
			879 => 3, 
			_ => 0, 
		};
		if (1 == 0)
		{
		}
		int amount = num;
		int transferAmount = Math.Min(amount, 100 - taiwuNeiliProportion[taiwuTargetFiveElementsType]);
		jixiData.TaiwuTransformFiveElementsCurrent[taiwuTargetFiveElementsType] += transferAmount;
		jixiData.TaiwuTransformFiveElementsTotal[taiwuTargetFiveElementsType] += transferAmount;
		if (taiwu.GetGender() == 1)
		{
			taiwuNeiliProportion.Transfer(taiwuTargetFiveElementsType, 0, amount);
		}
		else
		{
			taiwuNeiliProportion.Transfer(taiwuTargetFiveElementsType, 2, amount);
		}
		if (targetCharacter.GetGender() == 1)
		{
			sbyte fiveElementsType = FiveElementsType.Countering[taiwuTargetFiveElementsType];
			targetNeiliProportion.Transfer(fiveElementsType, 0, amount);
		}
		else
		{
			sbyte fiveElementsType2 = FiveElementsType.Producing[taiwuTargetFiveElementsType];
			targetNeiliProportion.Transfer(fiveElementsType2, 2, amount);
		}
		targetCharacter.SetBaseNeiliProportionOfFiveElements(targetNeiliProportion, context);
		taiwu.SetBaseNeiliProportionOfFiveElements(taiwuNeiliProportion, context);
		DomainManager.Global.CheckFiveElementConflictGuidingTrigger(context, taiwu.GetNeiliType());
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		lifeRecordCollection.AddSectMainStoryXuehouTaiwuTransferFiveElements(targetCharId, currDate, targetCharId);
		monthlyNotifications.AddSectMainStoryXuehouTaiwuTransFiveElements(location, targetCharId, taiwu.GetId());
	}

	private bool JixiMovementTarget(DataContext context, Character character, int targetCharId)
	{
		List<NpcTravelTarget> travelTargets = character.GetNpcTravelTargets();
		bool isDrainNeili = DomainManager.Extra.GetJixiData().JixiDrainNeili;
		if (targetCharId < 0 || !_objects.TryGetValue(targetCharId, out var targetChar) || targetChar.GetLocation() == Location.Invalid)
		{
			ClearAndCheckTarget(targetCharId, travelTargets, isDrainNeili);
			return false;
		}
		if (isDrainNeili)
		{
			CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanBeSelectJixiDrainTarget;
			if (!matcher.Match(targetChar) || targetChar.IsCompletelyInfected() || targetChar.IsActiveExternalRelationState(4uL))
			{
				ClearAndCheckTarget(targetCharId, travelTargets, isDrainNeili);
				return false;
			}
		}
		short templateId = character.GetTemplateId();
		if (1 == 0)
		{
		}
		sbyte b = templateId switch
		{
			877 => 12, 
			878 => 9, 
			879 => 6, 
			_ => throw new Exception($"Template out of range: charId={character.GetId()}, templateId={character.GetTemplateId()}"), 
		};
		if (1 == 0)
		{
		}
		sbyte stayMonth = b;
		if (travelTargets.Count > 0)
		{
			if (travelTargets[0].TargetCharId != targetCharId)
			{
				NpcTravelTarget travelTarget = new NpcTravelTarget(targetCharId, stayMonth);
				travelTargets[0] = travelTarget;
				character.SetNpcTravelTargets(travelTargets, context);
			}
		}
		else
		{
			NpcTravelTarget travelTarget2 = new NpcTravelTarget(targetCharId, stayMonth);
			travelTargets.Add(travelTarget2);
			character.SetNpcTravelTargets(travelTargets, context);
		}
		Location tagetLocation = character.GetNpcTravelTargets()[0].GetRealTargetLocation();
		Location dstLocation = tagetLocation;
		JixiMovementChangeLocation(context, character, dstLocation);
		JixiKillAllTemplateEnemies(context, character);
		if (isDrainNeili)
		{
			JixiMovementDrainActionTarget(context, character, targetCharId);
		}
		else
		{
			JixiMovementKillActionTarget(context, character, targetCharId);
			ClearAndCheckTarget(targetCharId, travelTargets, isDrainNeili: false);
		}
		return true;
		void ClearAndCheckTarget(int num, List<NpcTravelTarget> list, bool flag)
		{
			if (flag && num >= 0)
			{
				_objects.TryGetValue(num, out var targetChar2);
				MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
				if (targetChar2 == null)
				{
					monthlyNotifications.AddSectMainStoryXuehouJixiDrainNeiliFail1(num);
				}
				else if (targetChar2.IsCompletelyInfected())
				{
					monthlyNotifications.AddSectMainStoryXuehouJixiDrainNeiliFail2(num);
				}
				else if (targetChar2.IsActiveExternalRelationState(4uL))
				{
					monthlyNotifications.AddSectMainStoryXuehouJixiDrainNeiliFail3(num);
				}
				else
				{
					monthlyNotifications.AddSectMainStoryXuehouJixiDrainNeiliFail(num);
				}
			}
			DomainManager.Extra.GetJixiData().JixiTargetCharIdByTaiwu = -1;
			if (list.Count > 0 && list[0].TargetCharId == num)
			{
				list.RemoveAt(0);
				character.SetNpcTravelTargets(list, context);
			}
		}
	}

	private void JixiMovementDrainActionTarget(DataContext context, Character character, int targetCharId)
	{
		if (targetCharId < 0 || !_objects.TryGetValue(targetCharId, out var targetChar))
		{
			return;
		}
		EventArgBox eventArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
		SectStoryJixiData jixiData = DomainManager.Extra.GetJixiData();
		if (targetCharId != jixiData.PreviousDrainTarget)
		{
			jixiData.DrainTargetBasicNeiliAllocProgress = 0;
			for (int i = 0; i < jixiData.CurrentTargetNeiliAllocProgressDrained.Items.Count; i++)
			{
				jixiData.CurrentTargetNeiliAllocProgressDrained.Items[i] = 0;
			}
		}
		List<int> validNeiliType = ObjectPool<List<int>>.Instance.Get();
		validNeiliType.Clear();
		NeiliAllocation targetBaseCharNeiliAlloc = targetChar.GetBaseNeiliAllocation();
		NeiliAllocation targetExtraCharNeiliAlloc = targetChar.GetExtraNeiliAllocation();
		NeiliAllocation targetCharNeiliAlloc = default(NeiliAllocation);
		for (int j = 0; j < 4; j++)
		{
			targetCharNeiliAlloc[j] = (short)Math.Max(targetBaseCharNeiliAlloc[j] + targetExtraCharNeiliAlloc[j], 0);
		}
		IntList jixiExtraNeili = jixiData.NeiliAllocProgressDrained;
		int maximumExtraNeiliProgress = 2750;
		for (int k = 0; k < 4; k++)
		{
			if (targetCharNeiliAlloc[k] > 0 && jixiExtraNeili.Items[k] < maximumExtraNeiliProgress)
			{
				validNeiliType.Add(k);
			}
		}
		if (validNeiliType.Count <= 0)
		{
			ObjectPool<List<int>>.Instance.Return(validNeiliType);
			return;
		}
		short templateId = character.GetTemplateId();
		if (1 == 0)
		{
		}
		int num = templateId switch
		{
			877 => 45, 
			878 => 70, 
			879 => 150, 
			_ => throw new Exception($"Template out of range: charId={character.GetId()}, templateId={character.GetTemplateId()}"), 
		};
		if (1 == 0)
		{
		}
		int drainNeiliAllocProgressAmount = num;
		bool needDrainFlag = true;
		bool hasRemain = false;
		if (jixiData.DrainTargetNeiliAllocType >= 0 && jixiData.DrainTargetNeiliAllocType < 4 && validNeiliType.Contains(jixiData.DrainTargetNeiliAllocType))
		{
			byte targetType = (byte)jixiData.DrainTargetNeiliAllocType;
			validNeiliType.Remove(targetType);
			drainNeiliAllocProgressAmount = JixiDrainNeili(context, character, targetChar, targetType, drainNeiliAllocProgressAmount, maximumExtraNeiliProgress, out var _, out hasRemain, out needDrainFlag);
		}
		while (drainNeiliAllocProgressAmount > 0 && validNeiliType.Count > 0 && needDrainFlag)
		{
			byte targetNeiliType = (byte)GetRandomElementFromList(context.Random, validNeiliType);
			drainNeiliAllocProgressAmount = JixiDrainNeili(context, character, targetChar, targetNeiliType, drainNeiliAllocProgressAmount, maximumExtraNeiliProgress, out var _, out var hasRemainSingle, out needDrainFlag);
			hasRemain = hasRemain || hasRemainSingle;
			if (hasRemain && !needDrainFlag)
			{
				jixiData.DrainTargetNeiliAllocType = targetNeiliType;
			}
		}
		ObjectPool<List<int>>.Instance.Return(validNeiliType);
		if (drainNeiliAllocProgressAmount > 0 && hasRemain)
		{
			jixiData.DrainTargetBasicNeiliAllocProgress = drainNeiliAllocProgressAmount;
		}
		jixiData.PreviousDrainTarget = targetCharId;
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		monthlyNotifications.AddSectMainStoryXuehouJixiDrainNeili(targetCharId);
		Character jixiChar = DomainManager.Story.TryGetJixi();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		lifeRecordCollection.AddSectMainStoryXuehouJixiDrainNeili(targetCharId, currDate, targetCharId);
		DomainManager.Extra.CalculateJixiGrow(context, character);
	}

	private unsafe int JixiDrainNeili(DataContext context, Character jixi, Character targetChar, byte targetNeiliType, int desireAmount, int maximumExtraNeiliProgress, out int totalDrainAmount, out bool hasRemain, out bool needDrain)
	{
		SectStoryJixiData jixiData = DomainManager.Extra.GetJixiData();
		needDrain = true;
		int previousProgress = jixiData.DrainTargetBasicNeiliAllocProgress;
		hasRemain = false;
		IntList jixiExtraNeiliAllocProgress = jixiData.NeiliAllocProgressDrained;
		int[] targetExtraNeiliAllocProgress = targetChar.GetExtraNeiliAllocationProgress();
		NeiliAllocation targetBasicNeiliAlloc = targetChar.GetBaseNeiliAllocation();
		int currentJixiAlloc = jixiExtraNeiliAllocProgress.Items[targetNeiliType] / 55;
		int maxDrain = maximumExtraNeiliProgress - jixiExtraNeiliAllocProgress.Items[targetNeiliType];
		maxDrain = Math.Min(maxDrain, desireAmount);
		maxDrain = Math.Max(maxDrain, 0);
		int maxDrainAlloc = (maxDrain + previousProgress) / 55;
		int remainMaxDrainAlloc = maxDrainAlloc;
		bool drainTargetSuccessFlag = maxDrainAlloc > 0;
		if (maxDrainAlloc == 0)
		{
			hasRemain = true;
		}
		if (targetExtraNeiliAllocProgress[targetNeiliType] > 0)
		{
			int targetCurrentAlloc = Character.GetExtraNeiliAllocationByProgress(targetExtraNeiliAllocProgress[targetNeiliType]);
			if (remainMaxDrainAlloc <= targetCurrentAlloc)
			{
				hasRemain = true;
				targetCurrentAlloc -= remainMaxDrainAlloc;
				remainMaxDrainAlloc = 0;
				int targetRemainProgress = Character.GetExtraNeiliAllocationProgressByExtraNeiliAllocation(targetCurrentAlloc);
				targetExtraNeiliAllocProgress[targetNeiliType] = targetRemainProgress;
				targetChar.SetExtraNeiliAllocationAndProgress(context, targetExtraNeiliAllocProgress);
			}
			else
			{
				remainMaxDrainAlloc -= targetCurrentAlloc;
				targetExtraNeiliAllocProgress[targetNeiliType] = 0;
				targetChar.SetExtraNeiliAllocationAndProgress(context, targetExtraNeiliAllocProgress);
			}
		}
		if (remainMaxDrainAlloc > 0)
		{
			short targetBasicNeiliAllocSingle = targetBasicNeiliAlloc.Items[(int)targetNeiliType];
			int drainFromBasic = 0;
			if (remainMaxDrainAlloc <= targetBasicNeiliAllocSingle)
			{
				hasRemain = true;
				drainFromBasic = remainMaxDrainAlloc;
			}
			else
			{
				drainFromBasic = targetBasicNeiliAllocSingle;
			}
			remainMaxDrainAlloc -= drainFromBasic;
			targetBasicNeiliAllocSingle -= (short)drainFromBasic;
			targetBasicNeiliAlloc.Items[(int)targetNeiliType] = targetBasicNeiliAllocSingle;
			targetChar.SetBaseNeiliAllocation(targetBasicNeiliAlloc, context);
		}
		totalDrainAmount = maxDrainAlloc - remainMaxDrainAlloc;
		needDrain = totalDrainAmount > 0;
		int drainTargetProgress = totalDrainAmount * 55;
		drainTargetProgress -= previousProgress;
		jixiData.DrainTargetBasicNeiliAllocProgress = 0;
		int currentProgressChange = drainTargetProgress;
		int remainDesireAmount = desireAmount - drainTargetProgress;
		if (hasRemain && remainDesireAmount > 0 && remainDesireAmount < 55)
		{
			currentProgressChange += remainDesireAmount;
			needDrain = false;
		}
		jixiExtraNeiliAllocProgress.Items[targetNeiliType] += currentProgressChange;
		jixiData.NeiliAllocProgressDrainedTotal.Items[targetNeiliType] += currentProgressChange;
		jixiData.CurrentTargetNeiliAllocProgressDrained.Items[targetNeiliType] += currentProgressChange;
		jixiData.CurrentFormNeiliAllocProgressDrained.Items[targetNeiliType] += currentProgressChange;
		jixiData.NeiliAllocProgressDrained = jixiExtraNeiliAllocProgress;
		return desireAmount - drainTargetProgress;
	}

