	public void UpdateFollowMovementCharacters(DataContext context)
	{
		if (DomainManager.Taiwu.AtPastTaiwuVillage() || _followMovementCharacters.Count == 0)
		{
			return;
		}
		List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		foreach (var (charId, followInfo) in _followMovementCharacters)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			if (character.GetCreatingType() == 1)
			{
				if (character.GetLeaderId() != -1 || character.GetKidnapperId() != -1 || !character.GetLocation().IsValid() || character.IsActiveExternalRelationState(252uL) || character.IsCompletelyInfected())
				{
					continue;
				}
			}
			else if (character.GetCreatingType() != 0)
			{
				continue;
			}
			Location srcLocation = character.GetLocation();
			MapBlockData srcBlock = (srcLocation.IsValid() ? DomainManager.Map.GetBlock(srcLocation) : null);
			Character targetChar = DomainManager.Taiwu.GetTaiwu();
			Location location = targetChar.GetValidLocation();
			MapBlockData targetBlock = DomainManager.Map.GetBlock(location);
			ByteCoordinate targetPos = targetBlock.GetBlockPos();
			if (srcBlock == null || srcBlock.GetManhattanDistanceToPos(targetPos.X, targetPos.Y) >= followInfo.Distance)
			{
				DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, neighborBlocks, followInfo.Distance);
				Location dstLocation = neighborBlocks.GetRandom(context.Random)?.GetLocation() ?? location;
				if (character.GetCreatingType() == 1)
				{
					GroupMove(context, character, dstLocation);
					continue;
				}
				character.SetLocation(dstLocation, context);
				Events.RaiseFixedCharacterLocationChanged(context, charId, srcLocation, dstLocation);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
	}

