	}

	private void GetNameRelatedData(int charId, ref NameRelatedData data)
	{
		if (_objects.TryGetValue(charId, out var character))
		{
			GetNameRelatedData(character, ref data);
			return;
		}
		if (_deadCharacters.TryGetValue(charId, out var deadChar))
		{
			GetNameRelatedData(charId, deadChar, ref data);
			return;
		}
		data.CharTemplateId = -1;
		data.NickNameId = DomainManager.Taiwu.GetFollowingNpcNickNameId(charId);
	}

	private void GetNameAndLifeRelatedData(int charId, ref NameAndLifeRelatedData data)
	{
		DeadCharacter deadChar;
		if (_objects.TryGetValue(charId, out var character))
		{
			GetNameRelatedData(character, ref data.NameRelatedData);
			data.LifeState = 0;
		}
		else if (_deadCharacters.TryGetValue(charId, out deadChar))
		{
			GetNameRelatedData(charId, deadChar, ref data.NameRelatedData);
			data.LifeState = 1;
			data.HasTomb = TryGetElement_Graves(charId, out var _);
		}
		else
		{
			data.NameRelatedData.CharTemplateId = -1;
			data.LifeState = 2;
		}
	}

