	private void PrepareContestForLegendaryBookPrioritizedActionData(DataContext context)
	{
		if (!DomainManager.LegendaryBook.IsAnyLegendaryBookOwned())
		{
			return;
		}
		int canContestTotalCount = 0;
		for (sbyte combatSkillType = 0; combatSkillType < 14; combatSkillType++)
		{
			if (DomainManager.LegendaryBook.GetOwner(combatSkillType) >= 0)
			{
				int contestantCount = DomainManager.LegendaryBook.GetContestForLegendaryBookCharacterSet(combatSkillType).GetCount();
				int canContestCount = 2 - contestantCount;
				if (canContestCount > 0)
				{
					canContestTotalCount += canContestCount;
				}
			}
		}
		if (canContestTotalCount <= 0)
		{
			return;
		}
		List<int> charIds = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		IList<int> topThousands = _topThousandCharDescendingRanking.Values;
		int i = 0;
		for (int count = Math.Min(topThousands.Count, 100); i < count; i++)
		{
			charIds.Add(topThousands[i]);
		}
		for (sbyte orgTemplateId = 1; orgTemplateId <= 15; orgTemplateId++)
		{
			Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
			for (int j = 1; j <= 3; j++)
			{
				long rankingInfo = settlement.GetRankingInfo(1);
				int charId = (int)(rankingInfo & 0x7FFFFFFF);
				charIds.Add(charId);
			}
		}
		CollectionUtils.Shuffle(context.Random, charIds);
		foreach (int charId2 in charIds)
		{
			if (canContestTotalCount <= 0)
			{
				break;
			}
			if (_objects.TryGetValue(charId2, out var character) && character.GetAgeGroup() != 0 && !character.IsActiveExternalRelationState(188uL) && !character.IsActiveExternalRelationState(1uL) && !DomainManager.LegendaryBook.IsCharacterActingCrazy(character))
			{
				_legendaryBookChallengers.Add(charId2);
				canContestTotalCount--;
			}
		}
		context.AdvanceMonthRelatedData.CharIdList.Release(ref charIds);
	}

