	private void PrepareInfantPrioritizedActionData(DataContext context)
	{
		_charactersWithInfantNearBy.Clear();
		_characterWithInfantWithBloodRelation.Clear();
		foreach (KeyValuePair<int, int> pair in _infantMap)
		{
			if (!TryGetElement_Objects(pair.Key, out var infant) || infant.GetAgeGroup() != 0 || infant.GetLeaderId() >= 0 || InfantHasPotentialAdopter(pair.Key) || infant.GetOrganizationInfo().OrgTemplateId == 16)
			{
				continue;
			}
			Location location = infant.GetLocation();
			if (!location.IsValid())
			{
				continue;
			}
			Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(location.AreaId);
			ByteCoordinate locationPos = DomainManager.Map.GetBlock(location).GetBlockPos();
			Span<MapBlockData> span = blocks;
			for (int i = 0; i < span.Length; i++)
			{
				MapBlockData block = span[i];
				if (block.CharacterSet == null)
				{
					continue;
				}
				foreach (int id in block.CharacterSet)
				{
					if (!RelationTypeHelper.AllowAddingAdoptiveChildRelation(id, pair.Key))
					{
						_characterWithInfantWithBloodRelation[id] = pair.Key;
					}
					int newDistance = locationPos.GetManhattanDistance(block.GetBlockPos());
					if (!_charactersWithInfantNearBy.TryGetValue(id, out var existed) || existed.Item2 > newDistance)
					{
						_charactersWithInfantNearBy[id] = (pair.Key, newDistance);
					}
					else if (existed.Item2 == newDistance && context.Random.CheckPercentProb(50))
					{
						_charactersWithInfantNearBy[id] = (pair.Key, newDistance);
					}
				}
			}
		}
	}

	private void PrepareEMeiPrioritizedActionData(DataContext context)
	{
		_eMeiPsychotics.Clear();
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(2);
		if (!sectArgBox.Contains<int>(SectMainStoryEventArgKey.DefValue.EmeiKillEachOtherStage))
		{
			return;
		}
		int limitation = ((sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.EmeiKillEachOtherStage) == 1) ? context.Random.Next(1, 4) : context.Random.Next(3, 10));
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(2);
		short locationAreaId = settlement.GetLocation().AreaId;
		OrgMemberCollection orgMembers = settlement.GetMembers();
		List<int> members = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		orgMembers.GetAllMembers(members);
		foreach (int charId in members)
		{
			if (DomainManager.Extra.SectEmeiGetInsaneCharacterIdCount() >= limitation)
			{
				break;
			}
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && character.GetLocation().AreaId == locationAreaId)
			{
				_eMeiPsychotics.Add(charId);
			}
		}
		context.AdvanceMonthRelatedData.CharIdList.Release(ref members);
	}

	private void PrepareBaihuaPrioritizedActionData()
	{
		BaihuaManicCharIds.Clear();
		IntList deadCharIds = DomainManager.Story.BaihuaGetSpecialDebuffIntList();
		List<int> items = deadCharIds.Items;
		if (items == null || items.Count <= 0)
		{
			return;
		}
		List<int> targets = ObjectPool<List<int>>.Instance.Get();
		targets.Clear();
		targets.AddRange(deadCharIds.Items);
		IntList cureCharIds = DomainManager.Story.BaihuaGetCureSpecialDebuffIntList();
		items = cureCharIds.Items;
		if (items != null && items.Count > 0)
		{
			targets.RemoveAll(cureCharIds.Items.Contains);
		}
		targets.RemoveAll(IsNotManicCharId);
		foreach (int target in targets)
		{
			BaihuaManicCharIds.Add(target);
		}
		ObjectPool<List<int>>.Instance.Return(targets);
	}

