	public void GenerateCharacterProfession(DataContext context, Character character)
	{
		int charId = character.GetId();
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			return;
		}
		ProfessionData currProfession = GetCharacterCurrentProfession(charId);
		if (currProfession != null)
		{
			return;
		}
		OrganizationMemberItem orgMemberCfg = OrganizationDomain.GetOrgMemberConfig(character.GetOrganizationInfo());
		IntPair[] preferProfessions = orgMemberCfg.PreferProfessions;
		if (preferProfessions == null || preferProfessions.Length <= 0)
		{
			return;
		}
		Span<IntPair> span = stackalloc IntPair[orgMemberCfg.PreferProfessions.Length];
		SpanList<IntPair> professions = span;
		professions.AddRange(orgMemberCfg.PreferProfessions);
		CollectionUtils.Shuffle(context.Random, professions);
		SpanList<IntPair>.Enumerator enumerator = professions.GetEnumerator();
		while (enumerator.MoveNext())
		{
			IntPair pair = enumerator.Current;
			if (!context.Random.CheckPercentProb(pair.Second))
			{
				continue;
			}
			ProfessionItem professionCfg = Profession.Instance[pair.First];
			int maxSeniority = character.GetMaxProfessionSeniority(pair.First);
			int seniority = MathUtils.Clamp(professionCfg.ProfessionSeniorityPerMonth[character.GetInteractionGrade()] * (character.GetCurrAge() - 16) * 12, 0, maxSeniority);
			SetCharacterCurrProfession(context, character.GetId(), pair.First, seniority);
			break;
		}
	}

	public void ChangeCharacterCurrProfessionSeniority(DataContext context, int charId, int delta)
	{
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			throw new InvalidOperationException("Cannot set taiwu's profession.");
		}
		if (_characterProfessions.TryGetValue(charId, out var professionDataList))
		{
			short settlementId = DomainManager.Character.GetElement_Objects(charId).GetOrganizationInfo().SettlementId;
			CValuePercentBonus buildingFactor = DomainManager.Building.GetBuildingBlockEffect(settlementId, EBuildingScaleEffect.ProfessionSeniorityBonus);
			professionDataList.CurrProfession.Seniority += delta * buildingFactor;
			int oldExtraSeniority = professionDataList.CurrProfession.ExtraSeniority;
			OfflineNormalizeProfessionSeniority(charId, professionDataList.CurrProfession);
			DomainManager.Information.GiveProfessionInformationRemainUsableCount(context, charId, professionDataList.CurrProfession.TemplateId, oldExtraSeniority, professionDataList.CurrProfession.ExtraSeniority);
			SetElement_CharacterProfessions(charId, professionDataList, context);
		}
	}

	public static void OfflineNormalizeProfessionSeniority(int charId, ProfessionData professionData)
	{
		int maxSeniority = ((charId == DomainManager.Taiwu.GetTaiwuCharId()) ? 3000000 : DomainManager.Character.GetElement_Objects(charId).GetMaxProfessionSeniority(professionData.TemplateId));
		int overflow = professionData.Seniority - maxSeniority;
		if (overflow > 0)
		{
			professionData.Seniority = maxSeniority;
			professionData.ExtraSeniority += overflow;
		}
		Tester.Assert(professionData.ExtraSeniority >= 0);
		professionData.ExtraSeniority %= 1500000;
		Tester.Assert(professionData.Seniority <= 3000000);
		Tester.Assert(professionData.ExtraSeniority <= 1500000);
	}

	public ProfessionData SetCharacterCurrProfession(DataContext context, int charId, int professionId, int initSeniority = 0)
	{
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			throw new InvalidOperationException("Cannot set taiwu's profession.");
		}
		if (_characterProfessions.TryGetValue(charId, out var professionDataList))
		{
			ProfessionData profession = professionDataList.ChangeCurrProfession(professionId);
			SetElement_CharacterProfessions(charId, professionDataList, context);
			return profession;
		}
		professionDataList = new ProfessionDataList();
		ProfessionData profession2 = professionDataList.ChangeCurrProfession(professionId);
		profession2.Seniority = initSeniority;
		profession2.ExtraSeniority = 0;
		AddElement_CharacterProfessions(charId, professionDataList, context);
		return profession2;
	}

