	public void UpdateSeniorityForCharacterProfessions(DataContext context)
	{
		HashSet<int> professionOldUnlockStates = new HashSet<int>();
		List<(int, ProfessionDataList)> modified = new List<(int, ProfessionDataList)>();
		foreach (var (charId, professionList) in _characterProfessions)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			ProfessionData currProfession = professionList.CurrProfession;
			ProfessionItem professionCfg = currProfession.GetConfig();
			sbyte grade = character.GetInteractionGrade();
			professionOldUnlockStates.Clear();
			for (int i = 0; i <= professionCfg.ProfessionSkills.Length; i++)
			{
				if (currProfession.IsSkillUnlocked(i))
				{
					professionOldUnlockStates.Add(i);
				}
			}
			CValuePercentBonus buildingFactor = DomainManager.Building.GetBuildingBlockEffect(character.GetOrganizationInfo().SettlementId, EBuildingScaleEffect.ProfessionSeniorityBonus);
			int delta = professionCfg.ProfessionSeniorityPerMonth[grade] * buildingFactor;
			currProfession.Seniority += delta;
			int oldExtraSeniority = currProfession.ExtraSeniority;
			OfflineNormalizeProfessionSeniority(charId, currProfession);
			for (int j = 0; j <= professionCfg.ProfessionSkills.Length; j++)
			{
				if (!professionOldUnlockStates.Contains(j) && currProfession.IsSkillUnlocked(j))
				{
					DomainManager.Information.GiveProfessionInformation(context, charId, currProfession.TemplateId);
				}
			}
			DomainManager.Information.GiveProfessionInformationRemainUsableCount(context, charId, currProfession.TemplateId, oldExtraSeniority, currProfession.ExtraSeniority);
			modified.Add((charId, professionList));
		}
		foreach (var (charId2, professionList2) in modified)
		{
			SetElement_CharacterProfessions(charId2, professionList2, context);
		}
	}

