	public void DirectlyChangeFavorabilityOptional(DataContext context, Character character, Character relatedChar, int delta, short type)
	{
		int charId = character.GetId();
		int relatedCharId = relatedChar.GetId();
		RelationKey relationKey = new RelationKey(charId, relatedCharId);
		if (!_relations.TryGetValue(relationKey, out var relation))
		{
			var (favor, relatedFavor) = CalcInitialFavorabilitiesOfAliveChars(context.Random, character, relatedChar);
			CreateRelation(context, charId, relatedCharId, 0, favor);
			CreateRelation(context, relatedCharId, charId, 0, relatedFavor);
			relation = _relations[relationKey];
		}
		(int, bool) favFactor = DomainManager.World.GetFavorabilityChangePercent(type, character.IsFavorabilityGainFixed);
		delta = ((delta < 0 && favFactor.Item2) ? (delta * 100 / favFactor.Item1) : (delta * favFactor.Item1 / 100));
		if (relatedCharId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			short maxFavorability = CalcMaxFavorabilityToTaiwuById(charId);
			relation.Favorability = (short)Math.Clamp(relation.Favorability + delta, -30000, maxFavorability);
			sbyte favorabilityType = FavorabilityType.GetFavorabilityType(relation.Favorability);
			if (favorabilityType >= 3)
			{
				character.SetLovingItemRevealed(lovingItemRevealed: true, context);
				character.SetHatingItemRevealed(hatingItemRevealed: true, context);
			}
			if (DomainManager.Organization.TryGetSettlementCharacter(character.GetId(), out var settlementChar))
			{
				short settlementId = settlementChar.GetSettlementId();
				Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
				Events.StatApproveTaiwuRate(context, settlement);
			}
			if (delta != 0)
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 255);
			}
			if (delta > 0 && favorabilityType >= 5)
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 257);
			}
		}
		else
		{
			relation.Favorability = (short)Math.Clamp(relation.Favorability + delta, -30000, 30000);
		}
		SetElement_Relations(relationKey, relation, context);
	}

