	}

	public void ChangeFavorabilityTendToZero(DataContext context, int charId, int targetCharId, int delta)
	{
		short favorability = GetFavorability(charId, targetCharId);
		if ((favorability != short.MinValue && favorability != 0) || 1 == 0)
		{
			short value = ((favorability > 0) ? ((short)Math.Max(0, favorability - delta)) : ((short)Math.Min(0, favorability + delta)));
			SetFavorability(context, charId, targetCharId, value);
		}
	}

	public List<(int charId, short favorability)> ChangeFavorabilitiesOfAllRelatedCharsWhenChangingHobby(DataContext context, Character character)
	{
		int charId = character.GetId();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		HashSet<int> relatedCharIds = context.AdvanceMonthRelatedData.RelatedCharIds.Occupy();
		GetAllRelatedCharIds(charId, relatedCharIds);
		if (relatedCharIds.Count <= 0)
		{
			context.AdvanceMonthRelatedData.RelatedCharIds.Release(ref relatedCharIds);
			return null;
		}
		sbyte behaviorType = character.GetBehaviorType();
		(short positive, short negative) tuple = BaseChangedFavorabilitiesOfChangingHobby[behaviorType];
		short positive = tuple.positive;
		short negative = tuple.negative;
		List<(int, short)> favorabilitiesOfRelatedChars = new List<(int, short)>();
		foreach (int relatedCharId in relatedCharIds)
		{
			if (IsCharacterAlive(relatedCharId))
			{
				short oriFavor = _relations[new RelationKey(charId, relatedCharId)].Favorability;
				sbyte favorabilityType = FavorabilityType.GetFavorabilityType(oriFavor);
				sbyte factor = FavorabilityChangingFactorsOfChangingHobby[FavorabilityType.ToIndex(favorabilityType)];
				int delta = ((favorabilityType >= 0) ? positive : negative) * factor / 100;
				short maxValue = (short)((relatedCharId == taiwuCharId) ? CalcMaxFavorabilityToTaiwuById(charId) : 30000);
				short newFavor = (short)Math.Clamp(oriFavor + delta, -30000, maxValue);
				if (newFavor != oriFavor)
				{
					favorabilitiesOfRelatedChars.Add((relatedCharId, newFavor));
				}
			}
		}
		context.AdvanceMonthRelatedData.RelatedCharIds.Release(ref relatedCharIds);
		return (favorabilitiesOfRelatedChars.Count > 0) ? favorabilitiesOfRelatedChars : null;
	}

	public void ApplyFavorabilitiesOfRelatedCharsWhenChangingHobby(DataContext context, int charId, List<(int charId, short favorability)> relatedChars)
	{
		int i = 0;
		for (int count = relatedChars.Count; i < count; i++)
		{
			var (relatedCharId, favorability) = relatedChars[i];
			if (IsCharacterAlive(relatedCharId))
			{
				RelationKey relationKey = new RelationKey(charId, relatedCharId);
				RelatedCharacter relation = _relations[relationKey];
				relation.Favorability = favorability;
				SetElement_Relations(relationKey, relation, context);
			}
		}
	}

