	public void TransferFixedCharacterFavorability(DataContext context, int oldTaiwuCharId, int newTaiwuCharId)
	{
		List<int> fixedCharList = ObjectPool<List<int>>.Instance.Get();
		fixedCharList.Clear();
		fixedCharList.AddRange(_fixedCharactersCache.Values);
		foreach (int charId in fixedCharList)
		{
			Character character = _objects[charId];
			short templateId = character.GetTemplateId();
			short num = templateId;
			short num2 = num;
			if (num2 == 831 || num2 == 833)
			{
				short favorability = GetFavorability(charId, oldTaiwuCharId);
				DirectlySetFavorabilities(context, charId, newTaiwuCharId, favorability, favorability);
			}
		}
		ObjectPool<List<int>>.Instance.Return(fixedCharList);
	}

	public void GetPotentialRelatedCharactersInSet(PotentialRelatedCharacters canStartRelationChars, PotentialRelatedCharacters canEndRelationChars, List<Character> needToCreateRelations, Character character, HashSet<int> blockCharSet)
	{
		canStartRelationChars.OfflineClear();
		canEndRelationChars.OfflineClear();
		int charId = character.GetId();
		short charAge = character.GetCurrAge();
		sbyte charAgeGroup = AgeGroup.GetAgeGroup(charAge);
		bool charIsMarried = GetAliveSpouse(charId) >= 0 || !character.GetOrganizationInfo().Principal;
		bool charCanMarry = character.OrgAndMonkTypeAllowMarriage();
		sbyte selfBehaviorType = character.GetBehaviorType();
		sbyte selfOrgTemplateId = character.GetOrganizationInfo().OrgTemplateId;
		foreach (int blockCharId in blockCharSet)
		{
			if (charId == blockCharId)
			{
				continue;
			}
			if (!TryGetRelation(charId, blockCharId, out var selfToTarget))
			{
				needToCreateRelations.Add(DomainManager.Character.GetElement_Objects(blockCharId));
			}
			else
			{
				if (!TryGetRelation(blockCharId, charId, out var targetToSelf))
				{
					continue;
				}
				Character blockChar = DomainManager.Character.GetElement_Objects(blockCharId);
				sbyte targetBehaviorType = blockChar.GetBehaviorType();
				short targetAge = blockChar.GetCurrAge();
				sbyte blockCharAgeGroup = AgeGroup.GetAgeGroup(targetAge);
				if (blockCharAgeGroup == 0 || blockChar.GetLegendaryBookOwnerState() > 1)
				{
					continue;
				}
				if (AiHelper.Relation.CanStartRelation_Enemy(selfToTarget, selfBehaviorType))
				{
					canStartRelationChars.Enemies.Add(blockCharId);
				}
				else if (AiHelper.Relation.CanEndRelation_Enemy(selfToTarget, selfBehaviorType))
				{
					canEndRelationChars.Enemies.Add(blockCharId);
				}
				if (AiHelper.Relation.CanStartRelation_Friend(selfToTarget, selfBehaviorType, targetToSelf, targetBehaviorType))
				{
					canStartRelationChars.Friends.Add(blockCharId);
				}
				else if (AiHelper.Relation.CanEndRelation_Friend(selfToTarget, selfBehaviorType))
				{
					canEndRelationChars.Friends.Add(blockCharId);
				}
				if (AiHelper.Relation.CanStartRelation_SwornBrotherOrSister(selfToTarget, selfBehaviorType, targetToSelf, targetBehaviorType))
				{
					canStartRelationChars.SwornBrothersAndSisters.Add(blockCharId);
				}
				else if (AiHelper.Relation.CanEndRelation_SwornBrotherOrSister(selfToTarget, selfBehaviorType))
				{
					canEndRelationChars.SwornBrothersAndSisters.Add(blockCharId);
				}
				if (AiHelper.Relation.CanStartRelation_AdoptiveParent(charId, selfToTarget, charAge, blockCharId, targetToSelf, targetAge))
				{
					canStartRelationChars.AdoptiveParents.Add(blockCharId);
				}
				else if (AiHelper.Relation.CanStartRelation_AdoptiveChild(charId, selfToTarget, charAge, blockCharId, targetToSelf, targetAge))
				{
					canStartRelationChars.AdoptiveChildren.Add(blockCharId);
				}
				if (charAgeGroup != 2 || blockCharAgeGroup != 2)
				{
					continue;
				}
				if (!RelationType.HasRelation(selfToTarget.RelationType, 1024))
				{
					if (AiHelper.Relation.CanStartRelation_Adored(selfToTarget, selfBehaviorType))
					{
						canStartRelationChars.Adored.Add(blockCharId);
					}
					else if (AiHelper.Relation.CanStartRelation_BoyOrGirlFriend(selfToTarget, selfBehaviorType, targetToSelf, targetBehaviorType))
					{
						canStartRelationChars.BoyAndGirlFriends.Add(blockCharId);
					}
				}
				if (AiHelper.Relation.CanEndRelation_BoyOrGirlFriend(selfToTarget, selfBehaviorType, targetToSelf, targetBehaviorType))
				{
					canEndRelationChars.BoyAndGirlFriends.Add(blockCharId);
					continue;
				}
				if (AiHelper.Relation.CanEndRelation_HusbandOrWife(selfToTarget, selfBehaviorType))
				{
					canEndRelationChars.HusbandsAndWives.Add(blockCharId);
					continue;
				}
				OrganizationInfo blockCharOrgInfo = blockChar.GetOrganizationInfo();
				switch (blockCharOrgInfo.OrgTemplateId)
				{
				case 0:
					if (selfOrgTemplateId != 0)
					{
						continue;
					}
					break;
				case 16:
					if (selfOrgTemplateId != 16)
					{
						continue;
					}
					break;
				default:
					if ((selfOrgTemplateId == 0 || selfOrgTemplateId == 16) ? true : false)
					{
						continue;
					}
					break;
				}
				bool blockCharIsMarried = GetAliveSpouse(blockCharId) >= 0 || !blockCharOrgInfo.Principal;
				bool blockCharCanMarry = blockChar.OrgAndMonkTypeAllowMarriage();
				if (charCanMarry && blockCharCanMarry && !charIsMarried && !blockCharIsMarried && AiHelper.Relation.CanStartRelation_HusbandOrWife(charId, selfToTarget, selfBehaviorType, blockCharId, targetToSelf, targetBehaviorType))
				{
					canStartRelationChars.HusbandsAndWives.Add(blockCharId);
				}
			}
		}
	}

