	[DomainMethod]
	public RelatedCharactersForRelations GetRelatedCharactersForRelations(int charId)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && character.GetSrcCharId() >= 0)
		{
			charId = character.GetSrcCharId();
		}
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return new RelatedCharactersForRelations();
		}
		RelatedCharactersForRelations collection = new RelatedCharactersForRelations(relatedChars);
		collection.RelatedAdored = GetReversedRelatedCharIds(charId, 16384);
		collection.RelatedEnemies = GetReversedRelatedCharIds(charId, 32768);
		if (character != null && character.GetFactionId() >= 0)
		{
			collection.FactionMembers.AddRange(DomainManager.Organization.GetElement_Factions(collection.FactionLeaderId = character.GetFactionId()).GetCollection());
		}
		else
		{
			collection.FactionLeaderId = -1;
		}
		return collection;
	}

	[DomainMethod]
	public void TryCreateRelation(DataContext context, int charId, int relatedCharId)
	{
		if (charId == relatedCharId)
		{
			throw new Exception($"Cannot create relationship with oneself: {relatedCharId}");
		}
		bool charIsTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		bool relatedCharIsTaiwu = relatedCharId == DomainManager.Taiwu.GetTaiwuCharId();
		if (_relations.ContainsKey(new RelationKey(charId, relatedCharId)))
		{
			if (charIsTaiwu || relatedCharIsTaiwu)
			{
				GetAlertnessData(context, charIsTaiwu ? relatedCharId : charId, init: true);
			}
			return;
		}
		Character character = _objects[charId];
		Character relatedChar = _objects[relatedCharId];
		if (character.GetCreatingType() != 1 || relatedChar.GetCreatingType() != 1)
		{
			throw new Exception($"Both sides must be intelligent characters: {charId}, {relatedCharId}");
		}
		var (favor, relatedFavor) = CalcInitialFavorabilitiesOfAliveChars(context.Random, character, relatedChar);
		CreateRelation(context, charId, relatedCharId, 0, favor);
		CreateRelation(context, relatedCharId, charId, 0, relatedFavor);
		if (charIsTaiwu || relatedCharIsTaiwu)
		{
			DomainManager.Taiwu.AddLegacyPoint(context, 0);
			GetAlertnessData(context, charIsTaiwu ? relatedCharId : charId, init: true);
		}
	}

	[DomainMethod]
	public void TryAddAndApplyOneWayRelation(DataContext context, int charId, int relatedCharId, ushort relationType)
	{
		if (!RelationType.IsOneWayRelation(relationType))
		{
			throw new Exception("Cannot add two way relation directly.");
		}
		if (HasRelation(charId, relatedCharId, relationType))
		{
			return;
		}
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		Location selfCharLocation = GetElement_Objects(charId).GetValidLocation();
		Location targetCharLocation = GetElement_Objects(relatedCharId).GetValidLocation();
		DomainManager.Character.AddRelation(context, charId, relatedCharId, relationType, currDate);
		switch (relationType)
		{
		case 16384:
			DomainManager.LifeRecord.GetLifeRecordCollection().AddAdore(charId, currDate, relatedCharId, selfCharLocation);
			if (DomainManager.Character.HasRelation(relatedCharId, charId, relationType))
			{
				Character selfChar = GetElement_Objects(charId);
				Character targetChar = GetElement_Objects(relatedCharId);
				DomainManager.Character.ChangeFavorabilityOptional(context, selfChar, targetChar, 3000, 3);
				DomainManager.Character.ChangeFavorabilityOptional(context, targetChar, selfChar, 3000, 3);
				selfChar.ChangeHappiness(context, AiHelper.RelationsRelatedConstants.ConfessLoveSucceedHappinessChange[selfChar.GetBehaviorType()]);
				SecretInformationCollection secretInformationCollection2 = DomainManager.Information.GetSecretInformationCollection();
				int secretInfoOffset2 = secretInformationCollection2.AddBecomeLover(charId, relatedCharId);
				SecretInformationId secretInfoId2 = DomainManager.Information.AddSecretInformation(context, secretInfoOffset2);
				if (IsTaiwuPeople(charId))
				{
					DomainManager.Information.ReceiveSecretInformation(context, secretInfoId2, taiwuId, charId);
				}
			}
			break;
		case 32768:
		{
			DomainManager.LifeRecord.GetLifeRecordCollection().AddMakeEnemy(charId, currDate, relatedCharId, selfCharLocation);
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = secretInformationCollection.AddBecomeEnemy(charId, relatedCharId);
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(context, secretInfoOffset);
			if (IsTaiwuPeople(charId))
			{
				DomainManager.Information.ReceiveSecretInformation(context, secretInfoId, taiwuId, charId);
			}
			break;
		}
		}
		if (charId == taiwuId && targetCharLocation != Location.Invalid)
		{
			MapBlockData blockData = DomainManager.Map.GetBlock(targetCharLocation);
			DomainManager.Map.SetBlockData(context, blockData);
		}
		else if (relatedCharId == taiwuId && selfCharLocation != Location.Invalid)
		{
			MapBlockData blockData2 = DomainManager.Map.GetBlock(selfCharLocation);
			DomainManager.Map.SetBlockData(context, blockData2);
		}
	}

