	public void AddRelation(DataContext context, int charId, int relatedCharId, ushort addingType, int establishmentDate = int.MinValue)
	{
		if (charId == relatedCharId)
		{
			throw new Exception($"Cannot create relationship with oneself: {charId}");
		}
		AddRelationInternal(context, charId, relatedCharId, addingType, establishmentDate);
		ushort oppositeAddingType = RelationType.GetOppositeRelationType(addingType);
		AddRelationInternal(context, relatedCharId, charId, oppositeAddingType, establishmentDate);
	}

	public void ChangeRelationType(DataContext context, int charId, int relatedCharId, ushort removingType, ushort addingType)
	{
		RelationKey relationKey = new RelationKey(charId, relatedCharId);
		RelatedCharacter relation = _relations[relationKey];
		ushort relationType = RelatedCharIds_ChangeRelation(charId, relatedCharId, relation.RelationType, removingType, addingType);
		AddRemovedSpecialRelations(context, relationKey, removingType);
		Events.RaiseRelationAdded(context, charId, relatedCharId, relationType);
		relation.RelationType = relationType;
		SetElement_Relations(relationKey, relation, context);
	}

	public void RemoveRelation(DataContext context, int charId, int relatedCharId)
	{
		RelationKey key = new RelationKey(charId, relatedCharId);
		if (_relations.TryGetValue(key, out var relation))
		{
			RelatedCharIds_RemoveRelations(charId, relatedCharId, relation.RelationType);
			ClearRemovedSpecialRelations(context, key);
			RemoveElement_Relations(key, context);
		}
	}

	public void RemoveAllGeneralRelations(DataContext context, int charId)
	{
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return;
		}
		CharacterSet general = relatedChars.General;
		foreach (int relatedCharId in general.GetCollection())
		{
			RelationKey key = new RelationKey(charId, relatedCharId);
			RemoveElement_Relations(key, context);
			ClearRemovedSpecialRelations(context, key);
			RelationKey reverseKey = new RelationKey(relatedCharId, charId);
			if (_relations.TryGetValue(reverseKey, out var reverseRelation) && reverseRelation.RelationType == 0)
			{
				RemoveElement_Relations(reverseKey, context);
				ClearRemovedSpecialRelations(context, reverseKey);
				RelatedCharIds_RemoveRelations(relatedCharId, charId, 0);
			}
		}
		general.Clear();
	}

	public void RemoveAllRelations(DataContext context, int charId, bool removeRelatedRelations)
	{
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return;
		}
		_relatedCharIds.Remove(charId);
		HashSet<int> relatedCharIds = new HashSet<int>();
		relatedChars.GetAllRelatedCharIds(relatedCharIds);
		relatedChars.OfflineClear();
		foreach (int relatedCharId in relatedCharIds)
		{
			RelationKey key = new RelationKey(charId, relatedCharId);
			RemoveElement_Relations(key, context);
			ClearRemovedSpecialRelations(context, key);
		}
		if (!removeRelatedRelations)
		{
			return;
		}
		foreach (int relatedCharId2 in relatedCharIds)
		{
			RemoveRelation(context, relatedCharId2, charId);
		}
	}

	public bool HasTwoWayRelation(int charId, ushort relationType)
	{
		Tester.Assert(RelationType.IsOneWayRelation(relationType));
		HashSet<int> relatedCharIds = GetRelatedCharIds(charId, relationType);
		if (relatedCharIds.Count <= 0)
		{
			return false;
		}
		foreach (int relatedCharId in relatedCharIds)
		{
			HashSet<int> currRelatedCharIds = GetRelatedCharIds(relatedCharId, relationType);
			if (currRelatedCharIds.Contains(charId))
			{
				return true;
			}
		}
		return false;
	}

	public bool HasEnemyRelationWithFamily(int charId, int relatedCharId)
	{
		HashSet<int> enemies = GetRelatedCharIds(charId, 32768);
		if (enemies.Contains(relatedCharId))
		{
			return true;
		}
		foreach (int enemyId in enemies)
		{
			if (!TryGetRelation(enemyId, relatedCharId, out var enemyToTarget) || !RelationType.ContainBloodRelatedRelations(enemyToTarget.RelationType))
			{
				continue;
			}
			return true;
		}
		return false;
	}

	public bool IsInsect(int charId, int relatedCharId)
	{
		sbyte generationCount = GlobalConfig.Instance.InsectDetectionGenerationCount;
		HashSet<int> charAncestorSet = ObjectPool<HashSet<int>>.Instance.Get();
		charAncestorSet.Clear();
		GetAncestors(charId, charAncestorSet, generationCount);
		HashSet<int> relatedCharAncestorSet = ObjectPool<HashSet<int>>.Instance.Get();
		relatedCharAncestorSet.Clear();
		GetAncestors(relatedCharId, relatedCharAncestorSet, generationCount);
		bool result = charAncestorSet.Overlaps(relatedCharAncestorSet);
		ObjectPool<HashSet<int>>.Instance.Return(charAncestorSet);
		ObjectPool<HashSet<int>>.Instance.Return(relatedCharAncestorSet);
		return result;
	}

	public unsafe void GetAncestors(int charId, HashSet<int> ancestors, int recursionCount)
	{
		ancestors.Add(charId);
		if (recursionCount <= 0)
		{
			return;
		}
		int* pActualBloodParentIds = stackalloc int[2];
		RelatedCharacters relatedChars = GetRelatedCharacters(charId);
		GetActualBloodParents(charId, relatedChars, pActualBloodParentIds);
		for (int i = 0; i < 2; i++)
		{
			int parentId = pActualBloodParentIds[i];
			if (parentId >= 0)
			{
				GetAncestors(parentId, ancestors, recursionCount - 1);
			}
		}
	}

	public bool HasNominalBloodRelation(int charId, int relatedCharId, RelatedCharacter relation)
	{
		if (relation.RelationType != ushort.MaxValue && RelationType.ContainDirectBloodRelations(relation.RelationType))
		{
			return true;
		}
		if (_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			if (HasNominalDirectBloodRelation(relatedChars.BloodParents, relatedCharId, exceptBloodParent: false))
			{
				return true;
			}
			if (HasNominalDirectBloodRelation(relatedChars.BloodBrothersAndSisters, relatedCharId, exceptBloodParent: false))
			{
				return true;
			}
			if (HasNominalDirectBloodRelation(relatedChars.BloodChildren, relatedCharId, exceptBloodParent: true))
			{
				return true;
			}
		}
		return false;
	}

	public bool HasActualBloodRelation(int charId, int relatedCharId)
	{
		HashSet<int> actualDirectBloodCharIds = new HashSet<int>();
		if (HasActualDirectBloodRelation(charId, relatedCharId, exceptBloodParent: false, actualDirectBloodCharIds))
		{
			return true;
		}
		RelatedCharacters relatedChars = GetRelatedCharacters(charId);
		foreach (int actualDirectBloodCharId in actualDirectBloodCharIds)
		{
			bool exceptParent = IsActualBloodChildren(charId, relatedChars, actualDirectBloodCharId);
			if (HasActualDirectBloodRelation(actualDirectBloodCharId, relatedCharId, exceptParent))
			{
				return true;
			}
		}
		return false;
	}

