	public unsafe bool IsClosePeople(IRandomSource random, Character selfChar, Character targetChar)
	{
		if (selfChar.GetId() == targetChar.GetId())
		{
			return true;
		}
		if (selfChar.GetLeaderId() >= 0 && selfChar.GetLeaderId() == targetChar.GetLeaderId())
		{
			return true;
		}
		Personalities personalities = targetChar.GetPersonalities();
		Location selfLocation = selfChar.GetLocation();
		Location targetLocation = targetChar.GetLocation();
		if (selfLocation.IsValid() && targetLocation.IsValid())
		{
			if (selfLocation.Equals(targetLocation))
			{
				return random.CheckPercentProb(30 + personalities.Items[2]);
			}
			MapBlockData selfBlock = DomainManager.Map.GetBlock(selfLocation);
			MapBlockData targetBlock = DomainManager.Map.GetBlock(targetLocation);
			if (selfBlock.GetBlockPos().GetManhattanDistance(targetBlock.GetBlockPos()) < 1)
			{
				random.CheckPercentProb(15 + personalities.Items[2] / 2);
			}
		}
		return false;
	}

