	private void AddRemovedSpecialRelations(DataContext context, RelationKey relationKey, ushort relationType)
	{
		if (RelationType.NeedRecordOnRemoval(relationType))
		{
			if (_removedSpecialRelations.TryGetValue(relationKey, out var prevType))
			{
				relationType |= prevType;
				SetElement_RemovedSpecialRelations(relationKey, relationType, context);
			}
			else
			{
				AddElement_RemovedSpecialRelations(relationKey, relationType, context);
			}
		}
	}

	public ushort GetRemovedSpecialRelations(RelationKey relationKey)
	{
		return _removedSpecialRelations.GetValueOrDefault<RelationKey, ushort>(relationKey, 0);
	}

	private void ClearRemovedSpecialRelations(DataContext context, RelationKey relationKey)
	{
		if (_removedSpecialRelations.ContainsKey(relationKey))
		{
			RemoveElement_RemovedSpecialRelations(relationKey, context);
		}
	}

	private void InitializeRelations()
	{
		_relatedCharIds = new Dictionary<int, RelatedCharacters>();
		foreach (var (key, relation) in _relations)
		{
			RelatedCharIds_AddRelations(key.CharId, key.RelatedCharId, relation.RelationType);
		}
	}

	private ushort RelatedCharIds_AddRelation(int charId, int relatedCharId, ushort oriTypes, ushort addingType)
	{
		Tester.Assert(addingType != 0);
		RelatedCharacters relatedChars = _relatedCharIds[charId];
		ushort currTypes = RelationTypeHelper.AddRelation(relatedChars, relatedCharId, oriTypes, addingType);
		if (oriTypes == 0 && currTypes != 0)
		{
			relatedChars.General.Remove(relatedCharId);
		}
		return currTypes;
	}

	private ushort RelatedCharIds_ChangeRelation(int charId, int relatedCharId, ushort oriTypes, ushort removingType, ushort addingType)
	{
		RelatedCharacters relatedChars = _relatedCharIds[charId];
		ushort currTypes = oriTypes;
		if (removingType != 0)
		{
			relatedChars.Remove(relatedCharId, removingType);
			currTypes &= (ushort)(~removingType);
		}
		if (addingType != 0)
		{
			currTypes = RelationTypeHelper.AddRelation(relatedChars, relatedCharId, currTypes, addingType);
		}
		if (oriTypes == 0 && currTypes != 0)
		{
			relatedChars.General.Remove(relatedCharId);
		}
		else if (oriTypes != 0 && currTypes == 0)
		{
			relatedChars.General.Add(relatedCharId);
		}
		return currTypes;
	}

	private void RelatedCharIds_AddRelations(int charId, int relatedCharId, ushort relationTypes)
	{
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			relatedChars = new RelatedCharacters();
			_relatedCharIds.Add(charId, relatedChars);
		}
		if (relationTypes == 0)
		{
			relatedChars.General.Add(relatedCharId);
			return;
		}
		for (int i = 0; i < 17; i++)
		{
			ushort currType = (ushort)(1 << i);
			if ((relationTypes & currType) != 0)
			{
				relatedChars.Add(relatedCharId, currType);
			}
		}
	}

	private void RelatedCharIds_RemoveRelations(int charId, int relatedCharId, ushort relationTypes)
	{
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return;
		}
		if (relationTypes == 0)
		{
			relatedChars.General.Remove(relatedCharId);
			return;
		}
		for (int i = 0; i < 17; i++)
		{
			ushort currType = (ushort)(1 << i);
			if ((relationTypes & currType) != 0)
			{
				relatedChars.Remove(relatedCharId, currType);
			}
		}
	}

	private void AddRelationInternal(DataContext context, int charId, int relatedCharId, ushort addingType, int establishmentDate)
	{
		RelationKey relationKey = new RelationKey(charId, relatedCharId);
		if (_relations.TryGetValue(relationKey, out var relation))
		{
			if (addingType != 0)
			{
				ushort relationType = RelatedCharIds_AddRelation(charId, relatedCharId, relation.RelationType, addingType);
				relation.RelationType = relationType;
				SetElement_Relations(relationKey, relation, context);
				Events.RaiseRelationAdded(context, charId, relatedCharId, addingType);
			}
		}
		else
		{
			short initialFavorability = (IsAnyCharacterCreating() ? GetInitialFabricatedFavorability(context.Random, charId, addingType) : CalcInitialFavorability(context.Random, charId, relatedCharId));
			CreateRelation(context, charId, relatedCharId, addingType, initialFavorability, establishmentDate);
			Events.RaiseRelationAdded(context, charId, relatedCharId, addingType);
		}
	}

	private RelatedCharacter CreateRelation(DataContext context, int charId, int relatedCharId, ushort relationType, short initialFavorability, int establishmentDate = int.MinValue)
	{
		RelationKey key = new RelationKey(charId, relatedCharId);
		RelatedCharacter relation = new RelatedCharacter(relationType, initialFavorability, (establishmentDate == int.MinValue) ? DomainManager.World.GetCurrDate() : establishmentDate);
		AddElement_Relations(key, relation, context);
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			relatedChars = new RelatedCharacters();
			_relatedCharIds.Add(charId, relatedChars);
		}
		relatedChars.Add(relatedCharId, relationType);
		return relation;
	}

	internal short CalcInitialFavorability(IRandomSource random, int charId, int relatedCharId)
	{
		bool notIntelligentCharacter = true;
		sbyte selfBehaviorType;
		OrganizationMemberItem selfOrgMemberCfg;
		DeadCharacter deadChar;
		if (_objects.TryGetValue(charId, out var character))
		{
			notIntelligentCharacter = character.IsFavorabilityGainFixed;
			selfBehaviorType = character.GetBehaviorType();
			selfOrgMemberCfg = OrganizationDomain.GetOrgMemberConfig(character.GetOrganizationInfo());
		}
		else if (_deadCharacters.TryGetValue(charId, out deadChar))
		{
			selfBehaviorType = BehaviorType.GetBehaviorType(deadChar.Morality);
			selfOrgMemberCfg = OrganizationDomain.GetOrgMemberConfig(deadChar.OrganizationInfo);
		}
		else
		{
			selfBehaviorType = -1;
			selfOrgMemberCfg = OrganizationMember.Instance[(short)0];
		}
		Character relatedChar;
		DeadCharacter deadChar2;
		(short, sbyte, sbyte, short, sbyte, sbyte, OrganizationMemberItem) targetData = (_objects.TryGetValue(relatedCharId, out relatedChar) ? GetInitialFavorabilityRelatedDataOfAliveChar(relatedChar, character) : ((!_deadCharacters.TryGetValue(charId, out deadChar2)) ? GetDefaultInitialFavorabilityRelatedData() : GetInitialFavorabilityRelatedDataOfDeadChar(deadChar2)));
		bool relatedCharIsTaiwu = relatedCharId == DomainManager.Taiwu.GetTaiwuCharId();
		bool selfCharIsTaiwu = charId == DomainManager.Taiwu.GetTaiwuCharId();
		bool hasTaiwu = relatedCharIsTaiwu || selfCharIsTaiwu;
		int initialFavor = CalcInitialFavorability(selfOrgMemberCfg, targetData.Item1, targetData.Item2, targetData.Item3, targetData.Item4, selfBehaviorType, targetData.Item5, hasTaiwu, notIntelligentCharacter);
		if (relatedCharIsTaiwu)
		{
			short percent = GetWorldFavorabilityPercent(notIntelligentCharacter);
			if (selfOrgMemberCfg.Organization == 16)
			{
				initialFavor += 9000 * percent / 100;
			}
			short taiwuSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
			int buildingEffect = DomainManager.Building.GetBuildingBlockEffect(taiwuSettlementId, EBuildingScaleEffect.InitialFavorability);
			initialFavor += buildingEffect * percent / 100;
		}
		return (short)Math.Clamp(initialFavor, -30000, 30000);
	}

	private static (short favor, short relatedFavor) CalcInitialFavorabilitiesOfAliveChars(IRandomSource random, Character character, Character relatedChar)
	{
		(short, sbyte, sbyte, short, sbyte, sbyte, OrganizationMemberItem) selfData = GetInitialFavorabilityRelatedDataOfAliveChar(character, relatedChar);
		(short, sbyte, sbyte, short, sbyte, sbyte, OrganizationMemberItem) relatedData = GetInitialFavorabilityRelatedDataOfAliveChar(relatedChar, character);
		bool selfNotIntelligentCharacter = character.IsFavorabilityGainFixed;
		bool relatedNotIntelligentCharacter = relatedChar.IsFavorabilityGainFixed;
		bool relatedCharIsTaiwu = relatedChar.GetId() == DomainManager.Taiwu.GetTaiwuCharId();
		bool selfCharIsTaiwu = character.GetId() == DomainManager.Taiwu.GetTaiwuCharId();
		bool hasTaiwu = relatedCharIsTaiwu || selfCharIsTaiwu;
		int initialFavor = CalcInitialFavorability(selfData.Item7, relatedData.Item1, relatedData.Item2, relatedData.Item3, relatedData.Item4, selfData.Item5, relatedData.Item5, hasTaiwu, selfNotIntelligentCharacter);
		if (relatedCharIsTaiwu)
		{
			initialFavor = TaiwuRelatedFavorAdd(initialFavor, character);
		}
		short favor = (short)Math.Clamp(initialFavor, -30000, 30000);
		int relatedInitialFavor = CalcInitialFavorability(relatedData.Item7, selfData.Item1, selfData.Item2, selfData.Item3, selfData.Item4, relatedData.Item5, selfData.Item5, hasTaiwu, relatedNotIntelligentCharacter);
		if (selfCharIsTaiwu)
		{
			relatedInitialFavor = TaiwuRelatedFavorAdd(relatedInitialFavor, relatedChar);
		}
		short relatedFavor = (short)Math.Clamp(relatedInitialFavor, -30000, 30000);
		return (favor: favor, relatedFavor: relatedFavor);
		static int TaiwuRelatedFavorAdd(int initFavor, Character otherCharacter)
		{
			bool notIntelligentCharacter = otherCharacter.IsFavorabilityGainFixed;
			short percent = GetWorldFavorabilityPercent(notIntelligentCharacter);
			OrganizationInfo charOrgInfo = otherCharacter.GetOrganizationInfo();
			OrganizationItem orgCfg = Config.Organization.Instance[charOrgInfo.OrgTemplateId];
			if (otherCharacter.GetOrganizationInfo().OrgTemplateId == 16)
			{
				initFavor += 9000 * percent / 100;
			}
			short settlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
			int buildingEffect = DomainManager.Building.GetBuildingBlockEffect(settlementId, EBuildingScaleEffect.InitialFavorability);
			initFavor += buildingEffect * percent / 100;
			if (DomainManager.Extra.MartialArtistSkill0Useful(orgCfg) || DomainManager.Extra.CivilianSkill0Useful(orgCfg))
			{
				initFavor += initFavor * GlobalConfig.Instance.ProfessionInitialFavorabilitiesImprovePercent / 100;
			}
			return initFavor;
		}
	}

