		ItemKey clothingKey = character.GetEquipment()[4];
		short clothingTemplateId = (short)((clothingKey.IsValid() && !DomainManager.Item.GetBaseItem(clothingKey).IsDurabilityRunningOut()) ? clothingKey.TemplateId : (-1));
		return (attraction: character.GetAttraction(), fameType: FameType.GetFameType(character.GetFame()), gender: character.GetDisplayingGender(), clothingTemplateId: clothingTemplateId, behaviorType: character.GetBehaviorType(), interactionGrade: character.GetInteractionGrade(relatedChar), orgMemberCfg: OrganizationDomain.GetOrgMemberConfig(character.GetOrganizationInfo()));
	}

