	private static int CalcInitialFavorability(OrganizationMemberItem selfOrgMemberCfg, short relatedAttraction, sbyte relatedFameType, sbyte relatedGender, short relatedClothingTemplateId, sbyte selfBehaviorType, sbyte relatedBehaviorType, bool hasTaiwu, bool selfIsNotIntelligentCharacter)
	{
		int factor = 100;
		factor += relatedAttraction / 3;
		factor += (relatedFameType - 3) * 60;
		if (relatedGender == 0)
		{
			factor += 20;
		}
		if (selfOrgMemberCfg.FavoriteClothingIds.Contains(relatedClothingTemplateId))
		{
			factor += 20;
			if (selfOrgMemberCfg.Organization == 13)
			{
				factor += 20;
			}
		}
		else if (selfOrgMemberCfg.HatedClothingIds.Contains(relatedClothingTemplateId))
		{
			factor -= 20;
		}
		if (selfBehaviorType >= 0 && relatedBehaviorType >= 0)
		{
			if (BehaviorType.IsHarmonious(selfBehaviorType, relatedBehaviorType))
			{
				factor += 60;
			}
			else if (BehaviorType.IsConflicting(selfBehaviorType, relatedBehaviorType))
			{
				factor -= 60;
			}
		}
		if (hasTaiwu)
		{
			short percent = GetWorldFavorabilityPercent(selfIsNotIntelligentCharacter);
			int change = factor - 100;
			change = change * percent / 100;
			factor = 100 + change;
		}
		int initValue = (hasTaiwu ? GlobalConfig.Instance.TaiwuBaseInitialFavorabilityValue : GlobalConfig.Instance.NpcBaseInitialFavorabilityValue);
		return initValue * factor / 100;
	}

	private short GetInitialFabricatedFavorability(IRandomSource random, int charId, ushort relationType)
	{
		if (relationType == 0)
		{
			return 0;
		}
		short morality;
		sbyte orgTemplateId;
		if (_objects.TryGetValue(charId, out var character))
		{
			morality = character.GetMorality();
			orgTemplateId = character.GetOrganizationInfo().OrgTemplateId;
		}
		else
		{
			if (!_deadCharacters.TryGetValue(charId, out var deadChar))
			{
				return 0;
			}
			morality = deadChar.Morality;
			orgTemplateId = deadChar.OrganizationInfo.OrgTemplateId;
		}
		(short[] settings, int offset) initialFabricatedFavorabilitySettings = GetInitialFabricatedFavorabilitySettings(orgTemplateId, relationType);
		short[] settings = initialFabricatedFavorabilitySettings.settings;
		int offset = initialFabricatedFavorabilitySettings.offset;
		sbyte behaviorType = BehaviorType.GetBehaviorType(morality);
		short mean = settings[offset + behaviorType];
		short min = settings[offset + 5];
		short max = settings[offset + 5 + 1];
		float stdDev = (float)(max - min) / 7f;
		return (short)RedzenHelper.NormalDistribute(random, mean, stdDev, min, max);
	}

	private static (short[] settings, int offset) GetInitialFabricatedFavorabilitySettings(sbyte orgTemplateId, ushort relationType)
	{
		if (relationType == 2048 || relationType == 4096)
		{
			sbyte largeSectIndex = OrganizationDomain.GetLargeSectIndex(orgTemplateId);
			if (largeSectIndex >= 0)
			{
				return (settings: InitialMentorFabricatedFavorOfSects, offset: largeSectIndex * 7);
			}
		}
		sbyte relationTypeId = RelationType.GetTypeId(relationType);
		return (settings: InitialFabricatedFavorOfRelationTypes, offset: relationTypeId * 7);
	}

	private bool HasNominalDirectBloodRelation(CharacterSet characterSet, int relatedCharId, bool exceptBloodParent)
	{
		HashSet<int> charIds = characterSet.GetCollection();
		if (charIds.Count <= 0)
		{
			return false;
		}
		foreach (int charId in charIds)
		{
			if (!_relations.TryGetValue(new RelationKey(charId, relatedCharId), out var relation) || !RelationType.ContainDirectBloodRelations(relation.RelationType) || (exceptBloodParent && (relation.RelationType & 1) != 0))
			{
				continue;
			}
			return true;
		}
		return false;
	}

	private unsafe bool HasActualDirectBloodRelation(int charId, int relatedCharId, bool exceptBloodParent, HashSet<int> actualDirectBloodCharIds = null)
	{
		_relatedCharIds.TryGetValue(charId, out var relatedChars);
		int* pActualBloodParentIds = stackalloc int[2];
		GetActualBloodParents(charId, relatedChars, pActualBloodParentIds);
		for (int i = 0; i < 2; i++)
		{
			int actualBloodParentId = pActualBloodParentIds[i];
			if (actualBloodParentId >= 0)
			{
				if (actualBloodParentId == relatedCharId && !exceptBloodParent)
				{
					return true;
				}
				actualDirectBloodCharIds?.Add(actualBloodParentId);
			}
		}
		for (int j = 0; j < 2; j++)
		{
			int actualBloodParentId2 = pActualBloodParentIds[j];
			if (actualBloodParentId2 >= 0)
			{
				_relatedCharIds.TryGetValue(actualBloodParentId2, out var currRelatedChars);
				if (IsActualBloodChildren(actualBloodParentId2, currRelatedChars, relatedCharId, actualDirectBloodCharIds))
				{
					return true;
				}
			}
		}
		actualDirectBloodCharIds?.Remove(charId);
		if (IsActualBloodChildren(charId, relatedChars, relatedCharId, actualDirectBloodCharIds))
		{
			return true;
		}
		return false;
	}

	private unsafe void GetActualBloodParents(int charId, RelatedCharacters relatedChars, int* pActualBloodParentIds)
	{
		int* pNominalBloodParentIds = stackalloc int[2] { -2, -1 };
		if (relatedChars != null)
		{
			HashSet<int> bloodParentIds = relatedChars.BloodParents.GetCollection();
			foreach (int bloodParentId in bloodParentIds)
			{
				sbyte gender = GetAliveOrDeadCharacterGender(bloodParentId);
				if (gender != -1)
				{
					pNominalBloodParentIds[gender] = bloodParentId;
				}
				else if (*pNominalBloodParentIds < 0)
				{
					*pNominalBloodParentIds = bloodParentId;
				}
				else
				{
					pNominalBloodParentIds[1] = bloodParentId;
				}
			}
		}
		for (int i = 0; i < 2; i++)
		{
			int nominalBloodParentId = pNominalBloodParentIds[i];
			pActualBloodParentIds[i] = (TryGetActualBloodParent(nominalBloodParentId, charId, out var actualParentId) ? actualParentId : nominalBloodParentId);
		}
	}

	private bool IsActualBloodChildren(int charId, RelatedCharacters relatedChars, int relatedCharId, HashSet<int> actualDirectBloodCharIds = null)
	{
		if (relatedChars != null)
		{
			HashSet<int> bloodChildIds = relatedChars.BloodChildren.GetCollection();
			foreach (int bloodChildId in bloodChildIds)
			{
				if (!TryGetActualBloodParent(charId, bloodChildId, out var _))
				{
					if (bloodChildId == relatedCharId)
					{
						return true;
					}
					actualDirectBloodCharIds?.Add(bloodChildId);
				}
			}
		}
		List<ParentAndChild> nominalRelations = GetNominalBloodParentRelations(charId);
		if (nominalRelations != null)
		{
			int i = 0;
			for (int count = nominalRelations.Count; i < count; i++)
			{
				int childId = nominalRelations[i].ChildId;
				if (childId == relatedCharId)
				{
					return true;
				}
				actualDirectBloodCharIds?.Add(childId);
			}
		}
		return false;
	}

	private int GetAliveRemarrySpouse(int charId, int firstSpouseCharId)
	{
		if (_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			HashSet<int> husbandOrWifeIds = relatedChars.HusbandsAndWives.GetCollection();
			foreach (int husbandOrWifeId in husbandOrWifeIds)
			{
				if (husbandOrWifeId != firstSpouseCharId && IsCharacterAlive(husbandOrWifeId))
				{
					return husbandOrWifeId;
				}
			}
		}
		return -1;
	}

	private void SetFavorability(DataContext context, int charId, int relatedCharId, short value)
	{
		value = Math.Clamp(value, (short)(-30000), (short)30000);
		RelationKey relationKey = new RelationKey(charId, relatedCharId);
		if (_relations.TryGetValue(relationKey, out var relation))
		{
			relation.Favorability = value;
			SetElement_Relations(relationKey, relation, context);
		}
		else
		{
			CreateRelation(context, charId, relatedCharId, 0, value);
		}
	}

	private int CalcItemsFavorabilityDelta(int characterId, int relatedCharId, Inventory items, short type, bool isAdd)
	{
		if (items != null && items.InventoryItemTotalCount == 0)
		{
			return 0;
		}
		Character character = GetElement_Objects(characterId);
		Character relatedChar = GetElement_Objects(relatedCharId);
		int itemFavor = 0;
		foreach (var (itemKey2, count) in items.Items)
		{
			if (ItemTemplateHelper.IsMiscResource(itemKey2.ItemType, itemKey2.TemplateId))
			{
				sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(itemKey2.ItemType, itemKey2.TemplateId);
				short favorChange = AiHelper.GeneralActionConstants.GetResourceFavorabilityChange(resourceType, count);
				itemFavor += favorChange;
			}
			else
			{
				ItemBase itemBase = DomainManager.Item.GetBaseItem(itemKey2);
				int value = count * itemBase.GetFavorabilityChange();
				itemFavor += value;
			}
		}
		if (!isAdd)
		{
			itemFavor = -itemFavor;
		}
		return CalcFavorabilityDelta(character, relatedChar, itemFavor, type);
	}

	private int CalcItemsHappinessDelta(Inventory items, bool isAdd)
	{
		if (items != null && items.InventoryItemTotalCount == 0)
		{
			return 0;
		}
		int itemHappiness = 0;
		foreach (var (itemKey2, count) in items.Items)
		{
			if (ItemTemplateHelper.IsMiscResource(itemKey2.ItemType, itemKey2.TemplateId))
			{
				sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(itemKey2.ItemType, itemKey2.TemplateId);
				sbyte favorChange = AiHelper.GeneralActionConstants.GetResourceHappinessChange(resourceType, count);
				itemHappiness += favorChange;
			}
			else
			{
				ItemBase itemBase = DomainManager.Item.GetBaseItem(itemKey2);
				int value = count * itemBase.GetBaseHappinessChange();
				itemHappiness += value;
			}
		}
		if (!isAdd)
		{
			itemHappiness = -itemHappiness;
		}
		return Math.Clamp(itemHappiness, -238, 238);
	}

	private int CalcItemsAlertnessDelta(Inventory items, bool isReduce)
	{
		if (items != null && items.InventoryItemTotalCount == 0)
		{
			return 0;
		}
		int delta = 0;
		foreach (var (itemKey2, count) in items.Items)
		{
			if (ItemTemplateHelper.IsMiscResource(itemKey2.ItemType, itemKey2.TemplateId))
			{
				sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(itemKey2.ItemType, itemKey2.TemplateId);
				InteractAlertnessFormulaItem alertnessFormulaItem = InteractAlertnessFormula.Instance[0];
				long worth = (long)GlobalConfig.ResourcesWorth[resourceType] * (long)count;
				int clampedWorth = (int)Math.Clamp(worth, -2147483648L, 2147483647L);
				int result = -alertnessFormulaItem.Calculate(clampedWorth);
				delta += result;
			}
			else
			{
				InteractAlertnessFormulaItem alertnessFormulaItem2 = InteractAlertnessFormula.Instance[1];
				int favorabilityChange = DomainManager.Item.GetBaseItem(itemKey2).GetBaseFavorabilityChange() * count;
				int result2 = -alertnessFormulaItem2.Calculate(favorabilityChange);
				delta += result2;
			}
		}
		if (!isReduce)
		{
			delta = -delta;
		}
		return DomainManager.Character.CalcAlertnessChangeValue(delta);
	}

	[DomainMethod]
	public TransferItemPreviewDisplayData GetTransferItemPreviewDisplayData(int characterId, Inventory items, bool isGive)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int favorChange = CalcItemsFavorabilityDelta(characterId, taiwuCharId, items, 1, isGive);
		int happinessChange = CalcItemsHappinessDelta(items, isGive);
		int alertnessChange = CalcItemsAlertnessDelta(items, isGive);
		short originalFavor = DomainManager.Character.GetFavorability(characterId, taiwuCharId);
		sbyte originalHappiness = DomainManager.Character.GetElement_Objects(characterId).GetHappiness();
		int originalAlertness = DomainManager.Character.GetAlertnessValue(characterId);
		int finalAlertness = CharacterAlertnessData.ClampValue(originalAlertness + alertnessChange);
		int effectMaxFavor = CharacterAlertnessData.GetEffectMaxFavor(finalAlertness);
		short maxFavor = CharacterAlertnessData.GetMaxFavor(effectMaxFavor);
		short finalFavor = (short)Math.Clamp(originalFavor + favorChange, -30000, maxFavor);
		sbyte finalHappiness = (sbyte)Math.Clamp(originalHappiness + happinessChange, -119, 119);
		return new TransferItemPreviewDisplayData
		{
			OriginalFavor = originalFavor,
			OriginalHappiness = originalHappiness,
			OriginalAlertness = originalAlertness,
			FinalFavor = finalFavor,
			FinalHappiness = finalHappiness,
			FinalAlertness = finalAlertness
		};
	}

	public int CalcFavorabilityDelta(int characterId, int relatedCharId, int baseDelta, short type)
	{
		Character character = GetElement_Objects(characterId);
		Character relatedChar = GetElement_Objects(relatedCharId);
		return CalcFavorabilityDelta(character, relatedChar, baseDelta, type);
	}

	public static int CalcFavorabilityDelta(Character character, Character relatedChar, int baseDelta, short type)
	{
		int factor = 1000;
		if (baseDelta > 0)
		{
			if (character.GetCreatingType() == 1)
			{
				sbyte selfBehaviorType = character.GetBehaviorType();
				sbyte relatedBehaviorType = relatedChar.GetBehaviorType();
				if (selfBehaviorType == relatedBehaviorType)
				{
					factor += 400;
				}
				else if (BehaviorType.IsContradictory(selfBehaviorType, relatedBehaviorType))
				{
					factor -= 400;
				}
				short relatedSettlementId = relatedChar.GetOrganizationInfo().SettlementId;
				int buildingBonus = DomainManager.Building.GetBuildingBlockEffect(relatedSettlementId, EBuildingScaleEffect.FavorIncreaseBonus);
				factor += buildingBonus * 10;
				int gradeDiff = character.GetInteractionGrade(relatedChar) - relatedChar.GetInteractionGrade(character);
				factor = factor * FavorabilityFactorOfGradeDifferences[8 + gradeDiff] / 100;
			}
			factor = factor * character.GetFavorabilityChangingFactor().Outer / 100;
			(int, bool) favFactor = DomainManager.World.GetFavorabilityChangePercent(type, character.IsFavorabilityGainFixed);
			factor = ((factor < 0 && favFactor.Item2) ? (factor * 100 / favFactor.Item1) : (factor * favFactor.Item1 / 100));
		}
		else
		{
			if (relatedChar == DomainManager.Taiwu.GetTaiwu() && character.GetCreatingType() == 1)
			{
				OrganizationInfo selfOrgInfo = character.GetOrganizationInfo();
				if (OrganizationDomain.IsSect(selfOrgInfo.OrgTemplateId))
				{
					if (DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(12) && selfOrgInfo.InteractionGrade <= DomainManager.Extra.GetProfessionData(3).GetSeniorityOrgGrade())
					{
						factor -= 200;
					}
				}
				else if (DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(40) && selfOrgInfo.InteractionGrade <= DomainManager.Extra.GetProfessionData(10).GetSeniorityOrgGrade())
				{
					factor -= 200;
				}
			}
			short relatedSettlementId2 = relatedChar.GetOrganizationInfo().SettlementId;
			int buildingBonus2 = DomainManager.Building.GetBuildingBlockEffect(relatedSettlementId2, EBuildingScaleEffect.FavorDecreaseReduction);
			factor -= buildingBonus2 * 10;
			factor = factor * character.GetFavorabilityChangingFactor().Inner / 100;
			(int, bool) favFactor2 = DomainManager.World.GetFavorabilityChangePercent(type, character.IsFavorabilityGainFixed);
			factor = ((factor > 0 && favFactor2.Item2) ? (factor * 100 / favFactor2.Item1) : (factor * favFactor2.Item1 / 100));
		}
		int alertnessEffect = 0;
		if (relatedChar == DomainManager.Taiwu.GetTaiwu())
		{
			int alertness = DomainManager.Character.GetAlertnessValue(character.GetId());
			sbyte level = CharacterAlertnessData.GetLevel(alertness);
			alertnessEffect = CharacterAlertnessData.GetEffectChangeFavor(level);
		}
		int result = baseDelta * factor / 1000 * (100 + alertnessEffect) / 100;
		return Math.Clamp(result, -60000, 60000);
	}

	public CharacterSet GetReversedRelatedCharIds(int charId, ushort relationType)
	{
		CharacterSet relatedCharIds = default(CharacterSet);
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return relatedCharIds;
		}
		ushort oppositeRelationType = RelationType.GetOppositeRelationType(relationType);
		if (oppositeRelationType != 0)
		{
			HashSet<int> currCharIds = relatedChars.GetCharacterSet(oppositeRelationType).GetCollection();
			relatedCharIds.AddRange(currCharIds);
		}
		else
		{
			HashSet<int> currCharIds2 = ObjectPool<HashSet<int>>.Instance.Get();
			currCharIds2.Clear();
			relatedChars.GetAllRelatedCharIds(currCharIds2);
			foreach (int currCharId in currCharIds2)
			{
				if (HasRelation(currCharId, charId, relationType))
				{
					relatedCharIds.Add(currCharId);
				}
			}
			ObjectPool<HashSet<int>>.Instance.Return(currCharIds2);
		}
		return relatedCharIds;
	}

	public int GetReversedRelatedCharIdCount(int charId, ushort relationType)
	{
		if (!_relatedCharIds.TryGetValue(charId, out var relatedChars))
		{
			return 0;
		}
		ushort oppositeRelationType = RelationType.GetOppositeRelationType(relationType);
		if (oppositeRelationType != 0)
		{
			HashSet<int> currCharIds = relatedChars.GetCharacterSet(oppositeRelationType).GetCollection();
			return currCharIds.Count;
		}
		HashSet<int> currCharIds2 = ObjectPool<HashSet<int>>.Instance.Get();
		currCharIds2.Clear();
		relatedChars.GetAllRelatedCharIds(currCharIds2);
		int count = 0;
		foreach (int currCharId in currCharIds2)
		{
			if (HasRelation(currCharId, charId, relationType))
			{
				count++;
			}
		}
		ObjectPool<HashSet<int>>.Instance.Return(currCharIds2);
		return count;
	}

	private static short GetWorldFavorabilityPercent(bool notIntelligentCharacter)
	{
		byte favorabilityChange = DomainManager.World.GetFavorabilityChange();
		short type = (short)(notIntelligentCharacter ? 6 : 0);
		WorldFavorabilityItem worldFavorability = WorldFavorability.Instance[type];
		return worldFavorability.InfluenceFactors[favorabilityChange];
	}

	public void AddFavorabilityChangeInstantNotification(Character characterA, Character characterB, bool isIncrease)
	{
		int charAId = characterA.GetId();
		int charBId = characterB.GetId();
		if (DomainManager.Taiwu.GetTaiwuCharId() != charBId)
		{
			return;
		}
		InstantNotificationCollection collection = DomainManager.World.GetInstantNotificationCollection();
		short settlementId = characterA.GetOrganizationInfo().SettlementId;
		if (settlementId >= 0)
		{
			if (isIncrease)
			{
				collection.AddFavorabilityIncreased(settlementId, charAId, charBId);
			}
			else
			{
				collection.AddFavorabilityDecreased(settlementId, charAId, charBId);
			}
		}
	}

	[DomainMethod]
	public Genealogy GetGenealogy(int charId)
	{
		if (TryGetElement_Objects(charId, out var character) && character.GetSrcCharId() >= 0)
		{
			charId = character.GetSrcCharId();
		}
		Genealogy genealogy = new Genealogy
		{
			CoreCharId = charId,
			BloodFatherId = GetBloodParent(charId, 1),
			BloodMotherId = GetBloodParent(charId, 0)
		};
		if (genealogy.BloodFatherId >= 0)
		{
			genealogy.GrandfatherId = GetBloodParent(genealogy.BloodFatherId, 1);
			genealogy.GrandmotherId = GetBloodParent(genealogy.BloodFatherId, 0);
		}
		if (genealogy.BloodMotherId >= 0)
		{
			genealogy.MaternalGrandfatherId = GetBloodParent(genealogy.BloodMotherId, 1);
			genealogy.MaternalGrandmotherId = GetBloodParent(genealogy.BloodMotherId, 0);
		}
		genealogy.Parents = GetParents(charId, genealogy.BloodFatherId, genealogy.BloodMotherId);
		genealogy.BrothersAndSisters = GetBrothersAndSisters(charId);
		genealogy.Spouses = GetSpouseAndChildren(charId);
		return genealogy;
	}

	public int GetOtherBloodParent(int charId, int parentId)
	{
		HashSet<int> parentCharIds = GetRelatedCharIds(charId, 1);
		foreach (int parentCharId in parentCharIds)
		{
			if (parentCharId == parentId)
			{
				continue;
			}
			return parentCharId;
		}
		if (_objects.TryGetValue(parentId, out var parentChar))
		{
			return (parentChar.GetGender() == 0) ? (-1) : (-2);
		}
		if (_deadCharacters.TryGetValue(parentId, out var parentDeadChar))
		{
			return (parentDeadChar.Gender == 0) ? (-1) : (-2);
		}
		return -1;
	}

	public int GetBloodParent(int charId, sbyte parentGender)
	{
		HashSet<int> parentCharIds = GetRelatedCharIds(charId, 1);
		List<int> removedParents = null;
		foreach (int parentCharId in parentCharIds)
		{
			sbyte gender = GetAliveOrDeadCharacterGender(parentCharId);
			if (gender == parentGender)
			{
				return parentCharId;
			}
			if (gender == -1)
			{
				if (removedParents == null)
				{
					removedParents = new List<int>();
				}
				removedParents.Add(parentCharId);
			}
		}
		if (removedParents != null)
		{
			int index = ((parentGender != 0) ? 1 : 0);
			return (removedParents.Count > index) ? removedParents[index] : (-1);
		}
		return (parentGender == 0) ? (-2) : (-1);
	}

	private List<CharIdAndRelation> GetParents(int charId, int bloodFatherId, int bloodMotherId)
	{
		List<CharIdAndRelation> parents = new List<CharIdAndRelation>();
		if (bloodFatherId >= 0)
		{
			parents.Add(new CharIdAndRelation(bloodFatherId, 1));
		}
		if (bloodMotherId >= 0)
		{
			parents.Add(new CharIdAndRelation(bloodMotherId, 1));
		}
		foreach (int relatedCharId in GetRelatedCharIds(charId, 8))
		{
			parents.Add(new CharIdAndRelation(relatedCharId, 8));
		}
		foreach (int relatedCharId2 in GetRelatedCharIds(charId, 64))
		{
			parents.Add(new CharIdAndRelation(relatedCharId2, 64));
		}
		Sort(charId, parents);
		return parents;
	}

	private List<CharIdAndRelation> GetBrothersAndSisters(int charId)
	{
		List<CharIdAndRelation> brothersAndSisters = new List<CharIdAndRelation>
		{
			new CharIdAndRelation(charId, ushort.MaxValue)
		};
		foreach (int relatedCharId in GetRelatedCharIds(charId, 4))
		{
			brothersAndSisters.Add(new CharIdAndRelation(relatedCharId, 4));
		}
		foreach (int relatedCharId2 in GetRelatedCharIds(charId, 32))
		{
			brothersAndSisters.Add(new CharIdAndRelation(relatedCharId2, 32));
		}
		foreach (int relatedCharId3 in GetRelatedCharIds(charId, 256))
		{
			brothersAndSisters.Add(new CharIdAndRelation(relatedCharId3, 256));
		}
		Character character;
		int birthDate = (TryGetElement_Objects(charId, out character) ? character.GetBirthDate() : (TryGetDeadCharacter(charId)?.BirthDate ?? (-1)));
		Sort(charId, brothersAndSisters, birthDate);
		return brothersAndSisters;
	}

	private List<SpouseAndChildren> GetSpouseAndChildren(int charId, int depth = 0)
	{
		List<SpouseAndChildren> spouses = new List<SpouseAndChildren>();
		List<int> bloodChildIds = new List<int>(GetRelatedCharIds(charId, 2));
		List<int> stepChildIds = new List<int>(GetRelatedCharIds(charId, 16));
		List<int> adoptiveChildIds = new List<int>(GetRelatedCharIds(charId, 128));
		foreach (int spouseId in GetRelatedCharIds(charId, 1024))
		{
			SpouseAndChildren spouseAndChildren = new SpouseAndChildren
			{
				SpouseCharId = spouseId,
				Children = new List<CharIdAndRelation>(),
				BloodChildrenSpouses = new List<SpousesAndChildren>()
			};
			HashSet<int> spouseBloodChildIds = GetRelatedCharIds(spouseId, 2);
			foreach (int spouseBloodChildId in spouseBloodChildIds)
			{
				if (bloodChildIds.Contains(spouseBloodChildId))
				{
					bloodChildIds.Remove(spouseBloodChildId);
					spouseAndChildren.Children.Add(new CharIdAndRelation(spouseBloodChildId, 2));
					if (depth == 0)
					{
						List<SpouseAndChildren> childSpouses = GetSpouseAndChildren(spouseBloodChildId, depth + 1);
						spouseAndChildren.BloodChildrenSpouses.Add(new SpousesAndChildren(spouseBloodChildId, childSpouses));
					}
				}
				else if (stepChildIds.Contains(spouseBloodChildId))
				{
					stepChildIds.Remove(spouseBloodChildId);
					spouseAndChildren.Children.Add(new CharIdAndRelation(spouseBloodChildId, 16));
				}
				else
				{
					Logger.Warn($"Spouse's blood-child is neither someone's blood-child nor stepchild: ({charId}, {spouseId}) -> {spouseBloodChildId}");
				}
			}
			HashSet<int> spouseStepChildIds = GetRelatedCharIds(spouseId, 16);
			foreach (int spouseStepChildId in spouseStepChildIds)
			{
				if (stepChildIds.Contains(spouseStepChildId))
				{
					stepChildIds.Remove(spouseStepChildId);
					spouseAndChildren.Children.Add(new CharIdAndRelation(spouseStepChildId, 16));
				}
				else if (!bloodChildIds.Contains(spouseStepChildId))
				{
					Logger.Warn($"Spouse's stepchild is neither someone's blood-child nor stepchild: ({charId}, {spouseId}) -> {spouseStepChildId}");
				}
			}
			HashSet<int> spouseAdoptiveChildIds = GetRelatedCharIds(spouseId, 128);
			foreach (int spouseAdoptiveChildId in spouseAdoptiveChildIds)
			{
				if (adoptiveChildIds.Contains(spouseAdoptiveChildId))
				{
					adoptiveChildIds.Remove(spouseAdoptiveChildId);
					spouseAndChildren.Children.Add(new CharIdAndRelation(spouseAdoptiveChildId, 128));
				}
			}
			Sort(charId, spouseAndChildren.Children);
			spouses.Add(spouseAndChildren);
		}
		if (bloodChildIds.Count > 0 || stepChildIds.Count > 0 || adoptiveChildIds.Count > 0)
		{
			SpouseAndChildren spouseAndChildren2 = new SpouseAndChildren
			{
				SpouseCharId = -1,
				Children = new List<CharIdAndRelation>(),
				BloodChildrenSpouses = new List<SpousesAndChildren>()
			};
			foreach (int bloodChildId in bloodChildIds)
			{
				spouseAndChildren2.Children.Add(new CharIdAndRelation(bloodChildId, 2));
				if (depth == 0)
				{
					List<SpouseAndChildren> childSpouses2 = GetSpouseAndChildren(bloodChildId, depth + 1);
					spouseAndChildren2.BloodChildrenSpouses.Add(new SpousesAndChildren(bloodChildId, childSpouses2));
				}
			}
			foreach (int stepChildId in stepChildIds)
			{
				spouseAndChildren2.Children.Add(new CharIdAndRelation(stepChildId, 16));
			}
			foreach (int adoptiveChildId in adoptiveChildIds)
			{
				spouseAndChildren2.Children.Add(new CharIdAndRelation(adoptiveChildId, 128));
			}
			Sort(charId, spouseAndChildren2.Children);
			spouses.Add(spouseAndChildren2);
		}
		Sort(charId, spouses);
		return spouses;
	}

	private void Sort(int charId, List<CharIdAndRelation> relatedChars, int selfBirthDate = -1)
	{
		relatedChars.Sort(delegate(CharIdAndRelation lhs, CharIdAndRelation rhs)
		{
			int num = ((charId != lhs.CharId) ? DomainManager.Character.GetRelation(charId, lhs.CharId).EstablishmentDate : selfBirthDate);
			int num2 = ((charId != rhs.CharId) ? DomainManager.Character.GetRelation(charId, rhs.CharId).EstablishmentDate : selfBirthDate);
			return (num != num2) ? (num - num2) : (lhs.CharId - rhs.CharId);
		});
	}

	private void Sort(int charId, List<SpouseAndChildren> spousesAndChildren)
	{
		spousesAndChildren.Sort(delegate(SpouseAndChildren lhs, SpouseAndChildren rhs)
		{
			int num = ((lhs.SpouseCharId >= 0) ? DomainManager.Character.GetRelation(charId, lhs.SpouseCharId).EstablishmentDate : int.MaxValue);
			int num2 = ((rhs.SpouseCharId >= 0) ? DomainManager.Character.GetRelation(charId, rhs.SpouseCharId).EstablishmentDate : int.MaxValue);
			return (num != num2) ? (num - num2) : (lhs.SpouseCharId - rhs.SpouseCharId);
		});
	}

