	public void RemoveObsoleteActualBloodParents(DataContext context)
	{
		List<(ParentAndChild, int)> toBeRemoved = new List<(ParentAndChild, int)>();
		foreach (KeyValuePair<ParentAndChild, int> entry in _actualBloodParents)
		{
			ParentAndChild nominalRelation = entry.Key;
			int actualParentId = entry.Value;
			if ((nominalRelation.ChildId < 0 || IsCharacterDeadAndRemoved(nominalRelation.ChildId)) && (nominalRelation.ParentId < 0 || IsCharacterDeadAndRemoved(nominalRelation.ParentId)) && (actualParentId < 0 || IsCharacterDeadAndRemoved(actualParentId)))
			{
				toBeRemoved.Add((nominalRelation, actualParentId));
			}
		}
		int i = 0;
		for (int count = toBeRemoved.Count; i < count; i++)
		{
			var (nominalRelation2, actualParentId2) = toBeRemoved[i];
			RemoveElement_ActualBloodParents(nominalRelation2, context);
			RemoveNominalBloodParentRelation(actualParentId2, nominalRelation2);
		}
	}

	private void InitializeNominalBloodParentRelations()
	{
		_nominalBloodParentRelations = new Dictionary<int, List<ParentAndChild>>();
		foreach (KeyValuePair<ParentAndChild, int> entry in _actualBloodParents)
		{
			AddNominalBloodParentRelation(entry.Value, entry.Key);
		}
	}

	private void AddNominalBloodParentRelation(int actualParentId, ParentAndChild nominalRelation)
	{
		if (actualParentId >= 0)
		{
			if (!_nominalBloodParentRelations.TryGetValue(actualParentId, out var nominalRelations))
			{
				nominalRelations = new List<ParentAndChild>();
				_nominalBloodParentRelations.Add(actualParentId, nominalRelations);
			}
			nominalRelations.Add(nominalRelation);
		}
	}

	private void RemoveNominalBloodParentRelation(int actualParentId, ParentAndChild nominalRelation)
	{
		if (actualParentId >= 0)
		{
			List<ParentAndChild> nominalRelations = _nominalBloodParentRelations[actualParentId];
			nominalRelations.Remove(nominalRelation);
			if (nominalRelations.Count <= 0)
			{
				_nominalBloodParentRelations.Remove(actualParentId);
			}
		}
	}

	public void GetSkillBookLibrary(DataContext context, Character character, List<ItemKey> combatSkillBooks, List<ItemKey> lifeSkillBooks)
	{
		int charId = character.GetId();
		context.SwitchRandomSource((ulong)charId);
		if (!_soldLibrarySkillBooks.TryGetValue(charId, out var soldSkillBooks))
		{
			soldSkillBooks = GameData.Utilities.ShortList.Create();
		}
		if (soldSkillBooks.Items == null)
		{
			soldSkillBooks.Items = new List<short>();
		}
		List<short> soldBookTemplateIds = soldSkillBooks.Items;
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> charCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charId);
		foreach (KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> item in charCombatSkills)
		{
			item.Deconstruct(out var key, out var value);
			short skillTemplateId = key;
			GameData.Domains.CombatSkill.CombatSkill skill = value;
			ushort activationState = skill.GetActivationState();
			if (CombatSkillStateHelper.IsBrokenOut(activationState) && CombatSkillStateHelper.CanGenerateBookFromActivationState(activationState))
			{
				short bookTemplateId = Config.CombatSkill.Instance[skillTemplateId].BookId;
				if (bookTemplateId >= 0 && !soldBookTemplateIds.Contains(bookTemplateId))
				{
					int currRandomSeed = charId ^ ((activationState << 16) + bookTemplateId);
					context.Random.Reinitialise((ulong)currRandomSeed);
					ItemKey itemKey = DomainManager.Item.CreateSkillBook(context, bookTemplateId, activationState);
					DomainManager.Item.SetOwner(itemKey, ItemOwnerType.Library, charId);
					combatSkillBooks.Add(itemKey);
				}
			}
		}
		List<LifeSkillItem> lifeSkills = character.GetLearnedLifeSkills();
		int i = 0;
		for (int count = lifeSkills.Count; i < count; i++)
		{
			LifeSkillItem lifeSkill = lifeSkills[i];
			if (lifeSkill.GetReadPagesCount() >= 3)
			{
				short bookTemplateId2 = LifeSkill.Instance[lifeSkill.SkillTemplateId].SkillBookId;
				if (!soldBookTemplateIds.Contains(bookTemplateId2))
				{
					int currRandomSeed2 = charId ^ bookTemplateId2;
					context.Random.Reinitialise((ulong)currRandomSeed2);
					ItemKey itemKey2 = DomainManager.Item.CreateSkillBook(context, bookTemplateId2, -1, -1, -1, 50);
					DomainManager.Item.SetOwner(itemKey2, ItemOwnerType.Library, charId);
					lifeSkillBooks.Add(itemKey2);
				}
			}
		}
		context.RestoreRandomSource();
	}

	public void DealWithSkillBookLibraryAfterTrading(DataContext context, Character character, List<ItemKey> soldSkillBooks, List<ItemKey> leftSkillBooks)
	{
		int charId = character.GetId();
		GameData.Utilities.ShortList totalSoldSkillBooks;
		bool foundLibrary = _soldLibrarySkillBooks.TryGetValue(charId, out totalSoldSkillBooks);
		if (!foundLibrary)
		{
			totalSoldSkillBooks = GameData.Utilities.ShortList.Create();
		}
		if (totalSoldSkillBooks.Items == null)
		{
			totalSoldSkillBooks.Items = new List<short>();
		}
		int i = 0;
		for (int count = soldSkillBooks.Count; i < count; i++)
		{
			short bookTemplateId = soldSkillBooks[i].TemplateId;
			totalSoldSkillBooks.Items.Add(bookTemplateId);
		}
		if (foundLibrary)
		{
			SetElement_SoldLibrarySkillBooks(charId, totalSoldSkillBooks, context);
		}
		else
		{
			AddElement_SoldLibrarySkillBooks(charId, totalSoldSkillBooks, context);
		}
		if (leftSkillBooks != null)
		{
			DomainManager.Item.RemoveItems(context, leftSkillBooks);
		}
	}

	public void RecoverSkillBookLibraries(DataContext context)
	{
		ClearSoldLibrarySkillBooks(context);
	}

	public short[] GetSkillBookLibraryGradeCount(int charId)
	{
		short[] gradeCount = new short[9];
		Character character = GetElement_Objects(charId);
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> charCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charId);
		foreach (KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> item in charCombatSkills)
		{
			item.Deconstruct(out var key, out var value);
			short skillTemplateId = key;
			GameData.Domains.CombatSkill.CombatSkill skill = value;
			ushort activationState = skill.GetActivationState();
			if (CombatSkillStateHelper.IsBrokenOut(activationState) && CombatSkillStateHelper.CanGenerateBookFromActivationState(activationState))
			{
				short bookTemplateId = Config.CombatSkill.Instance[skillTemplateId].BookId;
				if (bookTemplateId >= 0)
				{
					SkillBookItem bookConfig = Config.SkillBook.Instance[bookTemplateId];
					gradeCount[bookConfig.Grade]++;
				}
			}
		}
		List<LifeSkillItem> lifeSkills = character.GetLearnedLifeSkills();
		int i = 0;
		for (int count = lifeSkills.Count; i < count; i++)
		{
			LifeSkillItem lifeSkill = lifeSkills[i];
			if (lifeSkill.GetReadPagesCount() >= 3)
			{
				short bookTemplateId2 = LifeSkill.Instance[lifeSkill.SkillTemplateId].SkillBookId;
				if (bookTemplateId2 >= 0)
				{
					SkillBookItem bookConfig2 = Config.SkillBook.Instance[bookTemplateId2];
					gradeCount[bookConfig2.Grade]++;
				}
			}
		}
		return gradeCount;
	}

	private static short GetBaseTemplateId(short charTemplateId, sbyte gender)
	{
		CharacterItem template = Config.Character.Instance[charTemplateId];
		if (template.CreatingType != 1 || template.Gender != gender)
		{
			return -1;
		}
		return (short)(charTemplateId - gender);
	}

	private static short GenerateTemplateId(short charBaseTemplateId, sbyte gender)
	{
		return (short)(charBaseTemplateId + gender);
	}

	[DomainMethod]
	public bool IsTemporaryIntelligentCharacter(int charId)
	{
		return _temporaryIntelligentCharIds.Contains(charId);
	}

	private void RegisterTemporaryIntelligentCharacter(int charId)
	{
		_temporaryIntelligentCharIds.Add(charId);
		SetTemporaryIntelligentCharIds(_temporaryIntelligentCharIds, null);
	}

	private void UnregisterTemporaryIntelligentCharacter(int charId)
	{
		bool success = _temporaryIntelligentCharIds.Remove(charId).Item2;
		SetTemporaryIntelligentCharIds(_temporaryIntelligentCharIds, null);
		if (!success)
		{
			throw new Exception($"Character {charId} is not temporary-intelligent-character");
		}
	}

	public void ClearTemporaryIntelligentCharacters(DataContext context)
	{
		HashSet<int> collection = _temporaryIntelligentCharIds.GetCollection();
		if (collection.Count <= 0)
		{
			return;
		}
		List<int> toRemoveCharIds = ObjectPool<List<int>>.Instance.Get();
		foreach (int charId in collection)
		{
			if (!DomainManager.LegendaryBook.IsPrevLegendaryBookOwnerCopy(charId) && !DomainManager.Adventure.IsAdventureTemporaryCharacter(charId))
			{
				toRemoveCharIds.Add(charId);
			}
		}
		Logger.Info($"Clearing temporary characters with a total count of {toRemoveCharIds.Count}");
		foreach (int charId2 in toRemoveCharIds)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId2, out var character))
			{
				RemoveTemporaryIntelligentCharacter(context, character);
			}
			else
			{
				UnregisterTemporaryIntelligentCharacter(charId2);
			}
		}
	}

