	public void RevertAllTemporaryModifications(DataContext context, Character character)
	{
		int charId = character.GetId();
		if (_characterTemporaryModifications.TryGetValue(charId, out var records))
		{
			RevertAllTemporaryModifications(context, character, records);
			_characterTemporaryModifications.Remove(charId);
		}
	}

	public void RevertAllTemporaryModificationsOfAllCharacters(DataContext context)
	{
		foreach (var (charId, records) in _characterTemporaryModifications)
		{
			if (_objects.TryGetValue(charId, out var character))
			{
				RevertAllTemporaryModifications(context, character, records);
			}
		}
		_characterTemporaryModifications.Clear();
	}

	public void CheckCharacterTemporaryModificationState()
	{
		if (_characterTemporaryModifications.Count <= 0)
		{
			return;
		}
		StringBuilder message = new StringBuilder("Some characters are still in temporary modification state:\n");
		foreach (var (charId, _) in _characterTemporaryModifications)
		{
			if (TryGetElement_Objects(charId, out var character))
			{
				StringBuilder stringBuilder = message;
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(38, 4, stringBuilder);
				handler.AppendLiteral("  TemplateId: ");
				handler.AppendFormatted(character.GetTemplateId());
				handler.AppendLiteral(", CreatingType: ");
				handler.AppendFormatted(character.GetCreatingType());
				handler.AppendLiteral(", Name: ");
				handler.AppendFormatted(character.GetSurname());
				handler.AppendFormatted(character.GetGivenName());
				stringBuilder2.AppendLine(ref handler);
			}
			else
			{
				StringBuilder stringBuilder = message;
				StringBuilder stringBuilder3 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(37, 1, stringBuilder);
				handler.AppendLiteral("  CharacterId: ");
				handler.AppendFormatted(charId);
				handler.AppendLiteral(" (Character not found)");
				stringBuilder3.AppendLine(ref handler);
			}
		}
		throw new Exception(message.ToString());
	}

	private void BeginTemporaryModificationInternal(Character character, RevertibleCharacterPropertyType type)
	{
		RevertibleCharacterPropertyValue value = default(RevertibleCharacterPropertyValue);
		switch (type)
		{
		case RevertibleCharacterPropertyType.Happiness:
			value.Sbyte = character.GetHappiness();
			break;
		case RevertibleCharacterPropertyType.BaseMorality:
			value.Short = character.GetBaseMorality();
			break;
		case RevertibleCharacterPropertyType.FeatureIds:
			value.Object = new List<short>(character.GetFeatureIds());
			break;
		case RevertibleCharacterPropertyType.BaseMainAttributes:
			value.MainAttributes = character.GetBaseMainAttributes();
			break;
		case RevertibleCharacterPropertyType.DisorderOfQi:
			value.Short = character.GetDisorderOfQi();
			break;
		case RevertibleCharacterPropertyType.Injuries:
			value.Injuries = character.GetInjuries();
			break;
		case RevertibleCharacterPropertyType.ExtraNeili:
			value.Int = character.GetExtraNeili();
			break;
		case RevertibleCharacterPropertyType.ConsummateLevel:
			value.Sbyte = character.GetConsummateLevel();
			break;
		case RevertibleCharacterPropertyType.BaseLifeSkillQualifications:
			value.LifeSkills = character.GetBaseLifeSkillQualifications();
			break;
		case RevertibleCharacterPropertyType.BaseCombatSkillQualifications:
			value.CombatSkills = character.GetBaseCombatSkillQualifications();
			break;
		case RevertibleCharacterPropertyType.Resources:
			value.Resources = character.GetResources();
			break;
		case RevertibleCharacterPropertyType.CurrMainAttributes:
			value.MainAttributes = character.GetCurrMainAttributes();
			break;
		case RevertibleCharacterPropertyType.Poisoned:
			value.Poisons = character.GetPoisoned();
			break;
		case RevertibleCharacterPropertyType.CurrNeili:
			value.Int = character.GetCurrNeili();
			break;
		case RevertibleCharacterPropertyType.ExtraNeiliAllocation:
			value.ExtraNeiliAllocation = character.GetExtraNeiliAllocation();
			break;
		case RevertibleCharacterPropertyType.XiangshuInfection:
			value.Byte = character.GetXiangshuInfection();
			break;
		default:
			throw new Exception($"Unsupported RevertibleCharacterPropertyType: {type}");
		}
		_currTemporaryModifyingValues.Add((type, value));
	}

	private void RecordTemporaryModificationInternal(int index, CharacterModificationRecords records)
	{
		var (type, value) = _currTemporaryModifyingValues[index];
		switch (type)
		{
		case RevertibleCharacterPropertyType.Happiness:
		{
			sbyte oriValue12 = value.Sbyte;
			sbyte currValue12 = _currTemporaryModifyingCharacter.GetHappiness();
			records.RecordHappiness(oriValue12, currValue12);
			break;
		}
		case RevertibleCharacterPropertyType.BaseMorality:
		{
			short oriValue11 = value.Short;
			short currValue11 = _currTemporaryModifyingCharacter.GetBaseMorality();
			records.RecordBaseMorality(oriValue11, currValue11);
			break;
		}
		case RevertibleCharacterPropertyType.FeatureIds:
		{
			List<short> oriValue10 = (List<short>)value.Object;
			List<short> currValue10 = _currTemporaryModifyingCharacter.GetFeatureIds();
			records.RecordFeatureIds(oriValue10, currValue10);
			break;
		}
		case RevertibleCharacterPropertyType.BaseMainAttributes:
		{
			MainAttributes oriValue9 = value.MainAttributes;
			MainAttributes currValue9 = _currTemporaryModifyingCharacter.GetBaseMainAttributes();
			records.RecordBaseMainAttributes(oriValue9, currValue9);
			break;
		}
		case RevertibleCharacterPropertyType.DisorderOfQi:
		{
			short oriValue8 = value.Short;
			short currValue8 = _currTemporaryModifyingCharacter.GetDisorderOfQi();
			records.RecordDisorderOfQi(oriValue8, currValue8);
			break;
		}
		case RevertibleCharacterPropertyType.Injuries:
		{
			Injuries oriValue7 = value.Injuries;
			Injuries currValue7 = _currTemporaryModifyingCharacter.GetInjuries();
			records.RecordInjuries(oriValue7, currValue7);
			break;
		}
		case RevertibleCharacterPropertyType.ExtraNeili:
		{
			int oriValue6 = value.Int;
			int currValue6 = _currTemporaryModifyingCharacter.GetExtraNeili();
			records.RecordExtraNeili(oriValue6, currValue6);
			break;
		}
		case RevertibleCharacterPropertyType.ConsummateLevel:
		{
			sbyte oriValue5 = value.Sbyte;
			sbyte currValue5 = _currTemporaryModifyingCharacter.GetConsummateLevel();
			records.RecordConsummateLevel(oriValue5, currValue5);
			break;
		}
		case RevertibleCharacterPropertyType.BaseLifeSkillQualifications:
			records.RecordBaseLifeSkillQualifications(ref value.LifeSkills, ref _currTemporaryModifyingCharacter.GetBaseLifeSkillQualifications());
			break;
		case RevertibleCharacterPropertyType.BaseCombatSkillQualifications:
			records.RecordBaseCombatSkillQualifications(ref value.CombatSkills, ref _currTemporaryModifyingCharacter.GetBaseCombatSkillQualifications());
			break;
		case RevertibleCharacterPropertyType.Resources:
			records.RecordResources(ref value.Resources, ref _currTemporaryModifyingCharacter.GetResources());
			break;
		case RevertibleCharacterPropertyType.CurrMainAttributes:
		{
			MainAttributes oriValue4 = value.MainAttributes;
			MainAttributes currValue4 = _currTemporaryModifyingCharacter.GetCurrMainAttributes();
			records.RecordCurrMainAttributes(oriValue4, currValue4);
			break;
		}
		case RevertibleCharacterPropertyType.Poisoned:
			records.RecordPoisoned(ref value.Poisons, ref _currTemporaryModifyingCharacter.GetPoisoned());
			break;
		case RevertibleCharacterPropertyType.CurrNeili:
		{
			int oriValue3 = value.Int;
			int currValue3 = _currTemporaryModifyingCharacter.GetCurrNeili();
