	private CharacterModificationRecords GetRecords(int charId)
	{
		if (_characterTemporaryModifications.TryGetValue(charId, out var records))
		{
			return records;
		}
		records = new CharacterModificationRecords();
		_characterTemporaryModifications.Add(charId, records);
		return records;
	}

	private unsafe static void RevertAllTemporaryModifications(DataContext context, Character character, CharacterModificationRecords records)
	{
		fixed (byte* pRawData = records.RawData)
		{
			while (records.Size > 0)
			{
				var (propertyType, offset, dataSize) = records.Pop(pRawData);
				RevertTemporaryModification(context, character, propertyType, pRawData + offset, dataSize);
			}
		}
	}

	private unsafe static void RevertTemporaryModificationsToSavepoint(DataContext context, Character character, CharacterModificationRecords records)
	{
		if (records.Savepoint < 0)
		{
			throw new Exception($"Character {character.GetId()}: records have no savepoint");
		}
		fixed (byte* pRawData = records.RawData)
		{
			while (records.Size > records.Savepoint)
			{
				var (propertyType, offset, dataSize) = records.Pop(pRawData);
				RevertTemporaryModification(context, character, propertyType, pRawData + offset, dataSize);
			}
		}
		if (records.Size != records.Savepoint)
		{
			throw new Exception($"Character {character.GetId()}: malformed records data");
		}
		records.DeleteSavepoint();
	}

	private unsafe static void RevertTemporaryModification(DataContext context, Character character, RevertibleCharacterPropertyType propertyType, byte* pModificationData, ushort dataSize)
	{
		switch (propertyType)
		{
		case RevertibleCharacterPropertyType.Happiness:
		{
			int delta11 = CharacterModificationRecords.RetrieveHappiness(pModificationData);
			character.ChangeHappiness(context, -delta11);
			break;
		}
		case RevertibleCharacterPropertyType.BaseMorality:
		{
			int delta10 = CharacterModificationRecords.RetrieveBaseMorality(pModificationData);
			character.ChangeBaseMorality(context, -delta10);
			break;
		}
		case RevertibleCharacterPropertyType.FeatureIds:
		{
			List<ShortListModification> modifications = CharacterModificationRecords.RetrieveFeatureIds(pModificationData, dataSize);
			character.RevertFeatures(context, modifications);
			break;
		}
		case RevertibleCharacterPropertyType.BaseMainAttributes:
			character.ChangeBaseMainAttributes(context, CharacterModificationRecords.RetrieveBaseMainAttributes(pModificationData).GetReversed());
			break;
		case RevertibleCharacterPropertyType.DisorderOfQi:
		{
			int delta9 = CharacterModificationRecords.RetrieveDisorderOfQi(pModificationData);
			character.ChangeDisorderOfQi(context, (short)(-delta9));
			break;
		}
		case RevertibleCharacterPropertyType.Injuries:
			character.ChangeInjuries(context, CharacterModificationRecords.RetrieveInjuries(pModificationData).GetReversed());
			break;
		case RevertibleCharacterPropertyType.ExtraNeili:
		{
			int delta8 = CharacterModificationRecords.RetrieveExtraNeili(pModificationData);
			character.ChangeExtraNeili(context, -delta8);
			break;
		}
		case RevertibleCharacterPropertyType.ConsummateLevel:
		{
			int delta7 = CharacterModificationRecords.RetrieveConsummateLevel(pModificationData);
			character.ChangeConsummateLevel(context, -delta7);
			break;
		}
		case RevertibleCharacterPropertyType.BaseLifeSkillQualifications:
		{
			LifeSkillShorts delta6 = CharacterModificationRecords.RetrieveBaseLifeSkillQualifications(pModificationData).GetReversed();
			character.ChangeBaseLifeSkillQualifications(context, ref delta6);
			break;
		}
		case RevertibleCharacterPropertyType.BaseCombatSkillQualifications:
		{
			CombatSkillShorts delta5 = CharacterModificationRecords.RetrieveBaseCombatSkillQualifications(pModificationData).GetReversed();
			character.ChangeBaseCombatSkillQualifications(context, ref delta5);
			break;
		}
		case RevertibleCharacterPropertyType.Resources:
		{
			ResourceInts delta4 = CharacterModificationRecords.RetrieveResources(pModificationData).GetReversed();
			character.ChangeResourcesWithoutChecking(context, ref delta4);
			break;
		}
		case RevertibleCharacterPropertyType.CurrMainAttributes:
			character.ChangeCurrMainAttributes(context, CharacterModificationRecords.RetrieveCurrMainAttributes(pModificationData).GetReversed());
			break;
		case RevertibleCharacterPropertyType.Poisoned:
		{
			PoisonInts delta3 = CharacterModificationRecords.RetrievePoisoned(pModificationData).GetReversed();
			character.DirectlyChangePoisoned(context, ref delta3);
			break;
		}
		case RevertibleCharacterPropertyType.CurrNeili:
		{
			int delta2 = CharacterModificationRecords.RetrieveCurrNeili(pModificationData);
			character.ChangeCurrNeiliWithoutChecking(context, -delta2);
			break;
		}
		case RevertibleCharacterPropertyType.ExtraNeiliAllocation:
			character.ChangeExtraNeiliAllocation(context, CharacterModificationRecords.RetrieveExtraNeiliAllocation(pModificationData).GetReversed());
			break;
		case RevertibleCharacterPropertyType.XiangshuInfection:
		{
			int delta = CharacterModificationRecords.RetrieveXiangshuInfection(pModificationData);
			character.ChangeXiangshuInfection(context, -delta);
			break;
		}
		case RevertibleCharacterPropertyType.CurrAge:
		{
			int value2 = CharacterModificationRecords.RetrieveCurrAge(pModificationData);
			character.SetCurrAge((short)value2, context);
			break;
		}
		case RevertibleCharacterPropertyType.Health:
		{
			int value = CharacterModificationRecords.RetrieveHealth(pModificationData);
			character.SetHealth((short)value, context);
			break;
		}
		default:
			throw new Exception($"Unsupported propertyType: {propertyType}");
		}
	}

	private void Test_Register_MakeAllXiangshuInfectedAndUpdateInfectedDemons()
	{
		DataUid uid = new DataUid(0, 1, ulong.MaxValue);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(uid, "Test_MakeAllXiangshuInfectedAndUpdateInfectedDemons", delegate(DataContext dataContext, DataUid dataUid)
		{
			Test_MakeAllXiangshuInfectedAndUpdateInfectedDemons(dataContext);
			GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(uid, "Test_MakeAllXiangshuInfectedAndUpdateInfectedDemons");
		});
	}

	private void Test_MakeAllXiangshuInfectedAndUpdateInfectedDemons(DataContext context)
	{
		ChallengeModeData challengeMode = DomainManager.World.GetChallengeModeData();
		if (!challengeMode.IsEnabled(EChallengeModeImplement.NI2))
		{
			List<int> modeIds = (List<int>)challengeMode.GetFieldValue("_challengeModeIds", BindingFlags.Instance | BindingFlags.NonPublic);
			if (modeIds == null)
			{
				modeIds = new List<int>();
			}
			modeIds.Add(ChallengeMode.Instance.First((ChallengeModeItem item) => item.Implement == EChallengeModeImplement.NI2).TemplateId);
			challengeMode.ModifyField("_challengeModeIds", modeIds, BindingFlags.Instance | BindingFlags.NonPublic);
		}
		foreach (var (charId, character2) in _objects)
		{
			if (CharacterMatcher.DefValue.CanInteractAsIntelligentCharacter.Match(character2) && !character2.IsInTaiwuGroup())
			{
				character2.ChangeXiangshuInfection(context, 200);
				character2.UpdateXiangshuInfectionState(context);
			}
		}
		DomainManager.Map.UpdateXiangshuInfectedDemons(context);
	}

	public static string ReportAttributesAndQualificationsStats(Character character)
	{
		(string, string) name = GetRealName(character);
		OrganizationInfo organizationInfo = character.GetOrganizationInfo();
		string orgName = Config.Organization.Instance[organizationInfo.OrgTemplateId].Name;
		string gradeName = OrganizationDomain.GetOrgMemberConfig(organizationInfo).GradeName;
		sbyte grade = organizationInfo.Grade;
		MainAttributes baseMainAttributes = character.GetBaseMainAttributes();
		LifeSkillShorts baseLifeSkillQualifications = character.GetBaseLifeSkillQualifications();
