	private unsafe void Test_GenerateFirstGeneration(DataContext context)
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("门派\t品级\t理想门派\t成长品级\t自身属性\t属性总和\t自身技艺\t技艺总和\t自身武学\t武学总和");
		IRandomSource random = context.Random;
		List<(Character, sbyte, sbyte)> characters = new List<(Character, sbyte, sbyte)>();
		foreach (OrganizationItem orgCfg in (IEnumerable<OrganizationItem>)Config.Organization.Instance)
		{
			bool flag = !orgCfg.IsSect;
			bool flag2 = flag;
			if (flag2)
			{
				sbyte templateId = orgCfg.TemplateId;
				bool flag3 = ((templateId < 21 || templateId > 35) ? true : false);
				flag2 = flag3;
			}
			if (flag2)
			{
				continue;
			}
			short[] members = orgCfg.Members;
			foreach (short memberId in members)
			{
				OrganizationMemberItem memberCfg = OrganizationMember.Instance[memberId];
				int count = (memberCfg.RestrictPrincipalAmount ? memberCfg.Amount : (memberCfg.Amount * 2));
				for (int j = 0; j < count; j++)
				{
					OrganizationInfo orgInfo = new OrganizationInfo(orgCfg.TemplateId, memberCfg.Grade, principal: true, -1);
					sbyte gender = Gender.GetRandom(random);
					if (!OrganizationDomain.MeetGenderRestriction(orgInfo.OrgTemplateId, gender) || (memberCfg.Gender >= 0 && memberCfg.Gender != gender))
					{
						gender = Gender.Flip(gender);
					}
					short charTemplateId = orgCfg.CharTemplateIds[gender];
					IntelligentCharacterCreationInfo creationInfo = new IntelligentCharacterCreationInfo(Location.Invalid, orgInfo, charTemplateId);
					creationInfo.MotherCharId = -1;
					creationInfo.ActualFatherCharId = -1;
					creationInfo.GrowingSectId = -1;
					Character fakeCharacter = new Character(charTemplateId);
					if (fakeCharacter.GetIdealSect() < 0)
					{
						fakeCharacter.CallMethod("OfflineGenerateRandomIdealSect", random);
					}
					sbyte idealSect = fakeCharacter.GetIdealSect();
					creationInfo.GrowingSectGrade = Math.Clamp(CharacterCreation.CalcGrowingSectGradeAndAssignWeights(random, ref creationInfo, idealSect), 0, 8);
					MainAttributes mainAttributes = CharacterCreation.CreateMainAttributes(random, ref creationInfo);
					LifeSkillShorts lifeSkillQualifications = CharacterCreation.CreateLifeSkillQualifications(random, ref creationInfo);
					CombatSkillShorts combatSkillQualifications = CharacterCreation.CreateCombatSkillQualifications(random, ref creationInfo);
					fakeCharacter.ModifyField("_organizationInfo", orgInfo);
					fakeCharacter.ModifyField("_baseMainAttributes", mainAttributes);
					fakeCharacter.ModifyField("_baseLifeSkillQualifications", lifeSkillQualifications);
					fakeCharacter.ModifyField("_baseCombatSkillQualifications", combatSkillQualifications);
					stringBuilder.AppendFormat("{0}\t{1}\t{2}\t{3}\t", orgCfg.Name, orgInfo.Grade, (idealSect < 0) ? ((object)(-1)) : Config.Organization.Instance[idealSect].Name, creationInfo.GrowingSectGrade);
					WriteString(mainAttributes.Items, 6, stringBuilder);
					stringBuilder.Append('\t');
					stringBuilder.Append(mainAttributes.GetSum());
					stringBuilder.Append('\t');
					WriteString(lifeSkillQualifications.Items, 16, stringBuilder);
					stringBuilder.Append('\t');
					stringBuilder.Append(lifeSkillQualifications.GetSum());
					stringBuilder.Append('\t');
					WriteString(combatSkillQualifications.Items, 14, stringBuilder);
					stringBuilder.Append('\t');
					stringBuilder.Append(combatSkillQualifications.GetSum());
					stringBuilder.AppendLine();
					characters.Add((fakeCharacter, creationInfo.GrowingSectId, creationInfo.GrowingSectGrade));
				}
			}
		}
		File.WriteAllText(Path.Combine(Program.BaseDataDir, "Logs", "FirstGeneration.txt"), stringBuilder.ToString());
		Test_GenerateChildren(context, characters);
	}

