	public unsafe void Test_GenerateChildren(DataContext context)
	{
		Stopwatch timer = GlobalDomain.StartTimer();
		List<(Character, Character)> charsToChildbirth = new List<(Character, Character)>();
		float childBirthProb = 0.5f;
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("母亲品级\t父亲品级\t父母最高品级\t自身未修正成长品级\t自身修正后成长品级\t母亲属性\t父亲属性\t自身属性\t属性总和\t母亲技艺\t父亲技艺\t自身技艺\t技艺总和\t母亲武学\t父亲武学\t自身武学\t武学总和");
		int count = 0;
		while (count < 10000)
		{
			for (short areaId = 0; areaId < 135; areaId++)
			{
				Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(areaId);
				int i = 0;
				for (int blocksCount = blocks.Length; i < blocksCount; i++)
				{
					HashSet<int> charIds = blocks[i].CharacterSet;
					if (charIds == null)
					{
						continue;
					}
					foreach (int charId in charIds)
					{
						Character character = DomainManager.Character.GetElement_Objects(charId);
						if (character.GetGender() == 0 && character.GetAgeGroup() == 2)
						{
							HashSet<int> spouseCharIds = DomainManager.Character.GetRelatedCharIds(charId, 1024);
							int aliveSpouseId = DomainManager.Character.GetAliveSpouse(charId);
							if ((spouseCharIds.Count <= 0 || aliveSpouseId >= 0) && !(context.Random.NextFloat() >= childBirthProb))
							{
								Character spouse = ((aliveSpouseId >= 0) ? DomainManager.Character.GetElement_Objects(aliveSpouseId) : null);
								charsToChildbirth.Add((character, spouse));
							}
						}
					}
				}
			}
			foreach (var item in charsToChildbirth)
			{
				Character mother = item.Item1;
				Character father = item.Item2;
				Location location = mother.GetLocation();
				(OrganizationInfo parentOrgInfo, short baseTemplateId, bool isAbandoned) mainParentInfo = GetMainParentInfo(mother, father, createMotherRelation: true, createFatherRelation: true, isMotherDead: false);
				OrganizationInfo orgInfo = mainParentInfo.parentOrgInfo;
				short baseTemplateId = mainParentInfo.baseTemplateId;
				bool isAbandoned = mainParentInfo.isAbandoned;
				IntelligentCharacterCreationInfo creationInfo = new IntelligentCharacterCreationInfo(location, orgInfo, baseTemplateId);
				creationInfo.MotherCharId = mother.GetId();
				creationInfo.Mother = mother;
				creationInfo.ActualFatherCharId = father?.GetId() ?? (-1);
				creationInfo.ActualFather = father;
				Character fakeCharacter = new Character(baseTemplateId);
				if (fakeCharacter.GetIdealSect() < 0)
				{
					fakeCharacter.CallMethod("OfflineGenerateRandomIdealSect", context.Random);
				}
				sbyte idealSect = fakeCharacter.GetIdealSect();
				stringBuilder.Append(mother.GetInteractionGrade());
				stringBuilder.Append('\t');
				if (father != null)
				{
					stringBuilder.Append(father.GetInteractionGrade());
				}
				else
				{
					stringBuilder.Append(-1);
				}
				stringBuilder.Append('\t');
				sbyte parentMaxGrade = mother.GetInteractionGrade();
				if (father != null && father.GetInteractionGrade() > parentMaxGrade)
				{
					parentMaxGrade = father.GetInteractionGrade();
				}
				stringBuilder.Append(parentMaxGrade);
				stringBuilder.Append('\t');
				creationInfo.AllowRandomGrowingGradeAdjust = false;
				creationInfo.GrowingSectGrade = CharacterCreation.CalcGrowingSectGradeAndAssignWeights(context.Random, ref creationInfo, idealSect);
				stringBuilder.Append(creationInfo.GrowingSectGrade);
				stringBuilder.Append('\t');
				creationInfo.AllowRandomGrowingGradeAdjust = true;
				creationInfo.GrowingSectGrade = CharacterCreation.CalcGrowingSectGradeAndAssignWeights(context.Random, ref creationInfo, idealSect);
				stringBuilder.Append(creationInfo.GrowingSectGrade);
				stringBuilder.Append('\t');
				MainAttributes motherAttr = mother.GetBaseMainAttributes();
				WriteString(motherAttr.Items, 6, stringBuilder);
				stringBuilder.Append('\t');
				if (father != null)
				{
					MainAttributes fatherAttr = father.GetBaseMainAttributes();
					WriteString(fatherAttr.Items, 6, stringBuilder);
				}
				else
				{
					stringBuilder.Append("{}");
				}
				stringBuilder.Append('\t');
				MainAttributes mainAttributes = CharacterCreation.CreateMainAttributes(context.Random, ref creationInfo);
				WriteString(mainAttributes.Items, 6, stringBuilder);
				stringBuilder.Append('\t');
				stringBuilder.Append(mainAttributes.GetSum());
				stringBuilder.Append('\t');
				LifeSkillShorts motherLifeSkillQualifications = mother.GetBaseLifeSkillQualifications();
				WriteString(motherLifeSkillQualifications.Items, 16, stringBuilder);
				stringBuilder.Append('\t');
				if (father != null)
				{
					LifeSkillShorts fatherLifeSkillQualifications = father.GetBaseLifeSkillQualifications();
					WriteString(fatherLifeSkillQualifications.Items, 16, stringBuilder);
				}
				else
				{
					stringBuilder.Append("{}");
				}
				stringBuilder.Append('\t');
				LifeSkillShorts lifeSkillQualifications = CharacterCreation.CreateLifeSkillQualifications(context.Random, ref creationInfo);
				WriteString(lifeSkillQualifications.Items, 16, stringBuilder);
				stringBuilder.Append('\t');
				stringBuilder.Append(motherLifeSkillQualifications.GetSum());
				stringBuilder.Append('\t');
				CombatSkillShorts motherCombatSkillQualifications = mother.GetBaseCombatSkillQualifications();
				WriteString(motherCombatSkillQualifications.Items, 14, stringBuilder);
				stringBuilder.Append('\t');
				if (father != null)
				{
					CombatSkillShorts fatherCombatSkillQualifications = father.GetBaseCombatSkillQualifications();
					WriteString(fatherCombatSkillQualifications.Items, 14, stringBuilder);
				}
				else
				{
					stringBuilder.Append("{}");
				}
				stringBuilder.Append('\t');
				CombatSkillShorts combatSkillQualifications = CharacterCreation.CreateCombatSkillQualifications(context.Random, ref creationInfo);
				WriteString(combatSkillQualifications.Items, 14, stringBuilder);
				stringBuilder.Append('\t');
				stringBuilder.Append(combatSkillQualifications.GetSum());
				stringBuilder.Append('\t');
				stringBuilder.AppendLine();
				count++;
			}
		}
		GlobalDomain.StopTimer(timer, "New Character Stats Generation");
		File.WriteAllText(Path.Combine(Program.BaseDataDir, "Logs", "GenerationSum"), stringBuilder.ToString());
	}

	private unsafe void WriteString(short* pArr, int count, StringBuilder stringBuilder)
	{
		stringBuilder.Append('{');
		for (int i = 0; i < count; i++)
		{
			stringBuilder.Append(pArr[i]);
			if (i != count - 1)
			{
				stringBuilder.Append(',');
			}
		}
		stringBuilder.Append('}');
	}

	public void Test_SoftCheckGroups()
	{
		foreach (var (leaderId, group) in _characterGroups)
		{
			if (!_objects.TryGetValue(leaderId, out var leader))
			{
				Logger.Warn($"group leader {leaderId} is dead.");
				continue;
			}
			HashSet<int> groupCharSet = group.GetCollection();
			foreach (int charId in groupCharSet)
			{
				if (!_objects.TryGetValue(charId, out var character))
				{
					Logger.Warn($"{charId} is not alive (leader {leader}).");
					continue;
				}
				if (character.GetLeaderId() != leaderId)
				{
					Logger.Warn($"{character}'s leader {character.GetLeaderId()} is not {leader}");
				}
				if (charId != leaderId && !TryGetRelation(leaderId, charId, out var _))
				{
					Logger.Warn($"{character} has not relation with leader {leader}");
				}
			}
		}
	}

	public void Test_HardCheckGroups()
	{
		foreach (var (leaderId, group) in _characterGroups)
		{
			Tester.Assert(!_objects.TryGetValue(leaderId, out var _));
			HashSet<int> groupCharSet = group.GetCollection();
			foreach (int charId in groupCharSet)
			{
				Tester.Assert(!_objects.TryGetValue(charId, out var character));
				Tester.Assert(character.GetLeaderId() != leaderId);
				if (charId != leaderId)
				{
					Tester.Assert(TryGetRelation(leaderId, charId, out var _));
				}
			}
		}
	}

