			builder.Append('\t');
			sbyte combatSkillType3 = -1;
			sbyte maxConsummateLevel3 = Test_CalcMaxConsummateLevel3(attainmentPanels, ref combatSkillType3);
			builder.Append(maxConsummateLevel3);
			builder.Append('\t');
