		void AppendGradesOnPanel(short[] combatSkillAttainmentPanels, sbyte skillType)
		{
			for (sbyte grade = 0; grade < 9; grade++)
			{
				int offset = 9 * skillType + grade;
				short skillTemplateId = combatSkillAttainmentPanels[offset];
				if (skillTemplateId >= 0)
				{
					builder.Append(grade);
					builder.Append('，');
				}
			}
		}
	}

	private static sbyte Test_CalcMaxConsummateLevel1(short[] combatSkillAttainmentPanels, ref sbyte combatSkillType)
	{
		int maxConsummateLevel = -1;
		for (sbyte skillType = 0; skillType < 14; skillType++)
		{
			int maxConsecutiveGrade = -1;
			int totalCount = 0;
			for (sbyte grade = 0; grade <= 8; grade++)
			{
				int offset = 9 * skillType + grade;
				short skillTemplateId = combatSkillAttainmentPanels[offset];
				if (skillTemplateId >= 0)
				{
					if (grade != 0)
					{
						totalCount++;
					}
					if (maxConsecutiveGrade + 1 == grade)
					{
						maxConsecutiveGrade = grade;
					}
				}
			}
			if (maxConsecutiveGrade > 0)
			{
				totalCount += maxConsecutiveGrade;
			}
			if (maxConsummateLevel < totalCount)
			{
				maxConsummateLevel = totalCount;
				combatSkillType = skillType;
			}
		}
		return (sbyte)Math.Clamp(maxConsummateLevel, 0, GlobalConfig.Instance.MaxConsummateLevel);
	}

	private unsafe static sbyte Test_CalcMaxConsummateLevel2(short[] combatSkillAttainmentPanels, ref sbyte combatSkillType)
	{
		short* gradePoints = stackalloc short[9] { 10, 10, 10, 10, 15, 15, 20, 30, 40 };
		int maxConsummateLevel = -1;
		for (sbyte skillType = 0; skillType < 14; skillType++)
		{
			int totalPoints = 0;
			for (sbyte grade = 0; grade <= 8; grade++)
			{
				int offset = 9 * skillType + grade;
				short skillTemplateId = combatSkillAttainmentPanels[offset];
				if (skillTemplateId >= 0)
				{
					totalPoints += gradePoints[grade];
				}
			}
			int currValue = totalPoints / 10;
			if (maxConsummateLevel < currValue)
			{
				maxConsummateLevel = currValue;
				combatSkillType = skillType;
			}
		}
		return (sbyte)Math.Clamp(maxConsummateLevel, 0, GlobalConfig.Instance.MaxConsummateLevel);
	}

	private unsafe static sbyte Test_CalcMaxConsummateLevel3(short[] combatSkillAttainmentPanels, ref sbyte combatSkillType)
	{
		short* gradePoints = stackalloc short[9] { 5, 10, 15, 20, 25, 30, 35, 45, 55 };
		int maxConsummateLevel = -1;
		for (sbyte skillType = 0; skillType < 14; skillType++)
		{
			int totalCount = 0;
			int lowPoint = 0;
			int middlePoint = 0;
			int highPoint = 0;
			for (sbyte grade = 0; grade <= 8; grade++)
			{
				int offset = 9 * skillType + grade;
				short skillTemplateId = combatSkillAttainmentPanels[offset];
				if (skillTemplateId >= 0)
				{
					if (grade != 0)
					{
						totalCount++;
					}
					short point = gradePoints[grade];
					switch (Grade.GetGroup(grade))
					{
					case 0:
						lowPoint = Math.Max(point, lowPoint);
						break;
					case 1:
						middlePoint = Math.Max(point, middlePoint);
						break;
					case 2:
						highPoint = Math.Max(point, highPoint);
						break;
					}
				}
			}
			totalCount += (lowPoint + middlePoint + highPoint) / 10;
			if (maxConsummateLevel < totalCount)
			{
				maxConsummateLevel = totalCount;
				combatSkillType = skillType;
			}
		}
		return (sbyte)Math.Clamp(maxConsummateLevel, 0, GlobalConfig.Instance.MaxConsummateLevel);
	}

