	public void UpdateTwelveImmortals(DataContext context)
	{
		TwelveImmortalsMovement3_Extern(context);
		TwelveImmortalsMovement4_Extern(context);
		TwelveImmortalsMovement5_Extern(context);
	}

	private void TwelveImmortalsMovement(DataContext context, Character character)
	{
		short templateId = character.GetTemplateId();
		switch (templateId)
		{
		case 1080:
			return;
		case 1083:
			TwelveImmortalsMovementPreMove8(character);
			break;
		}
		TwelveImmortalsMovementCommon(context, character);
		switch (templateId)
		{
		case 1075:
			TwelveImmortalsMovementRelation(context, character, 32768);
			break;
		case 1076:
			TwelveImmortalsMovement1(context, character);
			break;
		case 1081:
			TwelveImmortalsMovement6(context, character);
			break;
		case 1082:
			TwelveImmortalsMovement7(context, character);
			break;
		case 1083:
			TwelveImmortalsMovement8(context, character);
			break;
		case 1084:
			TwelveImmortalsMovement9(context, character);
			break;
		case 1085:
			TwelveImmortalsMovementRelation(context, character, 16384);
			break;
		}
		InvalidateTwelveImmortalsMoveCostCache(context);
	}

	private void TwelveImmortalsMovementCommon(DataContext context, Character character)
	{
		Location srcLocation = character.GetLocation();
		if (srcLocation.IsValid())
		{
			TwelveImmortalsUpdateTravelTarget(context, character);
			Location nextLocation = character.GetNpcTravelTargets()[0].GetRealTargetLocation();
			if (nextLocation.AreaId != srcLocation.AreaId)
			{
				character.SetLocation(nextLocation, context);
				Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), srcLocation, nextLocation);
				srcLocation = nextLocation;
			}
			int moveStep = context.Random.Next(1, 4);
			List<MapBlockData> neighbors = ObjectPool<List<MapBlockData>>.Instance.Get();
			DomainManager.Map.GetRealNeighborBlocks(srcLocation.AreaId, srcLocation.BlockId, neighbors, moveStep);
			Location dstLocation = ((neighbors.Count > 0) ? neighbors.GetRandom(context.Random).GetLocation() : srcLocation);
			ObjectPool<List<MapBlockData>>.Instance.Return(neighbors);
			if (!(srcLocation == dstLocation))
			{
				character.SetLocation(dstLocation, context);
				Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), srcLocation, dstLocation);
			}
		}
	}

	private void TwelveImmortalsUpdateTravelTarget(DataContext context, Character character)
	{
		List<NpcTravelTarget> targets = character.GetNpcTravelTargets();
		if (targets != null && targets.Count > 0)
		{
			NpcTravelTarget target = targets[0];
			target.RemainingMonth--;
			if (target.RemainingMonth <= 0)
			{
				targets.RemoveAt(0);
			}
			else
			{
				targets[0] = target;
			}
			character.SetNpcTravelTargets(targets, context);
		}
		if (targets.Count <= 0)
		{
			Location nextLocation = character.GetTwelveImmortalsNextLocation(context.Random);
			NpcTravelTarget nextTarget = new NpcTravelTarget(nextLocation, 6);
			character.AddTravelTarget(context, nextTarget);
		}
	}

	private void TwelveImmortalsMovementRelation(DataContext context, Character character, ushort relationType)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		MonthlyEventCollection monthlyEvent = DomainManager.World.GetMonthlyEventCollection();
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		foreach (Character blockChar in config.GetImpactRangeCharacters(character))
		{
			if (!context.Random.CheckPercentProb(33))
			{
				continue;
			}
			Location location = blockChar.GetLocation();
			int blockCharId = blockChar.GetId();
			int targetCharId = GetCharactersInRangeOnlyNormal(context, location, 1, includeTaiwu: true, blockCharId);
			if (targetCharId < 0)
			{
				continue;
			}
			blockChar.ChangeXiangshuInfection(context, 50);
			if (targetCharId == taiwuCharId)
			{
				if (relationType == 16384)
				{
					monthlyEvent.AddMainStoryImmortalZhenDanShengNv(blockCharId, taiwuCharId, location);
				}
				else
				{
					monthlyEvent.AddMainStoryImmortalChiHongZi(blockCharId, taiwuCharId, location);
				}
				continue;
			}
			TryAddAndApplyOneWayRelation(context, blockCharId, targetCharId, relationType);
			if (relationType == 16384)
			{
				lifeRecord.AddTwelveImmortalsEffectAdored(blockCharId, date, location, targetCharId);
			}
			else
			{
				lifeRecord.AddTwelveImmortalsEffectEnemy(blockCharId, date, location, targetCharId);
			}
		}
	}

	private void TwelveImmortalsMovement1(DataContext context, Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		List<MapBlockData> neighbors = ObjectPool<List<MapBlockData>>.Instance.Get();
		neighbors.AddRange(config.GetImpactRangeBlocks(character));
		int count = neighbors.Count * CValueHalf.RoundUp;
		neighbors.RemoveAll((MapBlockData x) => x.Destroyed);
		CValueFraction fraction = new CValueFraction(33, 100, roundUp: true);
		foreach (MapBlockData blockData in RandomUtils.GetRandomUnrepeated(context.Random, count, neighbors))
		{
			bool anyZero = false;
			MaterialResources maxResources = blockData.MaxResources;
			for (int i = 0; i < 6; i++)
			{
				blockData.CurrResources[i] = (short)Math.Max(blockData.CurrResources[i] - maxResources[i] * fraction, 0);
				anyZero = blockData.CurrResources[i] == 0 && maxResources[i] > 0;
				if (anyZero)
				{
					break;
				}
			}
			if (anyZero)
			{
				DomainManager.Map.MakeBlockDestroyedInAdvanceMonth(context, blockData);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighbors);
	}

	private void TwelveImmortalsMovement3_Extern(DataContext context)
	{
		Dictionary<Location, int> data = _twelveImmortalsData.TwelveImmortals3TaiwuMovedLocations;
		if (data == null || data.Count <= 0)
		{
			return;
		}
		int currDate = DomainManager.World.GetCurrDate();
		List<Location> outDateKeys = ObjectPool<List<Location>>.Instance.Get();
		foreach (var (key, outDate) in data)
		{
			if (outDate <= currDate)
			{
				outDateKeys.Add(key);
			}
		}
		foreach (Location outDateKey in outDateKeys)
		{
			data.Remove(outDateKey);
		}
		if (outDateKeys.Count > 0)
		{
			InvalidateTwelveImmortalsMoveCostCache(context);
		}
		ObjectPool<List<Location>>.Instance.Return(outDateKeys);
	}

	private void TwelveImmortalsMovement4_Extern(DataContext context)
	{
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		CValuePercent changeHealthPercent = -20;
		foreach (Character blockChar in TwelveImmortals.DefValue.Suxia.GetImpactRangeCharacters())
		{
			if (blockChar.GetCreatingType() == 1)
			{
				blockChar.ActivateAdvanceMonthStatus(7);
				blockChar.ChangeHealth(context, blockChar.GetMaxHealth() * changeHealthPercent);
				lifeRecord.AddTwelveImmortalsEffectSuxia(blockChar.GetId(), date, blockChar.GetLocation());
			}
		}
	}

	private void TwelveImmortalsMovement5_Extern(DataContext context)
	{
		if (!TryGetFixedCharacterByTemplateId(1080, out var character))
		{
			return;
		}
		Location location = character.GetLocation();
		if (!location.IsValid())
		{
			return;
		}
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		List<Character> minions = ObjectPool<List<Character>>.Instance.Get();
		foreach (Character blockChar in config.GetImpactRangeCharacters(character))
		{
			if (blockChar.GetFeatureIds().Contains(861))
			{
				minions.Add(blockChar);
			}
		}
		TwelveImmortalsMovementCommon(context, character);
		for (int i = minions.Count - 1; i >= 0; i--)
		{
			Character minion = minions[i];
			if (minion.GetLocation().GetManhattanDistanceToPos(location) > config.ImpactRange)
			{
				minion.RemoveFeature(context, 861);
				minions.RemoveAt(i);
			}
		}
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		if (minions.Count < 2)
		{
			List<Character> pool = ObjectPool<List<Character>>.Instance.Get();
			pool.AddRange(config.GetImpactRangeCharacters(character));
			pool.RemoveAll(minions.Contains);
			int newCount = 2 - pool.Count;
			foreach (Character blockChar2 in RandomUtils.GetRandomUnrepeated(context.Random, newCount, pool))
			{
				blockChar2.AddFeature(context, 861);
				minions.Add(blockChar2);
				lifeRecord.AddTwelveImmortalsEffectBecomeMoTian(blockChar2.GetId(), date, blockChar2.GetLocation());
			}
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		MonthlyEventCollection monthlyEvent = DomainManager.World.GetMonthlyEventCollection();
		foreach (Character minion2 in minions)
		{
			minion2.ActivateAdvanceMonthStatus(7);
			int minionCharId = minion2.GetId();
			Location minionLocation = minion2.GetLocation();
			int targetCharId = GetCharactersInRangeOnlyNormal(context, minionLocation, 2, includeTaiwu: true, minionCharId);
			if (targetCharId >= 0)
			{
				if (targetCharId == taiwuCharId)
				{
					monthlyEvent.AddMainStoryImmortalPoJinShangRen(targetCharId, minionCharId);
					continue;
				}
				Character targetChar = _objects[targetCharId];
				SimulateCharacterCombat(context, minion2, targetChar, CombatType.Die);
				lifeRecord.AddTwelveImmortalsEffectBeAttackByMoTian(targetCharId, date, minionLocation, minionCharId);
			}
		}
		ObjectPool<List<Character>>.Instance.Return(minions);
		InvalidateTwelveImmortalsMoveCostCache(context);
	}

	private void TwelveImmortalsMovement6(DataContext context, Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		MonthlyNotificationCollection monthlyNotification = DomainManager.World.GetMonthlyNotificationCollection();
		Location location = character.GetLocation();
		ByteCoordinate? blockPos = (location.IsValid() ? DomainManager.Map.GetBlock(location) : null)?.GetRootBlock().GetBlockPos();
		List<MapBlockData> neighbors = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, neighbors, config.ImpactRange);
		foreach (KeyValuePair<short, sbyte> jiaoCharacterToPoisonType in TwelveImmortalsConstants.JiaoCharacterToPoisonTypes)
		{
			jiaoCharacterToPoisonType.Deconstruct(out var key, out var value);
			short templateId = key;
			sbyte poisonType = value;
			Character jiaoCharacter = GetOrCreateFixedCharacterByTemplateId(context, templateId);
			Location jiaoLocation = jiaoCharacter.GetLocation();
			if (blockPos.HasValue)
			{
				bool randomMove = true;
				if (jiaoLocation.IsValid())
				{
					MapBlockData atBlock = DomainManager.Map.GetBlock(jiaoLocation.AreaId, jiaoLocation.BlockId);
					ByteCoordinate atBlockPos = atBlock.GetRootBlock().GetBlockPos();
					int distance = blockPos.Value.GetManhattanDistance(atBlockPos);
					if (distance <= config.ImpactRange)
					{
						randomMove = false;
					}
				}
				if (randomMove)
				{
					MapBlockData atBlock2 = neighbors.GetRandom(context.Random);
					Location atLocation = atBlock2.GetLocation();
					jiaoCharacter.SetLocation(atLocation, context);
					Events.RaiseFixedCharacterLocationChanged(context, jiaoCharacter.GetId(), jiaoLocation, atLocation);
				}
				int targetCharId = GetRandomCharacterInRange(context, jiaoCharacter.GetLocation(), 1, includeTaiwu: true);
				if (targetCharId >= 0)
				{
					Character targetChar = _objects[targetCharId];
					targetChar.ChangePoisoned(context, poisonType, 3, 6000);
					if (targetCharId == taiwuCharId)
					{
						monthlyNotification.AddMainStoryImmortalWuFanKe(targetCharId, jiaoCharacter.GetId());
					}
					else
					{
						lifeRecord.AddTwelveImmortalsEffectBeAttackByJiao(targetCharId, date, jiaoLocation, templateId);
					}
				}
			}
			else if (jiaoLocation.IsValid())
			{
				jiaoCharacter.SetLocation(location, context);
				Events.RaiseFixedCharacterLocationChanged(context, jiaoCharacter.GetId(), jiaoLocation, location);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighbors);
	}

	private void TwelveImmortalsMovement7(DataContext context, Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		MonthlyNotificationCollection monthlyNotification = DomainManager.World.GetMonthlyNotificationCollection();
		Location location = character.GetLocation();
		ByteCoordinate? blockPos = (location.IsValid() ? DomainManager.Map.GetBlock(location) : null)?.GetRootBlock().GetBlockPos();
		List<MapBlockData> neighbors = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, neighbors, config.ImpactRange);
		foreach (short templateId in TwelveImmortalsConstants.MirrorCharacters)
		{
			Character mirrorCharacter = GetOrCreateFixedCharacterByTemplateId(context, templateId);
			int mirrorCharId = mirrorCharacter.GetId();
			Location mirrorLocation = mirrorCharacter.GetLocation();
			if (blockPos.HasValue)
			{
				bool randomMove = true;
				if (mirrorLocation.IsValid())
				{
					MapBlockData atBlock = DomainManager.Map.GetBlock(mirrorLocation.AreaId, mirrorLocation.BlockId);
					ByteCoordinate atBlockPos = atBlock.GetRootBlock().GetBlockPos();
					int distance = blockPos.Value.GetManhattanDistance(atBlockPos);
					if (distance <= config.ImpactRange)
					{
						randomMove = false;
					}
				}
				if (randomMove)
				{
					MapBlockData atBlock2 = neighbors.GetRandom(context.Random);
					Location atLocation = atBlock2.GetLocation();
					mirrorCharacter.SetLocation(atLocation, context);
					Events.RaiseFixedCharacterLocationChanged(context, mirrorCharId, mirrorLocation, atLocation);
				}
				int targetCharId = GetRandomCharacterInRange(context, mirrorCharacter.GetLocation(), 1, includeTaiwu: true);
				if (targetCharId >= 0)
				{
					NeiliAllocation delta = default(NeiliAllocation);
					delta.Initialize();
					for (int i = 0; i < 30; i++)
					{
						delta[context.Random.Next(4)]--;
					}
					Character targetChar = _objects[targetCharId];
					targetChar.ChangeExtraNeiliAllocation(context, delta);
					if (taiwuCharId == targetCharId)
					{
						monthlyNotification.AddMainStoryImmortalDianFanMo(targetCharId, mirrorCharId);
					}
					else
					{
						lifeRecord.AddTwelveImmortalsEffectBeAttackByMirror(targetCharId, date, mirrorLocation, templateId);
					}
				}
			}
			else if (mirrorLocation.IsValid())
			{
				mirrorCharacter.SetLocation(location, context);
				Events.RaiseFixedCharacterLocationChanged(context, mirrorCharId, mirrorLocation, location);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighbors);
	}

	private void TwelveImmortalsMovementPreMove8(Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		foreach (MapBlockData block in config.GetImpactRangeBlocks(character))
		{
			HashSet<int> enemyCharacterSet = block.EnemyCharacterSet;
			if (enemyCharacterSet == null || enemyCharacterSet.Count <= 0)
			{
				continue;
			}
			foreach (int enemyCharId in block.EnemyCharacterSet)
			{
				if (_objects.TryGetValue(enemyCharId, out var enemyChar) && enemyChar.GetFeatureIds().Contains(880))
				{
					_twelveImmortals8SkeletonDemonCharacters.Add(enemyChar);
				}
			}
		}
	}

	private void TwelveImmortalsMovement8(DataContext context, Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		Location location = character.GetLocation();
		for (int i = _twelveImmortals8SkeletonDemonCharacters.Count - 1; i >= 0; i--)
		{
			Character demonCharacter = _twelveImmortals8SkeletonDemonCharacters[i];
			if (demonCharacter.GetLocation().GetManhattanDistanceToPos(location) > config.ImpactRange)
			{
				_twelveImmortals8SkeletonDemonCharacters.RemoveAt(i);
				RemoveNonIntelligentCharacter(context, demonCharacter);
			}
		}
		foreach (MapBlockData block in config.GetImpactRangeBlocks(character))
		{
			HashSet<int> graveSet = block.GraveSet;
			if (graveSet == null || graveSet.Count <= 0)
			{
				continue;
			}
			foreach (int graveId in block.GraveSet)
			{
				Grave grave = _graves[graveId];
				if (grave.GetSkeletonCharId() < 0)
				{
					CreateSkeletonCharacter(context, grave)?.AddFeature(context, 880);
				}
			}
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		MonthlyEventCollection monthlyEvent = DomainManager.World.GetMonthlyEventCollection();
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		foreach (Character demonCharacter2 in _twelveImmortals8SkeletonDemonCharacters)
		{
			Location demonLocation = demonCharacter2.GetLocation();
			int targetCharId = GetCharactersInRangeOnlyNormal(context, demonLocation, 1, includeTaiwu: true);
			if (targetCharId >= 0)
			{
				if (targetCharId == taiwuCharId)
				{
					monthlyEvent.AddMainStoryImmortalHuoGuShi(targetCharId, demonCharacter2.GetId());
					continue;
				}
				int demonId = demonCharacter2.GetId();
				int graveId2 = GetSkeletonSourceGraveId(demonId);
				int charId = ((graveId2 < 0) ? demonId : graveId2);
				Character targetChar = _objects[targetCharId];
				SimulateCharacterCombat(context, demonCharacter2, targetChar, CombatType.Die);
				lifeRecord.AddTwelveImmortalsEffectBeAttackBySkeletonDemon(targetCharId, date, demonLocation, charId);
			}
		}
		_twelveImmortals8SkeletonDemonCharacters.Clear();
	}

	private void TwelveImmortalsMovement9(DataContext context, Character character)
	{
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		List<Character> blockChars = ObjectPool<List<Character>>.Instance.Get();
		blockChars.AddRange(config.GetImpactRangeCharacters());
		Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		if (taiwuChar.GetLocation().GetManhattanDistanceToPos(character.GetLocation()) <= config.ImpactRange)
		{
			blockChars.Add(taiwuChar);
		}
		CollectionUtils.Shuffle(context.Random, blockChars);
		MonthlyEventCollection monthlyEvent = DomainManager.World.GetMonthlyEventCollection();
		int fightCount = blockChars.Count / 3;
		for (int i = 0; i < fightCount; i++)
		{
			Character srcChar = blockChars[i];
			Character dstChar = blockChars[i + fightCount];
			if (dstChar == taiwuChar)
			{
				monthlyEvent.AddMainStoryImmortalBaJiuJianYin(srcChar.GetId(), dstChar.GetId());
			}
			else
			{
				SimulateCharacterCombat(context, srcChar, dstChar, CombatType.Die);
			}
		}
		ObjectPool<List<Character>>.Instance.Return(blockChars);
	}

	public void RemoveTwelveImmortal(DataContext context, sbyte twelveImmortalTemplateId)
	{
		TwelveImmortalsItem config = TwelveImmortals.Instance[twelveImmortalTemplateId];
		if (config == null || !TryGetFixedCharacterByTemplateId(config.Character, out var character))
		{
			return;
		}
		switch (character.GetTemplateId())
		{
		case 1080:
			foreach (Character blockChar in config.GetImpactRangeCharacters())
			{
				if (blockChar.GetFeatureIds().Contains(861))
				{
					blockChar.RemoveFeature(context, 861);
				}
			}
			break;
		case 1081:
			foreach (short jiaoTemplateId in TwelveImmortalsConstants.JiaoCharacterToPoisonTypes.Keys)
			{
				if (TryGetFixedCharacterByTemplateId(jiaoTemplateId, out var jiao))
				{
					RemoveNonIntelligentCharacter(context, jiao);
				}
			}
			break;
		case 1082:
			foreach (short mirrorTemplateId in TwelveImmortalsConstants.MirrorCharacters)
			{
				if (TryGetFixedCharacterByTemplateId(mirrorTemplateId, out var mirror))
				{
					RemoveNonIntelligentCharacter(context, mirror);
				}
			}
			break;
		case 1083:
			foreach (MapBlockData block in config.GetImpactRangeBlocks())
			{
				HashSet<int> enemyCharacterSet = block.EnemyCharacterSet;
				if (enemyCharacterSet == null || enemyCharacterSet.Count <= 0)
				{
					continue;
				}
				List<Character> enemyChars = ObjectPool<List<Character>>.Instance.Get();
				foreach (int enemyCharId in block.EnemyCharacterSet)
				{
					if (_objects.TryGetValue(enemyCharId, out var enemyChar) && enemyChar.GetFeatureIds().Contains(880))
					{
						enemyChars.Add(enemyChar);
					}
				}
				foreach (Character enemyChar2 in enemyChars)
				{
					RemoveNonIntelligentCharacter(context, enemyChar2);
				}
				ObjectPool<List<Character>>.Instance.Return(enemyChars);
			}
			break;
		}
		Location location = character.GetLocation();
		character.SetLocation(Location.Invalid, context);
		Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), location, Location.Invalid);
		InvalidateTwelveImmortalsMoveCostCache(context);
	}

	private void TwelveImmortalsOnTaiwuMove(DataContext context, MapBlockData from, MapBlockData to, int costTime)
	{
		TwelveImmortalsOnTaiwuMove1(context, to);
		TwelveImmortalsOnTaiwuMove2(context, to, costTime);
		TwelveImmortalsOnTaiwuMove3(context, to);
		TwelveImmortalsOnTaiwuMove11(context, to, costTime);
		DomainManager.Story.InvokeTwelveImmortalsIntoImpactRangeEvent(context, to);
	}

	private void TwelveImmortalsOnTaiwuMove1(DataContext context, MapBlockData to)
	{
		TwelveImmortalsItem config = TwelveImmortals.DefValue.Jiuyan;
		if (TryGetFixedCharacterByTemplateId(config.Character, out var character) && character.GetLocation().GetManhattanDistanceToPos(to.GetLocation()) <= config.ImpactRange)
		{
			Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
			sbyte bodyPart = (sbyte)context.Random.Next(7);
			bool inner = context.Random.CheckPercentProb(50);
			taiwuChar.ChangeInjury(context, bodyPart, inner, 1);
		}
	}

	private void TwelveImmortalsOnTaiwuMove2(DataContext context, MapBlockData to, int costTime)
	{
		TwelveImmortalsItem config = TwelveImmortals.DefValue.YehuaFuren;
		if (TryGetFixedCharacterByTemplateId(config.Character, out var character) && character.GetLocation().GetManhattanDistanceToPos(to.GetLocation()) <= config.ImpactRange)
		{
			TwelveImmortalsData twelveImmortalsData = _twelveImmortalsData;
			Dictionary<sbyte, int> moveCost = twelveImmortalsData.TwelveImmortalsImpactRangeMoveCost ?? (twelveImmortalsData.TwelveImmortalsImpactRangeMoveCost = new Dictionary<sbyte, int>());
			int costedTime = moveCost.Accumulate<sbyte>(2, costTime);
			if (costedTime >= 100)
			{
				moveCost.Remove(2);
				DomainManager.TaiwuEvent.OnEvent_TwelveImmortals2AttackTaiwu();
			}
			SetTwelveImmortalsData(_twelveImmortalsData, context);
		}
	}

	private void TwelveImmortalsOnTaiwuMove3(DataContext context, MapBlockData to)
	{
		if (!TryGetFixedCharacterByTemplateId(1078, out var character))
		{
			return;
		}
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config != null)
		{
			Location location = to.GetLocation();
			if (character.GetLocation().GetManhattanDistanceToPos(location) <= config.ImpactRange)
			{
				int currDate = DomainManager.World.GetCurrDate();
				TwelveImmortalsData twelveImmortalsData = _twelveImmortalsData;
				Dictionary<Location, int> data = twelveImmortalsData.TwelveImmortals3TaiwuMovedLocations ?? (twelveImmortalsData.TwelveImmortals3TaiwuMovedLocations = new Dictionary<Location, int>());
				data[location] = currDate + 3;
				SetTwelveImmortalsData(_twelveImmortalsData, context);
			}
		}
	}

	private void TwelveImmortalsOnTaiwuMove11(DataContext context, MapBlockData to, int costTime)
	{
		if (!TryGetFixedCharacterByTemplateId(1086, out var character))
		{
			return;
		}
		TwelveImmortalsItem config = character.GetTwelveImmortalsConfig();
		if (config == null)
		{
			return;
		}
		Location location = to.GetLocation();
		if (character.GetLocation().GetManhattanDistanceToPos(location) <= config.ImpactRange)
		{
			TwelveImmortalsData twelveImmortalsData = _twelveImmortalsData;
			Dictionary<sbyte, int> moveCost = twelveImmortalsData.TwelveImmortalsImpactRangeMoveCost ?? (twelveImmortalsData.TwelveImmortalsImpactRangeMoveCost = new Dictionary<sbyte, int>());
			int costedTime = moveCost.Accumulate(config.TemplateId, costTime);
			if (costedTime >= 100)
			{
				Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
				taiwuChar.ChangeDisorderOfQiRandomRecovery(context, 2000);
				moveCost.Remove(config.TemplateId);
			}
			SetTwelveImmortalsData(_twelveImmortalsData, context);
		}
	}

	private void InvalidateTwelveImmortalsMoveCostCache(DataContext context)
	{
		SetTwelveImmortalsData(_twelveImmortalsData, context);
	}

	private void CalcTwelveImmortalsMoveCostMultiplier(Dictionary<Location, int> data)
	{
		data.Clear();
		if (TryGetFixedCharacterByTemplateId(TwelveImmortals.DefValue.YehuaFuren.Character, out var lady))
		{
			AddTwelveImmortalsMoveCostMultiplier(data, lady, TwelveImmortals.DefValue.YehuaFuren.ImpactRange, 5);
		}
		Dictionary<Location, int> twelveImmortals3TaiwuMovedLocations = _twelveImmortalsData.TwelveImmortals3TaiwuMovedLocations;
		if (twelveImmortals3TaiwuMovedLocations != null && twelveImmortals3TaiwuMovedLocations.Count > 0)
		{
			int currDate = DomainManager.World.GetCurrDate() - 3;
			foreach (var (location2, outDate) in _twelveImmortalsData.TwelveImmortals3TaiwuMovedLocations)
			{
				if (outDate > currDate)
				{
					AddTwelveImmortalsMoveCostMultiplier(data, location2, 30);
				}
			}
		}
		if (TryGetFixedCharacterByTemplateId(1080, out var immortal))
		{
			TwelveImmortalsItem config = immortal.GetTwelveImmortalsConfig();
			foreach (Character blockChar in config.GetImpactRangeCharacters(immortal))
			{
				if (blockChar.GetFeatureIds().Contains(861))
				{
					AddTwelveImmortalsMoveCostMultiplier(data, blockChar, 2, 10);
				}
			}
		}
		foreach (short templateId in TwelveImmortalsConstants.JiaoCharacterToPoisonTypes.Keys)
		{
			if (TryGetFixedCharacterByTemplateId(templateId, out var jiao))
			{
				AddTwelveImmortalsMoveCostMultiplier(data, jiao, 1, 5);
			}
		}
		foreach (short templateId2 in TwelveImmortalsConstants.MirrorCharacters)
		{
			if (TryGetFixedCharacterByTemplateId(templateId2, out var mirror))
			{
				AddTwelveImmortalsMoveCostMultiplier(data, mirror, 1, 30);
			}
		}
		foreach (MapBlockData block in TwelveImmortals.DefValue.HuoguShi.GetImpactRangeBlocks())
		{
			HashSet<int> enemyCharacterSet = block.EnemyCharacterSet;
			if (enemyCharacterSet == null || enemyCharacterSet.Count <= 0)
			{
				continue;
			}
			foreach (int enemyCharId in block.EnemyCharacterSet)
			{
				if (_objects.TryGetValue(enemyCharId, out var enemyChar) && enemyChar.GetFeatureIds().Contains(880))
				{
					AddTwelveImmortalsMoveCostMultiplier(data, enemyChar, 1, 3);
				}
			}
		}
		if (TryGetFixedCharacterByTemplateId(TwelveImmortals.DefValue.Youxiao.Character, out var character))
		{
			AddTwelveImmortalsMoveCostMultiplier(data, character, TwelveImmortals.DefValue.Youxiao.ImpactRange, 5);
		}
	}

	private void AddTwelveImmortalsMoveCostMultiplier(Dictionary<Location, int> data, Character character, int range, int value)
	{
		Location location = character.GetLocation();
		if (!location.IsValid())
		{
			return;
		}
		List<MapBlockData> blocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, blocks, range, includeCenter: true);
		foreach (MapBlockData block in blocks)
		{
			AddTwelveImmortalsMoveCostMultiplier(data, block.GetLocation(), value);
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(blocks);
	}

	private static void AddTwelveImmortalsMoveCostMultiplier(Dictionary<Location, int> data, Location location, int value)
	{
		data[location] = data.GetOrDefault(location, 1) * value;
	}

