	private int CheckModified_Graves(int objectId, ushort fieldId, RawDataPool dataPool)
	{
		if (!_graves.TryGetValue(objectId, out var instance))
		{
			return -1;
		}
		if (fieldId >= 7)
		{
			throw new Exception($"Not allow to check readonly field data: {fieldId}");
		}
		if (!_dataStatesGraves.IsModified(instance.DataStatesOffset, fieldId))
		{
			return -1;
		}
		_dataStatesGraves.ResetModified(instance.DataStatesOffset, fieldId);
		return fieldId switch
		{
			0 => GameData.Serializer.Serializer.Serialize(instance.GetId(), dataPool), 
			1 => GameData.Serializer.Serializer.Serialize(instance.GetLocation(), dataPool), 
			2 => GameData.Serializer.Serializer.Serialize(instance.GetLevel(), dataPool), 
			3 => GameData.Serializer.Serializer.Serialize(instance.GetDurability(), dataPool), 
			4 => GameData.Serializer.Serializer.Serialize(instance.GetInventory(), dataPool), 
			5 => GameData.Serializer.Serializer.Serialize(instance.GetResources(), dataPool), 
			6 => GameData.Serializer.Serializer.Serialize(instance.GetSkeletonCharId(), dataPool), 
			_ => throw new Exception($"Unsupported fieldId {fieldId}"), 
		};
	}

	private void ResetModifiedWrapper_Graves(int objectId, ushort fieldId)
	{
		if (_graves.TryGetValue(objectId, out var instance))
		{
			if (fieldId >= 7)
			{
				throw new Exception($"Not allow to reset modification state of readonly field data: {fieldId}");
			}
			if (_dataStatesGraves.IsModified(instance.DataStatesOffset, fieldId))
			{
				_dataStatesGraves.ResetModified(instance.DataStatesOffset, fieldId);
			}
		}
	}

	private bool IsModifiedWrapper_Graves(int objectId, ushort fieldId)
	{
		if (!_graves.TryGetValue(objectId, out var instance))
		{
			return false;
		}
		if (fieldId >= 7)
		{
			throw new Exception($"Not allow to check modification state of readonly field data: {fieldId}");
		}
		return _dataStatesGraves.IsModified(instance.DataStatesOffset, fieldId);
	}

