		foreach (KeyValuePair<int, Grave> grafe in _graves)
		{
			Grave instance2 = grafe.Value;
			instance2.CollectionHelperData = HelperDataGraves;
			instance2.DataStatesOffset = _dataStatesGraves.Create();
		}
	}

	[DomainMethod]
	public int CreateProtagonist(DataContext context, ProtagonistCreationInfo info)
	{
		sbyte sectOrgTemplateId = MapDomain.GetSectOrgTemplateIdByStateTemplateId(info.TaiwuVillageStateTemplateId);
		short orgMemberId = OrganizationDomain.GetMemberId(sectOrgTemplateId, 5);
		sbyte gender = info.InscribedChar?.Gender ?? info.Gender;
		short charTemplateId = MapDomain.GetCharacterTemplateId(info.TaiwuVillageStateTemplateId, gender);
		Character character = new Character(charTemplateId);
		Character.ProtagonistFeatureRelatedStatus status = character.OfflineCreateProtagonist(charTemplateId, orgMemberId, info, context);
		int charId = GenerateNextObjectId(context);
		character.OfflineSetId(charId);
		AddElement_Objects(charId, character);
		StartCreatingCharacter(charId);
		DomainManager.CombatSkill.RegisterCombatSkills(charId, status.CombatSkills);
		AutoActivateReadCombatSkillNormalPages(context, status.CombatSkills, charId);
		DomainManager.Taiwu.RegisterProtagonistLifeSkillsAndCombatSkills(context, character.GetLearnedLifeSkills(), status.CombatSkills);
		DomainManager.Taiwu.SetTaiwu(context, character);
		List<GameData.Domains.Item.SkillBook> lifeSkillBooks = status.LifeSkillBooks;
		if (lifeSkillBooks != null && lifeSkillBooks.Count > 0)
		{
			foreach (GameData.Domains.Item.SkillBook book in status.LifeSkillBooks)
			{
				for (byte i = 0; i < 5; i++)
				{
					DomainManager.Taiwu.ReadSkillBookPageAndSetComplete(context, book, i);
				}
			}
		}
		short blockId = DomainManager.Map.GetMainSettlementMainBlockId(135);
		Location location = new Location(135, blockId);
		character.SetLocation(location, context);
		DomainManager.Taiwu.JoinGroup(context, charId, showNotification: false);
		List<short> protagonistFeatureIds = info.ProtagonistFeatureIds;
		if (protagonistFeatureIds != null && protagonistFeatureIds.Count > 0)
		{
			foreach (short featureId in info.ProtagonistFeatureIds)
			{
				ProtagonistFeatureItem config = ProtagonistFeature.Instance[featureId];
				List<PropertyAndValueAndModifyType> permanentBonus = config.PermanentBonus;
				if (permanentBonus == null || permanentBonus.Count <= 0)
				{
					continue;
				}
				foreach (PropertyAndValueAndModifyType bonus in config.PermanentBonus)
				{
					DomainManager.Taiwu.AddTaiwuPropertyPermanentBonus(context, bonus.Type, bonus.Modify, bonus.Value);
				}
			}
		}
		CreateAdoptiveFather(context, character);
		if (status.CreateCloseFriend)
		{
			sbyte friendGender = Gender.Flip(gender);
			short friendTemplateId = MapDomain.GetCharacterTemplateId(info.TaiwuVillageStateTemplateId, friendGender);
			CreateCloseFriend(context, friendTemplateId, info.Morality, character);
		}
		CreateXiangshuAvatars(context, character);
		character.UpdateHobbyExpirationDate(context);
		short selfLocationInformationId = MapBlock.Instance[MapArea.Instance[MapState.Instance[info.TaiwuVillageStateTemplateId].MainAreaID].SettlementBlockCore[0]].InformationTemplateId;
		DomainManager.Information.AddNormalInformationToCharacter(context, charId, new NormalInformation(Config.Information.Instance.Where((InformationItem informationItem) => informationItem.IsGeneral && informationItem.Type == 0 && informationItem.TemplateId != selfLocationInformationId).ToArray().GetRandom(context.Random)
			.TemplateId, 4));
		Events.RaiseCharacterCreated(context, character);
		CompleteCreatingCharacter(charId);
		DomainManager.Taiwu.RecordAllOwnedClothing(context);
		DomainManager.World.ApplyChallengeModeInitialEffect(context, info.ChallengeModeInfo);
		DomainManager.Global.OnCurrWorldArchiveDataReady(context, isNewWorld: true);
		ItemKey item = DomainManager.Item.CreateAccessory(context, 90, 1);
		character.AddInventoryItem(context, item, 1);
		ItemKey[] equipments = character.GetEquipment().ToArray();
		equipments[14] = item;
		character.ChangeEquipment(context, equipments);
		return charId;
	}

	public void ConvertFixedCharacter(DataContext context, Character fixedChar, Location location, bool recreateAttributesAndQualifications)
	{
		Tester.Assert(fixedChar.GetCreatingType() == 0);
		int charId = fixedChar.GetId();
		short templateId = fixedChar.GetTemplateId();
		_fixedCharactersCache.Remove(templateId);
		_convertedFixedCharactersCache[templateId] = charId;
		fixedChar.OfflineSetCreatingType(1);
		fixedChar.OfflineSetBirthLocation(location);
		FullName fullname = ConvertFixedCharacterName(context, fixedChar.GetTemplateId(), fixedChar.GetGender());
		fixedChar.SetFullName(fullname, context);
		if (recreateAttributesAndQualifications)
		{
			sbyte growingSectId = fixedChar.GetIdealSect();
			if (growingSectId < 0)
			{
				growingSectId = fixedChar.GetOrganizationInfo().OrgTemplateId;
			}
			fixedChar.OfflineRecreateByGrowingSect(context.Random, growingSectId, 4);
		}
		RemoveElement_Objects(charId);
		AddElement_Objects(charId, fixedChar);
		OrganizationInfo orgInfo = fixedChar.GetOrganizationInfo();
		if (OrganizationDomain.IsSect(orgInfo.OrgTemplateId))
		{
			orgInfo.SettlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(orgInfo.OrgTemplateId);
			fixedChar.SetOrganizationInfo(orgInfo, context);
			DomainManager.Organization.JoinOrganization(context, fixedChar, orgInfo, charIsCreating: true);
		}
		else
		{
			if (orgInfo.OrgTemplateId == 20 || orgInfo.OrgTemplateId == 19)
			{
				throw new Exception($"{fixedChar.GetId()} is either XiangshuInfected or XiangshuMinion, " + "thus cannot be converted from fixed character to intelligent character");
			}
			if (orgInfo.OrgTemplateId != 0)
			{
				fixedChar.SetOrganizationInfo(OrganizationInfo.None, context);
			}
		}
		fixedChar.SetCurrMainAttributes(fixedChar.GetMaxMainAttributes(), context);
		DomainManager.Information.RegisterInformation(charId, context);
		Location srcLocation = fixedChar.GetLocation();
		Events.RaiseFixedCharacterLocationChanged(context, charId, srcLocation, Location.Invalid);
		fixedChar.SetLocation(location, context);
		Events.RaiseCharacterLocationChanged(context, charId, Location.Invalid, location);
	}

	private FullName ConvertFixedCharacterName(DataContext context, short templateId, sbyte gender)
	{
		CharacterItem config = Config.Character.Instance[templateId];
		int customSurnameId = (string.IsNullOrEmpty(config.Surname) ? (-1) : DomainManager.World.RegisterCustomText(context, config.Surname));
		int customGivenNameId = (string.IsNullOrEmpty(config.GivenName) ? (-1) : DomainManager.World.RegisterCustomText(context, config.GivenName));
		FullName fullName = ((config.Race == 0) ? GenerateRandomHanName(context.Random, customSurnameId, -1, gender, 0) : GenerateRandomZangName(context.Random, gender));
		if (customGivenNameId >= 0)
		{
			fullName.SetCustomGivenName(customGivenNameId);
		}
		return fullName;
	}

	public Character CreateFixedCharacter(DataContext context, short templateId)
	{
		Tester.Assert(Config.Character.Instance[templateId].CreatingType == 0);
		if (_fixedCharactersCache.ContainsKey(templateId))
		{
			throw new Exception($"FixedCharacter {templateId} has already been created.");
		}
		Character fixedCharacter = CreatePresetCharacter(context, templateId);
		_fixedCharactersCache.Add(templateId, fixedCharacter.GetId());
		DomainManager.LegendaryBook.UpdateBossCharacterLegendaryBookFeatures(context, fixedCharacter);
		return fixedCharacter;
	}

	public Character CreateFixedEnemy(DataContext context, short templateId, bool isTemporary)
	{
		Tester.Assert(Config.Character.Instance[templateId].CreatingType == 3);
		Character character = CreatePresetCharacter(context, templateId);
		if (isTemporary)
		{
			RegisterTemporaryEnemy(context, character.GetId());
		}
		return character;
	}

	public Character CreateFixedEnemy(DataContext context, short templateId, bool isTemporary, ref FixedEnemyCreationInfo creationInfo)
	{
		Character character = new Character(templateId);
		if (creationInfo.Gender != -1)
		{
			character.OfflineSetGenderInfo(creationInfo.Gender, character.GetTransgender());
		}
		List<GameData.Domains.CombatSkill.CombatSkill> combatSkills = character.OfflineCreatePresetCharacter(templateId, context);
		ComplementCreatePresetCharacter(context, character, combatSkills);
		if (isTemporary)
		{
			RegisterTemporaryEnemy(context, character.GetId());
		}
		return character;
	}

	private Character CreatePresetCharacter(DataContext context, short templateId)
	{
		Character character = new Character(templateId);
		List<GameData.Domains.CombatSkill.CombatSkill> combatSkills = character.OfflineCreatePresetCharacter(templateId, context);
		ComplementCreatePresetCharacter(context, character, combatSkills);
		return character;
	}

	private void ComplementCreatePresetCharacter(DataContext context, Character character, List<GameData.Domains.CombatSkill.CombatSkill> combatSkills)
	{
		int charId = GenerateNextObjectId(context);
		character.OfflineSetId(charId);
		AddElement_Objects(charId, character);
		StartCreatingCharacter(charId);
		DomainManager.CombatSkill.RegisterCombatSkills(charId, combatSkills);
		DomainManager.Extra.InitCombatSkillProficiency(context, character);
		AutoActivateReadCombatSkillNormalPages(context, combatSkills, charId);
		Events.RaiseCharacterCreated(context, character);
	}

