	private void ComplementCreateRandomEnemy(DataContext context, Character character, List<GameData.Domains.CombatSkill.CombatSkill> combatSkills, bool isTemporary)
	{
		int charId = GenerateNextObjectId(context);
		character.OfflineSetId(charId);
		AddElement_Objects(charId, character);
		StartCreatingCharacter(charId);
		if (isTemporary)
		{
			RegisterTemporaryEnemy(context, character.GetId());
		}
		DomainManager.CombatSkill.RegisterCombatSkills(charId, combatSkills);
		DomainManager.Extra.InitCombatSkillProficiency(context, character);
		AutoActivateReadCombatSkillNormalPages(context, combatSkills, charId);
		Events.RaiseCharacterCreated(context, character);
		character.RemoveUnequippedCombatSkills(context, 25);
	}

	public void ConvertRandomEnemy(DataContext context, Character character, Location location)
	{
		Tester.Assert(character.GetCreatingType() == 2);
		OrganizationInfo srcOrgInfo = character.GetOrganizationInfo();
		sbyte orgTemplateId = srcOrgInfo.OrgTemplateId;
		if ((uint)(orgTemplateId - 19) <= 1u)
		{
			throw new Exception($"{character.GetId()} is either XiangshuInfected or XiangshuMinion, " + "thus cannot be converted from random enemy to intelligent character");
		}
		if (!location.IsValid() || location.AreaId >= 135)
		{
			location = DomainManager.Taiwu.GetTaiwuVillageLocation();
		}
		int charId = character.GetId();
		short templateId = character.GetTemplateId();
		CharacterItem template = Config.Character.Instance[templateId];
		sbyte gender = character.GetGender();
		sbyte stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(location.AreaId);
		sbyte growingSectId = MapState.Instance[stateTemplateId].SectID;
		short charTemplateId = OrganizationDomain.GetCharacterTemplateId(growingSectId, stateTemplateId, gender);
		character.OfflineSetTemplateId(charTemplateId);
		character.OfflineSetCreatingType(1);
		character.OfflineCreateRandomName(context.Random);
		character.OfflineSetBirthLocation(location);
		character.SetFullName(character.GetFullName(), context);
		List<short> featureIds = character.GetFeatureIds();
		featureIds.Remove(213);
		RemoveElement_Objects(charId);
		AddElement_Objects(charId, character);
		OrganizationInfo targetOrgInfo = OrganizationInfo.None;
		character.SetOrganizationInfo(targetOrgInfo, context);
		Events.RaiseCharacterOrganizationChanged(context, character, srcOrgInfo, targetOrgInfo);
		DomainManager.Adventure.DynamicUnbindCharacterAndUnhideFromMap(context, character);
		UnregisterTemporaryEnemy(context, charId);
		DomainManager.Information.RegisterInformation(charId, context);
		Location srcLocation = character.GetLocation();
		character.SetLocation(location, context);
		if (character.IsCompletelyInfected())
		{
			Events.RaiseInfectedCharacterLocationChanged(context, charId, srcLocation, location);
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, charId, srcLocation, location);
		}
	}

	public Character CreateTemporaryIntelligentCharacter(DataContext context, short characterFilterRulesId, Location location)
	{
		TemporaryIntelligentCharacterCreationInfo tmpInfo = new TemporaryIntelligentCharacterCreationInfo
		{
			Location = location
		};
		GameData.Domains.Character.Filters.CharacterFilterRules.GetRandomCharacterPropertiesWithRulesId(context.Random, characterFilterRulesId, ref tmpInfo);
		return CreateTemporaryIntelligentCharacter(context, ref tmpInfo);
	}

	public Character CreateTemporaryIntelligentCharacter(DataContext context, ref TemporaryIntelligentCharacterCreationInfo tmpInfo)
	{
		IntelligentCharacterCreationInfo info = new IntelligentCharacterCreationInfo(tmpInfo.Location, tmpInfo.OrgInfo, tmpInfo.CharTemplateId);
		if (tmpInfo.ActualAge.HasValue)
		{
			info.Age = tmpInfo.ActualAge.Value;
		}
		if (tmpInfo.BaseAttraction.HasValue)
		{
			info.BaseAttraction = tmpInfo.BaseAttraction.Value;
		}
		Character character = new Character(info.CharTemplateId);
		CreateIntelligentCharacterModification mod = new CreateIntelligentCharacterModification
		{
			Self = character
		};
		character.OfflineCreateTemporaryIntelligentCharacter(context, mod, ref info, ref tmpInfo);
		int charId = GenerateNextObjectId(context);
		character.OfflineSetId(charId);
		AddElement_Objects(charId, character);
		StartCreatingCharacter(charId);
		RegisterTemporaryIntelligentCharacter(charId);
		if (tmpInfo.MonkType.HasValue)
		{
			SetMonkOfTemporaryIntelligentCharacter(context, character, tmpInfo.MonkType.Value);
		}
		if (tmpInfo.BountySeverity.HasValue)
		{
			sbyte severity = tmpInfo.BountySeverity.Value;
			var (bountySect, punishmentType) = GetRandomPunishmentType(context.Random, character.GetOrganizationInfo(), severity);
			DomainManager.Organization.AddSectBounty(context, bountySect, charId, tmpInfo.BountySeverity.Value, punishmentType, -1);
		}
		DomainManager.CombatSkill.RegisterCombatSkills(charId, mod.CombatSkills);
		DomainManager.Extra.InitCombatSkillProficiency(context, character);
		AutoActivateReadCombatSkillNormalPages(context, mod.CombatSkills, charId);
		character.AddEquipmentAndInventoryItems(context, mod.Equipment, mod.Inventory);
		character.AddSkillBooksAndWeapons(context, mod.InventorySkillBooks, mod.SkillWeaponIds);
		int challengePercent = DomainManager.World.GetChallengeModeData().GetCharacterResourcesCreateRate();
		for (int i = 0; i < 8; i++)
		{
			int value = tmpInfo.Resources.Get(i) * challengePercent / 100;
			tmpInfo.Resources.Set(i, value);
		}
		character.ChangeResources(context, ref tmpInfo.Resources);
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		if (OrganizationDomain.IsSect(orgInfo.OrgTemplateId) && orgInfo.Grade == 8 && orgInfo.Principal)
		{
			character.AddFeature(context, 696);
		}
		DomainManager.Organization.TryAddSectMemberFeature(context, character, orgInfo);
		Events.RaiseCharacterCreated(context, character);
		CompleteCreatingCharacter(charId);
		if (tmpInfo.IsCompletelyInfected.HasValue && tmpInfo.IsCompletelyInfected.Value)
		{
			character.ChangeXiangshuInfection(context, 200);
			character.UpdateXiangshuInfectionState(context);
		}
		return character;
	}

	public void ConvertTemporaryIntelligentCharacter(DataContext context, Character character)
	{
		int charId = character.GetId();
		if (character.IsActiveExternalRelationState(188uL))
		{
			DomainManager.Adventure.MarkMajorEventTemporaryCharacterAsCalled(context, charId);
		}
		else if (character.IsCompletelyInfected())
		{
			Events.RaiseInfectedCharacterLocationChanged(context, charId, Location.Invalid, character.GetLocation());
		}
		else
		{
			Events.RaiseCharacterLocationChanged(context, charId, Location.Invalid, character.GetLocation());
		}
		DomainManager.Organization.JoinOrganization(context, character, character.GetOrganizationInfo(), charIsCreating: true);
		character.UpdateHobbyExpirationDate(context);
		UnregisterTemporaryIntelligentCharacter(charId);
		Logger.Info($"Converting temporary character {character} to intelligent character.");
	}

	public Character CreateTemporaryCopyOfCharacter(DataContext context, Character srcCharacter)
	{
		int srcCharId = srcCharacter.GetId();
		Character character = GameData.Serializer.Serializer.CreateCopy(srcCharacter);
		int charId = GenerateNextObjectId(context);
		character.OfflineSetId(charId);
		character.OfflineSetCopySource(srcCharId);
		AddElement_Objects(charId, character);
		StartCreatingCharacter(charId);
		RegisterTemporaryIntelligentCharacter(charId);
		List<GameData.Domains.CombatSkill.CombatSkill> combatSkills = ObjectPool<List<GameData.Domains.CombatSkill.CombatSkill>>.Instance.Get();
		combatSkills.Clear();
		foreach (short combatSkillId in srcCharacter.GetLearnedCombatSkills())
		{
			GameData.Domains.CombatSkill.CombatSkill srcSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(srcCharId, combatSkillId));
			GameData.Domains.CombatSkill.CombatSkill newSkill = GameData.Serializer.Serializer.CreateCopy(srcSkill);
			newSkill.OfflineSetCharId(charId);
			newSkill.OfflineSetSpecialEffectId(-1L);
			combatSkills.Add(newSkill);
		}
		DomainManager.CombatSkill.RegisterCombatSkills(charId, combatSkills);
		AutoActivateReadCombatSkillNormalPages(context, combatSkills, charId);
		DomainManager.Extra.CopyCombatSkillProficiency(context, srcCharId, charId);
		ObjectPool<List<GameData.Domains.CombatSkill.CombatSkill>>.Instance.Return(combatSkills);
		ItemKey[] srcCharEquipments = srcCharacter.GetEquipment();
		for (int slot = 0; slot < srcCharEquipments.Length; slot++)
		{
			ItemKey srcItemKey = srcCharEquipments[slot];
			if (srcItemKey.IsValid())
			{
				ItemKey itemKey = DomainManager.Item.CreateCopyOfItem(context, srcItemKey);
				character.AddInventoryItem(context, itemKey, 1);
			}
		}
		Dictionary<ItemKey, int> srcCharInventoryItems = srcCharacter.GetInventory().Items;
		foreach (var (srcItemKey2, amount) in srcCharInventoryItems)
		{
			if (ItemTemplateHelper.GetItemSubType(srcItemKey2.ItemType, srcItemKey2.TemplateId) != 1202)
			{
				ItemKey itemKey3 = DomainManager.Item.CreateCopyOfItem(context, srcItemKey2);
				character.AddInventoryItem(context, itemKey3, amount);
			}
		}
		character.SetLocation(srcCharacter.GetValidLocation(), context);
		DomainManager.Information.RegisterInformation(charId, context);
		Events.RaiseCharacterCreated(context, character);
		CompleteCreatingCharacter(charId);
		return character;
	}

	public Character ConvertIntelligenceCharacterToFixedCharacterByTemplateId(DataContext context, Character srcCharacter, short templateId, bool transferItems = true)
	{
		int srcCharId = srcCharacter.GetId();
		Character character = GameData.Serializer.Serializer.CreateCopy(srcCharacter);
		Character template = GetOrCreateFixedCharacterByTemplateId(context, templateId);
		Location srcLocation = template.GetLocation();
		int charId = template.GetId();
		character.OfflineSetCreatingType(0);
		character.OfflineSetId(charId);
		character.OfflineSetCopySource(-1);
		List<GameData.Domains.CombatSkill.CombatSkill> combatSkills = (from combatSkillId in srcCharacter.GetLearnedCombatSkills()
			select DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(srcCharId, combatSkillId))).Select(GameData.Serializer.Serializer.CreateCopy).Select(delegate(GameData.Domains.CombatSkill.CombatSkill newSkill)
		{
			newSkill.OfflineSetCharId(charId);
			newSkill.OfflineSetSpecialEffectId(-1L);
			return newSkill;
		}).ToList();
		DomainManager.CombatSkill.RemoveAllCombatSkills(charId);
		DomainManager.CombatSkill.RegisterCombatSkills(charId, combatSkills);
		AutoActivateReadCombatSkillNormalPages(context, combatSkills, charId);
		DomainManager.Extra.CopyCombatSkillProficiency(context, srcCharId, charId);
		if (transferItems)
		{
			ItemKey[] srcCharEquipments = srcCharacter.GetEquipment();
			Array.Copy(srcCharEquipments, character.GetEquipment(), srcCharEquipments.Length);
			for (sbyte slot = 0; slot < srcCharEquipments.Length; slot++)
			{
				ItemKey srcItemKey = srcCharEquipments[slot];
				if (srcItemKey.IsValid())
				{
					srcCharacter.ChangeEquipment(context, slot, -1, ItemKey.Invalid);
					TransferItem(context, srcCharacter, character, srcItemKey, 1);
					EquipmentBase baseEquipment = DomainManager.Item.GetBaseEquipment(srcItemKey);
					baseEquipment.SetEquippedCharId(charId, context);
					baseEquipment.SetOwner(ItemOwnerType.CharacterEquipment, charId);
				}
			}
			KeyValuePair<ItemKey, int>[] array = srcCharacter.GetInventory().Items.ToArray();
			for (int num = 0; num < array.Length; num++)
			{
				KeyValuePair<ItemKey, int> keyValuePair = array[num];
				var (srcItemKey2, amount) = (KeyValuePair<ItemKey, int>)(ref keyValuePair);
				TransferItem(context, srcCharacter, character, srcItemKey2, amount);
			}
			srcCharacter.SetInventory(srcCharacter.GetInventory(), context);
			srcCharacter.SetEquipment(srcCharacter.GetEquipment(), context);
		}
		ResourceInts resource = new ResourceInts(default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int));
		(transferItems ? srcCharacter : character).SetResources(ref resource, context);
		if (TryGetRelation(srcCharacter.GetId(), DomainManager.Taiwu.GetTaiwuCharId(), out var relation))
		{
			SetElement_Relations(new RelationKey(character.GetId(), DomainManager.Taiwu.GetTaiwuCharId()), relation, context);
		}
		if (TryGetRelation(DomainManager.Taiwu.GetTaiwuCharId(), srcCharacter.GetId(), out var _))
		{
			SetElement_Relations(new RelationKey(DomainManager.Taiwu.GetTaiwuCharId(), character.GetId()), relation, context);
		}
		DomainManager.Extra.AddInteractedCharacter(context, character.GetId());
		DomainManager.Information.RegisterInformation(charId, context);
		RemoveElement_Objects(charId);
		AddElement_Objects(charId, character);
		character.SetLocation(srcCharacter.GetValidLocation(), context);
		if (srcLocation != character.GetValidLocation())
		{
			Events.RaiseFixedCharacterLocationChanged(context, charId, srcLocation, character.GetValidLocation());
		}
		return character;
		static void TransferItem(DataContext context2, Character character2, Character character3, ItemKey itemKey2, int amount2)
		{
			character2.RemoveInventoryItem(context2, itemKey2, amount2, deleteItem: false, offLine: true);
			character3.AddInventoryItem(context2, itemKey2, amount2, offLine: true);
		}
	}

	public void Possession(DataContext context, int charId, DeadCharacter deadChar, Character bodyChar, AvatarData customAvatarData, List<short> featureIds)
	{
		RemoveElement_Objects(charId);
		bodyChar.OfflinePossession(context, deadChar, featureIds);
		AddElement_Objects(charId, bodyChar);
		if (customAvatarData != null)
