			bodyChar.SetAvatar(context, customAvatarData);
		}
	}

	public void PossessionRemoveWaitingReincarnationChar(DataContext context, int charId)
	{
		IntPair target = default(IntPair);
		bool found = false;
		foreach (IntPair pair in _waitingReincarnationChars.Collection)
		{
			if (pair.Second == charId)
			{
				found = true;
				target = pair;
				break;
			}
		}
		if (found)
		{
			RemoveElement_WaitingReincarnationChars(target, context);
		}
	}

	private int GenerateNextObjectId(DataContext context)
	{
		int objectId = _nextObjectId;
		_nextObjectId++;
		if ((uint)_nextObjectId > 2147483647u)
		{
			_nextObjectId = 0;
		}
		SetNextObjectId(_nextObjectId, context);
		return objectId;
	}

	private void InitializeCharacterItemOwnersOnCreation(DataContext context, Character character)
	{
		int charId = character.GetId();
		Inventory inventory = character.GetInventory();
		foreach (var (itemKey2, _) in inventory.Items)
		{
			DomainManager.Item.SetOwner(itemKey2, ItemOwnerType.CharacterInventory, charId);
		}
		ItemKey[] equipments = character.GetEquipment();
		ItemKey[] array = equipments;
		for (int i = 0; i < array.Length; i++)
		{
			ItemKey itemKey3 = array[i];
			if (itemKey3.IsValid())
			{
				EquipmentBase baseEquipment = DomainManager.Item.GetBaseEquipment(itemKey3);
				baseEquipment.SetEquippedCharId(charId, context);
				baseEquipment.SetOwner(ItemOwnerType.CharacterEquipment, charId);
			}
		}
	}

	private void InitializeEatingItems(DataContext context, Character character)
	{
		CharacterItem template = character.Template;
		if (template.PresetEatingItems == null)
		{
			return;
		}
		foreach (PresetItemTemplateId templateKey in template.PresetEatingItems)
		{
			if (ItemTemplateHelper.IsWug(templateKey.ItemType, templateKey.TemplateId, includeKing: false))
			{
				character.AddWug(context, templateKey.TemplateId, -1);
				continue;
			}
			ItemKey itemKey = DomainManager.Item.CreateItem(context, templateKey.ItemType, templateKey.TemplateId);
			character.AddEatingItem(context, itemKey);
		}
	}

	internal int GetRandomValidAdopterInSettlement(IRandomSource random, Settlement settlement)
	{
		List<int> allMemberIds = ObjectPool<List<int>>.Instance.Get();
		settlement.GetMembers().GetAllMembers(allMemberIds);
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.CanAdoptChild;
		for (int i = allMemberIds.Count - 1; i >= 0; i--)
		{
			int charId = allMemberIds[i];
			Character character = GetElement_Objects(charId);
			if (!matcher.Match(character))
			{
				CollectionUtils.SwapAndRemove(allMemberIds, i);
			}
		}
		int adopterId = allMemberIds.GetRandom(random);
		ObjectPool<List<int>>.Instance.Return(allMemberIds);
		return adopterId;
	}

	private void CreateAdoptiveFather(DataContext context, Character protagonistChar)
	{
		Character character = CreateFixedCharacter(context, 880);
		int charId = character.GetId();
		int protagonistCharId = protagonistChar.GetId();
		if (!RelationTypeHelper.AllowAddingAdoptiveParentRelation(protagonistCharId, charId))
		{
			throw new Exception($"Failed to add adoptive parent relation: {protagonistCharId} - {charId}");
		}
		AddRelation(context, protagonistCharId, charId, 64);
		DirectlySetFavorabilities(context, protagonistCharId, charId, 30000, 30000);
		CompleteCreatingCharacter(charId);
	}

	public Character CreateCloseFriend(DataContext context, short charTemplateId, short morality, Character protagonistChar)
	{
		short settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(0);
		IntelligentCharacterCreationInfo intelligentCharacterCreationInfo = new IntelligentCharacterCreationInfo(orgInfo: new OrganizationInfo(0, 8, principal: true, settlementId), location: protagonistChar.GetLocation(), charTemplateId: charTemplateId);
		intelligentCharacterCreationInfo.GrowingSectGrade = 8;
		intelligentCharacterCreationInfo.Age = 13;
		intelligentCharacterCreationInfo.BaseAttraction = 900;
		IntelligentCharacterCreationInfo info = intelligentCharacterCreationInfo;
		CreateIntelligentCharacterModification mod = ParallelCreateIntelligentCharacter(context, ref info, recordModification: false);
		Character character = mod.Self;
		character.OfflineSetCloseFriendFields(context, morality);
		FeatureCreationContext featureCreationContext = new FeatureCreationContext(character, ref info);
		featureCreationContext.IsProtagonist = true;
		featureCreationContext.AllGoodBasicFeature = true;
		FeatureCreationContext creationContext = featureCreationContext;
		CharacterCreation.CreateFeatures(context.Random, ref creationContext);
		ComplementCreateIntelligentCharacter(context, mod, autoComplement: false);
		int charId = character.GetId();
		if (DomainManager.Taiwu.GetTaiwuCharIdForCloseFriend() == -1)
		{
			DomainManager.Taiwu.SetTaiwuCharIdForCloseFriend(protagonistChar.GetId(), context);
		}
		DomainManager.Taiwu.JoinGroup(context, charId, showNotification: false);
		int protagonistCharId = protagonistChar.GetId();
		if (!RelationTypeHelper.AllowAddingFriendRelation(protagonistCharId, charId))
		{
			throw new Exception($"Failed to add friend relation: {protagonistCharId} - {charId}");
		}
		AddRelation(context, protagonistCharId, charId, 8192);
		DirectlySetFavorabilities(context, protagonistCharId, charId, 30000, 30000);
		CompleteCreatingCharacter(charId);
		return character;
	}

	private void CreateXiangshuAvatars(DataContext context, Character protagonistChar)
	{
		int taiwuCharId = protagonistChar.GetId();
		for (int avatarId = 0; avatarId < 9; avatarId++)
		{
			short charTemplateId = XiangshuAvatarIds.JuniorXiangshuTemplateIds[avatarId];
			Character xiangshuAvatar = CreateFixedCharacter(context, charTemplateId);
			int avatarCharId = xiangshuAvatar.GetId();
			CompleteCreatingCharacter(avatarCharId);
			AddRelation(context, taiwuCharId, avatarCharId, 0);
			DirectlySetFavorabilities(context, taiwuCharId, avatarCharId, 0, 0);
			XiangshuAvatarTaskStatus xiangshuAvatarTaskStatus = DomainManager.World.GetElement_XiangshuAvatarTaskStatuses(avatarId);
			xiangshuAvatarTaskStatus.JuniorXiangshuCharId = avatarCharId;
			DomainManager.World.SetElement_XiangshuAvatarTaskStatuses(avatarId, xiangshuAvatarTaskStatus, context);
		}
	}

	public int CreateJuniorXiangshuCombatImage(DataContext context, sbyte xiangshuAvatarId)
	{
		sbyte xiangshuLevel = DomainManager.World.GetXiangshuLevel();
		return CreateXiangshuCombatImage(context, xiangshuAvatarId, 3, xiangshuLevel);
