	public int CreateXiangshuCombatImage(DataContext context, sbyte xiangshuAvatarId, sbyte xiangshuType, sbyte xiangshuLevel)
	{
		Tester.Assert(xiangshuType == 3 || xiangshuType == 4);
		XiangshuAvatarTaskStatus xiangshuAvatarTaskStatus = DomainManager.World.GetElement_XiangshuAvatarTaskStatuses(xiangshuAvatarId);
		short combatImageTemplateId = XiangshuAvatarIds.GetCurrentLevelXiangshuTemplateId(xiangshuAvatarId, xiangshuLevel);
		Character avatarChar = _objects[xiangshuAvatarTaskStatus.JuniorXiangshuCharId];
		Character combatImageChar = CreatePresetCharacter(context, combatImageTemplateId);
		int combatImageCharId = combatImageChar.GetId();
		RegisterTemporaryEnemy(context, combatImageCharId);
		combatImageChar.OfflineSetXiangshuType(xiangshuType);
		CompleteCreatingCharacter(combatImageCharId);
		combatImageChar.SetActualAge(avatarChar.GetActualAge(), context);
		combatImageChar.SetCurrAge(avatarChar.GetCurrAge(), context);
		combatImageChar.SetHappiness(avatarChar.GetHappiness(), context);
		combatImageChar.SetHealth(combatImageChar.GetLeftMaxHealth(), context);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		RelatedCharacter xiangshuToTaiwu = GetRelation(xiangshuAvatarTaskStatus.JuniorXiangshuCharId, taiwuCharId);
		AddRelation(context, taiwuCharId, combatImageCharId, 0);
		DirectlySetFavorabilities(context, taiwuCharId, combatImageCharId, 0, xiangshuToTaiwu.Favorability);
		return combatImageCharId;
	}

	private static (OrganizationInfo parentOrgInfo, short baseTemplateId, bool isAbandoned) GetMainParentInfo(Character mother, Character father, bool createMotherRelation, bool createFatherRelation, bool isMotherDead)
	{
		bool useFatherInfo = createFatherRelation && father != null;
		bool isMotherAvailable = createMotherRelation && !isMotherDead;
		bool isAbandoned = (!useFatherInfo || father.GetKidnapperId() >= 0) && !isMotherAvailable;
		return useFatherInfo ? (parentOrgInfo: father.GetOrganizationInfo(), baseTemplateId: GetBaseTemplateId(father.GetTemplateId(), father.GetGender()), isAbandoned: isAbandoned) : (parentOrgInfo: mother.GetOrganizationInfo(), baseTemplateId: GetBaseTemplateId(mother.GetTemplateId(), mother.GetGender()), isAbandoned: isAbandoned);
	}

	private static (short baseAttraction, AvatarData avatar) GenerateMainChildAvatar(IRandomSource random, Character mother, Character father, DeadCharacter deadFather, sbyte mainChildGender)
	{
		short baseAttraction = -1;
		AvatarData avatar = null;
		AvatarData motherAvatar = mother.GetAvatar();
		AvatarData fatherAvatar = father?.GetAvatar() ?? deadFather?.Avatar;
		if (motherAvatar != null || fatherAvatar != null)
		{
			avatar = AvatarManager.Instance.GetRandomAvatar(random, mainChildGender, transgender: false, -1, fatherAvatar, motherAvatar);
			baseAttraction = avatar.GetBaseCharm();
		}
		return (baseAttraction: baseAttraction, avatar: avatar);
	}

	private void SetBloodRelatedRelations(DataContext context, int charId, int motherId, int fatherId, int actualFatherId, bool createMotherRelation, bool createFatherRelation)
	{
		if (motherId >= 0)
		{
			if (createMotherRelation)
			{
				AddBloodParentRelations(context, charId, motherId);
			}
			else
			{
				AddChildAbandonment(context, -2, charId, motherId);
			}
		}
		if (fatherId < 0)
		{
			return;
		}
		if (createFatherRelation)
		{
			AddBloodParentRelations(context, charId, fatherId);
			if (actualFatherId >= 0)
			{
				AddFatherSubstitution(context, fatherId, charId, actualFatherId);
			}
		}
		else
		{
			AddChildAbandonment(context, -1, charId, fatherId);
		}
	}

	private static void SetMonkOfTemporaryIntelligentCharacter(DataContext context, Character character, byte monkType)
	{
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		if (!CheckMonkTypeCompatibility(orgInfo, monkType))
		{
			throw new Exception($"Monk type of character is not compatible with organization: {monkType}, {orgInfo.OrgTemplateId}");
		}
		if (monkType != 0)
		{
			if ((monkType & 0x80) == 0)
			{
				character.SetMonkType(monkType, context);
			}
			else
			{
				DomainManager.Organization.BecomeSectMonk(context, character, -1);
			}
		}
	}

	private static bool CheckMonkTypeCompatibility(OrganizationInfo orgInfo, byte selfMonkType)
	{
		OrganizationItem orgConfig = Config.Organization.Instance[orgInfo.OrgTemplateId];
		short orgMemberId = orgConfig.Members[orgInfo.Grade];
		OrganizationMemberItem orgMemberCfg = OrganizationMember.Instance[orgMemberId];
		if (orgMemberCfg.MonkType == 0)
		{
			if (selfMonkType == 0)
			{
				return true;
			}
			return !orgConfig.IsSect && (selfMonkType & 0x80) == 0;
		}
		if (selfMonkType == 0)
		{
			return orgMemberCfg.ProbOfBecomingMonk < 100;
		}
		return orgMemberCfg.MonkType == selfMonkType;
	}

	private static (sbyte, short) GetRandomPunishmentType(IRandomSource random, OrganizationInfo orgInfo, sbyte severity)
	{
		if (orgInfo.SettlementId < 0)
		{
			return (-1, -1);
		}
		Settlement settlement = DomainManager.Organization.GetSettlement(orgInfo.SettlementId);
		short areaId = settlement.GetLocation().AreaId;
		sbyte stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(areaId);
		sbyte bountySect = MapState.Instance[stateTemplateId].SectID;
		bool isSect = OrganizationDomain.IsSect(orgInfo.OrgTemplateId);
		List<short> punishmentTypes = new List<short>();
		foreach (PunishmentTypeItem punishmentTypeCfg in (IEnumerable<PunishmentTypeItem>)PunishmentType.Instance)
		{
			List<ShortPair> severities = (isSect ? punishmentTypeCfg.SectPunishmentSeverities : punishmentTypeCfg.CivilianPunishmentSeverities);
			if (severities == null || severities.Count <= 0)
			{
				continue;
			}
			foreach (ShortPair pair in severities)
			{
				if (pair.First != stateTemplateId || pair.Second != severity)
				{
					continue;
				}
				punishmentTypes.Add(punishmentTypeCfg.TemplateId);
				break;
			}
		}
		short punishmentType = punishmentTypes.GetRandomOrDefault<short>(random, -1);
		return (bountySect, punishmentType);
	}

	private void StartCreatingCharacter(int charId)
	{
		_creatingCharIds.Add(charId);
	}

	public void CompleteCreatingCharacter(int charId)
	{
		if (!_creatingCharIds.Remove(charId))
		{
			throw new Exception($"Character {charId} is not in creating state");
		}
	}

	public bool IsCharacterCreating(int charId)
	{
		return _creatingCharIds.Contains(charId);
	}

	private bool IsAnyCharacterCreating()
	{
		return _creatingCharIds.Count > 0;
	}

	public void CheckCharacterCreationState()
	{
		if (_creatingCharIds.Count <= 0)
		{
			return;
		}
		StringBuilder message = new StringBuilder("Some characters are still in creating state:\n");
		foreach (int charId in _creatingCharIds)
		{
			if (TryGetElement_Objects(charId, out var character))
			{
				StringBuilder stringBuilder = message;
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(38, 4, stringBuilder);
				handler.AppendLiteral("  TemplateId: ");
				handler.AppendFormatted(character.GetTemplateId());
				handler.AppendLiteral(", CreatingType: ");
				handler.AppendFormatted(character.GetCreatingType());
				handler.AppendLiteral(", Name: ");
				handler.AppendFormatted(character.GetSurname());
				handler.AppendFormatted(character.GetGivenName());
				stringBuilder2.AppendLine(ref handler);
			}
			else
			{
				StringBuilder stringBuilder = message;
				StringBuilder stringBuilder3 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(37, 1, stringBuilder);
				handler.AppendLiteral("  CharacterId: ");
				handler.AppendFormatted(charId);
				handler.AppendLiteral(" (Character not found)");
				stringBuilder3.AppendLine(ref handler);
			}
		}
		throw new Exception(message.ToString());
	}

	public int GetWorldPopulation()
	{
		return _objects.Count - _pregeneratedRandomEnemies.Count - _pregeneratedCityTownGuards.Length - _temporaryIntelligentCharIds.GetCount() - _fixedCharactersCache.Count;
	}

	public void ShowCharactersStats()
	{
		int date = DomainManager.World.GetCurrDate();
		Logger.Info($"[[{date}]] Alive characters: {_objects.Count}, dead characters: {_deadCharacters.Count}");
	}

	public void ShowNonIntelligentCharactersStats()
	{
		List<Character> nonIntelligentCharacters = new List<Character>();
		HashSet<int> registeredNonIntelligentChars = new HashSet<int>();
		registeredNonIntelligentChars.UnionWith(_pregeneratedRandomEnemies);
		registeredNonIntelligentChars.UnionWith(_pregeneratedCityTownGuards);
		registeredNonIntelligentChars.UnionWith(_fixedCharactersCache.Values);
		registeredNonIntelligentChars.UnionWith(_skeletonCharacterCache.Keys);
		ICollection<int> collection = DomainManager.Character.GetPregeneratedFixedEnemies();
		registeredNonIntelligentChars.UnionWith(collection);
		foreach (KeyValuePair<int, Character> @object in _objects)
		{
			@object.Deconstruct(out var key, out var value);
			int charId = key;
			Character character = value;
			short templateId = character.GetTemplateId();
			if (character.GetCreatingType() != 1 && !registeredNonIntelligentChars.Contains(charId))
			{
				nonIntelligentCharacters.Add(character);
			}
		}
		int count = nonIntelligentCharacters.Count;
		StringBuilder message = new StringBuilder($"Non-intelligent characters: {count}\n");
		int logCount = Math.Min(count, 40);
		for (int i = 0; i < logCount; i++)
		{
			Character nonIntelligentChar = nonIntelligentCharacters[i];
			short templateId2 = nonIntelligentChar.GetTemplateId();
			CharacterItem config = Config.Character.Instance[templateId2];
			StringBuilder stringBuilder = message;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(5, 4, stringBuilder);
			handler.AppendLiteral("  ");
			handler.AppendFormatted(nonIntelligentChar.GetId());
			handler.AppendLiteral(": ");
			handler.AppendFormatted(templateId2);
			handler.AppendLiteral("-");
			handler.AppendFormatted(config.Surname);
			handler.AppendFormatted(config.GivenName);
			stringBuilder.AppendLine(ref handler);
		}
		Logger.Info(message);
	}
}
